-- 00000000000005_bar_prep_questions.sql
--
-- MBE question bank: 7 subjects, consolidated from the eight seed files that
-- lived in the legacy directory.
--
-- One repair was applied. Three of the files wrote the case_citation value in
-- DOUBLE quotes:
--
--   ..., 'Relevance - FRE 401', "FRE 401", true),
--
-- PostgreSQL reads a double-quoted token as an identifier, so every one of those
-- rows failed with `column "FRE 401" does not exist` and rolled the file back.
-- They are now single-quoted, with internal apostrophes doubled. Nothing else in
-- the question content was altered.
--
-- Depends on 00000000000004 (bar_subjects rows are the foreign-key target).
-- Verified: loads with 0 errors.
--
-- Idempotency: each INSERT is written as INSERT ... SELECT FROM (VALUES ...)
-- WHERE NOT EXISTS (same subject_id + stem), so re-running this migration adds
-- no duplicate questions. First-run results are unchanged (the seed has no
-- duplicate subject_id+stem pairs: 548 rows, 548 distinct).


-- ══ from 20260717000002_seed_criminal_law_questions.sql ══
-- B-01 Criminal Law Question Bank Seed
-- 125 MBE questions: homicide / theft_property / defenses / criminal_procedure / fifth_sixth_amendment
-- generated from /tmp/criminal_law_qs.json

BEGIN;

INSERT INTO quiz_questions
  (subject_id, category, difficulty, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, rule_tested, case_citation, is_active)
SELECT v.* FROM (VALUES
('crim-law-001', 'homicide', 'medium', 'Dan intentionally shoots at Victor intending to kill him. The bullet misses Victor and kills Paula. Dan is charged with murder of Paula. Is Dan guilty?',
   'Yes, under the transferred intent doctrine.', 'No, because Dan had no knowledge of Paula.', 'Yes, but only for involuntary manslaughter.', 'No, because Dan did not intend to kill Paula.',
   'A', 'Under transferred intent, intent to harm one person transfers to the actual victim. Dan''s intent to kill Victor transfers to Paula, making him liable for Paula''s murder.', 'Transferred Intent Doctrine', 'People v. Suesser (1901)', true),
  ('crim-law-001', 'homicide', 'medium', 'Tom sees his wife in bed with Bob and immediately kills Bob in a rage. Tom''s best defense at common law is:',
   'Justification — defending his marital rights.', 'Self-defense — Bob was trespassing.', 'Insanity — shock caused temporary incapacity.', 'Voluntary manslaughter — heat of passion upon adequate provocation.',
   'D', 'Voluntary manslaughter = murder mitigated by heat of passion upon adequate provocation. Discovering a spouse in adultery is recognized adequate provocation at common law. Tom acted immediately without cooling off.', 'Voluntary Manslaughter — Heat of Passion', NULL, true),
  ('crim-law-001', 'homicide', 'hard', 'Alice poisons Bob''s coffee. Bob dies of a heart attack before drinking it. Alice is charged with attempted murder. The result:',
   'Guilty only of conspiracy.', 'Not guilty — attempt requires causation.', 'Not guilty — her act did not cause Bob''s death.', 'Guilty of attempted murder — she completed all acts necessary.',
   'D', 'Attempt requires specific intent and a substantial step. Alice completed her last act. Bob''s death from an unrelated cause does not negate the completed attempt.', 'Attempt — Last Act / Substantial Step Test', NULL, true),
  ('crim-law-001', 'homicide', 'easy', 'At common law, murder is defined as:',
   'The intentional killing of a human being without justification.', 'The unlawful killing of a human being with premeditation.', 'The reckless killing of a human being.', 'The unlawful killing of a human being with malice aforethought.',
   'D', 'At common law, murder = unlawful killing of a human being with malice aforethought. Malice aforethought includes intent to kill, intent to cause serious bodily harm, depraved heart, or felony murder.', 'Common Law Murder Definition', NULL, true),
  ('crim-law-001', 'homicide', 'hard', 'Dave and co-felons rob a bank. A guard shoots at co-felon Ed, misses, and the bullet kills a customer. Under agency theory (majority), Dave is:',
   'Guilty under felony murder — killing was during the felony.', 'Guilty only of robbery.', 'Not guilty — agency theory limits liability to killings by co-felons, not third parties.', 'Not guilty because the guard was not a co-conspirator.',
   'C', 'Under agency theory (majority), felony murder applies only to killings by co-felons or their agents. The guard is not a co-felon, so no felony murder liability.', 'Felony Murder — Agency vs. Proximate Cause Theory', 'People v. Antick (1975)', true),
  ('crim-law-001', 'homicide', 'medium', 'Mary knowingly drives 100 mph on a crowded highway and kills a pedestrian. No intent to kill. Under MPC, Mary is most likely guilty of:',
   'Reckless murder — extreme recklessness under MPC § 210.2.', 'Knowing murder.', 'Purposeful murder.', 'Negligent homicide.',
   'A', 'MPC § 210.2 includes killings committed recklessly under circumstances manifesting extreme indifference to the value of human life. Driving 100 mph through crowds qualifies.', 'MPC Extreme Recklessness Murder § 210.2', NULL, true),
  ('crim-law-001', 'homicide', 'medium', 'Carl shoots Victor intending to kill him. Victor survives 18 months before dying. If the jurisdiction retains the year-and-a-day rule, Carl is:',
   'Guilty of murder — the rule does not apply to gunshot wounds.', 'Not guilty of murder — death after more than a year and a day bars conviction.', 'Guilty of attempted murder only.', 'Guilty of murder — 18 months exceeds the limit.',
   'B', 'The year-and-a-day rule bars murder conviction when death occurs more than a year and a day after the injurious act.', 'Year-and-a-Day Rule', NULL, true),
  ('crim-law-001', 'homicide', 'medium', 'Which killing IS first-degree murder in a premeditation-deliberation jurisdiction?',
   'Eve shoots her attacker in a sudden fight.', 'Dan shoots his partner after a month of planning.', 'Frank drives recklessly and kills a pedestrian.', 'Grace kills her abusive husband while he sleeps.',
   'B', 'First-degree murder requires intent to kill, premeditation, and deliberation. Dan''s month of planning satisfies all elements. Eve lacks premeditation; Frank lacks intent to kill.', 'First-Degree Murder — Premeditation and Deliberation', NULL, true),
  ('crim-law-001', 'homicide', 'easy', 'Under MPC, the mental state for reckless homicide requires:',
   'Knowledge that death is practically certain.', 'Purpose to cause death.', 'Negligence grossly deviating from ordinary care.', 'Conscious disregard of a substantial and unjustifiable risk.',
   'D', 'MPC § 2.02(2)(c): recklessness = conscious disregard of a substantial and unjustifiable risk. Reckless homicide = manslaughter under MPC § 210.3.', 'MPC Recklessness § 2.02(2)(c)', NULL, true),
  ('crim-law-001', 'homicide', 'medium', 'During a burglary, Ted''s co-felon accidentally drops a lit torch while fleeing, starting a fire that kills a homeowner. Under majority felony murder rule, Ted is:',
   'Guilty only if he knew the torch was lit.', 'Not guilty — he did not personally cause the death.', 'Guilty — killing during furtherance of the felony by any co-felon.', 'Not guilty — accidents are not foreseeable.',
   'C', 'Under felony murder, all co-felons are liable for killings by any co-felon in furtherance of the felony. The death occurred during flight — within the res gestae.', 'Felony Murder — Co-Felon Liability / Res Gestae', NULL, true),
  ('crim-law-001', 'homicide', 'hard', 'Sam strikes Tom once with his fist intending only to hurt him. Tom falls, hits his head, and dies. Sam is most likely guilty of:',
   'Second-degree (depraved heart) murder.', 'First-degree murder.', 'Involuntary manslaughter.', 'Voluntary manslaughter.',
   'C', 'Sam intended to hurt, not kill. A single punch does not manifest extreme indifference to life. Most courts find involuntary manslaughter — criminal negligence from a dangerous act without intent to kill.', 'Involuntary Manslaughter vs. Depraved Heart Murder', NULL, true),
  ('crim-law-001', 'homicide', 'medium', 'The depraved heart theory of murder requires:',
   'Extreme recklessness manifesting depraved indifference to human life.', 'Intent to kill.', 'Intent to cause serious bodily harm.', 'Negligence substantially below the standard of care.',
   'A', 'Depraved heart murder requires conduct manifesting depraved indifference to human life — beyond mere recklessness. Classic examples: firing into a crowded room, Russian roulette.', 'Depraved Heart Murder', 'Malone v. State (1925)', true),
  ('crim-law-001', 'homicide', 'easy', 'Voluntary manslaughter differs from murder in that:',
   'Voluntary manslaughter is an intentional killing mitigated by heat of passion upon adequate provocation.', 'Voluntary manslaughter requires premeditation.', 'Murder requires the victim to be in a protected class.', 'Voluntary manslaughter is an unintentional killing.',
   'A', 'Voluntary manslaughter = intentional killing + heat of passion mitigation upon adequate provocation with insufficient cooling time. It IS intentional — the key distinction from involuntary manslaughter.', 'Voluntary Manslaughter Elements', NULL, true),
  ('crim-law-001', 'homicide', 'hard', 'Rachel poisons Paul''s food, then changes her mind and removes it before Paul returns. Paul never eats the poison. Under MPC, Rachel:',
   'Is not guilty because no harm occurred.', 'Is guilty because MPC attempt is irrevocable once a substantial step is taken.', 'Has a complete defense of abandonment — voluntarily and completely renounced her criminal purpose.', 'Is guilty of attempt — she already took a substantial step.',
   'C', 'MPC § 5.01(4): abandonment defense when the defendant voluntarily abandons her criminal purpose manifesting complete and voluntary renunciation. Rachel acted on her own volition, not from fear of discovery.', 'MPC Attempt — Abandonment Defense § 5.01(4)', NULL, true),
  ('crim-law-001', 'homicide', 'medium', 'At common law, which is NOT adequate provocation for voluntary manslaughter?',
   'An illegal arrest with force.', 'Receiving words of insult alone.', 'Witnessing adultery by a spouse.', 'Being subjected to a serious battery.',
   'B', 'At common law, mere words — no matter how insulting — are not sufficient provocation to reduce murder to voluntary manslaughter. Adequate provocation requires physical acts.', 'Voluntary Manslaughter — Words Insufficient Provocation', NULL, true),
  ('crim-law-001', 'homicide', 'hard', 'Jack drives drunk and kills a pedestrian. He was too intoxicated to appreciate the risk. Under MPC, Jack is most likely guilty of:',
   'Murder under the depraved heart theory.', 'Nothing — intoxication negated mens rea.', 'Reckless homicide — voluntary intoxication cannot negate recklessness under MPC.', 'Negligent homicide only.',
   'C', 'MPC § 2.08(2): voluntary intoxication cannot negate recklessness. If the actor would have been aware of the risk sober, voluntary intoxication is treated as recklessness. Jack''s DUI = reckless homicide (manslaughter).', 'MPC § 2.08 — Voluntary Intoxication and Recklessness', NULL, true),
  ('crim-law-001', 'homicide', 'medium', 'Larry shoots at Maria intending to kill her. The bullet grazes Maria but kills Nathan, a bystander. Under transferred intent, Larry can be convicted of:',
   'Only murder of Nathan — intent fully transfers and is exhausted.', 'Neither — the intent cannot split.', 'Both attempted murder of Maria AND murder of Nathan.', 'Assault on Maria and negligent homicide of Nathan.',
   'C', 'Transferred intent does not exhaust the original intent — it copies it. Larry''s intent to kill Maria supports attempted murder of Maria. That same intent transfers to Nathan for murder. Both convictions stand.', 'Transferred Intent — Intent Not Exhausted', NULL, true),
  ('crim-law-001', 'homicide', 'easy', 'Involuntary manslaughter differs from voluntary manslaughter in that:',
   'Voluntary requires negligence; involuntary requires intent.', 'Involuntary requires provocation; voluntary does not.', 'Both are identical — only the defendant''s age differs.', 'Involuntary involves an unintentional killing; voluntary is intentional.',
   'D', 'Voluntary manslaughter = intentional killing with heat of passion mitigation. Involuntary manslaughter = unintentional killing from criminal negligence or unlawful act. The key distinction is intent.', 'Voluntary vs. Involuntary Manslaughter', NULL, true),
  ('crim-law-001', 'homicide', 'hard', 'Steve deliberately steps in front of a bus to commit suicide. The driver swerves and kills a pedestrian. Steve survived. Steve''s liability for the pedestrian''s death:',
   'Murder under depraved heart theory.', 'None — he only intended to harm himself.', 'Felony murder.', 'Involuntary manslaughter based on reckless conduct toward third parties.',
   'D', 'Steve''s deliberate act created a substantial and unjustifiable risk to others. He did not intend to kill the pedestrian but acted recklessly toward third parties. Involuntary manslaughter (recklessness toward others) is the best fit.', 'Involuntary Manslaughter — Recklessness Causing Third-Party Death', NULL, true),
  ('crim-law-001', 'homicide', 'medium', 'Al threatens to kill Ben tomorrow. The next day Al approaches with his hands in his pockets. Ben shoots and kills Al. Al''s pockets are empty. Ben:',
   'Is guilty of murder — Al made no overt act.', 'May have a complete self-defense claim if he reasonably believed he was in imminent danger.', 'Is guilty of voluntary manslaughter due to provocation.', 'Has no defense because deadly force cannot be based on prior threats alone.',
   'B', 'Self-defense requires a reasonable belief of imminent death or serious bodily harm. The prior threat combined with approaching with hands in pockets could create a reasonable belief under the objective test.', 'Self-Defense — Reasonable Belief of Imminent Threat', NULL, true),
  ('crim-law-001', 'homicide', 'hard', 'Under MPC, the mental state of ''knowingly'' for homicide requires:',
   'The actor had a purpose to cause death.', 'The actor was aware that death was practically certain to result.', 'The actor consciously disregarded a substantial risk of death.', 'The actor should have known death would result.',
   'B', 'MPC § 2.02(2)(b): a person acts knowingly when aware that it is practically certain that his conduct will cause the result. Knowing murder (§ 210.2) is second only to purposeful murder in culpability.', 'MPC Knowing Murder § 2.02(2)(b)', NULL, true),
  ('crim-law-001', 'homicide', 'medium', 'Which statement about the felony murder rule is CORRECT?',
   'It is limited to inherently dangerous felonies in most jurisdictions.', 'Under MPC, it automatically makes the killing first-degree murder.', 'It requires the defendant to personally commit the killing.', 'It applies to any felony.',
   'A', 'Most jurisdictions limit felony murder to inherently dangerous felonies — commonly BARRK: Burglary, Arson, Robbery, Rape, Kidnapping. The MPC rejects an independent felony murder rule.', 'Felony Murder — BARRK Limitation', NULL, true),
  ('crim-law-001', 'homicide', 'easy', 'Which BEST describes ''malice aforethought'' in common law murder?',
   'Knowledge that death is practically certain.', 'Hatred or ill will toward the victim.', 'Intent to cause death, intent to cause grievous bodily harm, depraved heart recklessness, or felony murder.', 'Premeditation and deliberation only.',
   'C', 'Malice aforethought is a term of art meaning any of four mental states: (1) intent to kill, (2) intent to cause serious bodily harm, (3) depraved heart (extreme recklessness), or (4) intent to commit a felony (felony murder). It does NOT require actual malice or hatred.', 'Malice Aforethought — Four Forms', NULL, true),
  ('crim-law-001', 'homicide', 'hard', 'Pam fires a gun into a warehouse she believes is empty. An unknown security guard inside is killed. Pam is most likely guilty of:',
   'First-degree murder.', 'Depraved heart murder.', 'Involuntary manslaughter.', 'No crime — she reasonably believed no one was inside.',
   'C', 'Pam lacked intent to kill and did not act with extreme recklessness required for depraved heart murder. However, firing a gun into a building believed empty may constitute criminal negligence, supporting involuntary manslaughter.', 'Involuntary Manslaughter — Criminal Negligence', NULL, true),
  ('crim-law-001', 'homicide', 'medium', 'Under MPC, which killing is classified as MANSLAUGHTER (not murder)?',
   'A killing committed knowingly.', 'A killing committed recklessly, without extreme indifference.', 'A killing committed recklessly under circumstances manifesting extreme indifference to life.', 'A killing committed purposely.',
   'B', 'Under MPC § 210.3, manslaughter includes killings committed recklessly WITHOUT extreme indifference. Extreme recklessness elevates to murder under § 210.2. Purposeful and knowing killings are always murder.', 'MPC Murder vs. Manslaughter Distinction', NULL, true),
  ('crim-law-001', 'theft_property', 'easy', 'At common law, larceny requires:',
   'Obtaining property by false pretenses.', 'Use of force or threat of force.', 'Breaking and entering into a building.', 'A trespassory taking and carrying away of personal property of another with intent to permanently deprive.',
   'D', 'Common law larceny = (1) trespassory taking + (2) carrying away (asportation) + (3) personal property + (4) of another + (5) intent to permanently deprive.', 'Common Law Larceny Elements', NULL, true),
  ('crim-law-001', 'theft_property', 'medium', 'Bob finds a wallet containing $500 and ID. Bob keeps the money intending to return the wallet. Bob is guilty of:',
   'Larceny — he took another''s property with intent to permanently deprive.', 'Receiving stolen property.', 'Nothing — finders keepers.', 'Embezzlement — he was entrusted with the property.',
   'A', 'One who finds lost property and keeps it — when clues to the owner''s identity exist — commits larceny by finding. Bob saw the ID, knew the owner, yet kept the money.', 'Larceny by Finding', NULL, true),
  ('crim-law-001', 'theft_property', 'hard', 'An attorney withdraws client funds from escrow for personal use, intending to return them later. The attorney is most likely guilty of:',
   'Embezzlement — fraudulent conversion of property entrusted to her.', 'Robbery — taking by threat of professional harm.', 'Nothing — she intended to return the funds.', 'Larceny — trespassory taking of client funds.',
   'A', 'Embezzlement occurs when someone lawfully entrusted with property fraudulently converts it. Unlike larceny, there is no trespassory taking at the outset. The intent to return is NOT a defense.', 'Embezzlement — Fraudulent Conversion', NULL, true),
  ('crim-law-001', 'theft_property', 'medium', 'Carl approaches Dana with a realistic toy gun and demands her purse. Dana believes the gun is real and hands it over. Carl is guilty of:',
   'Extortion — the threat was for future harm.', 'Larceny only — no actual weapon used.', 'Robbery — taking by threat putting the victim in reasonable fear.', 'Attempted robbery — no actual force.',
   'C', 'Robbery requires taking property from another''s person by force or intimidation. Whether the gun was real is irrelevant — Dana reasonably feared it was real. Reasonable fear of imminent harm satisfies the element.', 'Robbery — Reasonable Fear of Force', NULL, true),
  ('crim-law-001', 'theft_property', 'medium', 'At common law, burglary requires breaking and entering into:',
   'A locked structure with tools.', 'A dwelling house of another at nighttime with intent to commit a felony therein.', 'A building at any time with intent to commit theft.', 'Any enclosed structure with intent to commit any crime.',
   'B', 'Common law burglary = (1) breaking + (2) entering + (3) dwelling house + (4) of another + (5) at nighttime + (6) with intent to commit a felony therein.', 'Common Law Burglary — Six Elements', NULL, true),
  ('crim-law-001', 'theft_property', 'hard', 'Ed enters an open store during business hours intending to steal. He conceals merchandise and leaves without paying. Ed is guilty of:',
   'No burglary — no breaking; his entry was consensual. He is guilty of larceny.', 'Robbery — he used force to escape.', 'Attempted burglary only.', 'Burglary — he broke and entered with intent to steal.',
   'A', 'No burglary occurs because Ed did not ''break'' into the store — he entered through an open entrance. Consent negates the breaking element. He is guilty of larceny.', 'Burglary — Breaking Element / Consent Negates Breaking', NULL, true),
  ('crim-law-001', 'theft_property', 'medium', 'Frank convinces Gary to invest $50,000 by lying about the investment''s track record. Gary hands over the money. Frank is guilty of:',
   'Extortion.', 'Embezzlement — Gary entrusted Frank with funds.', 'False pretenses — title passed based on a material misrepresentation.', 'Larceny — Gary''s property was taken.',
   'C', 'False pretenses = (1) false representation of a present or past material fact (2) knowing it is false (3) intended to defraud (4) victim relies on it (5) victim passes title. Gary voluntarily passed title based on Frank''s lies.', 'False Pretenses — Title Transfer by Misrepresentation', NULL, true),
  ('crim-law-001', 'theft_property', 'easy', 'The key distinction between robbery and larceny is:',
   'Larceny requires a threat; robbery does not.', 'Robbery requires breaking and entering; larceny does not.', 'Robbery involves taking from the person or presence by force or intimidation.', 'Robbery requires nighttime; larceny does not.',
   'C', 'Robbery is larceny from the person or presence of another, accomplished by force or intimidation. The ''from the person'' and ''force/intimidation'' elements distinguish robbery from simple larceny.', 'Robbery vs. Larceny Distinction', NULL, true),
  ('crim-law-001', 'theft_property', 'hard', 'Hannah enters a building to steal a television. While inside, she steals jewelry instead. She had no intent to steal jewelry when she entered. She is guilty of:',
   'No burglary — she did not intend to steal jewelry upon entry.', 'Larceny only.', 'Burglary only if she broke in at night.', 'Burglary — she entered with intent to commit a felony (larceny of the TV).',
   'D', 'Burglary is complete at the moment of breaking and entering with intent to commit a felony therein. Hannah had felonious intent when she entered. The fact that she later stole different property is irrelevant.', 'Burglary — Intent Must Exist at Time of Entry', NULL, true),
  ('crim-law-001', 'theft_property', 'medium', 'Ivan borrows his friend''s car with permission, drives it 200 miles, and uses it for a week without permission. Ivan is most likely guilty of:',
   'Embezzlement — the car was entrusted to him.', 'No crime — he had initial permission.', 'Joyriding (unauthorized use) — he lacked intent to permanently deprive.', 'Larceny — he permanently deprived his friend of the car.',
   'C', 'Larceny requires intent to permanently deprive. Ivan intended to return the car. Joyriding/unauthorized use statutes cover this gap.', 'Larceny — Permanent Deprivation Requirement / Joyriding', NULL, true),
  ('crim-law-001', 'theft_property', 'medium', 'Arson at common law requires:',
   'Malicious burning of any structure.', 'Intentional setting fire to any property.', 'Burning one''s own property for insurance fraud.', 'Malicious burning of a dwelling house of another.',
   'D', 'Common law arson = malicious burning of a dwelling house of another. Key elements: (1) dwelling (2) belonging to another (3) malicious intent (4) actual burning.', 'Common Law Arson Elements', NULL, true),
  ('crim-law-001', 'theft_property', 'hard', 'Joe obtains goods from a merchant by promising to pay in 30 days, knowing he is insolvent. Joe is most likely guilty of:',
   'Larceny — he took property without paying.', 'Larceny by trick — he obtained possession through deception.', 'No crime — failure to pay a debt is civil.', 'False pretenses — misrepresenting his intent or ability to pay.',
   'B', 'When a victim passes only possession (not title) based on a misrepresentation, it is larceny by trick. Joe obtained possession of goods on credit; title did not transfer. This distinguishes it from false pretenses (where title passes).', 'Larceny by Trick vs. False Pretenses — Possession vs. Title', NULL, true),
  ('crim-law-001', 'theft_property', 'easy', 'Which is NOT an element of receiving stolen property?',
   'Receiving property that was stolen.', 'Receiving the property for oneself or another.', 'Knowledge that the property was stolen.', 'Intent to permanently keep the property.',
   'D', 'Receiving stolen property = (1) receiving property (2) that was stolen (3) knowing it was stolen (4) with intent to aid the thief or deprive the owner. There is NO requirement of intent to permanently keep.', 'Receiving Stolen Property Elements', NULL, true),
  ('crim-law-001', 'theft_property', 'hard', 'Kim enters her neighbor''s home through an unlocked door at 2pm to retrieve her own umbrella, believing the neighbor stole it. She is guilty of:',
   'Larceny — she took property from another''s dwelling.', 'No burglary — she had a claim of right and no breaking occurred.', 'Trespass only.', 'Burglary — she broke and entered another''s dwelling.',
   'B', 'A claim of right (good faith belief the property is one''s own) negates the mens rea for burglary. No ''breaking'' occurred (unlocked door). Also, at 2pm it is not nighttime under common law.', 'Burglary / Larceny — Claim of Right Defense', NULL, true),
  ('crim-law-001', 'theft_property', 'medium', 'Leo, a bank teller, takes $100 from the till each day and replaces it before closing. On the last day he cannot replace it. Leo is most likely guilty of:',
   'Larceny — he trespassorily took the bank''s funds.', 'Embezzlement — he fraudulently converted funds entrusted to him.', 'False pretenses.', 'Nothing — he always intended to replace the funds.',
   'B', 'Leo, as a bank teller, was entrusted with the funds. He converted them for personal use — embezzlement. The intent to return is not a defense. The fraudulent conversion is complete upon each taking.', 'Embezzlement — Intent to Return Is Not a Defense', NULL, true),
  ('crim-law-001', 'theft_property', 'medium', 'Which is the BEST definition of extortion at common law?',
   'Taking property without consent by breaking and entering.', 'Obtaining property by threatening future harm unless property is paid.', 'Taking property from another''s person by force.', 'Fraudulently obtaining property by misrepresenting facts.',
   'B', 'Extortion (blackmail) = obtaining property by threats of future harm — distinguished from robbery by: (1) threats need not be of immediate bodily harm, and (2) threats are of future action.', 'Extortion vs. Robbery — Future vs. Immediate Harm', NULL, true),
  ('crim-law-001', 'theft_property', 'hard', 'Mike enters a store, puts on a coat, and is caught at the door before leaving. He is guilty of:',
   'No crime — he was caught before he left.', 'Attempted larceny only — no asportation occurred.', 'Shoplifting only, not larceny.', 'Larceny — asportation is minimal; moving the coat inside the store suffices.',
   'D', 'Asportation requires only the slightest movement. Putting on a coat inside a store satisfies asportation. Mike had trespassory intent when he put on the coat. Larceny was complete.', 'Larceny — Asportation (Minimal Movement Suffices)', NULL, true),
  ('crim-law-001', 'theft_property', 'medium', 'The element that distinguishes robbery from larceny when a thief snatches a purse from a victim''s shoulder is:',
   'Whether the victim resisted.', 'Whether the taking was from the victim''s person or presence by force or fear.', 'The value of the purse.', 'Whether the thief used a weapon.',
   'B', 'Robbery = larceny from the person or presence of another by force or intimidation. Purse-snatching may be robbery if any force is applied to the victim''s person or the victim is placed in fear.', 'Robbery — Force Element in Purse Snatching', NULL, true),
  ('crim-law-001', 'theft_property', 'hard', 'Nancy convinces Owen to give her $1,000 claiming she will invest it. She intends to keep it from the start. Nancy is guilty of:',
   'Embezzlement — Owen entrusted her.', 'Larceny by trick — she obtained possession through deception.', 'False pretenses — she obtained title by misrepresentation.', 'Larceny — she took Owen''s money.',
   'C', 'Nancy obtained title (not just possession) to the $1,000 through misrepresentation. Owen voluntarily passed title — distinguishing it from larceny by trick (possession only).', 'False Pretenses vs. Larceny by Trick — Title vs. Possession', NULL, true),
  ('crim-law-001', 'theft_property', 'medium', 'Paul takes a car with the owner''s consent to drive around the block, then keeps it permanently. At the moment Paul decided to keep it permanently, he committed:',
   'Larceny — the intent to permanently deprive arose after lawful possession.', 'No crime — he had initial consent.', 'Embezzlement — he was entrusted with the car and converted it.', 'Auto theft — special statutes apply.',
   'C', 'When someone obtains lawful possession of property and then converts it with fraudulent intent, the offense is embezzlement. Paul was given the car lawfully; the conversion occurred after lawful possession commenced.', 'Embezzlement vs. Larceny — Lawful vs. Trespassory Possession', NULL, true),
  ('crim-law-001', 'theft_property', 'easy', 'Which element is REQUIRED for both common law larceny and embezzlement?',
   'Breach of fiduciary duty.', 'Intent to permanently deprive.', 'Use of force.', 'Trespassory taking.',
   'B', 'Both larceny and embezzlement require intent to permanently deprive the owner of property. Larceny requires a trespassory taking; embezzlement requires lawful initial possession + fraudulent conversion.', 'Larceny and Embezzlement — Common Element', NULL, true),
  ('crim-law-001', 'theft_property', 'hard', 'Quinn, a parking attendant, takes a car for a joyride and returns it undamaged three hours later. Quinn is most likely guilty of:',
   'No crime — the car was returned undamaged.', 'Joyriding (unauthorized use) — no intent to permanently deprive.', 'Embezzlement — he was entrusted with the car.', 'Larceny — he took the car without permission during the joyride.',
   'B', 'Larceny requires intent to permanently deprive. Quinn intended to return the car. Joyriding/unauthorized use statutes fill the gap between larceny and embezzlement.', 'Joyriding — Gap Between Larceny and Embezzlement', NULL, true),
  ('crim-law-001', 'theft_property', 'medium', 'Robbery is distinguished from extortion primarily because robbery involves:',
   'Immediate threats of force; extortion involves threats of future harm.', 'Taking real property; extortion involves personal property.', 'A weapon; extortion does not.', 'Threats of future harm; extortion involves present force.',
   'A', 'Robbery uses immediate force or threats of imminent bodily harm. Extortion uses threats of future harm (including non-physical harm). The immediacy of the threatened harm distinguishes them.', 'Robbery vs. Extortion — Immediate vs. Future Harm', NULL, true),
  ('crim-law-001', 'theft_property', 'hard', 'Rita breaks into a neighbor''s shed (not a dwelling) at 3am to steal tools. Under strict common law burglary, Rita is:',
   'Not guilty of burglary — a shed is not a dwelling house.', 'Guilty of burglary — she broke in at nighttime with felonious intent.', 'Guilty of larceny only.', 'Guilty of attempted burglary only.',
   'A', 'Common law burglary requires the target to be a dwelling house. A shed is not a dwelling house (a place where people sleep). Rita is guilty of larceny and trespass but not common law burglary.', 'Burglary — Dwelling House Requirement', NULL, true),
  ('crim-law-001', 'theft_property', 'medium', 'Sam, a stockbroker, misappropriates client securities worth $500,000 and invests them for himself, planning to repay if his investment succeeds. Sam is guilty of:',
   'False pretenses.', 'Embezzlement.', 'No crime until he fails to repay.', 'Larceny.',
   'B', 'Sam was entrusted with client securities as a broker (fiduciary relationship). He converted them fraudulently for his own use. Embezzlement is complete upon the fraudulent conversion — the intent to repay is NOT a defense.', 'Embezzlement — Fiduciary Relationship / Intent to Repay Not a Defense', NULL, true),
  ('crim-law-001', 'defenses', 'medium', 'Ted is charged with assault. He argues he honestly but unreasonably believed he was about to be attacked. Under common law, this belief:',
   'Provides a complete defense of self-defense.', 'Reduces the charge to a lesser offense.', 'Is irrelevant because Ted struck first.', 'Provides no defense — self-defense requires reasonable belief.',
   'D', 'Common law self-defense (majority) requires a reasonable belief of imminent harm. An honest but unreasonable belief provides NO defense at common law.', 'Self-Defense — Reasonable Belief Requirement (Common Law)', NULL, true),
  ('crim-law-001', 'defenses', 'hard', 'Under the M''Naghten insanity test, a defendant is not guilty by reason of insanity if:',
   'She did not know the nature of her act OR did not know it was wrong.', 'She had a mental disease that caused the act.', 'She lacked substantial capacity to conform her conduct to law.', 'She suffered from an irresistible impulse.',
   'A', 'M''Naghten (majority test): NGRI if, due to a mental disease, she either (1) did not know the nature and quality of the act, OR (2) did not know the act was wrong. Cognitive test only — does NOT cover irresistible impulses.', 'M''Naghten Insanity Test', 'M''Naghten''s Case (1843)', true),
  ('crim-law-001', 'defenses', 'medium', 'Under the MPC insanity test, a defendant is not criminally responsible if, as a result of mental disease or defect, she lacked substantial capacity to:',
   'Control her impulses completely.', 'Appreciate the criminality of her conduct OR conform her conduct to the requirements of law.', 'Know her act was wrong.', 'Know the nature of her act.',
   'B', 'MPC § 4.01 (ALI test): NGRI if lacking substantial capacity to (1) appreciate the criminality (cognitive prong) OR (2) conform conduct to law (volitional prong). Broader than M''Naghten — includes the volitional prong.', 'MPC Insanity Test § 4.01 (ALI Test)', NULL, true),
  ('crim-law-001', 'defenses', 'medium', 'Alice is charged with murder. She claims she was so intoxicated she didn''t know what she was doing. Voluntary intoxication is:',
   'Never a defense.', 'A defense to all crimes under MPC.', 'A defense only to specific intent crimes.', 'A complete defense to any crime requiring intent.',
   'C', 'At common law, voluntary intoxication may negate the specific intent required for specific intent crimes. It is NOT a defense to general intent crimes. Intoxication negating first-degree murder intent may still result in second-degree conviction.', 'Voluntary Intoxication — Specific Intent Crimes Only', NULL, true),
  ('crim-law-001', 'defenses', 'hard', 'Bob is charged with battery. He claims duress — his boss threatened to fire him if he didn''t beat up a customer. Duress:',
   'Is a complete defense if the threat was genuine.', 'Is a complete defense to any crime.', 'Is an affirmative defense Bob must prove beyond a reasonable doubt.', 'Does not apply — duress only excuses when the threat was of death or serious bodily harm.',
   'D', 'Duress requires: (1) an immediate threat of death or serious bodily harm + (2) well-grounded fear + (3) no reasonable opportunity to escape. A threat of job termination does not qualify.', 'Duress Defense — Requirements', NULL, true),
  ('crim-law-001', 'defenses', 'medium', 'Carol shoots an intruder in her home. At common law, which statement about the castle doctrine is TRUE?',
   'She must retreat before using deadly force even in her home.', 'The castle doctrine only applies in stand-your-ground states.', 'She has no duty to retreat when attacked in her own home.', 'She may only use deadly force if she invited the intruder in.',
   'C', 'The castle doctrine holds that a person has no duty to retreat when attacked in her own home. This is an exception to the general common law rule requiring retreat before using deadly force when retreat is safe.', 'Castle Doctrine — No Duty to Retreat at Home', NULL, true),
  ('crim-law-001', 'defenses', 'hard', 'Dan commits a crime because an undercover officer gave him the opportunity and urged him to do it. Dan had a prior predisposition to commit the crime. Dan''s best defense is:',
   'No defense — entrapment fails when the defendant was predisposed.', 'Entrapment — government induced him.', 'Duress — the officer coerced him.', 'Necessity — government action created a necessity.',
   'A', 'Under the federal/majority (subjective) entrapment test, the defense fails if the defendant was predisposed to commit the crime before government contact. Dan''s prior predisposition defeats the defense.', 'Entrapment — Predisposition Test (Majority / Subjective)', 'Jacobson v. United States (1992)', true),
  ('crim-law-001', 'defenses', 'medium', 'Eve burns her neighbor''s barn to prevent a fast-moving wildfire from destroying her town. She is charged with arson. Her best defense is:',
   'Consent.', 'Necessity.', 'Duress.', 'Defense of others.',
   'B', 'Necessity (choice of evils) justifies otherwise criminal conduct when: (1) imminent threat, (2) no other reasonable alternative, (3) harm caused less than harm avoided, and (4) defendant not at fault in creating the situation.', 'Necessity Defense — Choice of Evils', NULL, true),
  ('crim-law-001', 'defenses', 'hard', 'Frank is told by a reliable source (falsely) that the government sanctioned him to commit burglary. He commits the burglary. Frank cannot claim:',
   'Mistake of fact — he reasonably believed he had authorization.', 'Entrapment — government action induced him.', 'Mistake of law — he reasonably believed his conduct was authorized.', 'Any defense — unauthorized representations do not excuse criminal conduct.',
   'D', 'Mistake of law is generally not a defense. Even if Frank''s reliance was reasonable, unofficial authorizations do not excuse criminal conduct. Only official and authoritative reliance on a court ruling, statute, or government interpretation may provide a defense.', 'Mistake of Law — General Rule / Official Authorization Exception', NULL, true),
  ('crim-law-001', 'defenses', 'medium', 'George honestly and reasonably believed the gun he grabbed in a fight was unloaded. He fired and killed the victim. He is charged with murder. His best defense is:',
   'No defense — he should have checked.', 'Voluntary manslaughter.', 'Mistake of fact — negates the mental state for murder.', 'Insanity.',
   'C', 'Mistake of fact is a defense when the mistake negates the required mental state. If George honestly and reasonably believed the gun was unloaded, he lacked the intent to kill. A reasonable mistake of fact can negate specific or general intent.', 'Mistake of Fact Defense', NULL, true),
  ('crim-law-001', 'defenses', 'hard', 'Harry is found legally insane under M''Naghten at the time of the crime but regains sanity before trial. The court should:',
   'Dismiss the case — insanity at time of act is a complete defense.', 'Stay proceedings until Harry becomes insane again.', 'Convict Harry — only present insanity matters.', 'Try Harry — legal insanity at the time of the act does not affect competency to stand trial.',
   'D', 'There are two separate standards: (1) insanity defense (mental state at time of crime) and (2) competency to stand trial (mental state at present). Harry has regained sanity and is competent to stand trial. Both issues are resolved separately.', 'Insanity Defense vs. Competency to Stand Trial — Distinct Standards', NULL, true),
  ('crim-law-001', 'defenses', 'medium', 'Irene, a parent, disciplines her child with a belt, leaving bruises. She is charged with battery. Her best defense is:',
   'Parental privilege — reasonable parental discipline.', 'Necessity — she had to correct the child''s behavior.', 'No defense — parental privilege does not cover physical discipline.', 'Consent — parents impliedly consent on behalf of children.',
   'A', 'Most jurisdictions recognize a parental privilege to use reasonable physical discipline on a child. The question is whether the discipline crossed the line into unreasonable force (abuse).', 'Parental Privilege — Reasonable Discipline Defense', NULL, true),
  ('crim-law-001', 'defenses', 'hard', 'Jack beats Kim severely. Later, Kim kills Jack to prevent future attacks. Kim''s claim of self-defense will likely fail because:',
   'She used excessive force.', 'Self-defense requires an imminent threat — not fear of future attacks.', 'She had a duty to retreat from Jack.', 'She was the initial aggressor.',
   'B', 'Self-defense requires an imminent threat of death or serious bodily harm. Killing Jack to prevent future attacks — when he is not presently threatening her — does not satisfy the imminence requirement.', 'Self-Defense — Imminence Requirement', NULL, true),
  ('crim-law-001', 'defenses', 'medium', 'The defense of consent is MOST likely to succeed in which scenario?',
   'Victim consented to being killed.', 'Victim consented under duress.', 'Victim, a minor, consented to sexual contact.', 'Victim consented to a minor touching in a contact sport.',
   'D', 'Consent is valid when (1) the victim had capacity to consent, (2) consented voluntarily, (3) the consented-to conduct is not inherently harmful, and (4) the defendant acted within the scope of consent. Contact sport participants impliedly consent to normal physical contact.', 'Consent Defense — Scope and Limitations', NULL, true),
  ('crim-law-001', 'defenses', 'hard', 'Linda commits theft under the direction of a police officer who tells her it is part of a sting. The officer exceeded his authority. Linda argues public authority. The defense will:',
   'Fail — public authority is not a recognized defense.', 'Succeed under MPC because she had an honest belief in authorization.', 'Fail — public authority defense requires reliance on officially authorized conduct, not ultra vires acts.', 'Succeed — she reasonably relied on the officer''s instructions.',
   'C', 'The public authority defense requires that the defendant act in reasonable reliance on a properly authorized request from a government official acting within their authority. If the officer acted outside his authority (ultra vires), Linda''s reliance cannot justify the theft.', 'Public Authority Defense — Requires Authorized Official Action', NULL, true),
  ('crim-law-001', 'defenses', 'medium', 'Mark shoots and kills an intruder who had already been subdued and posed no threat. Mark claims self-defense. The defense will:',
   'Fail — the threat was no longer imminent.', 'Fail — deadly force requires a warrant.', 'Succeed — castle doctrine allows any force against intruders.', 'Succeed — intruders can always be killed.',
   'A', 'Self-defense only justifies force while the threat is imminent. Once the intruder is subdued and no longer poses an immediate threat, the right to use deadly force ends.', 'Self-Defense — Imminence Ends When Threat Ends', NULL, true),
  ('crim-law-001', 'defenses', 'hard', 'Under MPC, an honest but unreasonable belief in the need for self-defense:',
   'May reduce a murder charge to manslaughter.', 'Is treated the same as a reasonable belief.', 'Is a complete defense to any homicide charge.', 'Is no defense whatsoever.',
   'A', 'Under MPC § 3.09, if a defendant raises a justification defense but her belief was reckless or negligent, the justification fails, but she can only be convicted of a crime for which recklessness or negligence suffices as mens rea (e.g., manslaughter). An honest but unreasonable belief thus reduces murder to manslaughter under MPC.', 'MPC § 3.09 — Honest but Unreasonable Belief / Imperfect Justification', NULL, true),
  ('crim-law-001', 'defenses', 'medium', 'Nick kills his wife''s lover in heat of passion moments after discovering them together. Under MPC, Nick argues extreme mental or emotional disturbance (EMED). The EMED defense:',
   'Is not available for intentional killings.', 'Is broader than common law — considers whether the disturbance was reasonable from the actor''s viewpoint.', 'Is narrower than common law — requires objective reasonable provocation.', 'Is identical to the common law heat of passion defense.',
   'B', 'MPC § 210.3 allows murder to be reduced to manslaughter if committed under EMED for which there is reasonable explanation from the actor''s viewpoint. Unlike common law: (1) no categorical adequate provocation list, (2) no strict cooling time rule, (3) more subjective test.', 'MPC EMED Defense § 210.3 — Broader than Common Law', NULL, true),
  ('crim-law-001', 'defenses', 'medium', 'Olivia is addicted to drugs and commits theft to feed her addiction. She argues she had no choice. This argument is:',
   'A valid duress defense.', 'Not a valid defense — addiction does not excuse property crimes.', 'A valid necessity defense.', 'A valid involuntary intoxication defense.',
   'B', 'Drug addiction does not constitute a legal defense to property crimes. Necessity requires an imminent external threat (not internal compulsion). Addiction-driven compulsion is not recognized as duress or necessity for property crimes.', 'Addiction — Not a Defense to Property Crimes', NULL, true),
  ('crim-law-001', 'defenses', 'hard', 'Patricia shoots her abusive husband while he sleeps to prevent future beatings. Battered woman syndrome (BWS) evidence is admissible to:',
   'Explain why she reasonably believed she was in imminent danger even when he was asleep.', 'Negate the imminence requirement.', 'Prove insanity.', 'Automatically establish self-defense.',
   'A', 'Expert testimony on BWS is admissible to help the jury understand why Patricia reasonably believed she was in imminent danger — not to eliminate the imminence requirement. BWS contextualizes the perceived threat. The jury still must find the belief reasonable.', 'Battered Woman Syndrome — Evidentiary Purpose in Self-Defense', NULL, true),
  ('crim-law-001', 'defenses', 'medium', 'Quinn is a soldier who kills enemy combatants under orders during a lawful military operation. The applicable defense is:',
   'Necessity.', 'Superior orders (Nuremberg defense).', 'Public duty / military authority.', 'Duress.',
   'C', 'Soldiers acting under lawful orders in a lawful military operation may invoke the defense of public duty or military authority. This differs from the superior orders defense, which is largely rejected when orders require clearly illegal acts such as war crimes.', 'Public Duty Defense — Lawful Military Operations', NULL, true),
  ('crim-law-001', 'defenses', 'hard', 'Rita believes she must kill her neighbor to stop an alien invasion. She kills the neighbor. The M''Naghten test applies. Rita is:',
   'Not guilty by reason of insanity — she did not know her act was wrong.', 'Guilty of manslaughter only.', 'Not guilty — she suffered from a delusion.', 'Guilty — she knew killing was wrong, even if she believed it was necessary.',
   'A', 'Under M''Naghten, a defendant is NGRI if she didn''t know the act was wrong. Rita''s delusion may have been so severe she genuinely didn''t know the act was wrong in the relevant sense. Courts generally find that delusional beliefs making the act seem necessary satisfy M''Naghten.', 'M''Naghten — Delusional Belief / Knowing Act Was Wrong', NULL, true),
  ('crim-law-001', 'defenses', 'medium', 'Stan is charged with battery. He argues he acted in defense of his property — he punched an intruder trying to steal his car. Defense of property:',
   'Justifies any force necessary to protect property.', 'Justifies deadly force if the property is a vehicle.', 'Justifies only non-deadly force to protect property.', 'Never justifies force.',
   'C', 'At common law, a person may use reasonable (non-deadly) force to protect personal property. Deadly force is NEVER justified solely to protect property.', 'Defense of Property — Non-Deadly Force Only', NULL, true),
  ('crim-law-001', 'defenses', 'hard', 'Tom is set up by his friend to commit a drug deal. Tom had no prior drug history and was not predisposed to deal. Under the objective (minority) entrapment test, Tom:',
   'May be entrapped only if there was duress.', 'Is entrapped — the government''s conduct would have induced a law-abiding person.', 'Is not entrapped — he intended to deal drugs.', 'Is not entrapped — he completed the crime.',
   'B', 'The objective (MPC/minority) entrapment test focuses on whether law enforcement''s methods would have induced a normally law-abiding person to commit the offense — not on whether this particular defendant was predisposed.', 'Entrapment — Objective Test (MPC / Minority)', NULL, true),
  ('crim-law-001', 'defenses', 'medium', 'Uma is insane under M''Naghten but is found guilty by the jury. This verdict is:',
   'Improper — M''Naghten is the legal standard the jury must apply.', 'Proper if the jury finds the act was morally wrong.', 'Proper only if the judge instructed on a different standard.', 'Proper if the jury disagrees with the M''Naghten standard.',
   'A', 'If M''Naghten is the applicable insanity test, the jury is bound to apply it. A guilty verdict would be improper if Uma satisfied M''Naghten criteria. The jury''s disagreement with the legal standard does not entitle them to convict — this would be reversible error.', 'Insanity Defense — Jury Must Apply Legal Standard', NULL, true),
  ('crim-law-001', 'criminal_procedure', 'easy', 'Police arrest Alex without a warrant after witnessing him commit a felony. The arrest is:',
   'Unconstitutional — probable cause alone is insufficient without a warrant.', 'Constitutional — warrantless arrests for felonies committed in the officer''s presence are valid.', 'Unconstitutional — all arrests require a warrant.', 'Constitutional only if Alex was dangerous.',
   'B', 'Warrantless arrests in public are constitutional when officers have probable cause to believe a felony has been committed and witnessed it.', 'Warrantless Arrest in Public — Probable Cause Sufficient', 'United States v. Watson (1976)', true),
  ('crim-law-001', 'criminal_procedure', 'medium', 'Police stop Betty''s car after observing her run a stop sign. They smell marijuana and search the entire vehicle. The search is:',
   'Unconstitutional — car searches require a warrant.', 'Constitutional — automobile exception allows warrantless search with probable cause.', 'Unconstitutional — minor traffic violations don''t justify searches.', 'Constitutional only if Betty consented.',
   'B', 'The automobile exception allows warrantless searches of vehicles when officers have probable cause to believe the vehicle contains contraband or evidence. The smell of marijuana provides probable cause.', 'Automobile Exception — Probable Cause Required', 'Carroll v. United States (1925)', true),
  ('crim-law-001', 'criminal_procedure', 'hard', 'An officer, without a warrant, attaches a GPS device to Carl''s car and tracks his movements for 30 days. This is:',
   'Constitutional — no reasonable expectation of privacy in public movements.', 'Unconstitutional — long-term GPS tracking is a Fourth Amendment search.', 'Unconstitutional — the driveway is curtilage.', 'Constitutional — the car was used on public roads.',
   'B', 'United States v. Jones (2012): attaching a GPS device to a vehicle constitutes a Fourth Amendment search. Carpenter v. United States (2018) also recognized that long-term surveillance creates a mosaic of private information protected by the Fourth Amendment.', 'Fourth Amendment — GPS Tracking as Search', 'United States v. Jones (2012)', true),
  ('crim-law-001', 'criminal_procedure', 'medium', 'Officers search Diana''s house under a valid drug warrant. While searching, they find a gun in plain view. They seize the gun. The seizure is:',
   'Constitutional — plain view doctrine allows seizure of contraband in plain view.', 'Unconstitutional — the warrant was only for drugs.', 'Unconstitutional — plain view does not apply inside a home.', 'Constitutional only if a new warrant was obtained first.',
   'A', 'The plain view doctrine allows officers lawfully in a position to observe an item to seize it without a warrant if: (1) lawfully in position, (2) incriminating nature immediately apparent, and (3) lawful right of access.', 'Plain View Doctrine — Three-Part Test', 'Horton v. California (1990)', true),
  ('crim-law-001', 'criminal_procedure', 'hard', 'Officers obtain a warrant to search Ed''s house based on an informant tip. The informant''s basis for knowledge was not stated. Under Illinois v. Gates, the warrant is:',
   'Invalid — the Aguilar-Spinelli two-prong test requires veracity and basis of knowledge.', 'Valid if the affidavit established a ''fair probability'' under a totality of the circumstances.', 'Valid only if the informant testified before the magistrate.', 'Invalid — informant tip without corroboration can never support a warrant.',
   'B', 'Illinois v. Gates (1983) replaced the strict Aguilar-Spinelli test with a ''totality of the circumstances'' test. A warrant is valid if the affidavit establishes a ''fair probability'' that contraband or evidence will be found.', 'Probable Cause — Gates Totality of Circumstances Test', 'Illinois v. Gates (1983)', true),
  ('crim-law-001', 'criminal_procedure', 'medium', 'Frank is in custody and given Miranda warnings. He says ''maybe I should talk to a lawyer.'' Officers continue questioning and Frank confesses. The confession:',
   'Is inadmissible — the warning was inadequate.', 'Is inadmissible — any mention of a lawyer requires all questioning to cease.', 'Is admissible if Frank waived his rights afterward.', 'Is admissible — ''maybe'' is not an unequivocal invocation of counsel.',
   'D', 'Davis v. United States (1994): an ambiguous request for counsel (''maybe I should talk to a lawyer'') does not require police to stop questioning. Only a clear, unambiguous invocation of the right to counsel requires cessation.', 'Miranda — Unambiguous Invocation of Counsel Required', 'Davis v. United States (1994)', true),
  ('crim-law-001', 'criminal_procedure', 'hard', 'Police interrogate Grace without Miranda warnings. She confesses. Officers then give Miranda warnings and she confesses again. The second confession is:',
   'Inadmissible — the cat-out-of-the-bag doctrine taints the second confession.', 'Admissible — Miranda only applies to the first statement.', 'Admissible — Miranda warnings before the second confession cure the first violation.', 'Admissible only if the second confession was voluntary and the Miranda omission was not deliberate.',
   'D', 'Missouri v. Seibert (2004): a deliberate two-step interrogation strategy — withholding Miranda, getting a confession, then giving Miranda and re-interrogating — is unconstitutional. If the omission was not deliberate and the second statement was voluntary, it may be admissible.', 'Two-Step Interrogation — Seibert / Missouri v. Seibert', 'Missouri v. Seibert (2004)', true),
  ('crim-law-001', 'criminal_procedure', 'medium', 'Officers search Harry''s trash cans left at the curb for collection and find drug paraphernalia. The search is:',
   'Unconstitutional — the trash is Harry''s private property.', 'Constitutional only if Harry had a criminal record.', 'Unconstitutional — a warrant is required to search containers.', 'Constitutional — trash left for collection lacks a reasonable expectation of privacy.',
   'D', 'California v. Greenwood (1988): there is no reasonable expectation of privacy in trash left for collection at the curb.', 'Fourth Amendment — No REP in Trash at Curb', 'California v. Greenwood (1988)', true),
  ('crim-law-001', 'criminal_procedure', 'hard', 'Police stop Ian on the street to ask questions. Ian is not under arrest. In a state with a stop-and-identify statute, Ian must:',
   'Submit to a pat-down if asked.', 'Remain at the location until released.', 'Answer all police questions — refusal is suspicious.', 'Provide his name if the state has a stop-and-identify statute.',
   'D', 'Hiibel v. Nevada (2004): stop-and-identify statutes requiring a suspect to identify themselves during a Terry stop are constitutional. Absent such a statute, there is no general obligation to answer police questions.', 'Stop-and-Identify — Hiibel / Fifth Amendment', 'Hiibel v. Nevada (2004)', true),
  ('crim-law-001', 'criminal_procedure', 'medium', 'Officer Jones stops Julia based on an anonymous tip that she matches the description of a drug courier. Jones pats her down and finds drugs. The stop was:',
   'Invalid if the tip lacked sufficient indicia of reliability to constitute reasonable suspicion.', 'Valid — anonymous tips always justify stops.', 'Valid — the matching description provided reasonable suspicion.', 'Invalid — only probable cause can justify a stop.',
   'A', 'Florida v. J.L. (2000): an anonymous tip that a person is carrying a gun does not, without more, justify a Terry stop and frisk. The tip must be sufficiently reliable to create reasonable suspicion.', 'Terry Stop — Anonymous Tips Require Corroboration', 'Florida v. J.L. (2000)', true),
  ('crim-law-001', 'criminal_procedure', 'medium', 'Officers arrest Ken with probable cause. They search his car incident to arrest. Ken was secured in the patrol car before the search. Under Arizona v. Gant, the search is:',
   'Constitutional if officers had any reasonable belief.', 'Constitutional — search incident to arrest always allows a car search.', 'Unconstitutional if Ken is secured and officers had no reasonable belief the car contained evidence of the arrest offense.', 'Constitutional — the car was in the officer''s control.',
   'C', 'Arizona v. Gant (2009): police may search a vehicle incident to arrest only if the arrestee is unsecured and within reaching distance, OR if it is reasonable to believe the vehicle contains evidence of the offense of arrest. Ken is secured — SILA does not automatically apply.', 'Search Incident to Arrest — Arizona v. Gant Rule', 'Arizona v. Gant (2009)', true),
  ('crim-law-001', 'criminal_procedure', 'hard', 'Lena moves to suppress evidence found during an illegal search. The government argues the ''good faith'' exception. This exception has been extended to:',
   'Officers who acted in good faith reliance on a statute later held unconstitutional only.', 'Both A and B — good faith has been applied in multiple contexts including warrants and statutes.', 'Officers who had probable cause regardless of the warrant.', 'Officers who acted in good faith under a facially valid warrant only.',
   'B', 'The good faith exception (Leon) was originally limited to reasonable reliance on a facially valid warrant. It has been extended to: reliance on a statute later found unconstitutional (Illinois v. Krull), court records (Arizona v. Evans), and clerical errors in police databases (Herring v. United States).', 'Good Faith Exception — Multiple Contexts (Leon and Beyond)', 'United States v. Leon (1984)', true),
  ('crim-law-001', 'criminal_procedure', 'medium', 'Officers have a valid warrant to search Mia''s house for guns. While executing it, they find a locked safe. They can search the safe:',
   'Never — locked containers require separate warrants.', 'Only if Mia consents to opening it.', 'Only if they obtain a separate warrant.', 'If the warrant authorizes the search for guns and the safe is a place where guns could reasonably be found.',
   'D', 'A search warrant authorizes officers to search anywhere within the described premises where the items sought might be found. If the warrant is for guns, officers may search any area — including a safe — where guns could reasonably be found.', 'Scope of Search Warrant — Anywhere Evidence Could Be Found', NULL, true),
  ('crim-law-001', 'criminal_procedure', 'hard', 'Ned confesses to police. Later, it is discovered the confession resulted from a false promise of leniency. The confession is:',
   'Possibly inadmissible if the promise of leniency rendered the confession involuntary.', 'Admissible if Ned is intelligent and educated.', 'Admissible — Miranda was given.', 'Inadmissible — any inducement makes a confession involuntary per se.',
   'A', 'A confession must be voluntary under the totality of circumstances. A false promise of leniency can render a confession involuntary and inadmissible under the Due Process Clause.', 'Due Process — Involuntary Confessions / Police Promises of Leniency', 'Colorado v. Connelly (1986)', true),
  ('crim-law-001', 'criminal_procedure', 'medium', 'During a lawful traffic stop, an officer asks Olivia if he can search the car. Olivia says yes. A warrant was not obtained. The search is:',
   'Constitutional — consent is a recognized exception to the warrant requirement.', 'Constitutional only if Olivia was advised of her right to refuse.', 'Unconstitutional — consent during a traffic stop is inherently coerced.', 'Unconstitutional — cars require probable cause regardless of consent.',
   'A', 'Consent is a well-established exception to the Fourth Amendment warrant requirement. Officers are NOT required to advise suspects of their right to refuse (Schneckloth v. Bustamonte).', 'Consent Search — Voluntary Consent / No Right-to-Refuse Warning Required', 'Schneckloth v. Bustamonte (1973)', true),
  ('crim-law-001', 'criminal_procedure', 'hard', 'At Pete''s criminal trial, a key prosecution witness refuses to testify. The prosecutor seeks to admit the witness''s prior recorded testimony from Pete''s preliminary hearing where Pete''s attorney cross-examined. The admission is:',
   'Unconstitutional — preliminary hearings don''t count as prior testimony.', 'Unconstitutional — Pete has the right to confront witnesses at trial.', 'Constitutional only if the witness is dead.', 'Constitutional — Pete had a prior opportunity for cross-examination.',
   'D', 'The Confrontation Clause bars admission of testimonial statements unless the declarant is unavailable AND the defendant had a prior opportunity to cross-examine. Both requirements are satisfied here.', 'Confrontation Clause — Prior Opportunity to Cross-Examine', 'Crawford v. Washington (2004)', true),
  ('crim-law-001', 'criminal_procedure', 'medium', 'Police arrest Quinn without probable cause. At the station, officers discover an outstanding warrant for Quinn. Evidence found during booking is:',
   'Inadmissible — the exclusionary rule applies to all evidence after an illegal arrest.', 'Inadmissible — the initial arrest without probable cause taints everything.', 'Admissible only for the outstanding warrant charges.', 'Admissible — the outstanding warrant constitutes an intervening circumstance.',
   'D', 'Utah v. Strieff (2016): an outstanding arrest warrant constitutes an intervening circumstance that can break the causal chain between an unconstitutional stop and subsequently discovered evidence under the attenuation doctrine.', 'Attenuation Doctrine — Outstanding Warrant / Utah v. Strieff', 'Utah v. Strieff (2016)', true),
  ('crim-law-001', 'criminal_procedure', 'medium', 'The prosecution fails to disclose exculpatory evidence it possessed. This violates:',
   'The Sixth Amendment right to counsel.', 'Brady v. Maryland — due process requires disclosure of material exculpatory evidence.', 'The Fifth Amendment only if the defendant was not read Miranda rights.', 'The Eighth Amendment''s proportionality requirement.',
   'B', 'Brady v. Maryland (1963): prosecution''s suppression of material exculpatory evidence violates due process. Evidence is ''material'' if there is a reasonable probability that its disclosure would have produced a different result.', 'Brady Violation — Prosecutorial Duty to Disclose Exculpatory Evidence', 'Brady v. Maryland (1963)', true),
  ('crim-law-001', 'criminal_procedure', 'hard', 'Sam is placed in a police lineup after formal charges were filed. His attorney was not present. Sam is identified. The identification is:',
   'Constitutional — the Sixth Amendment right to counsel only attaches at critical stages after indictment.', 'Constitutional — no right to counsel at lineups.', 'Unconstitutional — lineups are always critical stages requiring counsel.', 'Unconstitutional — a post-indictment lineup without counsel present violates the Sixth Amendment.',
   'D', 'The Sixth Amendment right to counsel attaches at critical stages of prosecution once adversarial proceedings have formally begun. A post-indictment lineup is a critical stage requiring the right to counsel (United States v. Wade).', 'Right to Counsel — Critical Stages / Post-Indictment Lineups', 'United States v. Wade (1967)', true),
  ('crim-law-001', 'criminal_procedure', 'medium', 'At Tara''s double jeopardy hearing, the prosecution argues jeopardy had not attached. In a jury trial, jeopardy attaches when:',
   'The defendant is indicted.', 'The jury is sworn in.', 'The jury is sent to deliberate.', 'The first witness is called to testify.',
   'B', 'In jury trials, jeopardy attaches when the jury is sworn in. In bench trials, jeopardy attaches when the first witness is sworn. Understanding when jeopardy attaches is fundamental to double jeopardy analysis.', 'Double Jeopardy — Jeopardy Attaches When Jury Is Sworn', NULL, true),
  ('crim-law-001', 'criminal_procedure', 'hard', 'Police stop Uma on the street to ask questions. She tries to walk away. Officers grab her arm. This is:',
   'Constitutional because Uma was suspicious.', 'A valid Terry stop — reasonable suspicion justifies brief detention.', 'Always unconstitutional — people may refuse police encounters.', 'An unlawful seizure unless officers had reasonable suspicion.',
   'D', 'A Terry stop requires reasonable, articulable suspicion. Grabbing Uma''s arm is a seizure — it communicates she is not free to leave. Without reasonable suspicion, the stop is unconstitutional.', 'Terry Stop — Reasonable Suspicion Required for Seizure', 'Terry v. Ohio (1968)', true),
  ('crim-law-001', 'criminal_procedure', 'medium', 'Evidence is obtained from Victor''s house through an illegal search. Victor''s girlfriend also lived there. The girlfriend may suppress the evidence:',
   'Automatically — any illegal search yields suppressible evidence for all defendants.', 'Only if she was present during the search.', 'Only if she demonstrates her own reasonable expectation of privacy was violated.', 'If she paid rent at the house.',
   'C', 'Fourth Amendment rights are personal. A defendant can only challenge a search that violated her own constitutional rights (Rakas v. Illinois). Victor''s violation alone does not automatically give her standing.', 'Fourth Amendment — Personal Rights / Standing (Rakas v. Illinois)', 'Rakas v. Illinois (1978)', true),
  ('crim-law-001', 'criminal_procedure', 'hard', 'Wendy is questioned by a government-contracted social worker investigating child abuse. No Miranda warnings are given. Wendy''s statements are:',
   'Admissible only if Wendy signed a waiver.', 'Inadmissible — any government questioning requires Miranda.', 'Admissible — Miranda only applies to police custody and interrogation, not government contractors in non-custodial settings.', 'Inadmissible — government contractors must give Miranda warnings.',
   'C', 'Miranda applies to custodial interrogations by law enforcement. A social worker investigating child abuse is generally not required to give Miranda warnings unless the investigation crosses into criminal investigation with custodial interrogation by those functioning as law enforcement.', 'Miranda — Applies to Law Enforcement Custody and Interrogation Only', NULL, true),
  ('crim-law-001', 'criminal_procedure', 'medium', 'Xavier invokes his Fifth Amendment right not to testify at trial. The prosecutor comments to the jury that Xavier''s silence speaks volumes. This is:',
   'Permissible only if Xavier testified at a prior proceeding.', 'Permissible — the jury may draw adverse inferences from silence.', 'Impermissible — the Fifth Amendment prohibits adverse comment on the defendant''s failure to testify.', 'Permissible if Xavier is guilty.',
   'C', 'Griffin v. California (1965): prosecutorial comment on the defendant''s failure to testify violates the Fifth Amendment privilege against self-incrimination. The jury may not draw adverse inferences from a defendant''s silence.', 'Fifth Amendment — No Adverse Comment on Defendant''s Silence at Trial', 'Griffin v. California (1965)', true),
  ('crim-law-001', 'criminal_procedure', 'hard', 'Yolanda is arrested for DUI. An officer orders her to take a blood test without a warrant. She refuses. Under Missouri v. McNeely, can the officer draw blood without a warrant?',
   'No — warrantless blood draws generally require a warrant; natural dissipation alone is not automatically exigent.', 'Yes — the natural dissipation of blood alcohol constitutes exigent circumstances.', 'Yes — DUI is a serious offense that always justifies warrantless blood draws.', 'Yes — consent to drive implies consent to testing.',
   'A', 'Missouri v. McNeely (2013): the natural dissipation of blood alcohol does not automatically create exigent circumstances. Exigency is determined case-by-case. If officers can obtain a warrant without unreasonably delaying the investigation, they must do so.', 'Warrantless Blood Draw — McNeely / Case-by-Case Exigency', 'Missouri v. McNeely (2013)', true),
  ('crim-law-001', 'fifth_sixth_amendment', 'easy', 'Miranda warnings must be given before police may interrogate a suspect who is:',
   'Questioned in a public place.', 'Questioned by a private detective.', 'In custody and subject to interrogation.', 'Not yet arrested but suspected of a crime.',
   'C', 'Miranda warnings are required when a suspect is (1) in custody (formal arrest or restraint on freedom of movement equivalent to arrest) AND (2) subject to interrogation. Both elements must be present.', 'Miranda — Custody + Interrogation Both Required', 'Miranda v. Arizona (1966)', true),
  ('crim-law-001', 'fifth_sixth_amendment', 'medium', 'Andy is arrested. He invokes his right to counsel under Miranda. Police return 3 days later, re-Mirandize him, and he confesses without counsel. The confession is:',
   'Admissible if 3 days is a sufficient break.', 'Admissible if he waived his rights this time.', 'Admissible — he was re-Mirandized.', 'Inadmissible — once counsel is invoked, questioning must stop unless counsel is present.',
   'D', 'Edwards v. Arizona: once a suspect invokes the right to counsel under Miranda, all interrogation must cease until counsel is provided or the suspect reinitiates communication. Maryland v. Shatzer (2010) allows re-interrogation after 14+ days of release from custody — a 3-day break in the same custody does not qualify.', 'Edwards Rule — Right to Counsel Invocation / 14-Day Break Rule', 'Edwards v. Arizona (1981); Maryland v. Shatzer (2010)', true),
  ('crim-law-001', 'fifth_sixth_amendment', 'hard', 'Beth is in custody but not Mirandized. An officer asks ''Do you have any weapons on you?'' for officer safety. Beth says ''Yes, a knife.'' This admission:',
   'Is admissible only if Beth waived Miranda.', 'Is inadmissible — Miranda was required before any questioning.', 'Is admissible under the public safety exception to Miranda.', 'Is inadmissible — the weapon was already found.',
   'C', 'New York v. Quarles (1984): a ''public safety'' exception to Miranda allows officers to ask questions necessary to secure their immediate safety without first administering Miranda warnings.', 'Miranda — Public Safety Exception (Quarles)', 'New York v. Quarles (1984)', true),
  ('crim-law-001', 'fifth_sixth_amendment', 'medium', 'Carol is not in custody but is questioned by police about a crime. She makes incriminating statements. Later, she is arrested and tries to suppress the statements. They are:',
   'Admissible only if she was advised of her rights.', 'Inadmissible because the questioning was coercive.', 'Admissible — Miranda does not apply without custody.', 'Inadmissible — any police questioning requires Miranda.',
   'C', 'Miranda only applies to custodial interrogations. Carol was not in custody during questioning, so Miranda warnings were not required. Non-custodial statements are admissible regardless of whether warnings were given.', 'Miranda — Non-Custodial Questioning Does Not Require Warnings', NULL, true),
  ('crim-law-001', 'fifth_sixth_amendment', 'hard', 'Dan''s attorney fails to investigate alibi witnesses. Dan is convicted. For a successful ineffective assistance of counsel claim, Dan must show:',
   'Counsel''s performance was deficient AND a reasonable probability the outcome would have been different.', 'Only that counsel''s performance fell below an objective standard of reasonableness.', 'Counsel failed to object to any evidence.', 'The state failed to provide funds for a proper defense.',
   'A', 'Strickland v. Washington (1984): two-prong test — (1) Deficiency — counsel''s performance fell below an objective standard of reasonableness; AND (2) Prejudice — a reasonable probability that but for counsel''s deficient performance, the result would have been different. Both prongs must be satisfied.', 'Ineffective Assistance of Counsel — Strickland Two-Prong Test', 'Strickland v. Washington (1984)', true),
  ('crim-law-001', 'fifth_sixth_amendment', 'medium', 'Eve is charged with a misdemeanor carrying a potential 6-month sentence. She claims a Sixth Amendment right to a jury trial. Under the Sixth Amendment:',
   'She has no Sixth Amendment right to a jury trial — it applies only to ''serious'' offenses (more than 6 months).', 'She has a right to a jury trial if she could receive more than 30 days.', 'She has a right to a jury trial if authorized by state law.', 'She has an absolute right to a jury trial for all criminal charges.',
   'A', 'The Sixth Amendment jury trial right applies only to ''serious'' offenses — potential punishment exceeding 6 months of imprisonment. A potential sentence of 6 months or less = petty offense, no Sixth Amendment jury trial right (Baldwin v. New York).', 'Sixth Amendment Jury Trial Right — Serious Offenses Over 6 Months', 'Baldwin v. New York (1970)', true),
  ('crim-law-001', 'fifth_sixth_amendment', 'hard', 'After Frank''s indictment, an informant placed in his jail cell befriends him and elicits incriminating statements. The statements are:',
   'Admissible — Frank waived his right to counsel by talking to the informant.', 'Inadmissible under Miranda — any questioning after arrest requires warnings.', 'Admissible — informants are not agents of the government.', 'Inadmissible — the government deliberately elicited statements after indictment without counsel.',
   'D', 'Massiah v. United States (1964) and United States v. Henry (1980): once formal proceedings have begun, the government may not use undercover agents or informants to deliberately elicit incriminating statements from a defendant in the absence of counsel.', 'Sixth Amendment — Massiah Doctrine / Informant Elicitation After Indictment', 'Massiah v. United States (1964)', true),
  ('crim-law-001', 'fifth_sixth_amendment', 'medium', 'Grace is before a grand jury. She invokes her Fifth Amendment right not to testify. The prosecutor grants her use immunity and orders her to testify. Now she:',
   'May still refuse — use immunity is insufficient.', 'Must testify only if she also receives transactional immunity.', 'May refuse if she believes she will be prosecuted despite immunity.', 'Must testify — use immunity removes the Fifth Amendment protection.',
   'D', 'The Fifth Amendment privilege can be removed by granting immunity. Use immunity bars the government from using the witness''s testimony or its fruits against her. Once use immunity is granted, the Fifth Amendment no longer protects from testifying.', 'Fifth Amendment — Use Immunity Compels Testimony', 'Kastigar v. United States (1972)', true),
  ('crim-law-001', 'fifth_sixth_amendment', 'hard', 'During interrogation, Harry invokes his right to remain silent. Officers wait 30 minutes, re-Mirandize him, and he confesses. The confession is:',
   'Admissible — police scrupulously honored the right by waiting and then re-Mirandizing.', 'Admissible only if 24 hours passed.', 'Inadmissible — Miranda must be re-invoked by the suspect.', 'Inadmissible — invoking silence permanently bars further questioning.',
   'A', 'Michigan v. Mosley (1975): police must ''scrupulously honor'' the invocation of the right to remain silent — cease questioning, wait a significant time, re-administer Miranda, then question. A 30-minute wait with re-Mirandizing generally satisfies this standard.', 'Right to Remain Silent — Must Be Scrupulously Honored (Mosley)', 'Michigan v. Mosley (1975)', true),
  ('crim-law-001', 'fifth_sixth_amendment', 'medium', 'Irene is convicted. She appeals, arguing double jeopardy bars retrial after a mistrial declared due to jury deadlock (manifest necessity). Double jeopardy:',
   'Bars retrial — the first trial counts as jeopardy.', 'Does not bar retrial — manifest necessity is an exception.', 'Bars retrial because the mistrial was over Irene''s objection.', 'Does not bar retrial only if she was acquitted.',
   'B', 'Double jeopardy does not bar retrial after a mistrial declared for ''manifest necessity.'' A hung jury constitutes manifest necessity. Only mistrials declared without manifest necessity and over the defendant''s objection may bar retrial.', 'Double Jeopardy — Manifest Necessity Exception for Mistrials', 'Arizona v. Washington (1978)', true),
  ('crim-law-001', 'fifth_sixth_amendment', 'hard', 'Jack is tried in state court and acquitted of robbery. He is then charged in federal court for violation of a federal bank robbery statute based on the same act. This is:',
   'Permitted only if the federal offense has different elements.', 'Barred by double jeopardy — the same act cannot be prosecuted twice.', 'Permitted — the Dual Sovereignty doctrine allows separate federal and state prosecutions.', 'Barred — the acquittal in state court bars all subsequent prosecutions.',
   'C', 'The Dual Sovereignty doctrine holds that separate sovereigns may each prosecute a defendant for the same underlying conduct without violating double jeopardy. Each sovereign''s laws are separate offenses.', 'Double Jeopardy — Dual Sovereignty Doctrine', 'Abbate v. United States (1959)', true),
  ('crim-law-001', 'fifth_sixth_amendment', 'medium', 'Karen is in custody. After 2 hours of silence, she answers a question. She later claims her silence was an invocation. Under Berghuis v. Thompkins:',
   'Invocation of the right to remain silent must be unambiguous — silence alone is not an invocation.', 'Her silence was an invocation — questioning should have stopped.', 'The 2-hour silence was an implied waiver of Miranda rights.', 'Her later answer was coerced.',
   'A', 'Berghuis v. Thompkins (2010): a defendant''s silence during interrogation does not invoke the Fifth Amendment right to remain silent. Invocation must be unambiguous and unequivocal.', 'Miranda — Invocation of Silence Must Be Unambiguous (Berghuis)', 'Berghuis v. Thompkins (2010)', true),
  ('crim-law-001', 'fifth_sixth_amendment', 'hard', 'The Sixth Amendment right to counsel attaches at:',
   'When the suspect becomes a focus of investigation.', 'The moment of arrest.', 'The initiation of formal adversarial proceedings (indictment, information, arraignment, or preliminary hearing).', 'When the first interrogation occurs.',
   'C', 'The Sixth Amendment right to counsel attaches at the initiation of formal adversarial judicial proceedings. This is distinct from the Fifth Amendment/Miranda right to counsel, which is based on custody and interrogation. The Sixth Amendment right is offense-specific.', 'Sixth Amendment Right to Counsel — Attachment at Formal Proceedings', 'Brewer v. Williams (1977)', true),
  ('crim-law-001', 'fifth_sixth_amendment', 'medium', 'Mia waives her Miranda rights and speaks to police. During questioning she says ''I think I need a lawyer.'' Officers continue and she confesses. The confession is:',
   'Inadmissible because she had already waived her rights.', 'Admissible if officers re-Mirandized her.', 'Inadmissible — any mention of a lawyer requires cessation of questioning.', 'Admissible — ''I think I need a lawyer'' is ambiguous.',
   'D', 'Davis v. United States (1994): an ambiguous statement about wanting a lawyer (''I think I need a lawyer'') does not trigger the Edwards rule. Only a clear and unambiguous invocation of the right to counsel requires police to stop questioning.', 'Miranda — Ambiguous Request for Counsel / Davis v. United States', 'Davis v. United States (1994)', true),
  ('crim-law-001', 'fifth_sixth_amendment', 'hard', 'Nick pleads guilty without an attorney, not knowing the consequences. Later he seeks to withdraw the plea. The plea is:',
   'Valid — guilty pleas are always final.', 'Invalid only if Nick was actually innocent.', 'Invalid if Nick did not knowingly and voluntarily waive his right to counsel.', 'Valid — defendants may waive counsel.',
   'C', 'A guilty plea must be knowing, voluntary, and intelligent (Brady v. United States). A defendant may waive the right to counsel only if the waiver was made knowingly and intelligently — the court must ensure the defendant understands the nature and consequences.', 'Guilty Plea — Knowing, Voluntary, and Intelligent / Waiver of Counsel', 'Brady v. United States (1970)', true),
  ('crim-law-001', 'fifth_sixth_amendment', 'medium', 'Olivia is indicted. She requests counsel but cannot afford one. The state must:',
   'Appoint counsel in any criminal prosecution where she faces the possibility of incarceration.', 'Appoint counsel only for felony charges.', 'Appoint counsel only if she faces incarceration of more than one year.', 'Appoint counsel at the state''s discretion.',
   'A', 'Gideon v. Wainwright (1963) established the right to appointed counsel for indigent defendants in felony cases. Argersinger v. Hamlin (1972) extended this to any offense where the defendant is actually sentenced to imprisonment.', 'Right to Appointed Counsel — Gideon / Argersinger', 'Gideon v. Wainwright (1963); Argersinger v. Hamlin (1972)', true),
  ('crim-law-001', 'fifth_sixth_amendment', 'hard', 'Pete is in custody and invokes his right to counsel regarding Crime A. Police stop questioning about Crime A but then question Pete about unrelated Crime B. This is:',
   'Permissible — the invocation as to Crime A does not extend to Crime B.', 'Impermissible — once invoked, counsel must be present for all future questioning.', 'Permissible if police believed Pete had information about Crime B.', 'Impermissible — any invocation of counsel under Miranda bars all further questioning about any crime.',
   'D', 'The Sixth Amendment right to counsel is offense-specific. However, the Fifth Amendment/Miranda right to counsel, once invoked, is NOT offense-specific. Arizona v. Roberson (1988): once a suspect invokes the right to counsel under Miranda, police must stop all interrogation — about any offense — until counsel is provided.', 'Miranda Right to Counsel — Not Offense-Specific (Roberson)', 'Arizona v. Roberson (1988)', true),
  ('crim-law-001', 'fifth_sixth_amendment', 'medium', 'A defendant discovers after conviction that the prosecution had offered a favorable plea to her attorney, who never told her. She has a claim for:',
   'Ineffective assistance of counsel — counsel failed to communicate a plea offer.', 'Brady violation.', 'Prosecutorial misconduct.', 'No claim — plea deals are not constitutionally required.',
   'A', 'Missouri v. Frye (2012): the Sixth Amendment right to effective assistance of counsel extends to the plea bargaining process. An attorney has a duty to communicate formal plea offers from the prosecution to the defendant.', 'Ineffective Assistance — Duty to Communicate Plea Offers (Missouri v. Frye)', 'Missouri v. Frye (2012)', true),
  ('crim-law-001', 'fifth_sixth_amendment', 'hard', 'Rita invokes her Sixth Amendment right to self-representation. The judge should allow her to represent herself only if:',
   'She knowingly and voluntarily waives the right to counsel after being advised of the risks.', 'She is an attorney.', 'The charges are minor.', 'She demonstrates legal competence.',
   'A', 'Faretta v. California (1975): defendants have a Sixth Amendment right to self-representation. The right must be invoked knowingly, voluntarily, and intelligently. The trial court must advise the defendant of the dangers and disadvantages. No legal skills test is required.', 'Right to Self-Representation — Faretta / Knowing Waiver of Counsel', 'Faretta v. California (1975)', true),
  ('crim-law-001', 'fifth_sixth_amendment', 'medium', 'Sam is compelled to provide a handwriting exemplar to investigators. He claims this violates his Fifth Amendment privilege. The exemplar is:',
   'Protected only if the exemplar will be used at trial.', 'Not protected — handwriting exemplars are non-testimonial physical evidence.', 'Protected — Sam was compelled to produce it.', 'Protected — providing a handwriting sample is testimonial.',
   'B', 'The Fifth Amendment protects against compelled testimonial self-incrimination. Physical evidence (blood, voice samples, handwriting exemplars, sobriety tests) is non-testimonial — it does not communicate a belief. Compelling physical evidence does not violate the Fifth Amendment.', 'Fifth Amendment — Non-Testimonial Evidence Not Protected', 'Schmerber v. California (1966)', true),
  ('crim-law-001', 'fifth_sixth_amendment', 'hard', 'Tina''s attorney learns after the verdict of exculpatory evidence the prosecutor withheld. Brady material is evidence that is:',
   'Any evidence the prosecution knows about.', 'Favorable to the defense and material — reasonable probability of different result if disclosed.', 'Only evidence that directly proves innocence.', 'Evidence the defense specifically requested.',
   'B', 'Brady material is (1) favorable to the accused (exculpatory or impeachment), (2) suppressed by the prosecution (willfully or inadvertently), and (3) material — reasonable probability that disclosure would have produced a different result. Failure to request does not excuse nondisclosure.', 'Brady Material — Three Requirements / Materiality Standard', 'Brady v. Maryland (1963); United States v. Agurs (1976)', true),
  ('crim-law-001', 'fifth_sixth_amendment', 'medium', 'During custodial interrogation, police tell Uma: ''It will go easier for you if you confess.'' Uma confesses. The confession is:',
   'Inadmissible — any inducement makes a confession involuntary per se.', 'Admissible — the statement was merely encouraging.', 'Admissible — psychological pressure is permitted in interrogations.', 'Possibly inadmissible if the promise of leniency rendered the confession involuntary.',
   'D', 'A confession must be voluntary under the totality of circumstances. A false promise of leniency can render a confession involuntary and inadmissible under the Due Process Clause.', 'Voluntariness of Confessions — Police Promises of Leniency', NULL, true),
  ('crim-law-001', 'fifth_sixth_amendment', 'hard', 'A co-defendant''s confession implicating Victor is admitted at their joint trial. Victor''s attorney cannot cross-examine the co-defendant (who invoked the Fifth). Under Bruton v. United States:',
   'The admission violates Victor''s Confrontation Clause rights — a limiting instruction is insufficient.', 'The admission is proper because co-defendants are not ''witnesses against'' each other.', 'The admission is proper if Victor''s guilt was independently proven.', 'The admission is proper if the jury is instructed to consider the confession only against the co-defendant.',
   'A', 'Bruton v. United States (1968): admitting a non-testifying co-defendant''s confession that directly implicates the defendant violates the Confrontation Clause, even with a limiting instruction. The remedy is to sever the trials, redact the confession, or try them separately.', 'Confrontation Clause — Bruton Problem / Co-Defendant Confessions at Joint Trial', 'Bruton v. United States (1968)', true),
  ('crim-law-001', 'fifth_sixth_amendment', 'medium', 'A defendant charged with a federal felony has a right to be indicted by a grand jury. Which statement is correct?',
   'The grand jury indictment requirement applies only to federal prosecutions; states may use other methods.', 'Grand jury proceedings are open to the public under the Sixth Amendment.', 'The grand jury indictment requirement has been incorporated against the states.', 'Grand jury indictment is required for all felonies in all jurisdictions.',
   'A', 'The Fifth Amendment grand jury indictment requirement is one of the few Bill of Rights provisions NOT incorporated against the states (Hurtado v. California, 1884). States may use grand juries, preliminary hearings, or other methods to bring felony charges.', 'Grand Jury Indictment — Fifth Amendment / Not Incorporated Against States', 'Hurtado v. California (1884)', true),
  ('crim-law-001', 'fifth_sixth_amendment', 'hard', 'Walt is on trial for murder. The prosecution introduces a lab report prepared by a forensic analyst who does not testify. The analyst is unavailable. Walt argues a Confrontation Clause violation. Under Melendez-Diaz v. Massachusetts, the report is:',
   'Admissible if the supervising analyst testifies instead.', 'Admissible — scientific documents are non-testimonial.', 'Inadmissible — forensic lab reports are testimonial; Walt had no opportunity to cross-examine.', 'Admissible — lab reports are business records not subject to the Confrontation Clause.',
   'C', 'In Melendez-Diaz v. Massachusetts (2009), the Supreme Court held that forensic lab reports prepared for use at trial are testimonial under Crawford v. Washington. Introducing a lab report without the analyst''s testimony violates the Confrontation Clause. The prosecution must call the analyst or establish an exception. The fact that lab reports may also serve a business function does not make them non-testimonial when prepared for use at trial.', 'Confrontation Clause — Forensic Lab Reports Are Testimonial (Melendez-Diaz)', 'Melendez-Diaz v. Massachusetts (2009)', true)
) AS v(subject_id, category, difficulty, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, rule_tested, case_citation, is_active)
WHERE NOT EXISTS (SELECT 1 FROM quiz_questions q
                  WHERE q.subject_id = v.subject_id AND q.stem = v.stem);

COMMIT;
-- ══ from 20260717000003_seed_con_law_questions.sql ══
-- B-02 Constitutional Law Question Bank Seed
-- 125 MBE questions: fourth_amendment / due_process / equal_protection / first_amendment / incorporation_14th

BEGIN;

INSERT INTO quiz_questions
  (subject_id, category, difficulty, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, rule_tested, case_citation, is_active)
SELECT v.* FROM (VALUES
('con-law-001', 'fourth_amendment', 'easy', 'The Fourth Amendment''s protection against unreasonable searches and seizures is triggered when the government violates a person''s:',
   'Property rights in any tangible item.', 'Right to be free from any government surveillance.', 'Absolute right to privacy in any location.', 'Reasonable expectation of privacy (REP) — both subjective and objective.',
   'D', 'Katz v. United States (1967) established the two-part REP test: (1) the individual must have a subjective expectation of privacy, and (2) society must recognize that expectation as reasonable. This replaced the prior property-based trespass test for most Fourth Amendment analysis.', 'Fourth Amendment — Katz REP Test', 'Katz v. United States (1967)', true),
  ('con-law-001', 'fourth_amendment', 'medium', 'Police fly a helicopter at 400 feet over Alex''s backyard and observe marijuana plants inside his fenced enclosure. Alex had no roof. This observation is:',
   'Unconstitutional — the helicopter was too low.', 'Constitutional only if police had a warrant.', 'Constitutional — there is no REP in areas visible from navigable public airspace.', 'An unconstitutional search — the backyard is curtilage.',
   'C', 'Florida v. Riley (1989): aerial observations from navigable public airspace — even from a helicopter at 400 feet — do not constitute a search because there is no reasonable expectation of privacy in what is visible from that vantage point. The Fourth Amendment is not violated by observations from public navigable airspace.', 'Fourth Amendment — Aerial Observation / Navigable Airspace', 'Florida v. Riley (1989)', true),
  ('con-law-001', 'fourth_amendment', 'hard', 'Police use a thermal imaging device from the street to detect heat patterns inside Bob''s home, revealing a marijuana growing operation. Bob had not consented. The thermal scan is:',
   'Not a search — no physical intrusion occurred.', 'Not a search — heat radiates outside the home voluntarily.', 'A Fourth Amendment search — technology not in general public use was used to explore the home''s interior.', 'A search only if the device was pointed directly at the home.',
   'C', 'Kyllo v. United States (2001): using sense-enhancing technology not in general public use to obtain information about the interior of a home constitutes a search under the Fourth Amendment. The Court emphasized that the home receives the highest Fourth Amendment protection. Police must obtain a warrant to use such technology.', 'Fourth Amendment — Thermal Imaging / Sense-Enhancing Technology (Kyllo)', 'Kyllo v. United States (2001)', true),
  ('con-law-001', 'fourth_amendment', 'medium', 'Carol calls her friend and confesses to a crime. Unbeknownst to Carol, the friend is a government informant who reports the conversation. Carol argues a Fourth Amendment violation. The argument:',
   'Fails — the Fourth Amendment does not protect information shared with a third party who reveals it (third-party doctrine).', 'Succeeds — she had a subjective expectation of privacy.', 'Fails — the Fourth Amendment only applies to tangible items.', 'Succeeds — conversations are always protected by the Fourth Amendment.',
   'A', 'The third-party doctrine holds that information voluntarily shared with third parties carries no Fourth Amendment protection. United States v. White (1971): a person takes the risk that a confidant will reveal information to the government. One who assumes the risk of disclosure to a third party cannot claim the government violated their Fourth Amendment rights when that third party reports to police.', 'Fourth Amendment — Third-Party Doctrine', 'United States v. White (1971)', true),
  ('con-law-001', 'fourth_amendment', 'hard', 'The government obtains seven years of Dan''s historical cell-site location information (CSLI) from his wireless carrier without a warrant. Under Carpenter v. United States, this is:',
   'Constitutional — only real-time tracking requires a warrant.', 'Unconstitutional — accessing comprehensive CSLI requires a warrant; the third-party doctrine does not apply to this volume of digital data.', 'Constitutional — CSLI is voluntarily shared with the carrier (third-party doctrine).', 'Constitutional — location information in public carries no REP.',
   'B', 'Carpenter v. United States (2018): the Supreme Court held that obtaining seven days or more of CSLI requires a warrant. The Court recognized a Fourth Amendment interest in the comprehensive record of physical movements the data reveals. The traditional third-party doctrine does not automatically extend to digital data that allows near-perfect surveillance of a person''s life.', 'Fourth Amendment — CSLI / Carpenter Third-Party Doctrine Limitation', 'Carpenter v. United States (2018)', true),
  ('con-law-001', 'fourth_amendment', 'medium', 'Eve lives in a house with two roommates. A police officer knocks on the door. One roommate consents to a search of the common areas; Eve (who is present) objects. The search is:',
   'Valid — one cotenant can consent for common areas.', 'Valid — the roommate had actual authority over the entire premises.', 'Invalid — Eve''s objection overrides her roommate''s consent when she is physically present.', 'Valid — the officer could not know whose property was whose.',
   'C', 'Georgia v. Randolph (2006): when a physically present occupant refuses consent, a co-occupant''s consent does not validate a warrantless search. Eve''s present objection controls over her roommate''s consent. The Court later limited this: if the objecting occupant is removed from the premises (e.g., lawfully arrested), consent from the remaining cotenant is valid (Fernandez v. California, 2014).', 'Fourth Amendment — Co-Tenant Consent / Objecting Cotenant Present (Randolph)', 'Georgia v. Randolph (2006)', true),
  ('con-law-001', 'fourth_amendment', 'hard', 'Police have probable cause to believe Frank has heroin in his apartment. They enter without a warrant to prevent destruction of evidence. They hear nothing indicating destruction is occurring. The entry is:',
   'Valid — the entry was based on probable cause.', 'Invalid — police cannot manufacture exigency to avoid the warrant requirement.', 'Valid — drug cases always create exigent circumstances.', 'Valid — mere probability of drug destruction creates exigency.',
   'B', 'Kentucky v. King (2011) held that police can rely on exigent circumstances they did not manufacture by engaging in bad-faith conduct. However, when police themselves create the exigency (e.g., by knocking and announcing their presence and then claiming to hear destruction), the entry may still be valid if they acted lawfully up to the point of entry. But a general claim of probable cause alone, without actual exigency, cannot justify warrantless entry.', 'Fourth Amendment — Exigent Circumstances / Police-Created Exigency', 'Kentucky v. King (2011)', true),
  ('con-law-001', 'fourth_amendment', 'medium', 'Grace is stopped at a sobriety checkpoint with all vehicles being stopped briefly. She argues the checkpoint is an unconstitutional seizure. The Supreme Court held:',
   'All checkpoints are unconstitutional — every stop requires individualized suspicion.', 'Sobriety checkpoints require reasonable suspicion of intoxication.', 'Checkpoints are constitutional only during holidays.', 'Sobriety checkpoints are constitutional if conducted under a neutral program with minimal discretion.',
   'D', 'Michigan Dept. of State Police v. Sitz (1990): sobriety checkpoints are constitutional under the Fourth Amendment when (1) there is a compelling government interest (highway safety), (2) stops are brief, and (3) the program operates under neutral guidelines limiting officer discretion. By contrast, checkpoints designed to detect general crime (drug interdiction) are unconstitutional (City of Indianapolis v. Edmond, 2000).', 'Fourth Amendment — Sobriety Checkpoints / Programmatic Searches', 'Michigan Dept. of State Police v. Sitz (1990)', true),
  ('con-law-001', 'fourth_amendment', 'easy', 'Henry is arrested and booked into jail. Officers conduct a strip search as part of the intake procedure. Henry had not been arrested for a violent offense. The strip search is:',
   'Constitutional — jails may strip-search all detainees entering the general population.', 'Unconstitutional — strip searches require individualized reasonable suspicion.', 'Unconstitutional — strip searches require a warrant.', 'Constitutional only if Henry was arrested for a drug offense.',
   'A', 'Florence v. Board of Chosen Freeholders (2012): the Supreme Court held that jails may conduct suspicionless strip searches of all detainees — including those arrested for minor offenses — being admitted to the general population. The government''s interest in jail security and preventing contraband overrides individual privacy interests in the intake context.', 'Fourth Amendment — Strip Searches at Jail Intake', 'Florence v. Board of Chosen Freeholders (2012)', true),
  ('con-law-001', 'fourth_amendment', 'hard', 'Police receive an anonymous tip that Irene is selling drugs from her porch. They approach, smell marijuana, and enter without a warrant. The warrantless entry is justified by:',
   'The plain smell of marijuana establishing probable cause plus exigent circumstances.', 'Consent implied by the fact that the porch was visible to the public.', 'The automobile exception applied to the porch.', 'The anonymous tip alone, which provided reasonable suspicion.',
   'A', 'The smell of marijuana can establish probable cause. Combined with a legitimate concern that evidence could be destroyed (exigent circumstances), officers may enter without a warrant. The anonymous tip alone was insufficient for entry, but the plain-smell observation transformed this into a situation where probable cause and exigency existed. Note: where there is no urgency and a warrant can be obtained, officers should do so.', 'Fourth Amendment — Plain Smell + Exigent Circumstances', NULL, true),
  ('con-law-001', 'fourth_amendment', 'medium', 'Officers lawfully arrest Jake at his home. As part of the booking process, they take a cheek swab for DNA without a warrant. This is:',
   'Unconstitutional — DNA requires a warrant under all circumstances.', 'Constitutional — DNA collection from those arrested for serious offenses serves a significant government interest.', 'Unconstitutional — DNA is testimonial evidence protected by the Fifth Amendment.', 'Constitutional only if Jake is convicted.',
   'B', 'Maryland v. King (2013): the Supreme Court upheld warrantless DNA collection as part of the routine booking procedure for those arrested for serious offenses. The Court treated the cheek swab as a minimal physical intrusion similar to fingerprinting, which serves the legitimate government interest of identifying arrestees.', 'Fourth Amendment — DNA Collection at Booking (Maryland v. King)', 'Maryland v. King (2013)', true),
  ('con-law-001', 'fourth_amendment', 'hard', 'A school official opens and searches a student''s backpack based on a reasonable suspicion that the student is smoking on campus. The search is:',
   'Unconstitutional — only police can conduct searches at school.', 'Constitutional — school officials need only reasonable suspicion, not probable cause.', 'Unconstitutional — schools must have probable cause to search students.', 'Constitutional only with parental consent.',
   'B', 'New Jersey v. T.L.O. (1985): public school officials may search students with only reasonable suspicion (not probable cause), balancing students'' privacy rights against school officials'' need to maintain order. The search must be (1) justified at its inception — reasonable suspicion of wrongdoing — and (2) reasonably related in scope to the circumstances that justified it.', 'Fourth Amendment — School Searches / Reasonable Suspicion Standard (T.L.O.)', 'New Jersey v. T.L.O. (1985)', true),
  ('con-law-001', 'fourth_amendment', 'medium', 'Larry is a parolee. His parole conditions allow warrantless searches of his person and home by parole officers at any time. A parole officer searches Larry''s home without suspicion and finds drugs. The search is:',
   'Unconstitutional — parolees retain full Fourth Amendment rights.', 'Constitutional only if the search was conducted by police, not parole officers.', 'Constitutional — parolees have significantly reduced Fourth Amendment expectations when they agree to search conditions.', 'Unconstitutional — parole conditions cannot waive constitutional rights.',
   'C', 'Samson v. California (2006): the Supreme Court held that parole search conditions — signed as a condition of release — are valid. Parolees have significantly diminished expectations of privacy compared to the general public. A warrantless, suspicionless search of a parolee pursuant to a parole condition does not violate the Fourth Amendment.', 'Fourth Amendment — Parolee Search Conditions (Samson v. California)', 'Samson v. California (2006)', true),
  ('con-law-001', 'fourth_amendment', 'hard', 'Police are executing a valid search warrant at Mary''s house. Officer Nash sees her neighbor''s window is open and, without entering, reaches through the window to retrieve what appears to be stolen property on the neighbor''s windowsill. This is:',
   'An invalid search and seizure — the officer had no authority to reach into the neighbor''s home.', 'Valid because the property was visible from the street.', 'A valid plain view seizure — the officer was already lawfully present.', 'Valid because the property was stolen.',
   'A', 'The plain view doctrine requires that the officer have a lawful right of access to the object. Even if the contraband was in plain view through the open window, Nash was executing a warrant for Mary''s property — not the neighbor''s. Reaching into the neighbor''s home without a warrant or another exception constitutes an unauthorized search and seizure.', 'Fourth Amendment — Plain View / Right of Access Requirement', NULL, true),
  ('con-law-001', 'fourth_amendment', 'medium', 'The exclusionary rule''s primary purpose is to:',
   'Protect the integrity of the trial process.', 'Deter future Fourth Amendment violations by police.', 'Compensate victims of unlawful searches.', 'Punish law enforcement officers for misconduct.',
   'B', 'Mapp v. Ohio (1961) incorporated the exclusionary rule against the states, and Weeks v. United States (1914) established it federally. The Supreme Court has consistently identified the rule''s primary purpose as deterrence — dissuading law enforcement from conducting future unconstitutional searches. The rule is not a personal constitutional right of the defendant (United States v. Calandra).', 'Fourth Amendment — Exclusionary Rule / Deterrence Rationale', 'Mapp v. Ohio (1961)', true),
  ('con-law-001', 'fourth_amendment', 'hard', 'Police illegally arrest Nick and take him to the station. Nick voluntarily confesses four hours later after receiving Miranda warnings and a meal. Under the attenuation doctrine, the confession is:',
   'Automatically inadmissible as fruit of the poisonous tree.', 'Admissible because Miranda warnings always cure an illegal arrest.', 'Inadmissible because Nick would not have confessed but for the illegal arrest.', 'Potentially admissible if the connection between the illegal arrest and the confession is attenuated.',
   'D', 'Brown v. Illinois (1975): Miranda warnings do not automatically purge the taint of an illegal arrest. Courts apply the attenuation doctrine, examining: (1) temporal proximity between illegality and confession, (2) intervening circumstances, and (3) purpose and flagrancy of the police misconduct. A four-hour gap, a meal, Miranda warnings, and voluntary cooperation are factors supporting attenuation.', 'Fourth Amendment — Attenuation Doctrine / Fruit of the Poisonous Tree', 'Brown v. Illinois (1975)', true),
  ('con-law-001', 'fourth_amendment', 'medium', 'Police conduct a valid search and find drugs belonging to Oliver and his girlfriend, who was also present. Oliver moves to suppress. The girlfriend also moves to suppress, arguing Oliver''s Fourth Amendment rights were violated. Which motion succeeds?',
   'Neither — the search was valid.', 'Oliver''s only — Fourth Amendment rights are personal.', 'Both — co-occupants share Fourth Amendment rights.', 'The girlfriend''s only — she owned the drugs.',
   'B', 'Fourth Amendment rights are personal and cannot be asserted vicariously. Even if Oliver''s rights were violated, the girlfriend cannot suppress evidence based on a violation of Oliver''s rights (Rakas v. Illinois, 1978). Each defendant must independently establish that their own REP was violated by the challenged search.', 'Fourth Amendment — Fourth Amendment Rights Are Personal / Standing', 'Rakas v. Illinois (1978)', true),
  ('con-law-001', 'fourth_amendment', 'hard', 'Police stop Paul''s car with reasonable suspicion. They order him out to conduct a pat-down. The authority to order Paul out comes from:',
   'Only probable cause — ordering someone out of a car requires more than reasonable suspicion.', 'The automobile exception.', 'The officer''s discretion, with no constitutional basis.', 'Pennsylvania v. Mimms — officers may order the driver out of a car during any lawful stop as a matter of course.',
   'D', 'Pennsylvania v. Mimms (1977): once police lawfully stop a vehicle, they may order the driver to exit the car as a matter of course, even without specific safety concerns. The Supreme Court held that the officer''s interest in safety outweighs the minor indignity of being asked to step out. Maryland v. Wilson (1997) extended this rule to passengers.', 'Fourth Amendment — Driver/Passenger Exit During Traffic Stops (Mimms/Wilson)', 'Pennsylvania v. Mimms (1977)', true),
  ('con-law-001', 'fourth_amendment', 'medium', 'The ''independent source'' doctrine allows evidence obtained through an illegal search to be admitted if:',
   'The evidence would have been discovered anyway through routine police procedures.', 'The officer had good faith belief the search was legal.', 'The evidence is probative and admission would not shock the conscience.', 'Police obtained the same evidence again through an untainted, lawful investigation.',
   'D', 'The independent source doctrine (Murray v. United States, 1988): if police independently obtain evidence through a source genuinely untainted by the prior illegal search, that evidence is admissible. The prosecution must show the second search was conducted on an independent basis — not prompted or directed by knowledge gained from the illegal search. This differs from inevitable discovery (Nix v. Williams), which covers evidence that would have been found anyway.', 'Fourth Amendment — Independent Source Doctrine', 'Murray v. United States (1988)', true),
  ('con-law-001', 'fourth_amendment', 'hard', 'Quinn''s attorney discovers that police had information establishing probable cause to search Quinn''s car before the traffic stop that led to the illegal search. The prosecution argues inevitable discovery. This argument:',
   'Succeeds if police would have eventually lawfully discovered the evidence through routine procedures.', 'Fails — inevitable discovery only applies to physical evidence, not cars.', 'Fails — inevitable discovery cannot be used where a warrant could have been obtained but was not.', 'Succeeds automatically because probable cause existed.',
   'A', 'Nix v. Williams (1984): the inevitable discovery doctrine allows admission of evidence that, though obtained illegally, would ultimately have been discovered through legal means. The prosecution must show by a preponderance that independent investigation would have led to discovery. Pre-existing probable cause that would have led to a warrant application can support the argument, but the standard is whether discovery was truly inevitable.', 'Fourth Amendment — Inevitable Discovery Doctrine (Nix v. Williams)', 'Nix v. Williams (1984)', true),
  ('con-law-001', 'fourth_amendment', 'medium', 'Rita owns a commercial warehouse. She operates a business subject to pervasive government regulation (firearms sales). Inspectors arrive without a warrant. This inspection is:',
   'Unconstitutional — all searches require a warrant.', 'Constitutional — owners of pervasively regulated businesses have reduced Fourth Amendment expectations regarding administrative inspections.', 'Unconstitutional — the business must consent to each inspection.', 'Constitutional only if prior notice was given.',
   'B', 'New York v. Burger (1987): owners of businesses in pervasively regulated industries (firearms, liquor, mines, junkyards) have reduced Fourth Amendment expectations. Warrantless administrative inspections are constitutional if: (1) there is a substantial government interest, (2) the warrantless inspection is necessary to further that interest, and (3) the statute''s inspection program provides a constitutionally adequate substitute for a warrant.', 'Fourth Amendment — Administrative Inspections / Pervasively Regulated Businesses', 'New York v. Burger (1987)', true),
  ('con-law-001', 'fourth_amendment', 'hard', 'Sam works at a public school. The principal searches Sam''s desk looking for evidence that Sam stole money from the school. The Fourth Amendment:',
   'Does not apply — the principal is not law enforcement.', 'Applies, and requires probable cause for any employer search.', 'Applies — the government must have reasonable suspicion before searching a public employee''s workspace for work-related misconduct.', 'Does not apply — Sam is an employee, not a student.',
   'C', 'O''Connor v. Ortega (1987): public employees retain Fourth Amendment rights in their workplaces. The government as employer may search an employee''s office for work-related reasons (not law enforcement) with reasonable suspicion, not probable cause. The search must be (1) justified at inception by reasonable grounds, and (2) not excessively intrusive in scope. The search must be work-related, not criminal investigation.', 'Fourth Amendment — Public Employee Workplace Searches (O''Connor v. Ortega)', 'O''Connor v. Ortega (1987)', true),
  ('con-law-001', 'fourth_amendment', 'medium', 'Police conduct a valid traffic stop and a drug-detection dog alerts on the vehicle. Can police search the car without a warrant based solely on the dog alert?',
   'No — dogs are not reliable enough to establish probable cause.', 'Yes, but only the exterior of the vehicle.', 'Yes — a trained drug-detection dog''s alert establishes probable cause to search.', 'No — a dog alert only creates reasonable suspicion.',
   'C', 'Florida v. Harris (2013): a well-trained drug-detection dog''s alert to a vehicle is sufficient to establish probable cause for a search under the Fourth Amendment. The Court held that the dog''s training history and certification records may be used to demonstrate reliability; the defendant may challenge reliability through cross-examination. A positive alert from a reliable dog = probable cause to search.', 'Fourth Amendment — Drug-Detection Dog Alert as Probable Cause (Harris)', 'Florida v. Harris (2013)', true),
  ('con-law-001', 'fourth_amendment', 'hard', 'A drug-detection dog is brought to sniff the exterior of Ted''s front door while he is inside. The dog alerts, leading to a warrant and subsequent drug seizure. The dog sniff at the door is:',
   'A search only if the officer entered the curtilage.', 'Not a search — dogs can sniff freely in public areas.', 'A Fourth Amendment search — bringing a drug-detection dog onto the curtilage of a home is a physical trespass.', 'Not a search — the dog was not inside the home.',
   'C', 'Florida v. Jardines (2013): bringing a drug-detection dog onto the porch (curtilage) of a home to conduct a search constitutes a Fourth Amendment search. The Court held this was a physical trespass on the home''s curtilage — an area protected like the home itself. Officers needed a warrant. This is distinct from dog sniffs in public places or airports, which are not searches.', 'Fourth Amendment — Drug Dog at Front Door / Curtilage Protection (Jardines)', 'Florida v. Jardines (2013)', true),
  ('con-law-001', 'fourth_amendment', 'easy', 'The curtilage of a home receives strong Fourth Amendment protection. The curtilage is best described as:',
   'Land within 100 feet of the home.', 'The area immediately surrounding the home intimately associated with domestic life.', 'Only the interior of the home.', 'Any land owned by the homeowner.',
   'B', 'United States v. Dunn (1987) established four factors for determining curtilage: (1) proximity to the home, (2) inclusion within an enclosure surrounding the home, (3) nature of uses to which the area is put, and (4) steps taken to protect the area from observation. Open fields beyond the curtilage receive no Fourth Amendment protection (Oliver v. United States, 1984).', 'Fourth Amendment — Curtilage vs. Open Fields', 'United States v. Dunn (1987)', true),
  ('con-law-001', 'due_process', 'easy', 'Procedural due process requires the government to provide, before depriving a person of life, liberty, or property:',
   'A full trial with jury in all cases.', 'Congressional approval.', 'Compensation equal to the value of the property taken.', 'Notice and an opportunity to be heard at a meaningful time and in a meaningful manner.',
   'D', 'The Due Process Clauses of the 5th and 14th Amendments require that before the government deprives a person of life, liberty, or property, it must provide notice and an opportunity to be heard. The level of process required varies depending on the interest at stake (Mathews v. Eldridge balancing test).', 'Procedural Due Process — Notice and Opportunity to Be Heard', NULL, true),
  ('con-law-001', 'due_process', 'medium', 'To determine what process is due under the Mathews v. Eldridge balancing test, courts weigh:',
   'The private interest, the risk of erroneous deprivation with current procedures, and the government''s interest (including administrative burden).', 'The cost of additional procedures only.', 'Congressional intent and the agency''s expertise.', 'Only the government''s interest in efficiency.',
   'A', 'Mathews v. Eldridge (1976) established a three-factor balancing test for procedural due process: (1) the private interest affected, (2) the risk of erroneous deprivation of that interest through the current procedures and the value of additional safeguards, and (3) the government''s interest, including the burden of additional procedures. This test is applied across a wide range of benefit and entitlement cases.', 'Procedural Due Process — Mathews v. Eldridge Balancing Test', 'Mathews v. Eldridge (1976)', true),
  ('con-law-001', 'due_process', 'hard', 'A city fires a tenured public school teacher without a hearing. She claims a due process violation. What must she first establish?',
   'That she was treated differently from other teachers.', 'That the firing was motivated by animus.', 'That she had a legitimate entitlement (protected property interest) in continued employment.', 'That the city had no legitimate reason for the termination.',
   'C', 'Board of Regents v. Roth (1972): to trigger procedural due process protections, the plaintiff must have a protected ''life, liberty, or property'' interest. A property interest in continued employment exists when there is a legitimate claim of entitlement — typically created by statute, contract, or established practice (tenure). Without a protected interest, no process is required, regardless of how the government acted.', 'Procedural Due Process — Protected Property Interest (Roth)', 'Board of Regents v. Roth (1972)', true),
  ('con-law-001', 'due_process', 'medium', 'A state terminates welfare benefits without a pre-termination hearing, offering only a post-termination hearing. This violates:',
   'Procedural due process — welfare recipients must receive a pre-termination hearing.', 'Equal protection, because welfare recipients are a suspect class.', 'No constitutional provision — welfare is a privilege, not a right.', 'Substantive due process — the government cannot terminate welfare.',
   'A', 'Goldberg v. Kelly (1970): welfare benefits constitute a property interest protected by due process. Before terminating benefits, the state must provide the recipient with notice and an opportunity for a pre-termination hearing. Post-termination hearings are insufficient when the stakes are as high as a person''s means of subsistence.', 'Procedural Due Process — Pre-Termination Hearing for Welfare Benefits (Goldberg v. Kelly)', 'Goldberg v. Kelly (1970)', true),
  ('con-law-001', 'due_process', 'hard', 'A state law prohibits the use of contraceptives by married couples. It is challenged under substantive due process. The correct analysis is:',
   'Strict scrutiny — it burdens the fundamental right to marital privacy.', 'Rational basis — contraception is not a fundamental right.', 'Intermediate scrutiny — it affects women''s rights.', 'No scrutiny — the regulation is purely medical.',
   'A', 'Griswold v. Connecticut (1965): the Supreme Court recognized a constitutional right to marital privacy, finding ''penumbras'' and ''emanations'' from several Bill of Rights amendments creating a right to use contraceptives. Laws burdening fundamental rights recognized under substantive due process receive strict scrutiny. The right was later extended to unmarried individuals in Eisenstadt v. Baird (1972).', 'Substantive Due Process — Right to Marital Privacy / Contraception (Griswold)', 'Griswold v. Connecticut (1965)', true),
  ('con-law-001', 'due_process', 'medium', 'A state law prohibits same-sex couples from marrying. It is challenged under substantive due process. Under Obergefell v. Hodges, the law is:',
   'Reviewed under rational basis, and upheld as promoting procreation.', 'Unconstitutional, but only under equal protection.', 'Unconstitutional — the fundamental right to marry extends to same-sex couples.', 'Constitutional — marriage is traditionally defined by the states.',
   'C', 'Obergefell v. Hodges (2015): the Supreme Court held that same-sex couples have a fundamental right to marry under the Due Process and Equal Protection Clauses of the Fourteenth Amendment. States cannot restrict marriage to opposite-sex couples. The Court reasoned that marriage is a fundamental right, and the right must be extended equally to same-sex couples.', 'Substantive Due Process / Equal Protection — Right to Marry / Same-Sex Marriage (Obergefell)', 'Obergefell v. Hodges (2015)', true),
  ('con-law-001', 'due_process', 'hard', 'Frank is convicted of a crime he did not commit. He later discovers exculpatory DNA evidence. He claims a substantive due process right to post-conviction DNA testing. The Supreme Court has held:',
   'The Eighth Amendment provides the right to DNA testing in capital cases.', 'There is a clearly established substantive due process right to post-conviction DNA testing.', 'Due process requires states to provide DNA testing upon request.', 'There is no clearly established federal constitutional right to post-conviction access to evidence for DNA testing.',
   'D', 'District Attorney''s Office v. Osborne (2009): the Supreme Court declined to recognize a substantive due process right to post-conviction access to the state''s evidence for DNA testing. The Court held that the state''s procedures provided sufficient process and that states may create their own frameworks for post-conviction DNA access. This is an area left primarily to state law.', 'Substantive Due Process — No Federal Right to Post-Conviction DNA Testing (Osborne)', 'District Attorney''s Office v. Osborne (2009)', true),
  ('con-law-001', 'due_process', 'medium', 'A state law prohibiting physician-assisted suicide for competent, terminally ill adults is challenged under substantive due process. The Supreme Court held:',
   'Such laws are unconstitutional as applied to terminally ill patients.', 'The law violates the right to privacy established in Griswold.', 'There is no fundamental right to physician-assisted suicide; the law is upheld under rational basis review.', 'There is a fundamental right to physician-assisted suicide.',
   'C', 'Washington v. Glucksberg (1997): the Supreme Court held that the right to physician-assisted suicide is not a fundamental liberty interest protected by substantive due process. The Court established a two-part test for new substantive due process rights: (1) the right must be deeply rooted in the nation''s history and tradition, and (2) it must be carefully described. Assisted suicide failed both prongs, so rational basis review applied, and the law was upheld.', 'Substantive Due Process — No Fundamental Right to Physician-Assisted Suicide (Glucksberg)', 'Washington v. Glucksberg (1997)', true),
  ('con-law-001', 'due_process', 'hard', 'A state passes a law that bars individuals from practicing optometry unless they purchase supplies from a licensed in-state dealer. The law is challenged as irrational economic regulation. Under substantive due process, the law:',
   'Is unconstitutional — it irrationally burdens the right to work.', 'Is unconstitutional under Lochner v. New York.', 'Requires intermediate scrutiny because it regulates a licensed profession.', 'Is constitutional — economic regulations survive rational basis review if rationally related to any conceivable legitimate government interest.',
   'D', 'Williamson v. Lee Optical (1955): post-Lochner, the Court uses rational basis review for economic regulations and will uphold them if any conceivable legitimate state interest could rationally explain them. The Court does not require the legislature to actually have that interest or for the law to be efficient. Lochner-era substantive due process protecting economic rights was repudiated.', 'Substantive Due Process — Post-Lochner Rational Basis for Economic Regulation', 'Williamson v. Lee Optical (1955)', true),
  ('con-law-001', 'due_process', 'medium', 'The government seeks to civilly commit a mentally ill person after his criminal sentence expires. Which standard of proof is constitutionally required for civil commitment?',
   'Beyond a reasonable doubt.', 'Reasonable suspicion.', 'Preponderance of the evidence.', 'Clear and convincing evidence.',
   'D', 'Addington v. Texas (1979): the Supreme Court held that due process requires at least clear and convincing evidence for civil commitment of an allegedly mentally ill person. The individual''s liberty interest is substantial. The Court rejected the criminal law''s beyond-a-reasonable-doubt standard but required more than a preponderance of evidence.', 'Substantive/Procedural Due Process — Clear and Convincing Evidence for Civil Commitment', 'Addington v. Texas (1979)', true),
  ('con-law-001', 'due_process', 'hard', 'A law makes it a crime to be a gang member in a public place without requiring any specific intent or act. The law is challenged on due process grounds. The law is:',
   'Constitutional if there is a rational basis.', 'Constitutional — states may define criminal conduct broadly.', 'Unconstitutional only as applied to juveniles.', 'Unconstitutional — it criminalizes status, which violates due process and the Eighth Amendment.',
   'D', 'Robinson v. California (1962): the Supreme Court held that punishing a person for the status of being a drug addict, without proof of any conduct, violates the Eighth Amendment (incorporated via the Fourteenth). A law punishing gang membership alone — a status — similarly criminalizes mere association without any culpable act, violating both due process (void for vagueness concerns) and the Eighth Amendment''s limits on criminalization.', 'Due Process / Eighth Amendment — Status Crimes Unconstitutional', 'Robinson v. California (1962)', true),
  ('con-law-001', 'due_process', 'medium', 'A criminal statute uses the term ''offensive conduct'' without defining it further. A defendant challenges the statute. The strongest constitutional argument is:',
   'The statute is an unconstitutional prior restraint.', 'The statute violates the Equal Protection Clause.', 'The statute violates substantive due process by regulating speech.', 'The statute is void for vagueness — it fails to give fair notice and invites arbitrary enforcement.',
   'D', 'Void-for-vagueness doctrine under the Due Process Clause: a criminal statute must give fair notice of what conduct is prohibited so that ordinary people can understand the law, and must provide standards to prevent arbitrary enforcement by police and prosecutors. A term like ''offensive conduct'' without further definition fails both prongs and is unconstitutionally vague.', 'Due Process — Void for Vagueness Doctrine', NULL, true),
  ('con-law-001', 'due_process', 'hard', 'A state removes a child from her parents without a hearing, claiming emergency child abuse. The parents challenge this as a due process violation. Under Mathews, the pre-removal hearing was likely:',
   'Required — child abuse is not an emergency per se.', 'Required in all circumstances — parents have an absolute right to a hearing before removal.', 'Not required — parental rights are not a protected liberty interest.', 'Not required here — emergency circumstances justify temporary removal without prior hearing, with a prompt post-removal hearing.',
   'D', 'Mathews v. Eldridge balancing: while parental rights are a fundamental liberty interest (Stanley v. Illinois), emergency child protection creates exigent circumstances where immediate action may be necessary. Courts generally hold that temporary emergency removal without a prior hearing is constitutional when there is immediate danger, provided a prompt post-removal hearing is held. The balance tips toward child safety in true emergencies.', 'Procedural Due Process — Emergency Child Removal / Post-Deprivation Hearing', 'Stanley v. Illinois (1972)', true),
  ('con-law-001', 'due_process', 'medium', 'A student is suspended from a public school for 10 days without any hearing. The student argues a due process violation. The suspension:',
   'Is constitutional — suspension from school is a privilege, not a right.', 'May violate due process — students have a property interest in education and must receive at least notice and an informal hearing.', 'Is constitutional — 10 days is too short to trigger due process.', 'Is constitutional — schools have plenary authority over disciplinary matters.',
   'B', 'Goss v. Lopez (1975): students facing suspension have a property interest in their education and a liberty interest in their reputation. Even a short suspension of 10 days requires at minimum (1) notice of the charges and (2) an opportunity to explain their side in an informal hearing. More severe sanctions (long-term suspension, expulsion) require more formal procedures.', 'Procedural Due Process — Student Suspension / Goss v. Lopez', 'Goss v. Lopez (1975)', true),
  ('con-law-001', 'due_process', 'hard', 'A state requires a person to post a bond before filing a lawsuit. A poor person who cannot afford the bond is denied access to court. This violates:',
   'The First Amendment — access to court is a form of petition.', 'No constitutional provision — states may regulate court access.', 'The Equal Protection Clause only — filing fees discriminate based on wealth.', 'Due process — the right of access to courts cannot be conditioned on the payment of fees for those who cannot afford them.',
   'D', 'Boddie v. Connecticut (1971): the Supreme Court held that the state cannot condition access to the only available divorce proceeding on the payment of court fees that an indigent person cannot afford. The right of access to courts is a fundamental interest, and the state monopoly on divorce proceedings means the fee effectively bars the exercise of a protected right. The ruling is narrow: not every court fee is unconstitutional, but fees that completely bar access for the indigent in critical proceedings are.', 'Procedural Due Process — Access to Courts / Boddie v. Connecticut', 'Boddie v. Connecticut (1971)', true),
  ('con-law-001', 'due_process', 'medium', 'A law limits the number of occupants in any household in a single-family zone, effectively preventing a grandmother from living with grandchildren from different nuclear families. The law is challenged under substantive due process. The Court should:',
   'Apply heightened scrutiny — the government may not interfere with the choice to live with extended family members.', 'Apply rational basis — the right to live with extended family is not fundamental.', 'Apply rational basis — zoning decisions are committed to local governments.', 'Dismiss the challenge — zoning is a policy matter, not a constitutional issue.',
   'A', 'Moore v. City of East Cleveland (1977): the Supreme Court struck down an ordinance limiting household occupancy in a way that prevented extended family arrangements. A plurality recognized that the right to live with extended family members is protected by substantive due process as a fundamental liberty, and that the government must justify interference with heightened scrutiny. The government''s efficiency-based zoning rationale was insufficient.', 'Substantive Due Process — Right to Live with Extended Family (Moore v. East Cleveland)', 'Moore v. City of East Cleveland (1977)', true),
  ('con-law-001', 'due_process', 'hard', 'Congress passes a law making it a crime to possess a firearm near a school. A defendant argues the law lacks any jurisdictional element connecting it to interstate commerce, but also raises a due process notice concern because the term ''near'' is undefined. The strongest due process argument is:',
   'The law violates the nondelegation doctrine.', 'Procedural due process — criminal laws require hearings before enforcement.', 'Void for vagueness — ''near a school'' provides insufficient notice of the prohibited zone.', 'Substantive due process — the right to bear arms is fundamental.',
   'C', 'A criminal statute that prohibits conduct in a geographic area defined only as ''near'' a school, without specifying a distance, may be unconstitutionally vague under the Due Process Clause. It fails to give fair notice of what conduct is prohibited and may invite arbitrary enforcement. (Compare with the Gun-Free School Zones Act, which courts analyzed on Commerce Clause grounds, but vagueness is independently raised here.)', 'Due Process — Void for Vagueness / Geographic Ambiguity in Criminal Statutes', NULL, true),
  ('con-law-001', 'due_process', 'medium', 'The government seeks to take away a convicted sex offender''s liberty by civil commitment after his sentence is complete. Which analysis applies?',
   'Rational basis, because sex offenders have no protected liberty interest.', 'The conviction itself justifies indefinite civil commitment.', 'No constitutional challenge is available to civil commitment schemes.', 'Substantive due process — the government must demonstrate the individual is mentally ill and dangerous, not merely that they committed a past offense.',
   'D', 'Kansas v. Hendricks (1997): the Supreme Court upheld civil commitment of sexually violent predators after release from prison, but only if the state demonstrates that the individual has a mental abnormality or personality disorder (beyond merely having committed a crime) making them likely to engage in future acts. Civil commitment cannot be used as a pretext for additional criminal punishment without the requisite mental illness finding.', 'Substantive Due Process — Sex Offender Civil Commitment (Hendricks)', 'Kansas v. Hendricks (1997)', true),
  ('con-law-001', 'due_process', 'hard', 'A state allows parents to institutionalize their minor children without a judicial hearing. This is challenged on procedural due process grounds. The Court held:',
   'Children have no due process rights because parents make decisions for them.', 'The state may institutionalize children based solely on parental consent, without any review.', 'A full judicial hearing is required before any commitment.', 'Some neutral fact-finding procedure is required, though not a full adversarial hearing.',
   'D', 'Parham v. J.R. (1979): the Supreme Court held that children committed by their parents to mental institutions have a liberty interest in not being confined needlessly. However, a full adversarial hearing is not required. The Constitution requires at minimum a neutral fact-finding inquiry — such as a staff physician''s independent medical evaluation — to determine whether the commitment criteria are met. Parental consent alone is insufficient.', 'Procedural Due Process — Juvenile Commitment by Parents / Parham v. J.R.', 'Parham v. J.R. (1979)', true),
  ('con-law-001', 'due_process', 'medium', 'A criminal defendant is denied the right to present a complete defense because the trial judge excluded a key piece of exculpatory evidence under a rigid evidentiary rule. This may violate:',
   'The Due Process Clause — defendants have a right to present a complete defense.', 'Only the Fourteenth Amendment''s Equal Protection Clause.', 'Only the Sixth Amendment right to counsel.', 'Only the Fifth Amendment''s privilege against self-incrimination.',
   'A', 'Chambers v. Mississippi (1973) and Holmes v. South Carolina (2006): the Due Process Clause of the Fourteenth Amendment guarantees defendants the right to present a complete defense. A mechanistic application of evidentiary rules that prevents a defendant from introducing clearly exculpatory evidence may violate due process, even if the rule is generally valid.', 'Due Process — Right to Present a Complete Defense', 'Chambers v. Mississippi (1973)', true),
  ('con-law-001', 'due_process', 'easy', 'Which standard of review applies to laws that burden a fundamental right recognized under substantive due process?',
   'Heightened rational basis — a step above the normal standard.', 'Strict scrutiny — the law must be narrowly tailored to serve a compelling government interest.', 'Rational basis — all laws are presumed constitutional.', 'Intermediate scrutiny — the government must show an important interest.',
   'B', 'When a law burdens a fundamental right — such as the right to marry, the right to travel, the right to privacy in contraception, or the right to rear children — the Court applies strict scrutiny. The government must show (1) a compelling government interest and (2) that the law is narrowly tailored (the least restrictive means) to achieve that interest. Absent a fundamental right, rational basis applies.', 'Substantive Due Process — Strict Scrutiny for Fundamental Rights', NULL, true),
  ('con-law-001', 'due_process', 'hard', 'A state automatically terminates parental rights when a child is placed in foster care for 18 months, without an individualized determination. This violates:',
   'Procedural and substantive due process — the fundamental right to parent requires individualized findings before termination.', 'Only equal protection — similarly situated parents are treated differently.', 'No constitutional provision — the state may terminate parental rights to protect children.', 'Only substantive due process — no additional process is required.',
   'A', 'Santosky v. Kramer (1982): the Supreme Court held that the fundamental right of parents to the care and custody of their children is protected by substantive due process. Before terminating parental rights, the state must provide at least clear and convincing evidence of unfitness. An automatic termination rule based on time in foster care alone — without individualized findings — violates both the procedural requirement (proper hearing) and the substantive right (no arbitrary termination).', 'Due Process — Termination of Parental Rights / Santosky v. Kramer', 'Santosky v. Kramer (1982)', true),
  ('con-law-001', 'due_process', 'medium', 'A state denies a prisoner good-time credit after an informal proceeding with no written findings. The prisoner claims a liberty interest in the credits. The claim:',
   'Fails — good-time credit is a privilege, not a right.', 'Succeeds automatically — any deprivation of liberty triggers full trial rights.', 'Succeeds only if state law creates a protected interest in the good-time credit, requiring appropriate procedural safeguards.', 'Fails — prisoners have no due process rights.',
   'C', 'Wolff v. McDonnell (1974): prisoners retain due process rights, though diminished by the fact of incarceration. When state law creates a protected liberty interest (such as in earned good-time credits), the Due Process Clause requires some procedural protections before the government revokes those credits — including written notice of the charges, an opportunity to appear and present witnesses (unless security risks), and a written statement of the reasons for any adverse decision.', 'Procedural Due Process — Prisoner Good-Time Credits / Wolff v. McDonnell', 'Wolff v. McDonnell (1974)', true),
  ('con-law-001', 'due_process', 'easy', 'The substantive due process doctrine protects persons from government action that is:',
   'Enacted without sufficient legislative findings.', 'Merely inefficient or unwise.', 'Arbitrary, oppressive, or shocking to the conscience, particularly when it burdens a fundamental right.', 'Only politically motivated.',
   'C', 'Substantive due process holds that even if the government follows proper procedures, certain laws may still violate the Constitution if they are arbitrary, capricious, or shocking to the conscience. The doctrine operates at two levels: (1) for fundamental rights, strict scrutiny applies; (2) for non-fundamental rights/economic regulation, rational basis review applies. Rochin v. California (1952) applied the ''shocks the conscience'' formulation.', 'Substantive Due Process — Core Principle / Shocks the Conscience', 'Rochin v. California (1952)', true),
  ('con-law-001', 'due_process', 'hard', 'A state statute retroactively eliminates a defense that was available when the defendant committed the crime. The defendant challenges the statute as an Ex Post Facto law. The law:',
   'Is constitutional — only criminal penalties, not defenses, are protected.', 'Violates the Ex Post Facto Clause — retroactively eliminating an available defense disadvantages the defendant.', 'Is constitutional — states may change procedural defenses at any time.', 'Violates the Due Process Clause only, not the Ex Post Facto Clause.',
   'B', 'The Ex Post Facto Clause (Art. I, § 10) prohibits retroactive laws that: (1) criminalize conduct that was innocent when done, (2) increase punishment beyond what was prescribed when the offense was committed, (3) change the rules of evidence to the defendant''s disadvantage, or (4) take away defenses available when the crime was committed. Retroactively eliminating a defense falls under category (4) and violates the clause.', 'Ex Post Facto Clause — Retroactive Elimination of Defenses', 'Beazell v. Ohio (1925)', true),
  ('con-law-001', 'equal_protection', 'easy', 'The Equal Protection Clause of the Fourteenth Amendment prohibits states from:',
   'Treating corporations differently from natural persons.', 'Classifying persons in any way without Congressional approval.', 'Passing any law that treats any two individuals differently.', 'Denying any person the equal protection of the laws through arbitrary or irrational classifications.',
   'D', 'The Equal Protection Clause bars states from denying persons the equal protection of the laws. The Clause does not prohibit all classifications — governments routinely classify for legitimate reasons. The constitutional question is whether a classification is sufficiently justified. The level of scrutiny depends on the type of classification and whether it burdens a fundamental right.', 'Equal Protection — Core Principle / 14th Amendment', NULL, true),
  ('con-law-001', 'equal_protection', 'medium', 'A state law provides that only natural-born citizens may hold civil service jobs. Foreign nationals challenge the law. The appropriate standard of review is:',
   'Strict scrutiny — alienage is a suspect class.', 'Intermediate scrutiny — alienage classifications affecting employment require heightened review.', 'Rational basis — alienage is not a suspect class when government employment is at stake.', 'Rational basis — government may restrict its own employment freely.',
   'A', 'Graham v. Richardson (1971): alienage is a suspect classification. State laws discriminating against aliens ordinarily receive strict scrutiny. However, there is a ''political function'' exception: states may restrict positions that go to the heart of representative government (teachers, police, probation officers, election officials) to citizens only under rational basis. Pure civil service jobs generally remain under strict scrutiny.', 'Equal Protection — Alienage as Suspect Class (Graham v. Richardson)', 'Graham v. Richardson (1971)', true),
  ('con-law-001', 'equal_protection', 'hard', 'A state law provides that widows but not widowers receive a property tax exemption. A widower challenges the law under equal protection. The Court applies:',
   'Strict scrutiny — gender is a suspect class.', 'Intermediate scrutiny — gender classifications must be substantially related to an important government interest.', 'Rational basis — gender classifications are presumed constitutional.', 'Rational basis with bite — gender classifications face heightened review only for truly arbitrary laws.',
   'B', 'Craig v. Boren (1976) established intermediate scrutiny for gender classifications: the classification must be substantially related to an important government interest. In Weinberger v. Wiesenfeld (1975), the Court struck down Social Security rules that provided benefits to widows but not widowers. Modern equal protection doctrine requires exceedingly persuasive justification (United States v. Virginia, 1996) for gender classifications.', 'Equal Protection — Intermediate Scrutiny for Gender Classifications', 'Craig v. Boren (1976)', true),
  ('con-law-001', 'equal_protection', 'medium', 'A state university''s admissions program uses race as a ''plus factor'' to achieve diversity in the student body. Under Grutter v. Bollinger, such a program:',
   'Violates the Equal Protection Clause — race can never be used in admissions.', 'May be constitutional under strict scrutiny if race is one factor among many, not a quota.', 'Violates equal protection as reverse discrimination against whites.', 'Is subject to rational basis review since it benefits minority students.',
   'B', 'Grutter v. Bollinger (2003): race-conscious admissions programs at public universities are subject to strict scrutiny. The compelling interest in student body diversity may justify the use of race if the program is narrowly tailored — meaning it uses race as a ''plus factor,'' not a quota, and gives individualized consideration. Note: Students for Fair Admissions v. Harvard (2023) subsequently held that such race-conscious admissions programs violate the Equal Protection Clause.', 'Equal Protection — Race-Conscious Admissions / Strict Scrutiny (Grutter)', 'Grutter v. Bollinger (2003)', true),
  ('con-law-001', 'equal_protection', 'hard', 'A state law allows unmarried fathers to veto their child''s adoption, but only if they have established a relationship with the child. Unmarried mothers automatically have the right to veto. The law applies intermediate scrutiny. Under that standard, the law:',
   'Is constitutional — the government has a compelling interest in protecting children.', 'Is constitutional — the law rationally distinguishes between mothers and fathers.', 'Is subject to rational basis review, not intermediate scrutiny.', 'Is unconstitutional — gender classifications must be exceedingly persuasive; the law stereotypes all unmarried fathers as disinterested.',
   'D', 'Caban v. Mohammed (1979): the Supreme Court struck down a state adoption law that gave unmarried mothers but not unmarried fathers the right to veto adoption without proof of a relationship. The law impermissibly relied on gender stereotypes. Under intermediate scrutiny, the government must show the classification is substantially related to an important interest and is based on actual, rather than assumed, differences.', 'Equal Protection — Gender Stereotypes / Intermediate Scrutiny (Caban)', 'Caban v. Mohammed (1979)', true),
  ('con-law-001', 'equal_protection', 'medium', 'A state law provides that all men 18-26 must register for the draft, but women are exempt. Under equal protection, the law:',
   'Requires strict scrutiny because it discriminates based on sex.', 'Is unconstitutional — the government cannot distinguish between men and women.', 'Is unconstitutional because women can serve in the military.', 'Is constitutional — the classification is substantially related to the important government interest in building a combat-ready military.',
   'D', 'Rostker v. Goldberg (1981): the Supreme Court upheld the male-only draft registration requirement. The Court found the classification substantially related to the important government interest in military effectiveness, reasoning (at the time) that women were excluded from combat and thus a male-only combat-ready draft was justified. The Court deferred significantly to Congress''s military expertise.', 'Equal Protection — Gender Classification / Male-Only Draft (Rostker)', 'Rostker v. Goldberg (1981)', true),
  ('con-law-001', 'equal_protection', 'hard', 'A state law denies undocumented children access to public education. This is challenged under equal protection. Under Plyler v. Doe, the law is:',
   'Constitutional under rational basis — states may regulate immigration-related matters.', 'Unconstitutional — undocumented aliens are a suspect class.', 'Unconstitutional — denying education to undocumented children is an ineffective and unjustifiable means of controlling illegal immigration.', 'Constitutional — undocumented immigrants have no constitutional rights.',
   'C', 'Plyler v. Doe (1982): the Supreme Court struck down a Texas law denying public education to undocumented children. The Court applied something more than rational basis (but less than strict scrutiny), noting the children''s special vulnerability and the importance of education. The Court found Texas''s interest in deterring illegal immigration insufficient to justify imposing a lasting disability on innocent children for their parents'' conduct.', 'Equal Protection — Undocumented Children''s Right to Education (Plyler v. Doe)', 'Plyler v. Doe (1982)', true),
  ('con-law-001', 'equal_protection', 'medium', 'A state law taxes alcohol differently based on whether it was produced in-state or out-of-state, with in-state producers receiving a lower tax rate. This is challenged under equal protection. The law:',
   'Violates equal protection under strict scrutiny — economic classifications are suspect.', 'Is constitutional because the 21st Amendment gives states broad power over alcohol.', 'Violates the Dormant Commerce Clause — states may not discriminate against out-of-state commerce.', 'Is constitutional under rational basis — states may favor local business.',
   'C', 'State laws that discriminate against interstate commerce in favor of local economic interests are analyzed under the Dormant Commerce Clause, not equal protection. Such facially discriminatory laws are virtually per se invalid unless the state can show no other adequate means to achieve a non-protectionist interest. This is the more relevant constitutional doctrine for economic discrimination between in-state and out-of-state goods.', 'Dormant Commerce Clause — Discrimination Against Interstate Commerce', NULL, true),
  ('con-law-001', 'equal_protection', 'hard', 'A law denies benefits to persons who moved to the state in the past year. The law is challenged as a durational residency requirement. The Court applies:',
   'Rational basis — welfare benefits are not a fundamental right.', 'Intermediate scrutiny — the right to interstate travel is important but not fundamental.', 'Rational basis — states may give preferences to long-term residents.', 'Strict scrutiny — the right to travel (specifically, the right of interstate migrants to be treated equally upon arrival) is fundamental.',
   'D', 'Saenz v. Roe (1999): the Supreme Court struck down California''s durational residency requirement that limited new residents'' welfare benefits to what they received in their prior state. The Court recognized a right to travel — specifically the right of newly arrived citizens to be treated like other citizens of the state — protected by the Privileges and Immunities Clause of the Fourteenth Amendment, triggering strict scrutiny.', 'Equal Protection / Right to Travel — Durational Residency Requirements (Saenz v. Roe)', 'Saenz v. Roe (1999)', true),
  ('con-law-001', 'equal_protection', 'medium', 'A state law establishes a classification based on illegitimacy (being born out of wedlock), denying illegitimate children the right to inherit from their fathers. The appropriate standard is:',
   'Strict scrutiny — children cannot be punished for their parents'' choices.', 'Strict scrutiny — classifications based on birth status are inherently suspect.', 'Intermediate scrutiny — illegitimacy is a quasi-suspect classification.', 'Rational basis — illegitimacy is not a suspect class.',
   'C', 'Mathews v. Lucas (1976) and Trimble v. Gordon (1977): the Supreme Court has applied something resembling intermediate scrutiny to classifications based on illegitimacy (though never formally declaring it a quasi-suspect class). The Court strikes down laws that impose disabilities on illegitimate children for their parents'' conduct, requiring that such classifications be substantially related to a legitimate state interest.', 'Equal Protection — Illegitimacy / Heightened Scrutiny', 'Mathews v. Lucas (1976)', true),
  ('con-law-001', 'equal_protection', 'hard', 'A state law excludes people with intellectual disabilities from residing in a group home in a residential area. The exclusion is challenged under equal protection. The Court holds:',
   'The law violates rational basis because it reflects irrational prejudice with no legitimate justification.', 'Intermediate scrutiny applies — disability is a quasi-suspect classification.', 'Strict scrutiny applies — disability is a suspect class.', 'Rational basis applies — disability is not a suspect class, and the law is presumptively valid.',
   'A', 'City of Cleburne v. Cleburne Living Center (1985): the Supreme Court applied rational basis review to classifications based on intellectual disability, declining to make disability a quasi-suspect class. However, the Court struck down the zoning exclusion because it was not rationally related to any legitimate government interest — it was based on fear, negative attitudes, and irrational prejudice. This is sometimes called ''rational basis with bite'' or ''rational basis plus.''', 'Equal Protection — Disability / Rational Basis with Bite (Cleburne)', 'City of Cleburne v. Cleburne Living Center (1985)', true),
  ('con-law-001', 'equal_protection', 'medium', 'Which equal protection tier of scrutiny applies to laws that classify based on sexual orientation?',
   'Strict scrutiny — sexual orientation is a suspect classification.', 'Rational basis — sexual orientation is not a recognized protected class.', 'The Court has not established a definitive tier; Romer and Lawrence struck down laws without specifying.', 'Intermediate scrutiny — sexual orientation is a quasi-suspect classification.',
   'C', 'The Supreme Court has not formally classified sexual orientation under a specific tier. In Romer v. Evans (1996), the Court struck down a Colorado amendment banning anti-discrimination protections for gay people under rational basis review. In Obergefell (2015), the Court invalidated same-sex marriage bans using equal protection and due process together. Officially, the Court has applied ''rational basis'' to strike down such laws without formally adopting intermediate or strict scrutiny.', 'Equal Protection — Sexual Orientation / No Formal Tier Established', 'Romer v. Evans (1996)', true),
  ('con-law-001', 'equal_protection', 'hard', 'A state law restricts voting to persons who own real property in the jurisdiction. This is challenged under equal protection. The law is:',
   'Unconstitutional — wealth-based restrictions on voting burden a fundamental right.', 'Constitutional for special-purpose elections only.', 'Constitutional under rational basis because property owners pay property taxes.', 'Constitutional — property ownership demonstrates a stake in local decisions.',
   'A', 'Harper v. Virginia Board of Elections (1966) struck down poll taxes under equal protection. The right to vote is fundamental, and conditioning voting on property ownership or wealth classifications triggers strict scrutiny. The government cannot condition the right to vote on economic status. Note: in Ball v. James (1981), the Court upheld property ownership restrictions for very limited special-purpose water district elections, but these are narrow exceptions.', 'Equal Protection — Voting as Fundamental Right / Wealth-Based Restrictions', 'Harper v. Virginia Board of Elections (1966)', true),
  ('con-law-001', 'equal_protection', 'medium', 'A state law provides that criminal sentences may be enhanced if the jury finds, by a preponderance of the evidence, that the defendant selected the victim based on race (hate crime). This is challenged under equal protection because it treats defendants differently based on the race of their victim. The law:',
   'Violates the First Amendment because it punishes thought.', 'Requires strict scrutiny because race is a factor.', 'Violates equal protection — defendants cannot be treated differently based on victim''s race.', 'Is constitutional — legislatures may punish more severely crimes motivated by racial bias without violating equal protection.',
   'D', 'Wisconsin v. Mitchell (1993): the Supreme Court unanimously upheld hate crime sentence enhancement statutes. Such laws punish conduct (criminal acts motivated by bias) more severely, not mere speech or thought. They do not violate equal protection because legislatures may punish bias-motivated crimes more harshly based on their greater impact on community. The law applies equally regardless of the race of the defendant.', 'Equal Protection — Hate Crime Sentence Enhancement Laws (Mitchell)', 'Wisconsin v. Mitchell (1993)', true),
  ('con-law-001', 'equal_protection', 'hard', 'A facially neutral criminal law is enforced selectively against one racial group. Which doctrine provides the strongest equal protection challenge?',
   'Discriminatory effect alone is sufficient to establish an equal protection violation.', 'The law is unconstitutional on its face because it is likely to be applied discriminatorily.', 'The selective enforcement violates equal protection if the defendant proves both discriminatory effect and discriminatory purpose.', 'The law is constitutional because it is facially neutral.',
   'C', 'Washington v. Davis (1976): a facially neutral law does not violate equal protection merely because it has a disparate racial impact. The plaintiff must prove discriminatory purpose — that the government acted with the intent to discriminate. Village of Arlington Heights v. Metro. Housing Corp. (1977) provided factors for showing discriminatory intent: statistical disparities, historical background, departures from normal procedure, and legislative/administrative history.', 'Equal Protection — Discriminatory Purpose Required for Neutral Laws (Davis)', 'Washington v. Davis (1976)', true),
  ('con-law-001', 'equal_protection', 'medium', 'A state establishes congressional districts designed to maximize minority voter representation, resulting in an oddly shaped majority-minority district. The district is challenged under equal protection. The Court applies:',
   'Rational basis — legislative redistricting is a political question.', 'Intermediate scrutiny — race is a quasi-suspect class in voting.', 'Strict scrutiny — if race was the predominant factor in drawing the district''s lines.', 'No scrutiny — the Voting Rights Act authorizes race-conscious redistricting.',
   'C', 'Shaw v. Reno (1993): the Supreme Court held that when race is the predominant factor in drawing district lines — to the point that the district''s shape is ''bizarre'' or ''highly irregular'' — the redistricting is subject to strict scrutiny. The government must show a compelling interest and that the plan is narrowly tailored. Merely complying with the VRA may not be enough if race was the overriding criterion.', 'Equal Protection — Racial Gerrymandering / Shaw v. Reno', 'Shaw v. Reno (1993)', true),
  ('con-law-001', 'equal_protection', 'easy', 'Under rational basis review (the default standard), a law survives equal protection challenge if:',
   'The government proves the law serves a compelling interest and is narrowly tailored.', 'The government proves the classification is necessary to achieve its goal.', 'The classification is substantially related to an important government interest.', 'The law is rationally related to a legitimate government interest.',
   'D', 'Rational basis is the default standard of equal protection review. The law need only be rationally related to a legitimate government interest. The government does not need to prove the interest existed or articulate it — courts will hypothesize any conceivable legitimate interest. This is a very deferential standard, and laws almost always survive it.', 'Equal Protection — Rational Basis Standard of Review', NULL, true),
  ('con-law-001', 'equal_protection', 'hard', 'A government affirmative action plan for federal contractor set-asides based on race is challenged. The Court applies:',
   'No scrutiny — the federal government has broad spending power.', 'Rational basis — remedying past discrimination is a legitimate government interest.', 'Strict scrutiny — racial classifications by the federal government are subject to the same standard as state classifications.', 'Intermediate scrutiny — the government may use race to remedy general societal discrimination.',
   'C', 'Adarand Constructors v. Pena (1995): the Supreme Court held that all racial classifications by any government actor — federal, state, or local — are subject to strict scrutiny. Federal affirmative action programs must serve a compelling government interest and be narrowly tailored. The government must point to specific, identified discrimination — not general societal discrimination — to justify the program.', 'Equal Protection — Federal Affirmative Action / Strict Scrutiny (Adarand)', 'Adarand Constructors v. Pena (1995)', true),
  ('con-law-001', 'equal_protection', 'medium', 'A law requires that persons of Japanese ancestry be relocated to internment camps during wartime. The law is challenged under equal protection. In Korematsu v. United States, the Court:',
   'Declared the question a non-justiciable political question.', 'Upheld the law under strict scrutiny, finding a compelling national security interest.', 'Applied rational basis, deferring to military judgment.', 'Struck down the law under strict scrutiny — race classifications are presumptively invalid.',
   'B', 'Korematsu v. United States (1944): the Supreme Court upheld Japanese American internment, applying what it called strict scrutiny but effectively deferring to the military''s national security determination. The decision has since been universally condemned and was formally overruled in Trump v. Hawaii (2018). Korematsu remains notable for being the first case to articulate that racial classifications receive strict scrutiny.', 'Equal Protection — Korematsu / Strict Scrutiny for Race Classifications', 'Korematsu v. United States (1944)', true),
  ('con-law-001', 'equal_protection', 'hard', 'A state provides that a man is the legal father of any child born to his wife during marriage, even if DNA proves he is not the biological father. A biological father challenges his exclusion from paternity rights under equal protection. The Court is most likely to apply:',
   'Rational basis with heightened attention because the classification directly affects family relations.', 'Intermediate scrutiny — gender and illegitimacy classifications are quasi-suspect.', 'Rational basis — paternity is a legislative policy matter.', 'Strict scrutiny — parental rights are fundamental.',
   'A', 'Michael H. v. Gerald D. (1989): the Supreme Court upheld the marital presumption of paternity. The plurality applied rational basis, finding the law rationally related to protecting the sanctity of the marital family and protecting the child''s interests in stability. The case illustrates the tension between protecting family relationships and recognizing biological parenthood. The result is most consistent with deferential review for legislative judgments about family law.', 'Equal Protection — Marital Presumption of Paternity / Michael H. v. Gerald D.', 'Michael H. v. Gerald D. (1989)', true),
  ('con-law-001', 'equal_protection', 'medium', 'The Equal Protection Clause applies directly to the states through the Fourteenth Amendment. It applies to the federal government through:',
   'Congressional legislation only.', 'Direct application of the 14th Amendment to federal actors.', 'The 5th Amendment''s Due Process Clause, which courts have interpreted to include an equal protection component.', 'The 1st Amendment.',
   'C', 'Bolling v. Sharpe (1954): the Supreme Court held that the Equal Protection Clause''s principles apply to the federal government through the Fifth Amendment''s Due Process Clause (reverse incorporation). While the 14th Amendment applies only to states, Bolling held that the federal government must also treat persons equally under due process. The Court struck down racially segregated D.C. schools as the companion case to Brown v. Board.', 'Equal Protection — Bolling v. Sharpe / Fifth Amendment Reverse Incorporation', 'Bolling v. Sharpe (1954)', true),
  ('con-law-001', 'equal_protection', 'hard', 'A school district assigns students to schools based solely on race to achieve racial balance. The district argues this promotes diversity. Under Parents Involved v. Seattle School District No. 1:',
   'Race-based school assignments are subject to strict scrutiny and are unconstitutional when race is the only criterion and no individualized consideration is given.', 'Racial assignment to achieve diversity is constitutional under Grutter.', 'The assignment plan is constitutional under rational basis review.', 'School districts have broad authority to make race-conscious assignments.',
   'A', 'Parents Involved in Community Schools v. Seattle School Dist. No. 1 (2007): the Supreme Court struck down voluntary race-based school assignment plans in Seattle and Louisville. Race-based classifications by schools trigger strict scrutiny. Unlike Grutter (where race was one factor in individualized decisions), here race was the sole factor in binary assignments. This was not narrowly tailored, and the plans were unconstitutional.', 'Equal Protection — Race-Based School Assignments (Parents Involved)', 'Parents Involved v. Seattle School Dist. No. 1 (2007)', true),
  ('con-law-001', 'equal_protection', 'easy', 'Which of the following classifications triggers strict scrutiny under equal protection?',
   'Wealth.', 'Age.', 'Race.', 'Disability.',
   'C', 'Race, national origin, and alienage (with exceptions) are suspect classifications triggering strict scrutiny. Age and disability trigger only rational basis review (Massachusetts Board of Retirement v. Murgia; Cleburne). Wealth is not a suspect class (though it receives some extra attention when combined with a fundamental right). Gender and illegitimacy receive intermediate scrutiny.', 'Equal Protection — Suspect Classifications Triggering Strict Scrutiny', NULL, true),
  ('con-law-001', 'equal_protection', 'medium', 'A state law bans persons convicted of a felony from ever voting. A formerly incarcerated person challenges this as discriminatory. The law is:',
   'Unconstitutional — criminal convictions are a protected classification.', 'Constitutional only for violent felonies.', 'Constitutional — the Fourteenth Amendment explicitly permits states to abridge voting rights for participation in rebellion or other crime.', 'Unconstitutional under strict scrutiny — voting is a fundamental right.',
   'C', 'Richardson v. Ramirez (1974): the Supreme Court upheld felon disenfranchisement laws under the equal protection analysis, pointing to Section 2 of the Fourteenth Amendment, which expressly provides that voting rights may be abridged for ''participation in rebellion, or other crime.'' This explicit textual exception removes felon disenfranchisement from ordinary equal protection strict scrutiny.', 'Equal Protection — Felon Disenfranchisement (Richardson v. Ramirez)', 'Richardson v. Ramirez (1974)', true),
  ('con-law-001', 'equal_protection', 'hard', 'A city requires that any zoning change to allow a group home for persons with intellectual disabilities obtain approval from 60% of neighboring property owners — a requirement not imposed on other uses. This:',
   'Violates equal protection — it requires a more difficult political process specifically for disfavored groups.', 'Is constitutional under rational basis — neighbors'' concerns are a legitimate government interest.', 'Is constitutional — neighbors have standing to veto zoning changes.', 'Violates substantive due process only.',
   'A', 'Cleburne Living Center (1985) and Hunter v. Erickson (1969): requiring a special vote or heightened approval process for a disfavored group — while not requiring it for comparable uses — restructures the political process to burden that group. This violates equal protection because it makes it harder for persons with disabilities to use the same processes available to others seeking similar land uses.', 'Equal Protection — Political Process Restructuring / Cleburne', 'City of Cleburne v. Cleburne Living Center (1985)', true),
  ('con-law-001', 'first_amendment', 'easy', 'A law criminalizes all speech that is ''offensive'' to the listener. The law is:',
   'Constitutional if the speech is also obscene.', 'Constitutional — states may protect people from offensive speech.', 'Unconstitutional only if the speech involves a matter of public concern.', 'Unconstitutional — the government may not ban speech simply because it is offensive.',
   'D', 'Matal v. Tam (2017); Snyder v. Phelps (2011): the government may not restrict speech simply because it is offensive. The First Amendment protects even deeply offensive speech on matters of public concern. Only narrow, well-defined categories — obscenity, incitement to imminent lawless action, true threats, fighting words — may be restricted.', 'First Amendment — No Ban on Offensive Speech', 'Snyder v. Phelps (2011)', true),
  ('con-law-001', 'first_amendment', 'medium', 'Under Brandenburg v. Ohio, the government may punish incitement to violence when the speech:',
   'Is directed to inciting imminent lawless action AND is likely to produce such action.', 'Is uttered by a person with a criminal record.', 'Causes serious emotional distress.', 'Has a tendency to cause unlawful action.',
   'A', 'Brandenburg v. Ohio (1969) replaced the old ''clear and present danger'' test. The First Amendment protects advocacy of illegal action unless: (1) the speech is directed to inciting or producing imminent lawless action, AND (2) the speech is likely to produce such action. Both elements must be present. This is a very high bar — abstract advocacy of violence or illegality is protected.', 'First Amendment — Brandenburg Incitement Test', 'Brandenburg v. Ohio (1969)', true),
  ('con-law-001', 'first_amendment', 'hard', 'A city ordinance prohibits all speech in a public park after 8pm. The ordinance is challenged. The strongest constitutional argument against it is:',
   'The ordinance violates the Establishment Clause by silencing religious speech.', 'The content-based restriction fails strict scrutiny.', 'Public parks are non-public forums and speech there is unprotected.', 'Even a content-neutral time-place-manner restriction must leave open alternative channels — an all-night ban may be unconstitutionally broad.',
   'D', 'Public parks are traditional public forums, receiving the highest First Amendment protection. Content-neutral time, place, and manner restrictions are constitutional if they (1) are content-neutral, (2) serve a significant government interest, (3) are narrowly tailored, and (4) leave open ample alternative channels for communication. A blanket 8pm-sunrise ban might fail the narrow tailoring requirement or not leave adequate alternative channels.', 'First Amendment — Traditional Public Forum / Time-Place-Manner Restrictions', NULL, true),
  ('con-law-001', 'first_amendment', 'medium', 'A state law requires anyone operating a pamphleteering campaign to disclose their identity. Anonymous pamphleteering is protected because:',
   'Anonymous speech is a form of expression protected by the First Amendment; forced disclosure may deter speech.', 'Identification requirements are always unconstitutional prior restraints.', 'The law restricts a political activity, which receives absolute protection.', 'Anonymous speech is protected only online, not in print.',
   'A', 'McIntyre v. Ohio Elections Commission (1995): the Supreme Court held that anonymous political pamphleteering is a form of expression protected by the First Amendment. The government cannot require speakers to identify themselves, because forced disclosure may deter constitutionally protected speech. Anonymity has a long historical tradition in political discourse (e.g., The Federalist Papers).', 'First Amendment — Anonymous Speech / McIntyre v. Ohio', 'McIntyre v. Ohio Elections Comm''n (1995)', true),
  ('con-law-001', 'first_amendment', 'hard', 'A federal law prohibits the burning of draft cards. A protester burns his draft card to protest the Vietnam War. The Court applies:',
   'Intermediate scrutiny — the O''Brien test for regulations of expressive conduct.', 'No scrutiny — the draft card belongs to the government.', 'Rational basis because the law is content-neutral.', 'Strict scrutiny because draft card burning is political speech.',
   'A', 'United States v. O''Brien (1968): when a law regulates conduct that has a communicative element (expressive conduct), the government may regulate it if: (1) the law is within the government''s constitutional power, (2) it furthers a substantial or important government interest, (3) the interest is unrelated to the suppression of expression, and (4) the restriction on First Amendment freedoms is no greater than essential. The draft card law passed this test.', 'First Amendment — O''Brien Test for Expressive Conduct', 'United States v. O''Brien (1968)', true),
  ('con-law-001', 'first_amendment', 'medium', 'A state law forbids flying the Confederate flag in public. A citizen challenges the law under the First Amendment. The law is:',
   'Constitutional — the government may restrict symbols of racial oppression.', 'Constitutional under the fighting words doctrine.', 'Unconstitutional only if the flag is displayed at home.', 'Unconstitutional — the government may not ban the display of a symbol based on its message.',
   'D', 'R.A.V. v. City of St. Paul (1992): the government cannot restrict speech based on its viewpoint or message, even hateful ones. The First Amendment protects the display of offensive symbols, including flag burning (Texas v. Johnson, 1989) and the Confederate flag. The only exception is if the expression falls within an unprotected category and the law targets a subset of that category.', 'First Amendment — No Viewpoint Discrimination / Offensive Symbols', 'Texas v. Johnson (1989)', true),
  ('con-law-001', 'first_amendment', 'hard', 'A content-based restriction on speech is subject to:',
   'Rational basis — the government may regulate speech when it has a legitimate interest.', 'Strict scrutiny — the law must be narrowly tailored to serve a compelling government interest.', 'The O''Brien test.', 'Intermediate scrutiny — the government must show a substantial interest.',
   'B', 'Reed v. Town of Gilbert (2015): content-based restrictions on speech — those that depend on the message conveyed — are presumptively unconstitutional and subject to strict scrutiny. The government bears the burden of proving the law serves a compelling interest and is narrowly tailored (least restrictive means). Very few content-based restrictions survive strict scrutiny.', 'First Amendment — Content-Based Restrictions / Strict Scrutiny (Reed v. Gilbert)', 'Reed v. Town of Gilbert (2015)', true),
  ('con-law-001', 'first_amendment', 'medium', 'A school punishes a student for wearing a black armband to protest the Vietnam War. Under Tinker v. Des Moines, the school action is:',
   'Unconstitutional — students do not shed their constitutional rights at the schoolhouse gate; expression may be restricted only if it substantially disrupts school operations.', 'Unconstitutional only if the student was punished off-campus.', 'Constitutional — the armband was disruptive to the learning environment.', 'Constitutional — schools may regulate any student expression on school grounds.',
   'A', 'Tinker v. Des Moines Independent Community School District (1969): students retain First Amendment rights in school. School officials may only restrict student speech when they can reasonably forecast it will cause substantial disruption to school operations or invade the rights of others. Mere discomfort or unpopularity of the message is insufficient. Wearing a silent armband without disruption was protected.', 'First Amendment — Student Speech in Schools (Tinker)', 'Tinker v. Des Moines (1969)', true),
  ('con-law-001', 'first_amendment', 'hard', 'A city grants permits to march in a parade to some groups but denies them to others based on their political message. The permit system is:',
   'Constitutional — cities may control traffic in public spaces.', 'A lawful content-neutral time-place-manner restriction.', 'Constitutional if the city has an important interest in maintaining order.', 'A prior restraint subject to strict scrutiny — permit systems for expression must be content-neutral with clear standards and prompt review.',
   'D', 'Shuttlesworth v. City of Birmingham (1969) and subsequent cases: permit requirements for expression are prior restraints — constitutional only if they contain narrow, objective, and definite standards that do not allow unbridled discretion to deny permits. Officials cannot deny permits based on the content of the message. A permit system that allows viewpoint-based denials is an unconstitutional prior restraint.', 'First Amendment — Permit Systems / Prior Restraints', 'Shuttlesworth v. City of Birmingham (1969)', true),
  ('con-law-001', 'first_amendment', 'medium', 'A tabloid newspaper publishes private (but accurate) facts about a private individual''s past drug addiction, which is no longer newsworthy. The individual sues for invasion of privacy. The newspaper argues:',
   'The First Amendment may protect true statements on matters of public concern, but a private person''s past addiction with no current newsworthiness may not be fully protected.', 'Accurate facts about private individuals are never actionable.', 'The truth is always a complete constitutional defense to any privacy claim.', 'Privacy claims are never constitutionally cognizable against media defendants.',
   'A', 'Cox Broadcasting Corp. v. Cohn (1975) and Florida Star v. B.J.F. (1989): the Court has protected truthful publication of information lawfully obtained from public records. However, private facts — those involving matters of purely private concern, not of public interest — may not receive full First Amendment protection. The First Amendment does not necessarily shield media from liability for disclosing private, non-newsworthy accurate information.', 'First Amendment — Truth vs. Privacy / Private Facts Doctrine', 'Cox Broadcasting Corp. v. Cohn (1975)', true),
  ('con-law-001', 'first_amendment', 'hard', 'A law prohibits distributing material that depicts actual children engaged in sexual conduct (child pornography). A defendant distributes digitally created (virtual) child pornography with no actual children involved. The law as applied to virtual CSAM is:',
   'Unconstitutional — the government may only restrict speech using actual children; virtual CSAM with no real victims is protected.', 'Constitutional — virtual child pornography is as harmful as actual CSAM.', 'Constitutional because obscenity is unprotected.', 'Constitutional if it meets the Miller obscenity test.',
   'A', 'Ashcroft v. Free Speech Coalition (2002): the Supreme Court struck down the federal law''s extension to virtual child pornography (no real children used). The Court held that actual child pornography (New York v. Ferber) is prohibited because its production harms real children. Virtual CSAM, with no real children involved, cannot be restricted on that basis. The law was overbroad. Only material meeting the Miller obscenity test can be restricted if no real children were used.', 'First Amendment — Virtual Child Pornography / Ashcroft v. Free Speech Coalition', 'Ashcroft v. Free Speech Coalition (2002)', true),
  ('con-law-001', 'first_amendment', 'medium', 'Under the Establishment Clause, a government action violates the Constitution if it:',
   'Requires any mention of religion in public discourse.', 'Has a primary effect of advancing or inhibiting religion, or involves excessive government entanglement with religion (Lemon test factors).', 'Treats religion and non-religion differently in any way.', 'Allows any religious group to use public resources.',
   'B', 'Lemon v. Kurtzman (1971) established the three-part Lemon test: (1) the law must have a secular purpose, (2) its principal effect must neither advance nor inhibit religion, and (3) it must not foster excessive government entanglement with religion. While the Court has moved away from strict Lemon application (Kennedy v. Bremerton School District, 2022, adopted a ''historical practices and understandings'' test), the Lemon factors remain relevant to most Establishment Clause analysis on the MBE.', 'Establishment Clause — Lemon Test', 'Lemon v. Kurtzman (1971)', true),
  ('con-law-001', 'first_amendment', 'hard', 'A public school''s policy requires all students to recite a prayer at the beginning of each school day. This:',
   'Is constitutional as long as the prayer is non-denominational.', 'Violates the Establishment Clause — school-sponsored prayer is unconstitutional in public schools.', 'Is constitutional if parents may opt their children out.', 'Is constitutional because the school is not compelling belief.',
   'B', 'Engel v. Vitale (1962) and Abington School District v. Schempp (1963): state-sponsored prayer or Bible readings in public schools violate the Establishment Clause. Even non-denominational or ''voluntary'' prayers organized by school authorities impermissibly advance religion. The Court emphasized that indirect coercion and the captive school environment make even ''voluntary'' prayers constitutionally problematic.', 'Establishment Clause — School-Sponsored Prayer (Engel v. Vitale)', 'Engel v. Vitale (1962)', true),
  ('con-law-001', 'first_amendment', 'medium', 'A state law requires science teachers in public schools to teach ''creation science'' alongside evolution. The law is challenged under the Establishment Clause. The law is:',
   'Constitutional because it promotes academic freedom.', 'Unconstitutional under the Free Exercise Clause.', 'Constitutional — creation science is a legitimate scientific theory.', 'Unconstitutional — the law lacks a secular purpose; it advances a religious doctrine.',
   'D', 'Edwards v. Aguillard (1987): the Supreme Court struck down Louisiana''s Creationism Act. The law failed the Lemon test''s first prong — secular purpose — because creation science is a religious concept, not a scientific one. The law''s stated purpose of promoting academic freedom was a sham; its actual purpose was to advance a particular religious viewpoint.', 'Establishment Clause — Teaching Creationism in Public Schools (Edwards v. Aguillard)', 'Edwards v. Aguillard (1987)', true),
  ('con-law-001', 'first_amendment', 'hard', 'The government denies a religious student organization campus recognition, which is available to other non-religious student groups. Under Rosenberger v. University of Virginia, this is:',
   'Unconstitutional viewpoint discrimination — the government cannot exclude religious groups from a public benefit available to secular groups.', 'Constitutional if the school has a compelling interest in avoiding religious entanglement.', 'Constitutional — the government need not fund or recognize religious groups.', 'Constitutional under the Establishment Clause — funding religion violates the First Amendment.',
   'A', 'Rosenberger v. University of Virginia (1995): the University''s exclusion of religious viewpoints from a student activity fund open to secular groups constituted viewpoint discrimination violating the Free Speech Clause. The Court held that the government may not selectively exclude religious speech from a generally available benefit program. Providing equal access to religious groups does not violate the Establishment Clause.', 'First Amendment — Viewpoint Discrimination / Equal Access for Religious Groups (Rosenberger)', 'Rosenberger v. University of Virginia (1995)', true),
  ('con-law-001', 'first_amendment', 'medium', 'A state requires pharmacists to dispense contraceptives regardless of their religious objections. The pharmacist challenges the law under the Free Exercise Clause. The law is:',
   'Unconstitutional unless the state provides a religious exemption.', 'Unconstitutional — it burdens religious practice and requires strict scrutiny.', 'Constitutional only if the government has a compelling interest.', 'Constitutional — neutral, generally applicable laws do not require religious exemptions under Employment Division v. Smith.',
   'D', 'Employment Division v. Smith (1990): the Supreme Court held that neutral, generally applicable laws that incidentally burden religious practice do not violate the Free Exercise Clause. No religious exemption is required unless the law (1) specifically targets religious conduct or (2) is not generally applicable (it has secular exemptions but not religious ones). A pharmacy dispensing law that applies to all pharmacists regardless of religion is neutral and generally applicable.', 'Free Exercise Clause — Neutral Generally Applicable Laws (Employment Division v. Smith)', 'Employment Division v. Smith (1990)', true),
  ('con-law-001', 'first_amendment', 'hard', 'A city denies a church a permit to expand its building under neutral zoning rules. The church argues the Religious Land Use and Institutionalized Persons Act (RLUIPA) protects them. Under RLUIPA, the church:',
   'Must exhaust administrative remedies before bringing any constitutional claim.', 'Must show the permit denial was specifically targeted at religion.', 'May challenge the denial if the land use law substantially burdens religious exercise and the government cannot show a compelling interest served in the least restrictive way.', 'Has no greater rights than any other landowner under the First Amendment.',
   'C', 'RLUIPA (42 U.S.C. § 2000cc) provides broader protection than the First Amendment under Employment Division v. Smith by requiring strict scrutiny whenever a government regulation substantially burdens religious exercise in the land use context, whether or not the law is neutral and generally applicable. This statute effectively requires the compelling-interest and least-restrictive-means analysis that Smith no longer requires under the First Amendment.', 'Free Exercise / RLUIPA — Land Use Regulations and Religious Institutions', NULL, true),
  ('con-law-001', 'first_amendment', 'medium', 'A public university provides meeting space to student clubs. It allows all groups to use the space except religious groups. The university''s policy is:',
   'Unconstitutional only if the religious group pays student fees.', 'Constitutional under the Establishment Clause — the university may not advance religion.', 'Constitutional because the university may choose which groups to recognize.', 'Unconstitutional — excluding only religious groups from an open forum is viewpoint discrimination.',
   'D', 'Widmar v. Vincent (1981): when a public university opens its facilities to student groups generally, it creates a limited public forum. Excluding religious groups from this forum constitutes viewpoint discrimination violating the Free Speech Clause. The Establishment Clause does not require — and does not permit — discriminating against religious speech in a generally open forum.', 'First Amendment — Equal Access / Limited Public Forum for Student Groups (Widmar)', 'Widmar v. Vincent (1981)', true),
  ('con-law-001', 'first_amendment', 'hard', 'A state law makes it a crime to engage in ''symbolic speech that denigrates national symbols.'' A defendant is convicted for burning an American flag in protest. The conviction is:',
   'Constitutional — flag burning is conduct, not speech.', 'Unconstitutional — burning the flag in political protest is protected expressive conduct.', 'Constitutional — the government has a compelling interest in protecting national symbols.', 'Constitutional under the O''Brien test for expressive conduct.',
   'B', 'Texas v. Johnson (1989): the Supreme Court held that burning an American flag in political protest is protected symbolic speech under the First Amendment. The O''Brien test failed because the law specifically targeted the suppression of the flag-burning message (it was content-based). The government''s interest in protecting the flag as a national symbol cannot justify suppressing political expression.', 'First Amendment — Flag Burning / Protected Symbolic Speech (Texas v. Johnson)', 'Texas v. Johnson (1989)', true),
  ('con-law-001', 'first_amendment', 'medium', 'A state law restricts campaign contributions to state elections to $1,000 per individual per candidate. The restriction is challenged under the First Amendment. The law is:',
   'Constitutional — reasonable limits on campaign contributions are permissible to prevent corruption or its appearance.', 'Unconstitutional — political contributions are pure speech subject to strict scrutiny.', 'Unconstitutional because money is property, not speech.', 'Constitutional because elections are a government function the state may regulate freely.',
   'A', 'Buckley v. Valeo (1976): the Supreme Court upheld contribution limits as constitutional to prevent corruption and its appearance — a sufficiently important government interest. However, independent expenditure limits are unconstitutional because they restrict pure speech. Citizens United v. FEC (2010) extended First Amendment protection to corporate political speech but addressed expenditures, not direct contributions.', 'First Amendment — Campaign Contribution Limits (Buckley v. Valeo)', 'Buckley v. Valeo (1976)', true),
  ('con-law-001', 'first_amendment', 'hard', 'A government employee is fired after making a public statement criticizing the agency''s budget policies. The employee claims a First Amendment violation. Under Garcetti v. Ceballos, the employee''s claim:',
   'Succeeds — government employees have the same First Amendment rights as any citizen.', 'Succeeds if the statement concerned a matter of public concern.', 'Fails — government employees have no First Amendment rights in the workplace.', 'Fails if the statement was made pursuant to the employee''s official duties, not as a citizen on a matter of public concern.',
   'D', 'Garcetti v. Ceballos (2006): when a government employee speaks pursuant to their official duties, the government may discipline them without First Amendment scrutiny. Only speech made as a citizen on a matter of public concern (not in the employee''s official capacity) receives First Amendment protection under the Pickering balancing test. The distinction between speech as a citizen vs. speech as an employee is critical.', 'First Amendment — Government Employee Speech (Garcetti / Pickering)', 'Garcetti v. Ceballos (2006)', true),
  ('con-law-001', 'first_amendment', 'medium', 'A law requires all advocacy organizations receiving government funds to have an explicit policy opposing sex work. The organizations challenge this as compelled speech. The law is:',
   'Constitutional if the condition serves a legitimate government purpose.', 'Unconstitutional — the government may not require funding recipients to adopt a specific ideological position as a condition of receiving unrelated funds.', 'Unconstitutional only if the organization actually opposes sex work.', 'Constitutional — the government may attach conditions to its funding.',
   'B', 'Agency for International Development v. Alliance for Open Society International (2013): the Supreme Court struck down a condition requiring organizations to adopt a policy opposing sex work to receive government funding. While the government may impose conditions related to the funded program, it may not compel organizations to adopt particular viewpoints on topics outside the scope of the funded activity. This crosses from defining the program''s parameters into compelling speech.', 'First Amendment — Compelled Speech / Government Funding Conditions (AOSI)', 'Agency for Int''l Development v. Alliance for Open Society Int''l (2013)', true),
  ('con-law-001', 'first_amendment', 'easy', 'A statute prohibits ''fighting words'' — face-to-face insults likely to provoke the average person to an immediate breach of the peace. This category of speech is:',
   'Fully protected by the First Amendment.', 'Protected unless the speaker intended to provoke a fight.', 'Unprotected — fighting words are a recognized exception to First Amendment protection.', 'Protected unless the listener is actually provoked.',
   'C', 'Chaplinsky v. New Hampshire (1942): the Supreme Court established that ''fighting words'' — face-to-face insults that by their very utterance inflict injury or tend to incite an immediate breach of the peace — are not protected by the First Amendment. The Court held that such utterances have little social value and are outweighed by the interest in order and morality. However, subsequent cases have narrowed this doctrine significantly.', 'First Amendment — Fighting Words Doctrine (Chaplinsky)', 'Chaplinsky v. New Hampshire (1942)', true),
  ('con-law-001', 'first_amendment', 'hard', 'A state law bars ''hate speech'' directed at persons based on their sexual orientation, even in private conversations. The law is:',
   'Constitutional under intermediate scrutiny as a content-neutral regulation.', 'Constitutional if the speech also qualifies as fighting words.', 'Unconstitutional — there is no hate speech exception to the First Amendment; viewpoint-based restrictions are unconstitutional.', 'Constitutional — states may protect victims of hate speech.',
   'C', 'Matal v. Tam (2017); R.A.V. v. City of St. Paul (1992): the Supreme Court has consistently held that the government may not restrict speech based on its viewpoint, including speech that expresses hatred toward groups. There is no separate ''hate speech'' exception to the First Amendment. Even speech targeting people based on protected characteristics is protected unless it falls into another recognized exception (e.g., true threats, incitement, fighting words).', 'First Amendment — No Hate Speech Exception (Matal v. Tam; R.A.V.)', 'Matal v. Tam (2017)', true),
  ('con-law-001', 'first_amendment', 'medium', 'A state law requires all charities soliciting donations to spend at least 75% of donations on their charitable purpose. The law is challenged. The First Amendment:',
   'Permits the law because spending requirements are content-neutral regulations.', 'Protects charitable solicitation as a form of expressive activity; the spending requirement is not sufficiently justified.', 'Provides no protection — charitable solicitation is purely commercial.', 'Permits the law because the government may regulate fraud.',
   'B', 'Riley v. National Federation of the Blind of North Carolina (1988): charitable solicitation is protected by the First Amendment because it is inextricably intertwined with expression and the exercise of freedom of association. A mandatory percentage spending requirement imposes a content-based restriction that is not narrowly tailored. While states may regulate fraudulent solicitation, blanket percentage requirements are too blunt.', 'First Amendment — Charitable Solicitation as Protected Speech (Riley)', 'Riley v. National Federation of the Blind (1988)', true),
  ('con-law-001', 'incorporation_14th', 'easy', 'The Fourteenth Amendment''s Due Process Clause ''incorporates'' Bill of Rights provisions against the states. Under selective incorporation:',
   'Only rights specifically mentioned in the 14th Amendment apply to the states.', 'States are exempt from all federal constitutional limitations.', 'Fundamental rights implicit in ordered liberty are incorporated one by one and apply to the states.', 'The entire Bill of Rights applies to the states automatically.',
   'C', 'The doctrine of selective incorporation holds that the Due Process Clause of the Fourteenth Amendment makes certain — but not all — provisions of the Bill of Rights applicable to the states. A right is incorporated if it is fundamental to ordered liberty and deeply rooted in the nation''s history and tradition (Palko v. Connecticut, 1937; McDonald v. City of Chicago, 2010). Today, most Bill of Rights provisions are incorporated.', 'Incorporation Doctrine — Selective Incorporation via 14th Amendment', 'Palko v. Connecticut (1937)', true),
  ('con-law-001', 'incorporation_14th', 'medium', 'Which Bill of Rights provision has NOT been incorporated against the states?',
   'The Fifth Amendment privilege against self-incrimination.', 'The Fifth Amendment requirement of grand jury indictment for felonies.', 'The Eighth Amendment prohibition on cruel and unusual punishment.', 'The Sixth Amendment right to counsel.',
   'B', 'Hurtado v. California (1884): the Fifth Amendment''s grand jury indictment requirement is one of the few Bill of Rights provisions that has NOT been incorporated against the states. States may use a preliminary hearing or information instead. Other unincorporated provisions include: the Third Amendment (quartering soldiers), the Seventh Amendment (civil jury trials over $20), and excessive fines (partially addressed in Timbs v. Indiana, 2019).', 'Incorporation — Grand Jury Indictment Not Incorporated (Hurtado)', 'Hurtado v. California (1884)', true),
  ('con-law-001', 'incorporation_14th', 'hard', 'The Second Amendment right to keep and bear arms was incorporated against the states in:',
   'District of Columbia v. Heller (2008) — applied against the federal government.', 'McDonald v. City of Chicago (2010) — incorporated via the 14th Amendment.', 'New York State Rifle & Pistol Association v. Bruen (2022) — applied to public carry.', 'The Second Amendment applies to states via the Privileges or Immunities Clause only.',
   'B', 'McDonald v. City of Chicago (2010): the Supreme Court incorporated the Second Amendment against the states through the Due Process Clause of the Fourteenth Amendment. Heller (2008) had already held that the Second Amendment protects an individual right to keep arms in the home for self-defense, but that case arose in D.C. (a federal enclave). McDonald extended that right against state and local governments.', 'Incorporation — Second Amendment Incorporated (McDonald v. Chicago)', 'McDonald v. City of Chicago (2010)', true),
  ('con-law-001', 'incorporation_14th', 'medium', 'The Fourteenth Amendment''s Section 1 contains two clauses that protect individual rights against state action. They are:',
   'The Due Process Clause and the Equal Protection Clause (plus the Privileges or Immunities Clause, largely rendered meaningless by the Slaughterhouse Cases).', 'The Privileges or Immunities Clause and the Equal Protection Clause only.', 'The Establishment Clause and the Due Process Clause.', 'The Commerce Clause and the Due Process Clause.',
   'A', 'Section 1 of the 14th Amendment contains: the Privileges or Immunities Clause (''no state shall make or enforce any law which shall abridge the privileges or immunities of citizens''), the Due Process Clause (''nor shall any State deprive any person of life, liberty, or property, without due process of law''), and the Equal Protection Clause (''nor deny to any person within its jurisdiction the equal protection of the laws''). The Slaughterhouse Cases (1873) gutted the Privileges or Immunities Clause, making due process and equal protection the workhorses of modern constitutional litigation.', '14th Amendment — Section 1 Clauses / Slaughterhouse Cases', 'Slaughterhouse Cases (1873)', true),
  ('con-law-001', 'incorporation_14th', 'hard', 'A state law bans integrated (racially mixed) public schools. Under Brown v. Board of Education, this law:',
   'Is constitutional under Plessy v. Ferguson''s ''separate but equal'' doctrine.', 'Is constitutional if the facilities are actually equal.', 'Violates the Privileges or Immunities Clause only.', 'Violates the Equal Protection Clause — separate educational facilities are inherently unequal.',
   'D', 'Brown v. Board of Education (1954): the Supreme Court unanimously overruled Plessy v. Ferguson''s ''separate but equal'' doctrine in the context of public education. The Court held that separate educational facilities are inherently unequal and violate the Equal Protection Clause of the Fourteenth Amendment. The decision triggered the modern civil rights movement and the dismantling of Jim Crow laws.', 'Equal Protection / 14th Amendment — School Segregation (Brown v. Board)', 'Brown v. Board of Education (1954)', true),
  ('con-law-001', 'incorporation_14th', 'medium', 'Section 5 of the Fourteenth Amendment grants Congress the power to:',
   'Create new constitutional rights beyond those in the Fourteenth Amendment.', 'Enforce the provisions of the Fourteenth Amendment by appropriate legislation.', 'Override Supreme Court decisions interpreting the Fourteenth Amendment.', 'Interpret the Fourteenth Amendment for the states.',
   'B', 'Section 5 of the 14th Amendment grants Congress the power to ''enforce, by appropriate legislation, the provisions of this article.'' However, in City of Boerne v. Flores (1997), the Supreme Court held that Section 5 power is remedial — Congress may only enforce rights, not define or expand them. Congress must identify unconstitutional conduct and adopt congruent and proportional remedies.', '14th Amendment — Section 5 Enforcement Power (City of Boerne v. Flores)', 'City of Boerne v. Flores (1997)', true),
  ('con-law-001', 'incorporation_14th', 'hard', 'A private company discriminates based on race against its customers. The Fourteenth Amendment''s Equal Protection Clause:',
   'Applies if the business is regulated by the government.', 'Does not apply — the Fourteenth Amendment only restricts state action, not private conduct.', 'Applies — any business open to the public must comply.', 'Applies through the incorporation doctrine.',
   'B', 'The Civil Rights Cases (1883): the Fourteenth Amendment restricts state action — it prohibits government entities (states, cities, agencies, public officials acting under color of state law) from engaging in certain conduct. It does not directly regulate private actors. Congress may regulate private discrimination through its Commerce Clause or Section 5 enforcement powers (e.g., Title II of the Civil Rights Act of 1964), but the Equal Protection Clause itself applies only to state actors.', '14th Amendment — State Action Requirement (Civil Rights Cases)', 'Civil Rights Cases (1883)', true),
  ('con-law-001', 'incorporation_14th', 'medium', 'A state official is sued under 42 U.S.C. § 1983 for violating a person''s constitutional rights. Section 1983 requires the plaintiff to show:',
   'Deprivation of a right secured by the Constitution or federal law, under color of state law.', 'Only that a constitutional right was violated.', 'Proof of an official policy or custom of the government entity.', 'Intentional discrimination.',
   'A', '42 U.S.C. § 1983 provides a civil remedy for persons whose constitutional rights are violated by persons acting ''under color of state law.'' The elements are: (1) the defendant acted under color of state law, and (2) the defendant''s conduct deprived the plaintiff of a right secured by the Constitution or federal law. § 1983 was enacted pursuant to Section 5 of the Fourteenth Amendment to enforce constitutional protections against state actors.', '14th Amendment — § 1983 Civil Rights Claims', NULL, true),
  ('con-law-001', 'incorporation_14th', 'hard', 'Under the state action doctrine, which of the following is NOT state action for constitutional purposes?',
   'A private club that receives no government funding or regulation discriminating based on race.', 'A state court enforcing a racially restrictive covenant.', 'A company town that performs all the functions of government.', 'A private actor performing a public function traditionally exclusively reserved to the state.',
   'A', 'The state action doctrine requires that constitutional violations be attributable to the government. Private actors are not bound by most constitutional provisions. However, state action may be found when: (1) a private actor performs an exclusively public function (Marsh v. Alabama, 1946), (2) the state significantly entangles itself with private discrimination (Shelley v. Kraemer, 1948 — court enforcement of racist covenants), or (3) the government compels private discrimination. A private club with no government involvement is purely private.', 'State Action — Public Function / Entanglement Exceptions', 'Shelley v. Kraemer (1948)', true),
  ('con-law-001', 'incorporation_14th', 'medium', 'Congress passes the Religious Freedom Restoration Act (RFRA), requiring the federal government to apply strict scrutiny before substantially burdening religious exercise. RFRA is:',
   'Constitutional as applied to both federal and state governments under Section 5.', 'Constitutional as applied to the federal government — Congress may impose higher standards on itself.', 'Unconstitutional — RFRA exceeds Congress''s Article I powers.', 'Unconstitutional as applied to states — Congress may not define constitutional standards for states via Section 5.',
   'B', 'City of Boerne v. Flores (1997): RFRA was held unconstitutional as applied to the states because Congress was not enforcing existing constitutional violations but creating new rights beyond the First Amendment (under Employment Division v. Smith). However, RFRA remains valid as applied to the federal government as a statute limiting federal action. Congress may set higher standards for itself beyond constitutional requirements.', 'RFRA — Constitutional as Applied to Federal Government / Unconstitutional as Applied to States (Boerne)', 'City of Boerne v. Flores (1997)', true),
  ('con-law-001', 'incorporation_14th', 'hard', 'A state adopts a constitutional amendment stripping the courts of any authority to order school desegregation. This amendment is challenged under the Fourteenth Amendment. The amendment:',
   'Violates the Fourteenth Amendment — a state may not restructure its political processes to prevent racial minorities from obtaining relief that others can seek.', 'Is constitutional because school segregation is a political question.', 'Is constitutional — states control their own courts.', 'Violates the Supremacy Clause only.',
   'A', 'Hunter v. Erickson (1969) and Washington v. Seattle School District (1982): the Fourteenth Amendment prohibits states from restructuring their decision-making processes to prevent racial minorities from achieving outcomes that other groups can seek through normal political channels. If a state strips a particular institution of authority to address racial discrimination while leaving that authority for other purposes, it violates equal protection.', '14th Amendment — Political Process Restructuring to Burden Racial Minorities', 'Hunter v. Erickson (1969)', true),
  ('con-law-001', 'incorporation_14th', 'medium', 'Congress passes a law abrogating state sovereign immunity and allowing states to be sued in federal court for ADA violations. Congress relied on Section 5 of the Fourteenth Amendment. This is:',
   'Constitutional because the ADA protects disabled persons who are a suspect class.', 'Unconstitutional — the Eleventh Amendment bars all suits against states.', 'Constitutional — Congress may abrogate sovereign immunity under any of its Article I powers.', 'Constitutional under Section 5 if Congress identifies a pattern of unconstitutional discrimination and the remedy is congruent and proportional.',
   'D', 'Board of Trustees v. Garrett (2001): Congress may abrogate state sovereign immunity through Section 5 of the Fourteenth Amendment if there is (1) a clear congressional statement, (2) identification of a pattern of unconstitutional state conduct, and (3) remedies congruent and proportional to the violations. Title I of the ADA failed because Congress did not identify sufficient evidence of unconstitutional discrimination by states against disabled employees.', '14th Amendment — Section 5 / Abrogation of State Sovereign Immunity (Garrett)', 'Board of Trustees v. Garrett (2001)', true),
  ('con-law-001', 'incorporation_14th', 'hard', 'Under Batson v. Kentucky, a prosecutor''s use of peremptory challenges based on race violates:',
   'The Fifth Amendment privilege against self-incrimination.', 'The Sixth Amendment right to a jury of one''s peers.', 'The Equal Protection Clause — race-based peremptory challenges are unconstitutional.', 'No constitutional provision — peremptory challenges are within prosecutorial discretion.',
   'C', 'Batson v. Kentucky (1986): the Supreme Court held that race-based peremptory challenges by prosecutors violate the Equal Protection Clause. The decision established a three-step process: (1) defendant makes prima facie showing of discrimination, (2) burden shifts to prosecution to provide race-neutral explanation, (3) court determines whether defendant has proven purposeful discrimination. Batson was extended to defense counsel (Georgia v. McCollum) and civil cases (Edmonson v. Leesville Concrete).', 'Equal Protection / 14th Amendment — Race-Based Peremptory Challenges (Batson)', 'Batson v. Kentucky (1986)', true),
  ('con-law-001', 'incorporation_14th', 'medium', 'A state provides that a criminal defendant convicted of a capital offense may be executed. On appeal, the defendant argues the jury was not instructed on a mitigating factor. The constitutional claim is grounded in:',
   'The Sixth Amendment''s right to trial by jury.', 'The Eighth Amendment''s prohibition on cruel and unusual punishment, incorporated against states.', 'The Fourteenth Amendment''s Privileges or Immunities Clause.', 'The Fifth Amendment''s Self-Incrimination Clause.',
   'B', 'Lockett v. Ohio (1978): the Eighth and Fourteenth Amendments require that the sentencer in a capital case consider all relevant mitigating circumstances. This principle is rooted in the Eighth Amendment''s bar on cruel and unusual punishment, which is incorporated against the states through the Fourteenth Amendment''s Due Process Clause. Capital punishment cannot be imposed under a scheme that prevents the consideration of relevant mitigating factors.', '8th Amendment / Incorporation — Capital Sentencing / Mitigating Factors (Lockett)', 'Lockett v. Ohio (1978)', true),
  ('con-law-001', 'incorporation_14th', 'hard', 'The Eighth Amendment prohibits cruel and unusual punishment. It has been interpreted to prohibit which of the following?',
   'Mandatory minimum sentences.', 'Execution of mentally retarded individuals, juvenile offenders, and grossly disproportionate sentences.', 'All corporal punishment in prison.', 'Any sentence of life imprisonment without the possibility of parole.',
   'B', 'The Eighth Amendment prohibits: (1) execution of intellectually disabled persons (Atkins v. Virginia, 2002), (2) execution of juvenile offenders (Roper v. Simmons, 2005), (3) life without parole for juveniles for non-homicide offenses (Graham v. Florida, 2010), and (4) grossly disproportionate sentences (Solem v. Helm). It does not categorically prohibit all corporal punishment in prison (Hudson v. McMillian holds some force is permissible) or all LWOP.', 'Eighth Amendment / Incorporation — Prohibited Punishments', 'Atkins v. Virginia (2002); Roper v. Simmons (2005)', true),
  ('con-law-001', 'incorporation_14th', 'medium', 'Which standard applies when a prisoner claims prison conditions constitute cruel and unusual punishment?',
   'Deliberate indifference — the prison official knew of and disregarded an excessive risk to inmate health or safety.', 'Negligence — any harm from prison conditions violates the Eighth Amendment.', 'Recklessness — prisons may not take unreasonable risks with prisoner safety.', 'Strict liability — prisons must provide comfortable conditions.',
   'A', 'Farmer v. Brennan (1994): an Eighth Amendment claim for prison conditions requires the plaintiff to show (1) the deprivation was objectively serious (sufficiently serious harm or risk), and (2) the prison official subjectively acted with deliberate indifference — knew of the excessive risk to inmate health or safety and deliberately disregarded it. Mere negligence is insufficient for an Eighth Amendment conditions-of-confinement claim.', 'Eighth Amendment / Incorporation — Prison Conditions / Deliberate Indifference (Farmer)', 'Farmer v. Brennan (1994)', true),
  ('con-law-001', 'incorporation_14th', 'hard', 'A state law imposes a mandatory sentence of life without parole on all juveniles convicted of homicide, regardless of individual circumstances. Under Miller v. Alabama, the law:',
   'Is constitutional — states have plenary authority over criminal sentencing.', 'Is constitutional under the Turner v. Safley standard for prison sentences.', 'Violates the Eighth Amendment — mandatory life without parole for all juvenile homicide offenders is unconstitutional.', 'Violates due process only.',
   'C', 'Miller v. Alabama (2012): the Supreme Court held that mandatory sentences of life without parole for juvenile homicide offenders violate the Eighth Amendment. The Constitution requires sentencers to consider the distinctive attributes of youth — including immaturity, vulnerability to peer pressure, and capacity for change — before imposing LWOP. A mandatory sentencing scheme that forecloses individualized consideration is unconstitutional.', 'Eighth Amendment / Incorporation — Mandatory JLWOP Unconstitutional (Miller v. Alabama)', 'Miller v. Alabama (2012)', true),
  ('con-law-001', 'incorporation_14th', 'medium', 'Which of the following rights has been incorporated through the 14th Amendment''s Due Process Clause?',
   'The Seventh Amendment right to civil jury trial.', 'The Sixth Amendment right to a speedy trial.', 'The Third Amendment right against quartering soldiers.', 'The Grand Jury Clause of the Fifth Amendment.',
   'B', 'The Sixth Amendment right to a speedy trial is incorporated against the states (Klopfer v. North Carolina, 1967). By contrast, the Grand Jury Clause of the 5th Amendment (Hurtado v. California), the Third Amendment (not formally decided but presumed not incorporated), and the Seventh Amendment civil jury right (Minneapolis & St. Louis Railroad v. Bombolis) have NOT been incorporated against the states.', 'Incorporation — Sixth Amendment Speedy Trial Incorporated; Others Not', 'Klopfer v. North Carolina (1967)', true),
  ('con-law-001', 'incorporation_14th', 'hard', 'A law provides that any person who is placed in a lineup at which the witness views the suspects and does not identify the correct person is forever immune from identification by that witness at any future lineup or in court. The law is challenged. What constitutional basis is most relevant?',
   'The Fourth Amendment prohibition on unreasonable seizures.', 'The Due Process Clause — identification procedures must comport with due process to avoid suggestiveness.', 'The Sixth Amendment right to counsel at all identification procedures.', 'The Fifth Amendment privilege against self-incrimination.',
   'B', 'Neil v. Biggers (1972) and Manson v. Brathwaite (1977): the Due Process Clause governs identification procedures. An identification may be suppressed if the procedure was unnecessarily suggestive AND there was a substantial likelihood of misidentification under the totality of the circumstances. While the Sixth Amendment right to counsel also applies at post-indictment lineups (Wade), the Due Process Clause provides the broader framework for evaluating identification procedure reliability.', '14th Amendment Due Process — Identification Procedure Reliability', 'Neil v. Biggers (1972)', true),
  ('con-law-001', 'incorporation_14th', 'medium', 'Congress enacts the Voting Rights Act, requiring states with a history of voter discrimination to obtain federal ''preclearance'' before changing voting laws. Congress relied on Section 2 (equal protection enforcement) and Section 2 of the 15th Amendment. In Shelby County v. Holder, the preclearance formula was:',
   'Struck down — the coverage formula was based on outdated data and did not reflect current conditions.', 'Struck down because the 15th Amendment does not authorize affirmative remedies.', 'Upheld — Congress has broad power to protect voting rights.', 'Upheld under the rational basis test.',
   'A', 'Shelby County v. Holder (2013): the Supreme Court struck down VRA''s Section 4(b) coverage formula (used to determine which states needed preclearance) because it was based on 40-year-old data and did not reflect current conditions. The Court held that the preclearance requirement itself was a valid exercise of congressional power (left Section 5 intact in theory), but without a valid coverage formula, preclearance could not be applied. Congress has not updated the formula since.', '14th and 15th Amendment — VRA Preclearance Formula (Shelby County v. Holder)', 'Shelby County v. Holder (2013)', true),
  ('con-law-001', 'incorporation_14th', 'easy', 'The Privileges or Immunities Clause of the Fourteenth Amendment, as interpreted since the Slaughterhouse Cases (1873), protects:',
   'All natural rights of citizens from state interference.', 'Economic rights of contract and property.', 'Only a narrow set of rights arising from national citizenship (e.g., access to federal offices, protection on the high seas).', 'The same rights as the Bill of Rights in their entirety.',
   'C', 'The Slaughterhouse Cases (1873) drastically limited the Privileges or Immunities Clause, holding it protects only rights arising from national citizenship (such as access to federal government, protection abroad, use of navigable waters). It does NOT protect the fundamental civil rights that were its apparent purpose. This decision effectively shifted the work of protecting individual rights to the Due Process and Equal Protection Clauses.', '14th Amendment — Slaughterhouse Cases / Privileges or Immunities Clause Narrowed', 'Slaughterhouse Cases (1873)', true),
  ('con-law-001', 'incorporation_14th', 'hard', 'A state constitution provides that the death penalty may be imposed without a jury finding any aggravating circumstances. A capital defendant challenges this under Ring v. Arizona. The sentencing scheme is:',
   'Unconstitutional only if the defendant requests a jury finding.', 'Unconstitutional — the Sixth Amendment requires juries to find any fact that increases the maximum sentence beyond what the jury verdict alone authorizes.', 'Constitutional because capital punishment is specifically permitted by the Fifth Amendment.', 'Constitutional — legislatures may establish sentencing factors without jury involvement.',
   'B', 'Ring v. Arizona (2002): applying Apprendi v. New Jersey (2000), the Supreme Court held that the Sixth Amendment requires a jury (not a judge) to find the aggravating factors that make a defendant eligible for the death penalty. The constitutional maximum sentence is what the jury verdict alone authorizes — any fact increasing that maximum must be found by a jury beyond a reasonable doubt, not by a judge at sentencing.', '6th Amendment / 14th Amendment — Jury Must Find Aggravating Factors in Capital Cases (Ring)', 'Ring v. Arizona (2002)', true),
  ('con-law-001', 'incorporation_14th', 'medium', 'The right against double jeopardy is incorporated against the states through the Fourteenth Amendment. Double jeopardy protects against all EXCEPT:',
   'A second prosecution for the same offense after an acquittal.', 'A second prosecution for the same offense after a conviction.', 'A retrial after a properly granted defense motion for mistrial.', 'Multiple punishments for the same offense in a single proceeding.',
   'C', 'Benton v. Maryland (1969) incorporated the Double Jeopardy Clause against the states. Double jeopardy protects against: (1) second prosecution after acquittal, (2) second prosecution after conviction, and (3) multiple punishments for the same offense. When the defendant requests or consents to a mistrial, retrial is generally not barred — the defendant is deemed to have waived the double jeopardy protection. Only when the government causes a mistrial to harass the defendant does it bar retrial.', 'Double Jeopardy / Incorporation — Defendant-Requested Mistrial Exception', 'Benton v. Maryland (1969)', true),
  ('con-law-001', 'incorporation_14th', 'medium', 'A defendant is convicted after a 10-2 non-unanimous jury verdict in a state court felony case. The defendant argues this violates the Sixth Amendment right to a jury trial. Under Ramos v. Louisiana, the verdict is:',
   'Unconstitutional — the Sixth Amendment right to jury trial, incorporated against the states, requires unanimous verdicts in felony cases.', 'Constitutional — states may require non-unanimous juries.', 'Unconstitutional only in capital cases.', 'Constitutional if the state expressly authorized non-unanimous verdicts by statute.',
   'A', 'Ramos v. Louisiana (2020): the Supreme Court held that the Sixth Amendment right to a jury trial — incorporated against the states through the Fourteenth Amendment — requires a unanimous verdict to convict a defendant of a serious crime. The Court overruled Apodaca v. Oregon (1972), which had permitted non-unanimous verdicts, holding that the Sixth Amendment''s jury right must mean the same thing in state and federal courts.', 'Sixth Amendment Incorporation — Unanimous Jury Verdict Required (Ramos v. Louisiana)', 'Ramos v. Louisiana (2020)', true),
  ('con-law-001', 'incorporation_14th', 'hard', 'The Fourth Amendment''s exclusionary rule was incorporated against the states in:',
   'Katz v. United States (1967) — established the REP test.', 'Mapp v. Ohio (1961) — incorporated against the states through the Fourteenth Amendment.', 'Weeks v. United States (1914) — applied in federal courts.', 'Terry v. Ohio (1968) — applied to investigative stops.',
   'B', 'Mapp v. Ohio (1961): the Supreme Court held that the Fourth Amendment''s exclusionary rule — which bars admission of evidence obtained through unconstitutional searches — is incorporated against the states through the Fourteenth Amendment Due Process Clause. Prior to Mapp, states were not required to exclude illegally obtained evidence. Mapp made the exclusionary rule a federal constitutional requirement in state court proceedings.', 'Exclusionary Rule Incorporation — Mapp v. Ohio', 'Mapp v. Ohio (1961)', true)
) AS v(subject_id, category, difficulty, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, rule_tested, case_citation, is_active)
WHERE NOT EXISTS (SELECT 1 FROM quiz_questions q
                  WHERE q.subject_id = v.subject_id AND q.stem = v.stem);

COMMIT;
-- ══ from 20260720000001_seed_con_law_gaps.sql ══
-- Con Law Gaps: 5th/6th Amendment, Commerce Clause, Executive Power, Takings, Incorporation
-- 75 MBE questions

BEGIN;

INSERT INTO quiz_questions
  (subject_id, category, difficulty, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, rule_tested, case_citation, is_active)
SELECT v.* FROM (VALUES
('con-law-001', 'fifth_sixth_amendment', 'easy', 'Under Miranda v. Arizona, police MUST administer Miranda warnings before custodial interrogation. Which statement about Miranda is CORRECT?',
   'Miranda warnings are required whenever police ask a question.', 'Miranda warnings are required only when a suspect is in custody and subject to interrogation.', 'A suspect who waives Miranda rights may reassert them only before confessing.', 'Miranda warnings are constitutionally required in all criminal investigations.',
   'B', 'Miranda applies only to custodial interrogation — both custody and interrogation are required. Routine non-custodial questioning does not require warnings.', 'Miranda Custody + Interrogation Requirement', 'Miranda v. Arizona (1966)', true),
  ('con-law-001', 'fifth_sixth_amendment', 'medium', 'Dan is arrested and, after receiving Miranda warnings, invokes his right to counsel. Two hours later, a different officer asks Dan about a separate crime. Dan makes incriminating statements. Are the statements admissible?',
   'Yes — the new officer''s questioning concerned a different crime.', 'Yes — two hours passed, giving Dan time to reconsider.', 'No — once counsel is invoked, all interrogation must cease until counsel is present.', 'No — the second officer did not re-administer Miranda warnings.',
   'C', 'Under Edwards v. Arizona, once a suspect invokes the right to counsel, police may not resume interrogation on ANY subject until counsel is present or the suspect reinitiates contact.', 'Edwards Rule — Right to Counsel Invocation', 'Edwards v. Arizona (1981)', true),
  ('con-law-001', 'fifth_sixth_amendment', 'hard', 'Paula is subpoenaed to testify before a grand jury about her participation in a tax fraud scheme. She invokes her Fifth Amendment right against self-incrimination. The prosecutor grants her use immunity. She then refuses to testify. What is the correct result?',
   'Paula may continue to refuse because immunity does not eliminate all Fifth Amendment concerns.', 'Paula must testify because use immunity removes the Fifth Amendment bar.', 'Paula may refuse because only transactional immunity satisfies the Fifth Amendment.', 'Paula must testify only if she is granted transactional immunity.',
   'B', 'Under Kastigar v. United States, use and derivative use immunity is constitutionally sufficient to compel testimony. The government cannot use the compelled testimony or anything derived from it in a prosecution.', 'Use Immunity — Kastigar', 'Kastigar v. United States (1972)', true),
  ('con-law-001', 'fifth_sixth_amendment', 'medium', 'Bob is charged with armed robbery. The prosecution wants to introduce Bob''s prior conviction for theft to impeach him if he testifies. Bob moves to exclude the conviction under the Double Jeopardy Clause, arguing he has already been punished. The court should:',
   'Grant the motion — using the conviction for impeachment constitutes additional punishment.', 'Grant the motion — the Double Jeopardy Clause bars any use of prior conviction evidence.', 'Deny the motion — the Double Jeopardy Clause does not bar use of prior convictions for impeachment.', 'Deny the motion — only the prosecution may raise Double Jeopardy issues.',
   'C', 'Double Jeopardy bars successive prosecutions and multiple punishments for the same offense. Using a prior conviction for impeachment purposes does not constitute punishment and raises no Double Jeopardy issue.', 'Double Jeopardy — Scope', 'U.S. Constitution Amend. V', true),
  ('con-law-001', 'fifth_sixth_amendment', 'medium', 'Carl is acquitted of first-degree murder by a jury. The prosecutor, believing the verdict was wrong, seeks to retry Carl for second-degree murder arising from the same killing. The Double Jeopardy Clause:',
   'Does not bar retrial because second-degree murder is a lesser included offense, not the same offense.', 'Bars retrial for second-degree murder because the same conduct is involved.', 'Bars retrial because acquittal for first-degree murder necessarily acquits Carl of second-degree murder.', 'Does not bar retrial if the prosecutor shows good cause.',
   'C', 'Under the Blockburger test, second-degree murder is a lesser included offense of first-degree murder. An acquittal of the greater offense bars retrial of any lesser included offense arising from the same transaction.', 'Double Jeopardy — Acquittal Bar / Lesser Included Offense', 'Blockburger v. United States (1932)', true),
  ('con-law-001', 'fifth_sixth_amendment', 'easy', 'The Sixth Amendment right to a speedy trial attaches:',
   'When the crime is committed.', 'When the defendant becomes a suspect.', 'When the defendant is formally charged or arrested, whichever is earlier.', 'Only when the defendant files a speedy trial demand.',
   'C', 'The Sixth Amendment speedy trial right attaches at arrest or formal charge (indictment/information), whichever occurs first. Pre-charge delay is analyzed under the Fifth Amendment Due Process Clause, not the Sixth Amendment.', 'Speedy Trial — Attachment', 'Dillingham v. United States (1975)', true),
  ('con-law-001', 'fifth_sixth_amendment', 'hard', 'Dave is convicted and sentenced. On appeal, Dave argues his trial counsel was constitutionally ineffective because counsel failed to investigate a key alibi witness. To prevail under Strickland, Dave must show:',
   'That counsel''s performance was deficient, and that there is a reasonable probability the outcome would have differed but for the deficiency.', 'That counsel made errors, and that Dave was actually innocent.', 'That counsel''s performance fell below the national standard for criminal defense attorneys.', 'That the trial court should have appointed different counsel.',
   'A', 'Strickland v. Washington requires: (1) deficient performance — counsel''s conduct fell below an objective standard of reasonableness; and (2) prejudice — a reasonable probability (more than a mere possibility) that the result would have differed but for the deficiency.', 'Ineffective Assistance — Strickland Two-Prong', 'Strickland v. Washington (1984)', true),
  ('con-law-001', 'fifth_sixth_amendment', 'medium', 'Maria is represented by counsel at her preliminary hearing. A police officer later conducts a lineup and deliberately elicits an identification without notifying Maria''s attorney. The identification is:',
   'Admissible — lineups are not a critical stage requiring counsel.', 'Admissible — the officer did not directly interrogate Maria.', 'Inadmissible — a post-charge lineup is a critical stage at which the right to counsel attaches.', 'Inadmissible — all lineups must be conducted with counsel present.',
   'C', 'Under United States v. Wade, a post-indictment lineup is a critical stage of prosecution because there is a substantial risk of irreparable misidentification. The Sixth Amendment requires that counsel be notified and given the opportunity to be present.', 'Right to Counsel — Critical Stage (Lineup)', 'United States v. Wade (1967)', true),
  ('con-law-001', 'fifth_sixth_amendment', 'easy', 'The Sixth Amendment Confrontation Clause guarantees a criminal defendant the right to:',
   'Be present at trial.', 'Confront and cross-examine adverse witnesses.', 'Remain silent and not testify against himself.', 'Have a jury determine guilt.',
   'B', 'The Sixth Amendment''s Confrontation Clause protects the defendant''s right to be confronted with the witnesses against him, primarily through the right to cross-examine. Crawford v. Washington extends this to out-of-court testimonial statements.', 'Confrontation Clause', 'Crawford v. Washington (2004)', true),
  ('con-law-001', 'fifth_sixth_amendment', 'medium', 'Eve is tried for robbery. At trial, the prosecution introduces a lab report identifying the substance found on Eve as cocaine, without calling the analyst who prepared it. The report is:',
   'Admissible — lab reports are business records, not testimonial statements.', 'Admissible — the Confrontation Clause applies only to eyewitnesses.', 'Inadmissible — the lab report is a testimonial statement and Eve had no prior opportunity to cross-examine the analyst.', 'Inadmissible — all out-of-court statements require a confrontation hearing.',
   'C', 'Under Melendez-Diaz v. Massachusetts, forensic lab reports prepared for use in criminal prosecution are testimonial statements. The Confrontation Clause bars admission unless the analyst testifies and is subject to cross-examination.', 'Confrontation Clause — Testimonial Lab Reports', 'Melendez-Diaz v. Massachusetts (2009)', true),
  ('con-law-001', 'fifth_sixth_amendment', 'hard', 'Tom is charged with a federal crime carrying a maximum of six months imprisonment. He demands a jury trial. The court denies the demand. Is this constitutional?',
   'No — the Sixth Amendment guarantees a jury trial in all federal criminal cases.', 'Yes — there is no jury trial right for crimes with a maximum sentence of six months or less.', 'Yes — the right to jury trial is waivable and Tom must affirmatively demand it in writing.', 'No — any incarceration triggers the Sixth Amendment jury trial right.',
   'B', 'The Sixth Amendment right to jury trial attaches only to ''serious'' offenses — those with a potential punishment of more than six months imprisonment. Petty offenses (max 6 months or less) carry no jury trial right under Baldwin v. New York.', 'Jury Trial Right — Serious vs. Petty Offense', 'Baldwin v. New York (1970)', true),
  ('con-law-001', 'fifth_sixth_amendment', 'medium', 'Police arrest Amy without a warrant. At the station, before Miranda warnings, Amy spontaneously says ''I did it — I shot him.'' The statement is:',
   'Inadmissible — Miranda warnings are required before any statement at the station.', 'Admissible — Miranda applies only to interrogation, not spontaneous statements.', 'Inadmissible — statements made after warrantless arrest are presumptively coerced.', 'Admissible — spontaneous statements are never protected by the Fifth Amendment.',
   'B', 'Miranda warnings are required for custodial interrogation — questioning designed to elicit incriminating responses. A spontaneous statement volunteered without any police questioning is not the product of interrogation and is admissible.', 'Miranda — Spontaneous Statements Exception', 'Rhode Island v. Innis (1980)', true),
  ('con-law-001', 'fifth_sixth_amendment', 'hard', 'Frank, represented by counsel, is being sentenced. The judge imposes a sentence based on facts (drug quantity) not submitted to the jury or admitted by Frank. Under Apprendi v. New Jersey, this is:',
   'Constitutional — judges have traditional authority to find facts at sentencing.', 'Constitutional — the Sixth Amendment applies only to guilt-phase proceedings.', 'Unconstitutional — any fact (other than a prior conviction) that increases the penalty beyond the prescribed statutory maximum must be found by the jury beyond a reasonable doubt.', 'Unconstitutional only if the fact increases the sentence by more than two years.',
   'C', 'Apprendi v. New Jersey holds: ''Other than the fact of a prior conviction, any fact that increases the penalty beyond the prescribed statutory maximum must be submitted to a jury and proved beyond a reasonable doubt.'' Blakely and Booker extended this to sentencing guidelines.', 'Apprendi Rule — Jury Fact-Finding at Sentencing', 'Apprendi v. New Jersey (2000)', true),
  ('con-law-001', 'fifth_sixth_amendment', 'easy', 'Which Amendment protects the right against double jeopardy?',
   'Fourth Amendment.', 'Fifth Amendment.', 'Sixth Amendment.', 'Eighth Amendment.',
   'B', 'The Fifth Amendment provides: ''nor shall any person be subject for the same offence to be twice put in jeopardy of life or limb.'' Double jeopardy protects against (1) successive prosecution after acquittal, (2) successive prosecution after conviction, and (3) multiple punishments for the same offense.', 'Double Jeopardy — Fifth Amendment', 'U.S. Constitution Amend. V', true),
  ('con-law-001', 'fifth_sixth_amendment', 'medium', 'Gina pleads guilty to felony drug possession and is sentenced to probation. Later, Gina challenges the plea, arguing she was not informed that the conviction would result in deportation. Under Padilla v. Kentucky, her counsel was:',
   'Not ineffective — deportation is a collateral consequence counsel need not advise about.', 'Not ineffective — only affirmative misrepresentations by counsel are actionable.', 'Ineffective — counsel has a Sixth Amendment duty to advise a non-citizen client that a plea carries a clear risk of deportation.', 'Ineffective only if the plea agreement itself mentioned immigration consequences.',
   'C', 'Padilla v. Kentucky held that the Sixth Amendment requires defense counsel to advise non-citizen clients about the deportation consequences of a guilty plea when those consequences are clear. Failure to advise constitutes deficient performance under Strickland''s first prong.', 'Ineffective Assistance — Immigration Consequences (Padilla)', 'Padilla v. Kentucky (2010)', true),
  ('con-law-001', 'commerce_clause', 'easy', 'Congress enacted a federal statute prohibiting the possession of firearms within 1,000 feet of a school. The Supreme Court struck down this law in United States v. Lopez primarily because:',
   'The Second Amendment protects gun possession.', 'The law did not regulate an activity that substantially affected interstate commerce.', 'States have exclusive authority to regulate schools.', 'The law violated the Tenth Amendment by commandeering state officers.',
   'B', 'In Lopez, the Court held the Gun-Free School Zones Act exceeded Commerce Clause authority because possession of a gun near a school was not an economic activity and Congress made no findings that it substantially affected interstate commerce.', 'Commerce Clause — Lopez Non-Economic Activity Limit', 'United States v. Lopez (1995)', true),
  ('con-law-001', 'commerce_clause', 'medium', 'A farmer grows wheat solely for his own consumption and never sells it. Congress seeks to regulate his wheat production under the Commerce Clause. Under Wickard v. Filburn, this regulation is:',
   'Unconstitutional — the farmer''s activity is purely local and non-commercial.', 'Constitutional — Congress may regulate purely local activities that, in the aggregate, substantially affect interstate commerce.', 'Unconstitutional — only activities that cross state lines may be regulated.', 'Constitutional — the federal power over agriculture is plenary.',
   'B', 'Wickard v. Filburn established the aggregation principle: even purely local, non-commercial activity can be regulated if, when aggregated with similar activities nationwide, it substantially affects interstate commerce. The farmer''s wheat consumption reduced demand in the national wheat market.', 'Commerce Clause — Aggregation (Wickard)', 'Wickard v. Filburn (1942)', true),
  ('con-law-001', 'commerce_clause', 'hard', 'Congress passes a law making it a federal crime for an individual to possess a controlled substance within 1,000 feet of a school, and includes extensive findings that drug markets substantially affect interstate commerce. Under Lopez/Morrison analysis, is this constitutional?',
   'No — drug possession is the same as gun possession in Lopez and is per se local.', 'Yes — Congress''s findings about drug markets and interstate commerce distinguish this from Lopez.', 'No — findings alone cannot save a law regulating non-economic activity.', 'Yes — controlled substances are fungible economic goods whose regulation has a long history.',
   'B', 'Unlike Lopez (no findings, no economic activity), this hypothetical includes congressional findings tying drug activity to interstate commerce. More importantly, drug markets are quintessentially economic — distinguishing this from the non-economic firearm possession in Lopez. The Court has upheld broad drug regulation under the Commerce Clause.', 'Commerce Clause — Lopez Findings + Economic Activity Distinction', 'Gonzales v. Raich (2005)', true),
  ('con-law-001', 'commerce_clause', 'medium', 'A state law requires that all milk sold in the state be processed at in-state facilities, effectively excluding cheaper out-of-state processed milk. Under the Dormant Commerce Clause, this law is:',
   'Valid — states may regulate health and safety within their borders.', 'Invalid — the law discriminates against interstate commerce on its face and protects in-state economic interests.', 'Valid — states have plenary power over food safety.', 'Invalid only if the discrimination is intentional.',
   'B', 'The Dormant Commerce Clause bars state laws that discriminate against interstate commerce either facially or in practical effect, unless the state can show a compelling local purpose that cannot be achieved through non-discriminatory means. A processing mandate that excludes out-of-state competition is classic economic protectionism.', 'Dormant Commerce Clause — Discrimination', 'Dean Milk Co. v. City of Madison (1951)', true),
  ('con-law-001', 'commerce_clause', 'easy', 'Under the market participant exception to the Dormant Commerce Clause, a state MAY:',
   'Tax goods crossing state lines at a higher rate than local goods.', 'Prefer in-state contractors when the state itself is purchasing goods or services.', 'Require out-of-state manufacturers to process goods locally.', 'Impose quotas on imported goods to protect local industry.',
   'B', 'The market participant exception: when a state acts as a buyer or seller in the market (rather than as a regulator), it may prefer in-state parties. The Dormant Commerce Clause restrains state regulation but not state participation in commerce.', 'Dormant Commerce Clause — Market Participant Exception', 'Hughes v. Alexandria Scrap Corp. (1976)', true),
  ('con-law-001', 'commerce_clause', 'hard', 'Congress passes a law requiring all trucks driving on interstate highways to be no more than 65 feet long. This directly conflicts with an Arizona law permitting trucks of up to 75 feet. The Arizona law:',
   'Prevails — states have police power authority over highway safety.', 'Is invalid — direct conflict with valid federal Commerce Clause regulation triggers federal supremacy.', 'Remains valid — trucks begin and end their journeys in states, making this a local matter.', 'Is invalid only as applied to trucks crossing state lines.',
   'B', 'When Congress exercises a valid Commerce Clause power and there is a direct conflict between federal and state law, the Supremacy Clause invalidates the conflicting state provision. A federal regulation of truck lengths on interstate highways is clearly within Commerce Clause authority.', 'Commerce Clause + Supremacy — Preemption', 'Southern Pacific Co. v. Arizona (1945)', true),
  ('con-law-001', 'commerce_clause', 'medium', 'A state levies a use tax on goods purchased out of state when no sales tax was paid. The tax is equal to the in-state sales tax rate. Under the Dormant Commerce Clause, this tax is:',
   'Invalid — any tax on out-of-state goods violates the Commerce Clause.', 'Valid — it does not discriminate against interstate commerce; it equalizes treatment.', 'Invalid — states may not tax goods that entered the state in interstate commerce.', 'Valid only if the state has a physical presence in the other state.',
   'B', 'A compensatory use tax that mirrors the in-state sales tax does not discriminate against interstate commerce — it treats in-state and out-of-state purchases equally. It prevents interstate commerce from being tax-advantaged over local commerce, which the Dormant Commerce Clause does not require.', 'Dormant Commerce Clause — Compensatory (Use) Tax', 'Henneford v. Silas Mason Co. (1937)', true),
  ('con-law-001', 'commerce_clause', 'easy', 'Gibbons v. Ogden established which foundational principle of the Commerce Clause?',
   'Congress may regulate only commerce between two or more states that physically crosses state lines.', 'The word ''commerce'' encompasses commercial intercourse, including navigation, and federal power over it is plenary within its domain.', 'State and federal governments have co-equal authority to regulate interstate commerce.', 'Congress may regulate production and manufacturing as part of interstate commerce.',
   'B', 'Gibbons v. Ogden (1824) established that ''commerce'' under Article I means commercial intercourse broadly — including navigation — and that federal power over it, when exercised, is supreme. Chief Justice Marshall rejected New York''s steamboat monopoly as conflicting with federal licensing authority.', 'Commerce Clause — Original Scope (Gibbons)', 'Gibbons v. Ogden (1824)', true),
  ('con-law-001', 'commerce_clause', 'hard', 'Congress enacts the Violence Against Women Act (VAWA) creating a federal civil cause of action for gender-motivated violence. The act contains findings that violence against women cumulatively affects interstate commerce. Under Morrison, the law is:',
   'Constitutional — violence against women is a national problem requiring a federal solution.', 'Constitutional — Congress made the required findings of effect on interstate commerce.', 'Unconstitutional — gender-motivated violence is non-economic and Congress may not aggregate non-economic criminal activity under the Commerce Clause.', 'Unconstitutional — civil remedies for private conduct are beyond Congress''s power.',
   'C', 'Morrison applied Lopez''s distinction between economic and non-economic activity. Gender-motivated violence is not economic activity, and the aggregation principle may not be used to regulate non-economic criminal conduct under the Commerce Clause, regardless of congressional findings.', 'Commerce Clause — Morrison Non-Economic Activity', 'United States v. Morrison (2000)', true),
  ('con-law-001', 'commerce_clause', 'medium', 'A state statute requires that 20% of all goods sold in state retail stores be manufactured in-state. The state argues this promotes local employment. Under the Dormant Commerce Clause, this law is:',
   'Valid — promoting local employment is a legitimate state interest.', 'Invalid — it facially discriminates against out-of-state manufacturers and is not saved by the state''s interest in local employment.', 'Valid — Congress has not enacted legislation preempting state purchase preferences.', 'Invalid only if it imposes a burden on commerce greater than the local benefit.',
   'B', 'A law mandating preference for in-state goods is facial discrimination against interstate commerce. Under strict scrutiny for discriminatory laws, the state must show no non-discriminatory alternative achieves the same goal. Promoting local employment is not a sufficient justification for facial discrimination.', 'Dormant Commerce Clause — Facial Discrimination (Local Preference Mandate)', 'Philadelphia v. New Jersey (1978)', true),
  ('con-law-001', 'commerce_clause', 'medium', 'Congress requires that companies shipping goods across state lines use union labor. The Tenth Amendment challenge to this law argues it intrudes on state sovereignty. Under current doctrine, the challenge should:',
   'Succeed — Congress may not regulate how private actors conduct their business.', 'Fail — the Tenth Amendment is not violated when Congress regulates private parties under the Commerce Clause, even if states are incidentally affected.', 'Succeed — labor regulation is traditionally a state function.', 'Fail only if the regulation is content-neutral.',
   'B', 'The Tenth Amendment limits Congress''s power to commandeer state governments (New York v. United States; Printz v. United States). It does not prevent Congress from regulating private parties, even if the regulation touches areas states traditionally regulate. The labor regulation here applies to private companies, not state governments.', 'Commerce Clause + Tenth Amendment — Private Party Regulation', 'Garcia v. San Antonio Metro. Transit Auth. (1985)', true),
  ('con-law-001', 'commerce_clause', 'hard', 'Congress passes the Affordable Care Act, which includes a requirement that individuals purchase health insurance or pay a penalty. The Commerce Clause challenge is STRONGEST because:',
   'Health care is not commerce.', 'The mandate regulates economic inactivity — the failure to buy insurance — not commercial activity.', 'Health insurance markets are purely local.', 'Congress lacks power to impose financial penalties.',
   'B', 'In NFIB v. Sebelius, five Justices agreed that the individual mandate could not be sustained under the Commerce Clause because Congress was regulating inactivity (the failure to purchase insurance). The Commerce Clause permits regulation of existing commercial activity, not compelling entry into commerce.', 'Commerce Clause — Limits (NFIB v. Sebelius)', 'NFIB v. Sebelius (2012)', true),
  ('con-law-001', 'commerce_clause', 'easy', 'The heart of the Dormant Commerce Clause doctrine is that, absent congressional authorization:',
   'States may regulate any matter with an incidental effect on interstate commerce.', 'States may not enact laws that discriminate against or unduly burden interstate commerce.', 'States must defer all commerce regulation to Congress.', 'States may impose taxes on goods moving through their borders.',
   'B', 'The Dormant Commerce Clause (implied negative Commerce Clause) prevents states from discriminating against or placing excessive burdens on interstate commerce, even when Congress has not spoken. It protects the national common market from state-imposed trade barriers.', 'Dormant Commerce Clause — Basic Doctrine', 'Cooley v. Board of Wardens (1851)', true),
  ('con-law-001', 'commerce_clause', 'medium', 'A state law prohibits the importation of solid waste generated outside the state, to protect the capacity of its landfills. This law is:',
   'Valid — states have broad authority to regulate waste disposal for health and safety reasons.', 'Invalid — the law facially discriminates against out-of-state waste and cannot be saved by the environmental rationale.', 'Valid — the environment is an area of traditional state authority.', 'Invalid only if out-of-state waste is treated differently once inside the state.',
   'B', 'Philadelphia v. New Jersey struck down a nearly identical law. Garbage is an article of commerce. A ban on out-of-state waste is facial discrimination against interstate commerce. Environmental concerns, while legitimate, cannot be achieved through discriminatory means that effectively embargo out-of-state articles.', 'Dormant Commerce Clause — Waste Import Prohibition', 'Philadelphia v. New Jersey (1978)', true),
  ('con-law-001', 'commerce_clause', 'hard', 'A state charges higher fees for out-of-state vessels docking at state-owned ports than for in-state vessels. This is:',
   'Potentially valid under the market participant exception because the state owns the ports.', 'Presumptively invalid as discrimination against interstate commerce regardless of state ownership.', 'Valid — states may price their own facilities as they choose.', 'Invalid per se as an impermissible tax on interstate commerce.',
   'A', 'The market participant exception allows a state acting as a proprietor (owner/seller) to prefer in-state parties. A state-owned port is a proprietary facility — the state is selling a service. While close to the line, the market participant exception would likely apply, though courts have sometimes limited its reach to direct purchases.', 'Dormant Commerce Clause — Market Participant / Port Fees', 'White v. Massachusetts Council (1983)', true),
  ('con-law-001', 'executive_power', 'medium', 'President acts without congressional authorization to seize steel mills during a national emergency. Under Justice Jackson''s Youngstown framework, this presidential action falls in which category?',
   'Zone 1: maximum presidential power with implicit congressional approval.', 'Zone 2: a zone of twilight where authority is uncertain.', 'Zone 3: lowest presidential power, potentially unconstitutional.', 'The President has inherent emergency power not covered by Youngstown.',
   'C', 'Jackson''s Youngstown framework: Zone 1 (express or implied congressional authorization — maximum power); Zone 2 (Congress silent — uncertain authority); Zone 3 (presidential action incompatible with congressional will — lowest ebb, action is unconstitutional unless Constitution grants exclusive authority). Truman''s seizure against implicit congressional disapproval was Zone 3.', 'Executive Power — Youngstown Steel Framework', 'Youngstown Sheet & Tube Co. v. Sawyer (1952)', true),
  ('con-law-001', 'executive_power', 'easy', 'The President may pardon offenses against the United States. The pardon power does NOT extend to:',
   'Federal criminal convictions.', 'Offenses committed before prosecution begins.', 'Impeachment.', 'Persons not yet charged with a crime.',
   'C', 'Article II, Section 2 grants the pardon power except in ''Cases of Impeachment.'' The pardon power is broad — it extends to pre-charge offenses, federal crimes, and persons convicted or not yet charged — but it cannot remove or prevent impeachment.', 'Executive Power — Pardon Power Limits', 'U.S. Constitution Art. II § 2', true),
  ('con-law-001', 'executive_power', 'hard', 'The House subpoenas presidential communications claiming executive privilege. The President refuses to produce the communications. Under Nixon, the court should:',
   'Enforce the subpoena — executive privilege is not recognized in the Constitution.', 'Balance: general executive privilege yields to a specific demonstrated need for evidence in a criminal trial.', 'Sustain the privilege — communications within the executive branch are absolutely protected.', 'Enforce the subpoena only if the President cannot show a national security basis.',
   'B', 'United States v. Nixon recognized executive privilege as constitutionally rooted but held it is not absolute. When the President asserts a general confidentiality interest (not military/diplomatic secrets), that interest must yield to a specific and demonstrated need for evidence in a pending criminal proceeding.', 'Executive Privilege — Nixon Balancing Test', 'United States v. Nixon (1974)', true),
  ('con-law-001', 'executive_power', 'medium', 'Congress passes a law creating an independent regulatory agency whose members the President may remove only ''for cause.'' Under Seila Law, which scenario raises the greatest removal power concern?',
   'A multi-member commission with staggered terms.', 'A single Director of an independent agency with broad regulatory authority and removal protections.', 'An officer confirmed by the Senate serving at will.', 'A cabinet secretary serving with Senate confirmation.',
   'B', 'Seila Law LLC v. CFPB held that a single-director independent agency (like the CFPB) with broad authority and for-cause removal protection violates the separation of powers. The President must have adequate removal authority over officers exercising substantial executive power. Multi-member commissions (Humphrey''s Executor) may still be constitutionally insulated.', 'Executive Power — Removal Power (Seila Law)', 'Seila Law LLC v. CFPB (2020)', true),
  ('con-law-001', 'executive_power', 'easy', 'Treaties become the supreme law of the land if:',
   'The Senate approves them by a majority vote.', 'The President signs them with two-thirds Senate approval.', 'The House and Senate both approve them by majority vote.', 'The President ratifies them without Senate action.',
   'B', 'Article II, Section 2: the President ''shall have Power, by and with the Advice and Consent of the Senate, to make Treaties, provided two thirds of the Senators present concur.'' Treaties are not submitted to the House.', 'Treaty Power — Constitutional Process', 'U.S. Constitution Art. II § 2', true),
  ('con-law-001', 'executive_power', 'medium', 'The President enters into an executive agreement with a foreign nation without Senate approval. The agreement conflicts with a prior federal statute. Under current doctrine:',
   'The executive agreement controls — foreign affairs are within presidential power.', 'The federal statute controls — only treaties approved by the Senate are supreme law.', 'The federal statute controls — executive agreements cannot override prior statutes.', 'The executive agreement controls if the President invokes national security.',
   'C', 'Executive agreements have the force of federal law but cannot override existing federal statutes. While the President may enter executive agreements as exercises of inherent foreign affairs power, they cannot supplant statutory law. Treaties approved by the Senate can supersede prior statutes under the last-in-time rule.', 'Executive Power — Executive Agreements vs. Statutes', 'Dames & Moore v. Regan (1981)', true),
  ('con-law-001', 'executive_power', 'hard', 'Congress passes a law allowing either the House or Senate alone (a ''legislative veto'') to overturn executive agency regulations without presenting the veto to the President. Under INS v. Chadha, this is:',
   'Constitutional — Congress may delegate and reclaim power to each chamber.', 'Constitutional — the legislative veto is an implicit power of Congress.', 'Unconstitutional — legislation affecting legal rights must be bicameral and presented to the President.', 'Unconstitutional only if the executive agency objects.',
   'C', 'INS v. Chadha held the one-house legislative veto unconstitutional. Any action with the force of legislation must comply with Article I''s requirements: bicameralism (both chambers) and presentment (to the President for signature or veto). A one-house veto bypasses both and violates separation of powers.', 'Separation of Powers — Legislative Veto (Chadha)', 'INS v. Chadha (1983)', true),
  ('con-law-001', 'executive_power', 'medium', 'The President issues an executive order directing federal agencies to prioritize climate change in all regulatory decisions, based on the President''s inherent executive power. Congress has not addressed this priority. Under Youngstown Zone 2, courts should:',
   'Strike down the order — executive orders require congressional authorization.', 'Uphold the order — directing executive agencies is a core presidential function.', 'Strike down the order — only Zone 1 actions survive judicial review.', 'Remand for agency rulemaking without ruling on presidential authority.',
   'B', 'Zone 2 covers presidential action where Congress has neither authorized nor forbidden it. In the ''zone of twilight,'' presidential power is uncertain but the President may act on the basis of executive authority. Directing federal agencies in their regulatory priorities falls within the President''s core executive power over the executive branch.', 'Executive Power — Youngstown Zone 2 (Agency Direction)', 'Youngstown Sheet & Tube Co. v. Sawyer (1952)', true),
  ('con-law-001', 'executive_power', 'easy', 'Which branch has the power to declare war under the Constitution?',
   'The President, as Commander-in-Chief.', 'Congress.', 'Both the President and Congress, jointly.', 'The National Security Council.',
   'B', 'Article I, Section 8 grants Congress the power to ''declare War.'' The President is Commander-in-Chief (Article II) but cannot unilaterally declare war. In practice, presidents have used military force without declarations under the War Powers Resolution framework.', 'War Powers — Constitutional Allocation', 'U.S. Constitution Art. I § 8; Art. II § 2', true),
  ('con-law-001', 'executive_power', 'hard', 'An independent prosecutor (special counsel) is appointed by the Attorney General to investigate the President. The President seeks to remove the special counsel. Under Morrison v. Olson, this removal:',
   'Is constitutional — the President has absolute power to remove all executive officers.', 'May be restricted to ''good cause'' removal without violating the Constitution.', 'Is unconstitutional — removing a special counsel investigating the President is per se corruption.', 'Must be approved by the Senate.',
   'B', 'Morrison v. Olson upheld the independent counsel statute''s ''good cause'' removal restriction. The Court applied a functional test: if removal restrictions do not impede the President''s ability to perform his constitutional duty, they are permissible. Later cases (Seila Law) have narrowed this, but limited removal protections for officers with circumscribed duties remain valid.', 'Executive Power — Removal Power / Morrison', 'Morrison v. Olson (1988)', true),
  ('con-law-001', 'executive_power', 'medium', 'Congress creates an executive agency and provides that its funding will be automatically appropriated from Federal Reserve earnings, not subject to annual congressional appropriation. This funding structure:',
   'Is constitutional — Congress has power to structure agency funding as it chooses.', 'May be unconstitutional — removing annual appropriation oversight undermines Congress''s power of the purse.', 'Is constitutional — the Federal Reserve is an independent entity.', 'Is unconstitutional — all federal money must flow through the Treasury.',
   'B', 'CFPB v. Community Financial Services Association held the CFPB''s funding structure (drawing from Federal Reserve funds without annual appropriation) could raise Appropriations Clause concerns, though the Supreme Court ultimately upheld it 7-2. The issue highlights separation of powers concerns when Congress bypasses its own oversight mechanisms.', 'Separation of Powers — Appropriations Clause', 'CFPB v. CFSA (2024)', true),
  ('con-law-001', 'executive_power', 'easy', 'The doctrine of nondelegation requires that when Congress delegates legislative authority to executive agencies, it must:',
   'Retain the ability to veto agency regulations.', 'Provide an intelligible principle to guide the agency''s exercise of delegated power.', 'Limit delegations to a maximum of two years.', 'Obtain two-thirds Senate approval for significant delegations.',
   'B', 'The nondelegation doctrine holds that Congress cannot transfer its legislative power to another branch. When delegating rulemaking authority, Congress must provide an ''intelligible principle'' — sufficient guidance to constrain the agency''s discretion. Courts rarely strike laws for violating this doctrine since 1935 (A.L.A. Schechter Poultry).', 'Nondelegation Doctrine — Intelligible Principle', 'Mistretta v. United States (1989)', true),
  ('con-law-001', 'executive_power', 'hard', 'The President nominates a principal officer (requiring Senate confirmation). Without Senate confirmation, the President appoints the same person as an ''acting'' official. The acting official exercises the full statutory powers of the office. Under NLRB v. SW General, this is:',
   'Constitutional — the President may use acting appointments to bypass Senate confirmation.', 'Constitutional — acting officials serve temporarily and do not require confirmation.', 'Potentially unconstitutional if the Federal Vacancies Reform Act prohibits the appointment.', 'Constitutional only if the Senate is in recess.',
   'C', 'NLRB v. SW General held that the Federal Vacancies Reform Act (FVRA) prohibits the President from naming a nominated person as an acting officer for the same position. If an appointment violates the FVRA, the acting official''s actions may be void. The Appointments Clause requires that principal officers be confirmed by the Senate.', 'Appointments Clause — FVRA / Acting Officials', 'NLRB v. SW General, Inc. (2017)', true),
  ('con-law-001', 'executive_power', 'medium', 'Congress enacts a law requiring the President to notify Congress before ordering military operations lasting more than 60 days. After 60 days, forces must be withdrawn unless Congress authorizes continuation. This is the War Powers Resolution. The President argues it is unconstitutional because:',
   'The Commander-in-Chief Clause grants the President exclusive authority over military deployment.', 'The Resolution violates separation of powers by allowing Congress to reclaim authority once delegated.', 'The Resolution is a legislative veto disapproved by Chadha.', 'Both A and C.',
   'A', 'Presidents of both parties have argued the War Powers Resolution infringes on the Commander-in-Chief power. The conventional presidential position is that the Commander-in-Chief Clause grants independent authority to deploy troops, and Congress cannot constitutionally impose time limits on that authority. Courts have largely avoided ruling on its constitutionality.', 'Executive Power — War Powers Resolution Controversy', '50 U.S.C. §§ 1541-1548', true),
  ('con-law-001', 'executive_power', 'hard', 'A federal statute grants the President the power to rescind any individual spending items from an appropriations act (a ''line-item veto''). Under Clinton v. City of New York, this statute is:',
   'Constitutional — Congress may delegate to the President the power to control spending.', 'Constitutional — the line-item veto is a reasonable exercise of the spending power.', 'Unconstitutional — the Constitution requires the President to sign or veto entire bills.', 'Unconstitutional — the spending power belongs exclusively to Congress.',
   'C', 'Clinton v. City of New York struck down the Line Item Veto Act. Article I''s Presentment Clause requires the President to sign or veto a bill in its entirety. Allowing the President to unilaterally cancel parts of a signed law effectively amends legislation — a power not granted by the Constitution.', 'Separation of Powers — Line Item Veto', 'Clinton v. City of New York (1998)', true),
  ('con-law-001', 'takings_clause', 'easy', 'The Takings Clause of the Fifth Amendment provides that private property shall not be taken for public use without:',
   'Due process.', 'Just compensation.', 'A legislative act of Congress.', 'Notice and a hearing.',
   'B', 'The Fifth Amendment''s Takings Clause states that ''private property [shall not] be taken for public use, without just compensation.'' The two requirements are (1) public use and (2) just compensation. Procedural due process is a separate constitutional protection.', 'Takings Clause — Basic Requirements', 'U.S. Constitution Amend. V', true),
  ('con-law-001', 'takings_clause', 'medium', 'A government regulation reduces the value of a beachfront property by 70% by prohibiting new construction but does not eliminate all economic value. This is:',
   'A per se taking requiring just compensation.', 'A regulatory taking analyzed under Penn Central balancing.', 'Not a taking — the owner retains some economic value.', 'A taking only if the government physically occupies the land.',
   'B', 'The Penn Central Transportation Co. v. NYC test applies to partial regulatory takings. Courts balance: (1) economic impact on the owner; (2) interference with investment-backed expectations; (3) character of the government action. Only a total wipe-out triggers Lucas''s per se rule; partial reductions are evaluated through Penn Central.', 'Regulatory Taking — Penn Central Balancing', 'Penn Central Transportation Co. v. City of New York (1978)', true),
  ('con-law-001', 'takings_clause', 'hard', 'South Carolina passes a coastal management law that bars developer Lucas from building houses on his beachfront lots, rendering them economically valueless. Lucas paid $975,000 for the lots before the law was passed. Under Lucas v. South Carolina Coastal Council:',
   'No taking — environmental protection is a legitimate exercise of police power.', 'A taking requiring just compensation — the regulation eliminates all economically beneficial use.', 'A taking only if Lucas can prove the law was enacted after he purchased the lots.', 'No taking — Lucas retains ownership and may sell or use the land in other ways.',
   'B', 'Lucas established the per se rule: when a regulation deprives an owner of ALL economically beneficial use of property, it is a taking requiring compensation, unless the prohibited uses were never permitted under background principles of state property and nuisance law.', 'Regulatory Taking — Lucas Per Se Rule (Total Wipe-Out)', 'Lucas v. South Carolina Coastal Council (1992)', true),
  ('con-law-001', 'takings_clause', 'medium', 'A city condemns a private home and transfers it to a private developer as part of an economic development plan intended to create jobs and tax revenue. Under Kelo v. City of New London, this is:',
   'An unconstitutional taking — private property cannot be transferred to other private parties.', 'A constitutional taking — economic development satisfies the ''public use'' requirement.', 'An unconstitutional taking — job creation is not a sufficient public purpose.', 'A constitutional taking only if the city obtains the property through negotiation, not condemnation.',
   'B', 'Kelo v. City of New London held that the government''s use of eminent domain for economic development — creating jobs and tax revenue — satisfies the ''public use'' requirement of the Fifth Amendment. The Court deferred to the city''s legislative judgment about the public benefit.', 'Takings — Public Use (Kelo)', 'Kelo v. City of New London (2005)', true),
  ('con-law-001', 'takings_clause', 'easy', 'Just compensation for a government taking of property means:',
   'The amount the government budgets for the project.', 'The fair market value of the property at the time of the taking.', 'The cost to replace the property with new construction.', 'The subjective value the owner placed on the property.',
   'B', 'Just compensation under the Fifth Amendment is the fair market value of the property at the time of the taking — the price a willing buyer would pay a willing seller in an arm''s-length transaction. The owner''s subjective value and replacement costs are not the constitutional standard.', 'Just Compensation — Fair Market Value', 'United States v. Dunn (1896)', true),
  ('con-law-001', 'takings_clause', 'hard', 'As a condition of approving a development permit, a city requires a homeowner to allow the public to walk across her beachfront property. The homeowner argues this is an unconstitutional taking. Under Nollan v. California Coastal Commission, this exaction is:',
   'Valid — the city may impose reasonable conditions on land use permits.', 'Invalid — a required dedication of land for public access is a per se taking.', 'Invalid unless there is an essential nexus between the exaction and the permit''s purpose.', 'Valid — dedication to public use is always a legitimate public interest.',
   'C', 'Nollan held that permit conditions (exactions) requiring dedication of property must have an ''essential nexus'' to a legitimate government interest that would have justified outright denial of the permit. A lateral easement for beach access was not sufficiently related to blocking the visual connection between street and sea.', 'Takings — Exactions (Nollan Nexus Test)', 'Nollan v. California Coastal Commission (1987)', true),
  ('con-law-001', 'takings_clause', 'medium', 'A city approves a flood control project that will permanently flood a farmer''s land for several months each year. The farmer seeks compensation. This is:',
   'Not a taking — the flooding is temporary and incidental.', 'A taking — permanent physical invasions, even periodic, require just compensation.', 'A taking only if the flooding is more than 50% of the year.', 'Not a taking — flood control is a government service that benefits landowners.',
   'B', 'Any permanent physical occupation or invasion of property — even if intermittent — constitutes a taking. In Loretto v. Teleprompter Manhattan CATV Corp., the Court established that a permanent physical invasion is a per se taking. Periodic but permanent flooding of private land requires just compensation.', 'Takings — Permanent Physical Invasion', 'Loretto v. Teleprompter Manhattan CATV Corp. (1982)', true),
  ('con-law-001', 'takings_clause', 'hard', 'A government regulation temporarily restricts the development of wetlands for two years while an environmental study is conducted, then the restriction is lifted. The landowner seeks compensation for lost value during the two years. Under First English Evangelical Lutheran Church, the landowner:',
   'Cannot recover — temporary restrictions are never compensable takings.', 'May recover — if the temporary restriction constituted a taking, compensation is due for the period of the taking.', 'Cannot recover — the owner has full use of the property after the restriction is lifted.', 'May recover only if the restriction eliminated all economic value permanently.',
   'B', 'First English Evangelical Lutheran Church v. County of Los Angeles held that if a government regulation constitutes a taking, the government must pay compensation for the period of the taking even if the restriction is temporary. There is no categorical rule exempting temporary takings from compensation.', 'Regulatory Taking — Temporary Takings Compensation', 'First English Evangelical Lutheran Church v. County of Los Angeles (1987)', true),
  ('con-law-001', 'takings_clause', 'medium', 'A city conditions a developer''s permit to build a larger store on a requirement that the developer dedicate land for a bike path. The bike path is roughly proportional to the increased traffic the larger store will generate. Under Dolan v. City of Tigard, this exaction is:',
   'Valid — the city may impose any reasonable conditions on development permits.', 'Invalid — requiring dedication of land is always a per se taking.', 'Valid — there is an essential nexus (traffic) and rough proportionality between the exaction and the permit''s impact.', 'Invalid — only monetary exactions, not land dedications, are permissible.',
   'C', 'Dolan added ''rough proportionality'' to the Nollan nexus test. The exaction must both (1) have an essential nexus to a legitimate government interest, and (2) be roughly proportional in degree to the projected impact of the proposed development. A traffic-related bike path exaction passes both prongs.', 'Takings — Exactions (Nollan/Dolan Two-Part Test)', 'Dolan v. City of Tigard (1994)', true),
  ('con-law-001', 'takings_clause', 'easy', 'A government agency physically takes a strip of private land to build a public road. This is BEST classified as:',
   'A regulatory taking requiring Penn Central balancing.', 'A per se physical taking requiring just compensation without further analysis.', 'A valid exercise of police power not requiring compensation.', 'A taking only if the landowner did not consent.',
   'B', 'A direct government physical taking of private land for a public road is the paradigm case for eminent domain. Physical appropriations are per se takings requiring just compensation. Unlike regulatory takings (Penn Central/Lucas), no balancing is needed.', 'Takings — Physical Taking vs. Regulatory Taking', 'U.S. Constitution Amend. V', true),
  ('con-law-001', 'takings_clause', 'hard', 'A state court applies newly expanded common-law nuisance principles to bar a property owner from operating a legitimate business he had operated for decades. If the rule was not part of the state''s background law at the time the owner acquired the property, Lucas suggests:',
   'The owner has no recourse because state courts may develop common law.', 'This may constitute a taking if the new rule eliminates all economic use and was not part of background principles when the property was acquired.', 'The owner must accept the loss as part of living in a regulated society.', 'This is never a taking because nuisance law serves a public health purpose.',
   'B', 'Lucas allows states to avoid compensation only when the prohibited uses were prohibited by ''background principles of the State''s law of property and nuisance'' that pre-existed the owner''s acquisition. A newly expanded nuisance rule applied retroactively to eliminate all use may not qualify as a background principle, triggering the per se taking rule.', 'Regulatory Taking — Lucas Background Principles', 'Lucas v. South Carolina Coastal Council (1992)', true),
  ('con-law-001', 'takings_clause', 'medium', 'Which of the following is NOT required to establish a taking under the Takings Clause?',
   'A property interest cognizable under state law.', 'Government action.', 'A diminution in property value of at least 50%.', 'The taking must be for public use (if compensation is sought).',
   'C', 'There is no minimum percentage threshold for a regulatory taking. Penn Central requires balancing multiple factors; Lucas applies when economic value reaches zero. A 50% reduction in value, while significant, is not per se a taking — Penn Central balancing applies to partial diminutions.', 'Takings — No Minimum Percentage Rule', 'Penn Central Transportation Co. v. City of New York (1978)', true),
  ('con-law-001', 'takings_clause', 'easy', 'The government physically installs a cable TV box on an apartment building''s roof over the owner''s objection. Under Loretto, this is:',
   'A taking only if the installation causes structural damage.', 'A taking — any permanent physical occupation is a per se taking.', 'Not a taking — the intrusion is minimal.', 'Not a taking — cable access serves the public interest.',
   'B', 'Loretto v. Teleprompter Manhattan CATV Corp. established that any permanent physical occupation of private property authorized by government, however minor, constitutes a per se taking requiring just compensation. The size of the intrusion is irrelevant to the threshold question.', 'Takings — Permanent Physical Occupation (Loretto)', 'Loretto v. Teleprompter Manhattan CATV Corp. (1982)', true),
  ('con-law-001', 'takings_clause', 'hard', 'A city has a long-standing policy of retaining any personal property (e.g., a car) that is abandoned on city property. The policy has never been codified by ordinance. When the city retains a towed car, the owner argues this is a taking. The BEST counter-argument for the city is:',
   'Abandoned property has no Fifth Amendment protection.', 'Background principles of property law — the common-law rule of abandonment — allowed the government to retain abandoned property before the Constitution was ratified.', 'The city is exercising its police power, which is not subject to the Takings Clause.', 'The car was on public property, where the owner had no reasonable expectation of privacy.',
   'B', 'Under Lucas''s background principles exception, if the government action is consistent with property and nuisance law that pre-dates the constitutional claim, no taking occurs. Common-law abandonment doctrine — which permits government retention of abandoned property — is exactly the type of background principle the Lucas Court contemplated.', 'Takings — Background Principles / Abandonment', 'Lingle v. Chevron U.S.A. Inc. (2005)', true),
  ('con-law-001', 'takings_clause', 'medium', 'The government condemns a business''s property but delays paying compensation for four years while litigation continues. During those four years, the owner is denied use of the property. The owner is entitled to:',
   'Just compensation for the value of the property at the time of taking, plus interest for the delay.', 'Only the fair market value at the time of payment.', 'Nothing additional — delay in payment is a normal incident of condemnation.', 'Replacement value, because the delay increased the owner''s losses.',
   'A', 'The government must pay just compensation — the fair market value at the time of the taking — as well as interest to compensate for the delay between the taking and actual payment. The Takings Clause requires that compensation be ''just,'' which includes making the owner whole for the delay in payment.', 'Takings — Just Compensation Including Interest', 'Jacobs v. United States (1933)', true),
  ('con-law-001', 'incorporation_14th', 'easy', 'The doctrine of selective incorporation holds that:',
   'All provisions of the Bill of Rights apply to the states through the Fourteenth Amendment.', 'Only those provisions of the Bill of Rights that are ''fundamental to the American scheme of justice'' are incorporated against the states.', 'The Bill of Rights does not apply to the states at all.', 'States may choose which Bill of Rights provisions to follow.',
   'B', 'Selective incorporation holds that not all, but most, provisions of the Bill of Rights apply to states through the Fourteenth Amendment''s Due Process Clause, if they are fundamental to our concept of ordered liberty or deeply rooted in American history and tradition.', 'Selective Incorporation — Basic Doctrine', 'Duncan v. Louisiana (1968)', true),
  ('con-law-001', 'incorporation_14th', 'medium', 'In Barron v. Baltimore (1833), the Supreme Court held that the Bill of Rights:',
   'Applies to the states through the Privileges and Immunities Clause.', 'Does not apply to the states — it restrains only the federal government.', 'Applies to the states only for criminal prosecutions.', 'Applies to state action through the common law.',
   'B', 'Barron v. Baltimore established that the Bill of Rights was intended to restrain only the federal government, not the states. This was the law before the Fourteenth Amendment. Post-1868, incorporation through the Fourteenth Amendment''s Due Process Clause gradually applied most Bill of Rights protections to the states.', 'Incorporation — Barron v. Baltimore (Pre-14th Amendment)', 'Barron v. Baltimore (1833)', true),
  ('con-law-001', 'incorporation_14th', 'hard', 'Palko v. Connecticut (1937) held that the Double Jeopardy Clause was NOT incorporated against the states. The standard used in Palko — which provisions are ''of the very essence of ordered liberty'' — was eventually replaced by which current test?',
   'The ''shock the conscience'' test from Rochin v. California.', 'The ''deeply rooted in this Nation''s history and tradition and implicit in the concept of ordered liberty'' test from Washington v. Glucksberg.', 'The ''total incorporation'' approach from Justice Black''s dissent.', 'The ''fundamental fairness'' approach retained from Palko.',
   'B', 'Modern selective incorporation (McDonald v. Chicago) uses the Glucksberg test: a right is incorporated if it is deeply rooted in American history and tradition AND implicit in the concept of ordered liberty. Palko''s narrower formulation was effectively superseded, and Double Jeopardy was eventually incorporated in Benton v. Maryland (1969).', 'Selective Incorporation — Evolution (Palko to McDonald)', 'McDonald v. City of Chicago (2010)', true),
  ('con-law-001', 'incorporation_14th', 'medium', 'In McDonald v. City of Chicago (2010), the Supreme Court incorporated the Second Amendment right to keep and bear arms against the states. The majority relied on the:',
   'Privileges or Immunities Clause of the Fourteenth Amendment.', 'Due Process Clause of the Fourteenth Amendment.', 'Equal Protection Clause of the Fourteenth Amendment.', 'Commerce Clause.',
   'B', 'McDonald incorporated the Second Amendment through the Fourteenth Amendment''s Due Process Clause, following the standard selective incorporation analysis. Justice Thomas wrote separately, arguing the Privileges or Immunities Clause would be a more historically accurate vehicle, but the majority chose the established Due Process framework.', 'Selective Incorporation — Second Amendment (McDonald)', 'McDonald v. City of Chicago (2010)', true),
  ('con-law-001', 'incorporation_14th', 'easy', 'Which of the following provisions of the Bill of Rights has NOT been incorporated against the states?',
   'The Fourth Amendment protection against unreasonable searches.', 'The Sixth Amendment right to jury trial in criminal cases.', 'The Fifth Amendment right to grand jury indictment in serious criminal cases.', 'The First Amendment freedom of speech.',
   'C', 'The Fifth Amendment grand jury requirement is one of the few Bill of Rights provisions not incorporated against the states. States may use information, preliminary hearings, or other charging mechanisms in lieu of a grand jury. This is one of the rare non-incorporated rights.', 'Selective Incorporation — Non-Incorporated Provisions', 'Hurtado v. California (1884)', true),
  ('con-law-001', 'incorporation_14th', 'medium', 'Duncan v. Louisiana (1968) incorporated the Sixth Amendment right to jury trial in criminal cases. The test used was whether the right is:',
   'Contained in the text of the Fourteenth Amendment.', '''Fundamental to the American scheme of justice.''', 'Essential to prevent arbitrary government action.', 'Recognized in a majority of state constitutions.',
   'B', 'Duncan v. Louisiana incorporated the jury trial right using the test: whether the right is ''fundamental to the American scheme of justice.'' Trial by jury in criminal cases plainly qualifies. Duncan reflects the peak of the Warren Court''s selective incorporation project.', 'Selective Incorporation — Duncan Standard', 'Duncan v. Louisiana (1968)', true),
  ('con-law-001', 'incorporation_14th', 'hard', 'In Adamson v. California (1947), Justice Black argued for ''total incorporation'' of the Bill of Rights against the states. The Court''s majority rejected this approach. What is the primary objection to total incorporation?',
   'The text of the Fourteenth Amendment does not mention the Bill of Rights.', 'Some Bill of Rights provisions were designed only for the federal context and may be inappropriate for states.', 'Total incorporation would eliminate the states'' police power.', 'The Due Process Clause cannot serve as a vehicle for incorporating explicit rights.',
   'B', 'The majority in Adamson (Justice Frankfurter) argued that the Due Process Clause protects fundamental fairness, not every Bill of Rights provision. Some provisions — like the Eighth Amendment''s ban on excessive fines — may require different calibration for state law enforcement contexts. Justice Black''s dissent (total incorporation) has attracted adherents but has never commanded a majority.', 'Selective vs. Total Incorporation — Theoretical Debate', 'Adamson v. California (1947)', true),
  ('con-law-001', 'incorporation_14th', 'easy', 'The Fourteenth Amendment''s Due Process Clause, through which selective incorporation occurs, provides that no state may deprive any person of life, liberty, or property:',
   'Without due process of law.', 'Without equal protection.', 'Without just compensation.', 'Without a warrant.',
   'A', 'Section 1 of the Fourteenth Amendment: ''No State shall... deprive any person of life, liberty, or property, without due process of law.'' This Due Process Clause is the vehicle for incorporating Bill of Rights protections against state action.', '14th Amendment — Due Process Clause (Text)', 'U.S. Constitution Amend. XIV § 1', true),
  ('con-law-001', 'incorporation_14th', 'medium', 'The Third Amendment''s prohibition on quartering soldiers in private homes has never been definitively incorporated against the states. If a court were to consider incorporation today, it would likely:',
   'Refuse incorporation — the right is not deeply rooted in American tradition.', 'Incorporate — the right is fundamental to liberty.', 'Refuse incorporation — the Third Amendment only applies to wartime.', 'Incorporate — all Bill of Rights provisions are now incorporated.',
   'B', 'The Third Amendment has never been litigated for incorporation. Under McDonald''s test, a court would likely find it deeply rooted in American history (it was a colonial grievance) and fundamental to the concept of ordered liberty. Most scholars believe it would be incorporated if the question arose, despite its practical irrelevance.', 'Selective Incorporation — Third Amendment (Unresolved)', 'Engblom v. Carey (2d Cir. 1982)', true),
  ('con-law-001', 'incorporation_14th', 'hard', 'Bolling v. Sharpe (1954) held that racial segregation in D.C. public schools violated the Fifth Amendment''s Due Process Clause. This is an example of:',
   'Direct application of the Fourteenth Amendment to the federal government.', 'Reverse incorporation — Fifth Amendment Due Process incorporating equal protection concepts against the federal government.', 'The Bill of Rights applying directly to the states.', 'The Tenth Amendment limiting federal school policy.',
   'B', 'Bolling v. Sharpe was decided alongside Brown v. Board of Education. The Fourteenth Amendment applies only to states; the federal government in D.C. was not subject to it. The Court held the Fifth Amendment''s Due Process Clause ''reverse incorporates'' equal protection norms, barring federal segregation. This reverse incorporation has no explicit textual basis but has been consistently applied.', 'Reverse Incorporation — Bolling v. Sharpe', 'Bolling v. Sharpe (1954)', true),
  ('con-law-001', 'incorporation_14th', 'medium', 'The Eighth Amendment prohibition on cruel and unusual punishment was incorporated against the states in:',
   'Mapp v. Ohio (1961).', 'Robinson v. California (1962).', 'Miranda v. Arizona (1966).', 'Gideon v. Wainwright (1963).',
   'B', 'Robinson v. California (1962) incorporated the Eighth Amendment''s cruel and unusual punishment clause against the states, holding that a California law criminalizing the status of being addicted to narcotics constituted cruel and unusual punishment.', 'Selective Incorporation — 8th Amendment', 'Robinson v. California (1962)', true),
  ('con-law-001', 'incorporation_14th', 'easy', 'Which famous case incorporated the right to counsel in felony cases against the states?',
   'Miranda v. Arizona.', 'Gideon v. Wainwright.', 'Mapp v. Ohio.', 'Terry v. Ohio.',
   'B', 'Gideon v. Wainwright (1963) incorporated the Sixth Amendment right to counsel in felony cases against the states. The Court held that the right to an attorney is fundamental to a fair trial, overruling Betts v. Brady. Clarence Gideon''s handwritten petition led to this landmark ruling.', 'Selective Incorporation — Right to Counsel (Gideon)', 'Gideon v. Wainwright (1963)', true),
  ('con-law-001', 'incorporation_14th', 'hard', 'Jot-for-jot incorporation holds that once a Bill of Rights provision is incorporated, it applies to the states in exactly the same way it applies to the federal government. Which justice most strongly disputed this approach?',
   'Justice Hugo Black.', 'Justice William Brennan.', 'Justice John Harlan II.', 'Chief Justice Earl Warren.',
   'C', 'Justice Harlan II argued that incorporation should not be jot-for-jot — states may have legitimate reasons to apply constitutional guarantees differently than the federal government. He preferred the ''fundamental fairness'' approach, allowing states flexibility while still meeting constitutional minimums. His view has never prevailed, but it influences debates about incorporation''s scope.', 'Selective Incorporation — Jot-for-Jot vs. Fundamental Fairness (Harlan)', 'Pointer v. Texas (1965)', true),
  ('con-law-001', 'incorporation_14th', 'medium', 'A state court convicts a defendant of a felony using a 10-2 jury verdict (non-unanimous). Under Ramos v. Louisiana (2020), this is:',
   'Constitutional — states may deviate from the federal requirement of unanimous juries.', 'Unconstitutional — the Sixth Amendment requires unanimous jury verdicts and is incorporated jot-for-jot.', 'Constitutional — only federal courts must have unanimous juries.', 'Unconstitutional only if the defendant is sentenced to death.',
   'B', 'Ramos v. Louisiana (2020) overruled Apodaca v. Oregon and held that the Sixth Amendment''s unanimity requirement is incorporated against the states and applies jot-for-jot. A 10-2 verdict violates the Sixth Amendment when applied to a state felony prosecution.', 'Selective Incorporation — Jury Unanimity (Ramos)', 'Ramos v. Louisiana (2020)', true),
  ('con-law-001', 'incorporation_14th', 'hard', 'Which of the following lists represents Bill of Rights provisions that remain NOT fully incorporated against the states as of the Supreme Court''s current doctrine?',
   'First Amendment Free Speech; Fourth Amendment Search and Seizure; Sixth Amendment Jury Trial.', 'Fifth Amendment Grand Jury; Seventh Amendment Civil Jury Trial; Third Amendment Quartering.', 'Second Amendment; Fifth Amendment Self-Incrimination; Eighth Amendment Cruel and Unusual Punishment.', 'Fourth Amendment; Fifth Amendment Takings; Sixth Amendment Confrontation.',
   'B', 'The primary non-incorporated provisions are: (1) Fifth Amendment grand jury requirement (Hurtado); (2) Seventh Amendment right to civil jury trial (only applies to federal courts); (3) Third Amendment quartering (never litigated for incorporation). All provisions in choices A, C, and D are incorporated.', 'Selective Incorporation — Non-Incorporated Rights (Complete List)', 'Hurtado v. California (1884); Minneapolis & St. Louis Ry. v. Bombolis (1916)', true)
) AS v(subject_id, category, difficulty, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, rule_tested, case_citation, is_active)
WHERE NOT EXISTS (SELECT 1 FROM quiz_questions q
                  WHERE q.subject_id = v.subject_id AND q.stem = v.stem);

COMMIT;

-- ══ from 20260720000002_seed_contracts.sql ══
-- Contracts: Formation, Consideration, Performance/Breach, Remedies, Defenses, UCC Article 2
-- 105 MBE questions

BEGIN;

INSERT INTO quiz_questions
  (subject_id, category, difficulty, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, rule_tested, case_citation, is_active)
SELECT v.* FROM (VALUES
('contracts-001', 'formation', 'easy', 'Under the objective theory of contracts, courts determine whether a contract was formed by asking:',
   'What the promisor subjectively intended.', 'What a reasonable person in the position of the promisee would understand.', 'Whether the promisor felt bound to perform.', 'Whether both parties read and understood all terms.',
   'B', 'Contract formation is judged objectively — courts ask what a reasonable person would understand from the words and conduct. A party''s unexpressed intentions are irrelevant to formation.', 'Objective Theory of Contracts', 'Lucy v. Zehmer (1954)', true),
  ('contracts-001', 'formation', 'medium', 'Ann offers to sell her car to Bob for $5,000. Bob replies: ''I accept, but I need delivery by Friday.'' Under common law, Bob''s response is:',
   'A valid acceptance creating a binding contract.', 'A counteroffer rejecting Ann''s offer.', 'A conditional acceptance that creates a contract subject to the Friday condition.', 'An inquiry that keeps the offer open.',
   'B', 'Under the common law mirror image rule, an acceptance that adds or changes terms is a counteroffer, not an acceptance, and operates as a rejection of the original offer. Bob''s addition of the delivery term is a counteroffer.', 'Mirror Image Rule — Counteroffer', 'Restatement (Second) of Contracts § 59', true),
  ('contracts-001', 'formation', 'medium', 'Carol sends an offer by mail on Monday. Dan mails an acceptance on Tuesday. Carol attempts to revoke by phone on Wednesday before receiving the acceptance. Under the mailbox rule:',
   'The contract is formed when Dan mailed the acceptance on Tuesday.', 'The contract is formed when Carol receives Dan''s acceptance.', 'No contract — Carol revoked before Dan''s acceptance arrived.', 'No contract — the revocation and acceptance must be received simultaneously.',
   'A', 'The mailbox rule (Restatement § 63): an acceptance by mail is effective upon dispatch (when mailed), not upon receipt. Since Dan mailed the acceptance Tuesday, the contract was formed Tuesday — before Wednesday''s revocation attempt.', 'Mailbox Rule — Acceptance Effective on Dispatch', 'Restatement (Second) of Contracts § 63', true),
  ('contracts-001', 'formation', 'hard', 'An advertisement in a newspaper states: ''First come, first served — one fur coat, black, size 16, $1 if you come in Wednesday.'' Under Lefkowitz v. Great Minneapolis Surplus Store, this advertisement is:',
   'An invitation to negotiate — offers cannot be made by advertisement.', 'An offer — it is specific, complete, leaves nothing open for negotiation, and can be accepted only by the first person who complies.', 'An illusory promise — the store can run out of coats.', 'A unilateral contract offer only if the buyer tenders $1.',
   'B', 'Lefkowitz held that a clear, definite, and explicit advertisement that leaves nothing open for negotiation constitutes an offer. ''First come, first served'' provides definiteness about the offeree. This is an exception to the general rule that advertisements are merely invitations to deal.', 'Advertisement as Offer — Lefkowitz', 'Lefkowitz v. Great Minneapolis Surplus Store (1957)', true),
  ('contracts-001', 'formation', 'easy', 'For a promise to be enforceable as a contract, it must be supported by:',
   'Good faith.', 'Consideration.', 'Writing.', 'An exchange of signatures.',
   'B', 'Consideration is required for contract formation. Consideration means a bargained-for exchange where each party gives something of legal value — a promise, an act, or a forbearance. Without consideration, a promise is generally unenforceable as a contract.', 'Consideration Requirement', 'Restatement (Second) of Contracts § 71', true),
  ('contracts-001', 'formation', 'medium', 'Eve promises to pay her nephew Frank $10,000 if he refrains from drinking alcohol for one year. Frank complies. Is there a binding contract?',
   'No — refraining from legal activity is not valid consideration.', 'Yes — Frank''s forbearance from a legal right he held is valid consideration.', 'No — the promise was gratuitous and lacked mutuality.', 'Yes — only if Frank was previously addicted to alcohol.',
   'B', 'Under Hamer v. Sidway, consideration can be the promisee''s forbearance from a legal right (here, the right to drink alcohol). Frank gave up something he had a legal right to do. The court held this sufficient consideration even though abstention was beneficial to Frank.', 'Forbearance as Consideration', 'Hamer v. Sidway (1891)', true),
  ('contracts-001', 'formation', 'medium', 'George is drowning and Helen, a passerby, rescues him. After the rescue, George promises to pay Helen $500 for saving his life. George later refuses to pay. Under the doctrine of past consideration:',
   'George must pay — morally he is obligated.', 'George need not pay — the rescue occurred before the promise, so there is no consideration.', 'George must pay — life-saving services always constitute consideration.', 'George need not pay — a promise to pay a stranger creates no legal duty.',
   'B', 'Past consideration is not valid consideration under common law. Consideration must be given in exchange for the promise — it must be bargained for. Helen''s rescue preceded and was not induced by George''s promise. The promise is unenforceable for lack of consideration.', 'Past Consideration', 'Restatement (Second) of Contracts § 71', true),
  ('contracts-001', 'formation', 'hard', 'Ida sends an offer to sell equipment for $20,000. Joe, a merchant, sends back a form that says ''we accept'' but adds a new term requiring arbitration of disputes. Under UCC § 2-207 (Battle of the Forms):',
   'No contract — the arbitration term is an acceptance with additional terms, creating a counteroffer.', 'A contract is formed without the arbitration clause, which is a proposed addition.', 'A contract is formed including the arbitration clause because both parties are merchants.', 'No contract — merchants must match all terms exactly.',
   'B', 'UCC § 2-207: between merchants, additional terms in an acceptance become part of the contract UNLESS (1) the offer expressly limited acceptance to its terms, (2) the new terms materially alter the offer, or (3) the offeror objects. An arbitration clause is generally deemed a material alteration, so it does not become part of the contract.', 'UCC § 2-207 — Battle of the Forms (Material Alteration)', 'UCC § 2-207', true),
  ('contracts-001', 'formation', 'easy', 'Under the concept of promissory estoppel (detrimental reliance), a promise is enforceable without consideration if:',
   'The promise is in writing.', 'The promisor should reasonably expect reliance, the promisee did rely, and injustice can be avoided only by enforcement.', 'The promisee paid nominal consideration.', 'The promise was made in the presence of witnesses.',
   'B', 'Restatement § 90 (Promissory Estoppel): A promise is binding if (1) the promisor reasonably expected to induce action or forbearance, (2) such action or forbearance was induced, and (3) injustice can be avoided only by enforcement. It is a substitute for consideration, not consideration itself.', 'Promissory Estoppel — Elements', 'Restatement (Second) of Contracts § 90', true),
  ('contracts-001', 'formation', 'medium', 'Karl offers to sell Lena his house for $200,000. Lena says: ''I accept. Can you paint the living room?'' Under common law:',
   'No contract — Lena''s question added a new term.', 'Contract formed — the question is merely an inquiry, not a condition.', 'Contract formed — the painting request creates an implied term.', 'No contract — real estate contracts require written acceptance.',
   'B', 'A pure question or inquiry following an acceptance does not negate the acceptance. Lena''s ''Can you paint?'' is an inquiry, not a condition on her acceptance. The mirror image rule is satisfied because Lena accepted the exact terms. The question has no legal effect on formation.', 'Mirror Image Rule — Inquiry vs. Counteroffer', 'Restatement (Second) of Contracts § 61', true),
  ('contracts-001', 'formation', 'hard', 'Mom promises in writing to give her son Tom her car, signed, sealed, and delivered as a formal deed of gift. Is this enforceable?',
   'Yes — a formal deed of gift requires no consideration.', 'No — even a formal deed requires consideration under modern contract law.', 'Yes — but only if Tom provides nominal consideration.', 'No — gifts of personal property may never be enforced by contract.',
   'A', 'Under the common law and Restatement, a promise under seal (formal deed) may be enforced without consideration in some jurisdictions. Modern courts often enforce signed written promises of gifts as exceptions to the consideration requirement, particularly when the formality serves the purposes consideration usually serves.', 'Consideration — Exception for Sealed Instruments', 'Restatement (Second) of Contracts § 95', true),
  ('contracts-001', 'formation', 'medium', 'An option contract is:',
   'A contract that can be cancelled at any time by either party.', 'A contract to keep an offer open for a specified period, supported by consideration.', 'An agreement where acceptance is automatic after a set period.', 'A contract formed by conduct, not words.',
   'B', 'An option contract is a separate contract, supported by consideration, under which the offeror is bound to keep the offer open for the agreed period. Acceptance during that period creates a binding contract. Without consideration, an option is merely a revocable offer.', 'Option Contracts — Definition', 'Restatement (Second) of Contracts § 25', true),
  ('contracts-001', 'formation', 'easy', 'Under UCC § 2-204, a contract for the sale of goods:',
   'May be formed in any manner sufficient to show agreement, even if the moment of formation cannot be determined.', 'Must follow common law offer and acceptance rules exactly.', 'Requires a writing for all transactions over $50.', 'Cannot be formed if any terms are left open.',
   'A', 'UCC § 2-204 reflects the Code''s flexibility for commerce: contracts may be formed by conduct, by an exchange of forms, or in any way that shows agreement. Open terms do not necessarily prevent contract formation if the parties intended to contract.', 'UCC § 2-204 — Flexible Formation', 'UCC § 2-204', true),
  ('contracts-001', 'formation', 'hard', 'Nina made a written offer to Oscar to purchase his business for $1 million. Oscar wrote back: ''I agree to sell for $1 million, provided you close within 90 days.'' Nina accepted. Oscar later argues no contract was formed because his response added a term. Under Restatement § 59:',
   'No contract — the 90-day term is a material change creating a counteroffer.', 'Contract formed — the 90-day term is a minor clarification, not a material change.', 'No contract — only if Nina objects to the 90-day term.', 'Contract formed with the 90-day term as an implied term regardless of the mirror image rule.',
   'A', 'Under common law''s mirror image rule (Restatement § 59), any different or additional term in an acceptance is a counteroffer that rejects the original offer. A 90-day closing condition materially alters the offer and operates as a counteroffer, not an acceptance.', 'Mirror Image Rule — Material Added Term', 'Restatement (Second) of Contracts § 59', true),
  ('contracts-001', 'formation', 'medium', 'Pete builds a garage on Mary''s property without asking and then demands payment. Mary knew Pete was building and said nothing. Under contract implied-in-law (quasi-contract):',
   'Pete may recover for unjust enrichment if Mary accepted the benefit knowing Pete expected payment.', 'Pete cannot recover — there was no contract or agreement.', 'Pete may recover the market value regardless of Mary''s knowledge.', 'Mary owes nothing — she never requested the work.',
   'A', 'Recovery in quasi-contract (unjust enrichment) requires: (1) a benefit conferred, (2) knowledge and acceptance by the defendant, and (3) it would be unjust for the defendant to retain the benefit without payment. If Mary knowingly watched Pete build and remained silent, a court may impose quasi-contractual liability.', 'Quasi-Contract — Implied-in-Law / Unjust Enrichment', 'Restatement (Third) of Restitution § 20', true),
  ('contracts-001', 'consideration', 'medium', 'Quinn promises to pay Rick $1,000 if Rick paints Quinn''s fence. Rick begins painting but Quinn revokes before Rick finishes. This is:',
   'A bilateral contract that cannot be revoked.', 'A unilateral contract; the offer can be revoked before completion unless Rick has substantially begun.', 'A unilateral contract; once begun, Quinn cannot revoke.', 'No contract; Quinn can revoke at any time.',
   'C', 'Under the modern rule (Restatement § 45), beginning performance on a unilateral contract creates an option: the offeror may not revoke once the offeree has begun performance. Rick''s painting gives him the right to complete and earn the $1,000.', 'Unilateral Contract — Part Performance / Option', 'Restatement (Second) of Contracts § 45', true),
  ('contracts-001', 'consideration', 'easy', 'Pre-existing duty rule provides that:',
   'A promise to perform an existing legal obligation is not valid consideration.', 'A promise to do more than required is always valid consideration.', 'Prior performance is valid consideration for a new promise.', 'Legal obligations may serve as partial consideration.',
   'A', 'The pre-existing duty rule: a promise to do what one is already legally obligated to do is not valid consideration for a new promise. The promisee is giving up nothing new. Under UCC § 2-209, modifications of goods contracts need no new consideration if made in good faith.', 'Pre-Existing Duty Rule', 'Restatement (Second) of Contracts § 73', true),
  ('contracts-001', 'consideration', 'medium', 'A contractor builds a house for $100,000. Midway through, he demands $20,000 more or he will stop. The owner agrees in writing. After completion, the owner refuses to pay the extra $20,000. Under common law:',
   'The owner must pay — the written agreement is binding.', 'The owner need not pay — the contractor had a pre-existing duty to complete the house.', 'The owner must pay — economic duress made the modification necessary.', 'The owner need not pay — contract modifications require new consideration under the UCC.',
   'B', 'The pre-existing duty rule bars enforcement of the modification. The contractor was already bound to complete for $100,000; his promise to continue is not new consideration. Under common law (unlike UCC § 2-209), contract modifications require consideration.', 'Pre-Existing Duty Rule — Modification', 'Alaska Packers'' Ass''n v. Domenico (1902)', true),
  ('contracts-001', 'consideration', 'hard', 'Sam promises to pay $5,000 to his adult daughter if she stays in college and graduates. She graduates. Sam then refuses to pay, claiming the promise was a gift. Under contract analysis:',
   'The promise is unenforceable as a gift promise.', 'The promise is enforceable only if the daughter changed her behavior in reliance.', 'The promise may be enforceable as a contract if she gave up other options in exchange.', 'The promise is never enforceable as between family members.',
   'C', 'Family promises can be contracts if there is genuine bargained-for exchange. If the daughter gave up something (other plans, another job) in exchange for the promise of payment, there is consideration. The issue is whether the graduation was bargained for or was a condition of a gratuitous promise.', 'Consideration — Gift vs. Bargained Exchange in Family Context', 'Restatement (Second) of Contracts § 71', true),
  ('contracts-001', 'consideration', 'easy', 'Nominal consideration (e.g., $1) in an option contract:',
   'Is never sufficient to support an option.', 'Is sufficient to support an option if the parties intended it as consideration.', 'Is insufficient unless the $1 was actually paid.', 'Is valid only if stated in a formal written instrument.',
   'B', 'Nominal consideration is generally sufficient to support an option contract as long as the parties intended it as consideration and it was actually paid or the option is in a signed writing. Courts will not police the adequacy of consideration.', 'Nominal Consideration — Adequacy', 'Restatement (Second) of Contracts § 79', true),
  ('contracts-001', 'consideration', 'medium', 'A settlement agreement in which a plaintiff gives up a claim in exchange for payment is valid consideration even if:',
   'The claim was not meritorious.', 'The claim was legally invalid, as long as the plaintiff honestly believed the claim had merit and it was not frivolous.', 'The plaintiff later discovers the claim would have succeeded at trial.', 'The plaintiff was represented by counsel who advised against settling.',
   'B', 'Forbearance from a legal claim is valid consideration if (1) the plaintiff honestly believed the claim had some validity, or (2) the claim was reasonably doubtful. If the plaintiff knew the claim was completely baseless, no valid consideration exists. Good faith belief in the claim is the key.', 'Consideration — Settlement of Doubtful Claim', 'Restatement (Second) of Contracts § 74', true),
  ('contracts-001', 'consideration', 'hard', 'Tom promises to pay Ursula $10,000 a year for life. After two years, Tom stops paying, arguing there was no consideration. Ursula argues promissory estoppel. To succeed, Ursula must show:',
   'She gave up economic activity worth $10,000 per year.', 'Tom should have reasonably expected her to rely, she did rely to her detriment, and injustice can only be avoided by enforcement.', 'Tom made the promise in writing.', 'She had a pre-existing legal right to the payments.',
   'B', 'Promissory estoppel under Restatement § 90 requires: (1) promise; (2) promisor reasonably expected reliance; (3) actual reliance/detrimental change of position; (4) enforcement necessary to avoid injustice. Consideration is not required but must be substituted by these elements.', 'Promissory Estoppel — Elements (§ 90)', 'Restatement (Second) of Contracts § 90', true),
  ('contracts-001', 'consideration', 'medium', 'Vicky finds Walt''s lost dog and returns it. Walt promises to pay Vicky $200 as a reward. Later, Walt learns Vicky found the dog by accident and had not seen the reward poster. Walt refuses to pay. Under contract law:',
   'Walt must pay — Vicky conferred a benefit.', 'Walt need not pay — Vicky did not know about the reward when she found the dog.', 'Walt must pay under promissory estoppel.', 'Walt need not pay — finding a dog is not valid consideration.',
   'B', 'For a reward to be enforceable, the claimant must have known about it at the time of performance. If Vicky did not see the reward poster, her act was not done in exchange for the promised reward — no bargained-for exchange occurred. The contract fails for lack of consideration.', 'Consideration — Knowledge of Offer Required', 'Restatement (Second) of Contracts § 71', true),
  ('contracts-001', 'consideration', 'easy', 'Under the illusory promise doctrine, a promise is illusory when:',
   'The promisor has the absolute discretion to perform or not, creating no real obligation.', 'The promise is conditional on an uncertain event.', 'The promise is made for the benefit of a third party.', 'The promise is not in writing.',
   'A', 'An illusory promise appears to be a promise but actually binds the promisor to nothing because the promisor has unfettered discretion. Without obligation on both sides, there is no consideration and no enforceable contract.', 'Illusory Promise Doctrine', 'Wood v. Lucy, Lady Duff-Gordon (1917)', true),
  ('contracts-001', 'consideration', 'hard', 'Xavier promises to sell ''all the widgets I manufacture'' to Yvette at a fixed price. Xavier later claims the contract is illusory because he has no obligation to manufacture anything. Under UCC § 2-306:',
   'The contract is illusory — Xavier has no obligation to produce.', 'The contract is an output contract; Xavier must use best efforts to produce and sell to Yvette.', 'The contract is a requirements contract governed by what Yvette needs.', 'The contract is unenforceable for indefiniteness.',
   'B', 'UCC § 2-306 governs output and requirements contracts. An output contract (seller promises to sell all output to buyer) imposes a good faith/best efforts obligation on both parties, making it non-illusory. The UCC saves these commercial arrangements from the illusory promise doctrine.', 'Output Contract — UCC § 2-306 / Illusory Promise', 'UCC § 2-306', true),
  ('contracts-001', 'performance_breach', 'easy', 'Substantial performance doctrine allows a contractor to recover the contract price minus damages when:',
   'The contractor performed perfectly.', 'The contractor performed most of the contract in good faith, with only minor deviations.', 'The contractor performed at least 50% of the required work.', 'The contractor''s breach was willful.',
   'B', 'Substantial performance allows recovery when performance is nearly complete and in good faith, even if not perfect. The owner may deduct the cost to cure minor deviations. Willful or material breaches do not qualify for this doctrine.', 'Substantial Performance Doctrine', 'Jacob & Youngs, Inc. v. Kent (1921)', true),
  ('contracts-001', 'performance_breach', 'medium', 'Alex contracts to build a house for Betty. Alex uses Cohoes pipe instead of Reading pipe — identical in quality — throughout the house. Using the wrong pipe is discovered only after completion, and replacing the pipe would require tearing down the walls. The measure of Betty''s damages is:',
   'The full contract price reduction for wrong pipe throughout the house.', 'The cost of replacing all the pipe.', 'The difference in value between a house with Cohoes pipe and a house with Reading pipe, if any.', 'The entire contract price because Alex materially breached.',
   'C', 'Under Jacob & Youngs v. Kent, when the cost of completion is grossly disproportionate to the benefit, courts use the diminution in value measure rather than cost of completion. Cohoes and Reading pipe being identical in quality, the difference in value is likely zero or minimal.', 'Measure of Damages — Substantial Performance / Diminution in Value', 'Jacob & Youngs, Inc. v. Kent (1921)', true),
  ('contracts-001', 'performance_breach', 'medium', 'When is a party''s duty to perform excused because the other party has not yet performed?',
   'When the other party''s breach was immaterial.', 'When the contract duties are mutually dependent (constructive conditions of exchange) and the other party has materially breached.', 'When the other party is merely late, not completely non-performing.', 'When the performing party has already substantially performed.',
   'B', 'In contracts with mutually dependent obligations (constructive conditions), a material breach by one party excuses the other from performing. If the breach is immaterial, the non-breaching party must still perform but may sue for damages.', 'Constructive Conditions of Exchange — Material Breach', 'Restatement (Second) of Contracts § 237', true),
  ('contracts-001', 'performance_breach', 'hard', 'Carl has a five-year contract to supply parts to Dana. Three years in, Carl announces that he will not perform the remaining two years. Dana wants to sue immediately. Carl argues Dana must wait until the two years have passed. Under anticipatory repudiation:',
   'Dana must wait — a contract claim does not arise until performance is due.', 'Dana may sue immediately — anticipatory repudiation is treated as an immediate breach.', 'Dana must wait, but may stop her own performance.', 'Dana must give Carl an opportunity to retract before suing.',
   'B', 'Anticipatory repudiation (Restatement § 253): a clear and unequivocal statement by one party that it will not perform is treated as an immediate breach entitling the non-breaching party to sue at once, stop their own performance, and pursue remedies without waiting for the performance date.', 'Anticipatory Repudiation', 'Hochster v. De La Tour (1853)', true),
  ('contracts-001', 'performance_breach', 'easy', 'The implied covenant of good faith and fair dealing requires that:',
   'Both parties perform exactly as written.', 'Neither party will do anything to unfairly deprive the other of the benefit of the bargain.', 'Parties negotiate in good faith before forming a contract.', 'Performance must meet an objective standard of reasonableness.',
   'B', 'Every contract contains an implied covenant of good faith and fair dealing under both common law (Restatement § 205) and UCC § 1-304. It prevents a party from exercising contractual discretion in bad faith to deprive the other of what it bargained for, without requiring literal reading of every term.', 'Implied Covenant of Good Faith and Fair Dealing', 'Restatement (Second) of Contracts § 205', true),
  ('contracts-001', 'performance_breach', 'medium', 'Elaine hired Frank to install flooring in her home for $8,000. Frank completed the job, but used the wrong type of wood. To restore the flooring to the contract specifications would cost $15,000. The home''s value is $5,000 higher with any hardwood than with the original carpet. Which measure of damages applies?',
   'Cost of completion: $15,000.', 'Diminution in value: the difference between the floor as installed and as specified.', 'Frank owes nothing because the home increased in value.', 'Frank owes Elaine the entire contract price back.',
   'B', 'When cost of completion is grossly disproportionate to the benefit, courts award the diminution in value — the difference in value between the performance rendered and the performance promised. The $15,000 cure for a $5,000+ benefit home is disproportionate, supporting the diminution measure.', 'Measure of Damages — Cost of Completion vs. Diminution in Value', 'Peevyhouse v. Garland Coal & Mining Co. (1963)', true),
  ('contracts-001', 'performance_breach', 'hard', 'A buyer of goods learns just before delivery that the seller is insolvent. Under UCC § 2-609 (Adequate Assurance):',
   'The buyer must accept delivery and sue for damages if performance is deficient.', 'The buyer may demand adequate assurance of performance in writing and suspend its own performance until assurance is received.', 'The buyer may cancel the contract immediately.', 'The buyer must pay in advance to secure delivery.',
   'B', 'UCC § 2-609: when reasonable grounds for insecurity arise about performance, either party may demand adequate assurance in writing. If assurance is not provided within a commercially reasonable time (max 30 days), the failure to provide it is a repudiation, allowing the other party to treat the contract as breached.', 'Adequate Assurance — UCC § 2-609', 'UCC § 2-609', true),
  ('contracts-001', 'performance_breach', 'easy', 'A material breach of contract allows the non-breaching party to:',
   'Sue for damages only.', 'Treat the contract as terminated and sue for damages.', 'Recover only reliance damages.', 'Continue performing and ignore the breach.',
   'B', 'A material breach gives the non-breaching party the right to (1) treat the contract as terminated/discharged, (2) withhold further performance, and (3) seek remedies including expectation damages. A non-material (partial) breach allows damages but requires continued performance.', 'Material Breach — Consequences', 'Restatement (Second) of Contracts § 237', true),
  ('contracts-001', 'performance_breach', 'medium', 'George''s contract requires delivery on June 1. He delivers on June 15. For a commercial goods contract, ''time is of the essence'' must:',
   'Always be implied in commercial contracts.', 'Be expressly stated or clearly inferred from the circumstances.', 'Be established by custom in the trade.', 'Never apply unless the contract is for real property.',
   'B', 'Time is of the essence must be expressed or clearly inferred. When time is of the essence, late performance is a material breach. Without such a provision, late performance is a partial breach — the buyer may recover delay damages but must accept the goods.', 'Time of the Essence Clause', 'Restatement (Second) of Contracts § 242', true),
  ('contracts-001', 'performance_breach', 'hard', 'Hilda contracts to sell her restaurant to Ivan. Before closing, Hilda commits anticipatory repudiation. Ivan covers by buying a different restaurant at a higher price. Ivan''s damages are:',
   'The difference between the contract price and the cover price.', 'Consequential damages from lost profits only.', 'The cover price minus any savings Ivan achieved.', 'Nothing — Ivan mitigated by finding a comparable restaurant.',
   'A', 'Under UCC § 2-712 (cover), when a buyer covers after seller''s breach, damages are the difference between the cover price and the contract price, plus incidental damages, minus savings. The buyer acts in good faith and commercially reasonable manner to cover.', 'Anticipatory Repudiation + Cover Damages (UCC § 2-712)', 'UCC § 2-712', true),
  ('contracts-001', 'performance_breach', 'medium', 'Jean contracts to paint Kevin''s house for $5,000. Kevin repudiates before Jean begins. Jean had $1,200 in materials ready. Jean''s recovery under expectation damages is:',
   '$5,000 — the contract price.', '$5,000 minus saved costs (materials not spent, time not used).', '$1,200 — only the cost of materials already acquired.', 'Nothing — Jean did not begin performance.',
   'B', 'Expectation damages aim to put the non-breaching party in the position performance would have created: contract price ($5,000) minus costs saved (not having to complete the job — labor and remaining materials). Jean may also recover the $1,200 already spent if it cannot be recouped.', 'Expectation Damages — Saved Costs Deduction', 'Restatement (Second) of Contracts § 347', true),
  ('contracts-001', 'performance_breach', 'hard', 'A contractor''s breach of a construction contract causes the owner to lose expected profits from operating the building. These lost profits are:',
   'Never recoverable — they are too speculative.', 'Recoverable as consequential damages if they were foreseeable at the time of contracting.', 'Recoverable as part of general damages.', 'Recoverable only if the contractor knew the owner''s specific business plans.',
   'B', 'Hadley v. Baxendale limits damages to those that (1) flow naturally from the breach, or (2) were within the reasonable contemplation of both parties at the time of contracting. Lost business profits are consequential damages — recoverable if foreseeable (known or should have been known) at contract formation.', 'Consequential Damages — Hadley v. Baxendale Rule', 'Hadley v. Baxendale (1854)', true),
  ('contracts-001', 'performance_breach', 'medium', 'Under UCC § 2-508, if a seller delivers non-conforming goods and the buyer rejects them, the seller:',
   'Has no right to try again if the contract date has passed.', 'May have a right to cure by making a conforming delivery within the contract time or within a reasonable additional time after the contract date if the seller had reasonable grounds to believe the goods would be accepted.', 'Must accept the rejection and pay full damages.', 'May cure only if the buyer agrees to a price reduction.',
   'B', 'UCC § 2-508 gives sellers a right to cure non-conforming deliveries: (1) if contract time has not passed, seller may notify of intent to cure and deliver conforming goods; (2) if contract time has passed, seller may cure within a reasonable additional time if it had reasonable grounds to believe the non-conforming goods were acceptable.', 'Seller''s Right to Cure — UCC § 2-508', 'UCC § 2-508', true),
  ('contracts-001', 'performance_breach', 'easy', 'The perfect tender rule under UCC § 2-601 means:',
   'A buyer may reject goods only for significant defects.', 'A buyer may reject goods for any reason if they fail in any respect to conform to the contract.', 'A buyer must accept and then sue for damages for minor defects.', 'A seller must deliver perfect goods without any commercial tolerances.',
   'B', 'UCC § 2-601''s perfect tender rule: if goods or the tender of delivery fails in any respect to conform to the contract, the buyer may (a) reject the whole, (b) accept the whole, or (c) accept any commercial units and reject the rest. This strict standard applies to single delivery contracts.', 'Perfect Tender Rule — UCC § 2-601', 'UCC § 2-601', true),
  ('contracts-001', 'performance_breach', 'hard', 'Under common law, when does a condition precedent excuse non-performance?',
   'When the promisor subjectively believes the condition has not occurred.', 'When the event that was a condition of the duty to perform does not occur.', 'When performance would be burdensome to the promisor.', 'When the promisor cannot perform for reasons outside its control.',
   'B', 'A condition precedent is an event that must occur before a duty to perform arises. If the condition does not occur, the conditional duty never becomes absolute, and failure to perform is excused. The promisor has no obligation to perform until and unless the condition is met.', 'Condition Precedent — Excuse of Non-Performance', 'Restatement (Second) of Contracts § 224', true),
  ('contracts-001', 'performance_breach', 'medium', 'Laura contracts to build a swimming pool for Mark for $40,000. Mark is to pay upon completion. Laura finishes the pool, but it leaks. Laura sues for the contract price. Mark counterclaims for repair costs of $8,000. Under substantial performance:',
   'Laura may recover $40,000 — construction is substantially complete.', 'Laura may recover $32,000 — the contract price minus the cost to cure the defect.', 'Laura may not recover — a leaking pool is not substantial performance.', 'Laura may recover in quantum meruit only.',
   'B', 'If Laura has substantially performed, she is entitled to the contract price ($40,000) minus the damages caused by her defective performance (the cost to repair, $8,000 = $32,000). The key is whether the leaking pool constitutes a material breach or a mere deficiency in an otherwise substantially complete job.', 'Substantial Performance — Breach Plus Recovery', 'Restatement (Second) of Contracts § 237', true),
  ('contracts-001', 'performance_breach', 'easy', 'Novation occurs when:',
   'The original contract is modified by adding new terms.', 'The original contract is extinguished and replaced by a new contract, often substituting a new party.', 'One party assigns its duties to a third party.', 'Both parties agree to suspend performance temporarily.',
   'B', 'Novation requires (1) a previous valid obligation, (2) agreement of all parties, (3) extinguishment of the old obligation, and (4) validity of the new contract. Unlike an assignment, a novation releases the original party from liability.', 'Novation', 'Restatement (Second) of Contracts § 280', true),
  ('contracts-001', 'performance_breach', 'hard', 'Nina was hired to build a bridge for Oscar for $500,000. Midway through, the project became twice as expensive due to unexpected soil conditions. Nina seeks to be excused from the contract under commercial impracticability. To succeed, Nina must show:',
   'Performance became more expensive or difficult.', 'The occurrence of a contingency whose non-occurrence was a basic assumption of the contract, making performance commercially impracticable, and Nina did not assume the risk.', 'Completion would bankrupt Nina''s company.', 'The unexpected conditions were hidden by Oscar.',
   'B', 'Restatement § 261 / UCC § 2-615: commercial impracticability requires (1) occurrence of a contingency, (2) whose non-occurrence was a basic assumption of the contract, (3) making performance impracticable, and (4) the party seeking excuse did not assume the risk. Mere increased cost without extreme difficulty is insufficient.', 'Commercial Impracticability — Elements', 'Restatement (Second) of Contracts § 261', true),
  ('contracts-001', 'performance_breach', 'medium', 'Pat and Quinn have a contract. Without Pat''s consent, Quinn delegates her duties to Rob, who will perform in Quinn''s place. Quinn remains liable:',
   'No — delegation extinguishes Quinn''s liability.', 'Yes — delegation does not relieve Quinn of her duty; Quinn remains secondarily liable.', 'Only if Rob fails to perform.', 'No — Pat must now look only to Rob for performance.',
   'B', 'Delegation of duties does not release the delegator (Quinn) from contractual liability. Quinn remains obligated to Pat as a surety. If Rob does not perform, Quinn remains liable. A delegatee''s assumption of duties may create direct liability to the obligee, but the delegator is not released without a novation.', 'Delegation — Delegator Remains Liable', 'Restatement (Second) of Contracts § 318', true),
  ('contracts-001', 'performance_breach', 'hard', 'Two parties enter a long-term supply contract. An unforeseen war destroys the supplier''s only factory. The supplier seeks excuse under frustration of purpose or impracticability. The supplier is MOST likely to succeed under:',
   'Frustration of purpose — the war prevented the purpose of supplying.', 'Commercial impracticability — the factory destruction makes performance objectively impossible.', 'Neither — contracts must always be performed.', 'Both simultaneously — both doctrines apply to war-caused losses.',
   'B', 'Commercial impracticability is more readily applicable when performance itself becomes impossible (factory destroyed). Frustration of purpose applies when performance is still possible but the purpose of the contract is destroyed. With a destroyed factory, performance is impossible — classic impracticability.', 'Commercial Impracticability vs. Frustration — Destruction of Factory', 'Taylor v. Caldwell (1863)', true),
  ('contracts-001', 'remedies', 'easy', 'The goal of expectation damages in contract law is to:',
   'Punish the breaching party.', 'Put the non-breaching party in the position it would have been in had the contract been performed.', 'Return the non-breaching party to its pre-contract position.', 'Compensate for all foreseeable losses.',
   'B', 'Expectation damages aim to give the aggrieved party the ''benefit of the bargain'' — the position it would have occupied had the contract been fully performed. This includes lost profits, direct losses, and incidental expenses, minus savings resulting from not having to complete performance.', 'Expectation Damages — Goal', 'Restatement (Second) of Contracts § 347', true),
  ('contracts-001', 'remedies', 'medium', 'Alex''s expectation interest in a contract is $10,000. His reliance expenditures are $4,000. He suffered no consequential damages. Normally, Alex should recover:',
   '$4,000 in reliance damages only.', '$10,000 in expectation damages.', '$14,000 (expectation plus reliance).', '$0 — reliance damages are not available when expectation damages are proven.',
   'B', 'A party recovers only once — the goal is to avoid over-compensation. Since Alex''s expectation damages ($10,000) already exceed reliance ($4,000), he recovers expectation damages. Reliance damages are an alternative, not in addition to, expectation damages when the latter is provable.', 'Expectation vs. Reliance Damages — No Double Recovery', 'Restatement (Second) of Contracts § 349', true),
  ('contracts-001', 'remedies', 'hard', 'Ben contracted to publish Carol''s manuscript for a $5,000 advance. Ben repudiates. Carol can prove she spent $2,000 preparing the manuscript but cannot prove lost profits with certainty. Carol''s best remedy is:',
   'Specific performance of the publishing contract.', 'Expectation damages of $5,000 plus lost profits.', 'Reliance damages of $2,000 plus the $5,000 advance.', 'Restitution of the market value of the manuscript.',
   'C', 'When lost profits are too uncertain to prove, a plaintiff may elect reliance damages — recovery of expenses incurred in reliance on the contract. Additionally, Carol is entitled to the promised advance ($5,000) as expectation damages (the certain part of her expectation). The $2,000 preparation cost is a reliance expenditure.', 'Reliance Damages — When Profits Are Uncertain', 'Chicago Coliseum Club v. Dempsey (1932)', true),
  ('contracts-001', 'remedies', 'easy', 'Specific performance as a remedy is available only when:',
   'The breach was willful and egregious.', 'Monetary damages are inadequate to compensate the plaintiff.', 'The contract involves real property.', 'Both parties request equitable relief.',
   'B', 'Specific performance is an equitable remedy ordered only when legal remedies (money damages) are inadequate. It is commonly granted for contracts involving unique property (real estate, rare goods, unique personal services) but not for standard commercial goods easily replaced on the open market.', 'Specific Performance — Inadequacy of Legal Remedy', 'Restatement (Second) of Contracts § 360', true),
  ('contracts-001', 'remedies', 'medium', 'A buyer repudiates a contract to purchase a house. The seller relists the house and eventually sells it for $10,000 less than the original contract price, after spending $2,000 in real estate fees. The seller''s damages are:',
   '$10,000.', '$12,000 — the price differential plus selling costs.', '$2,000 — only the additional costs caused by the breach.', 'Nothing — the seller successfully mitigated.',
   'B', 'Contract damages include the direct loss (price differential = $10,000) and incidental damages caused by the breach (real estate fees to re-sell = $2,000). The seller properly mitigated but is entitled to the full cost of that mitigation.', 'Damages — Price Differential + Incidentals', 'Restatement (Second) of Contracts § 347', true),
  ('contracts-001', 'remedies', 'medium', 'The duty to mitigate requires a non-breaching party to:',
   'Immediately accept any replacement opportunity.', 'Take reasonable steps to avoid or minimize losses caused by the breach.', 'Reduce damages as much as possible regardless of cost.', 'Act within 30 days of learning of the breach.',
   'B', 'The mitigation principle (Restatement § 350): a non-breaching party may not recover damages it could have avoided through reasonable efforts. The duty is to act reasonably, not heroically. The breaching party bears the burden of proving the plaintiff failed to mitigate.', 'Mitigation of Damages', 'Restatement (Second) of Contracts § 350', true),
  ('contracts-001', 'remedies', 'hard', 'Diana contracts to act in Eric''s film for $50,000. Eric repudiates. Diana is offered a role in a comparable film at the same salary. Diana refuses the offer, preferring not to work. Eric argues Diana failed to mitigate. Is Eric correct?',
   'Yes — Diana had an obligation to accept comparable employment.', 'No — Diana cannot be forced to take employment she does not want.', 'Yes — Diana''s refusal was unreasonable and she recovers nothing.', 'No — the comparable role was in a different film, making it not truly comparable.',
   'A', 'Under Shirley MacLaine Parker v. Fox Film Corp., a discharged employee must accept comparable employment to mitigate damages. Refusing a substantially equivalent opportunity constitutes failure to mitigate, and damages are reduced by what could have been earned. The key is whether the alternative was truly comparable.', 'Mitigation — Employment Contracts', 'Parker v. 20th Century-Fox Film Corp. (1970)', true),
  ('contracts-001', 'remedies', 'easy', 'Liquidated damages clauses are enforceable if:',
   'The stipulated sum is a penalty for breach.', 'The amount is a reasonable estimate of anticipated damages at the time of contracting, and actual damages would be difficult to prove.', 'The amount is exactly equal to actual damages.', 'The parties are sophisticated businesses.',
   'B', 'Liquidated damages are enforceable if (1) they are a reasonable estimate of anticipated damages at the time of contracting, and (2) actual damages are difficult to calculate. Clauses that function as penalties (clearly disproportionate to actual damages) are not enforceable.', 'Liquidated Damages — Enforcement Requirements', 'Restatement (Second) of Contracts § 356', true),
  ('contracts-001', 'remedies', 'medium', 'Frank breaches a construction contract with Grace. Grace sues for $100,000 in lost profits. Frank argues the profits are too speculative. Under the certainty requirement for damages:',
   'Grace must prove lost profits with mathematical precision.', 'Grace must prove lost profits with reasonable certainty — not conjecture but not certainty.', 'Grace may recover for lost profits as long as any profit was possible.', 'Lost profits are never recoverable in contract cases.',
   'B', 'The certainty limitation (Restatement § 352): a party may only recover for damages that can be established with reasonable certainty. New businesses face the hardest challenges (no track record). Established businesses may use prior profits as a basis. Reasonable certainty, not speculation, is the standard.', 'Damages — Certainty Requirement', 'Restatement (Second) of Contracts § 352', true),
  ('contracts-001', 'remedies', 'hard', 'Under restitution, a plaintiff who has breached a contract may recover:',
   'Nothing — a breaching party has no restitution rights.', 'The value of benefits conferred on the defendant in excess of the contract price if the breach was material.', 'The reasonable value of benefits conferred, minus any damages caused by the breach.', 'Only if the defendant was unjustly enriched beyond the contract terms.',
   'C', 'Even a breaching plaintiff may recover in restitution for the benefit conferred on the other party, minus any damages the breach caused. Without this rule, the non-breaching party would get a windfall. Recovery is limited to the contract price to prevent the breaching party from profiting from its own wrong.', 'Restitution — Availability for Breaching Party', 'Restatement (Second) of Contracts § 374', true),
  ('contracts-001', 'remedies', 'medium', 'A courier contract requires delivery within 24 hours. The courier is one day late. The recipient lost a $100,000 business deal as a result. The courier did not know the deal was at stake. The recipient seeks $100,000. Under Hadley v. Baxendale:',
   'The recipient recovers $100,000 — the breach caused the loss.', 'The recipient does not recover — the lost deal was not in the courier''s reasonable contemplation at contracting.', 'The recipient recovers if the contract was for a premium delivery service.', 'The recipient recovers $100,000 because foreseeability is judged at breach, not formation.',
   'B', 'Hadley v. Baxendale: consequential damages are recoverable only if they were within the reasonable contemplation of both parties at the time of contracting. The $100,000 lost deal was not foreseeable without the courier knowing the specific business purpose. The courier owes only general delay damages.', 'Consequential Damages — Hadley v. Baxendale Foreseeability', 'Hadley v. Baxendale (1854)', true),
  ('contracts-001', 'remedies', 'hard', 'A real estate buyer repudiates a purchase agreement. The seller does not find another buyer for six months and eventually sells at a $30,000 discount. During the six-month delay, the seller spent $5,000 on carrying costs (taxes, maintenance). The seller''s total damages are:',
   '$30,000 — the market price differential.', '$35,000 — the price differential plus carrying costs as incidental damages.', '$30,000 — carrying costs are the seller''s normal expenses.', '$35,000 — only if the seller made reasonable efforts to sell during the six months.',
   'B', 'Incidental damages (expenses caused directly by the breach and incurred in response to it) are recoverable alongside the market price differential. The $5,000 carrying costs were incurred as a direct consequence of the buyer''s breach and are incidental damages.', 'Incidental Damages — Carrying Costs', 'Restatement (Second) of Contracts § 347', true),
  ('contracts-001', 'remedies', 'easy', 'Restitution as a remedy for breach of contract gives the plaintiff:',
   'The benefit of the bargain.', 'The reasonable value of benefits conferred on the defendant.', 'Damages for all losses caused by the breach.', 'The difference between the contract price and market price.',
   'B', 'Restitution restores the plaintiff to the status quo ante — it recovers the value of what was conferred on the defendant (quantum meruit or quantum valebat). It is not designed to give the plaintiff the benefit of the bargain, which is the goal of expectation damages.', 'Restitution — Goal', 'Restatement (Third) of Restitution § 38', true),
  ('contracts-001', 'remedies', 'medium', 'An injunction may be granted to prevent a party from breaching a personal services contract when:',
   'The services are unique and money damages are inadequate.', 'The breach would cause irreparable harm that cannot be compensated monetarily.', 'Both A and B.', 'The party agreed to an injunction in the contract.',
   'C', 'Courts will not order specific performance of personal services (violates the 13th Amendment/involuntary servitude concerns), but may enjoin a breaching party from performing unique services for a competitor. Both conditions — uniqueness and inadequacy of damages — typically must be shown.', 'Injunction — Personal Services Contracts', 'Lumley v. Wagner (1852)', true),
  ('contracts-001', 'remedies', 'hard', 'A contractor''s breach causes a homeowner both $50,000 in direct losses and $20,000 in consequential damages. The contractor argues consequential damages were not foreseeable. The court finds the contractor knew the homeowner was running a business from the property. The correct award is:',
   '$50,000 — only direct damages are recoverable.', '$70,000 — both direct and consequential damages because the consequential damages were foreseeable.', '$50,000 — consequential damages require a specific agreement.', '$70,000 — all damages flowing from breach are recoverable.',
   'B', 'When the breaching party had actual knowledge of special circumstances at contract formation, consequential damages from those circumstances are recoverable under Hadley''s second limb. The contractor''s knowledge of the business use makes the $20,000 consequential loss foreseeable.', 'Consequential Damages — Actual Knowledge of Special Circumstances', 'Hadley v. Baxendale (1854)', true),
  ('contracts-001', 'remedies', 'medium', 'Punitive damages in a contract case are:',
   'Available whenever the breach was intentional.', 'Generally not available unless the breach also constitutes an independent tort.', 'Available when the defendant acted with malice or oppression.', 'Available in all commercial contract disputes.',
   'B', 'Punitive damages are not available for breach of contract alone, regardless of how bad the breach was. They are only available if the breach also constitutes an independent tort (e.g., fraud, intentional interference) for which punitive damages would otherwise be appropriate.', 'Punitive Damages — Not Available for Breach', 'Restatement (Second) of Contracts § 355', true),
  ('contracts-001', 'remedies', 'easy', 'When a buyer accepts non-conforming goods under the UCC, the buyer''s remedy is:',
   'Rejection of the goods and full refund.', 'Damages equal to the difference between the value of the goods as accepted and as warranted.', 'Return of the purchase price.', 'Lost profits from the non-conforming goods.',
   'B', 'UCC § 2-714: when a buyer accepts non-conforming goods, damages are the difference between the value of the goods as accepted and the value they would have had if they had been as warranted. This applies when the buyer does not timely reject.', 'Non-Conforming Goods — Accepted (UCC § 2-714)', 'UCC § 2-714', true),
  ('contracts-001', 'remedies', 'hard', 'A seller of widgets fails to deliver. The market price at the time of breach is $10/widget. The contract price was $8/widget. The buyer purchased 1,000 widgets from a third party for $11/widget. Under UCC § 2-712 (cover) vs. § 2-713 (market price):',
   'The buyer may recover only market price damages: ($10 - $8) × 1,000 = $2,000.', 'The buyer may choose the higher cover measure: ($11 - $8) × 1,000 = $3,000.', 'The buyer must use cover damages if the buyer actually covered.', 'The buyer recovers the greater of cover or market price damages.',
   'C', 'Under UCC § 2-712, a buyer who actually covers recovers cover price minus contract price. The market price remedy (§ 2-713) is available only if the buyer did not cover. Since the buyer actually bought replacement goods at $11/widget, it must use the cover measure ($3,000), not the market measure ($2,000).', 'Cover Damages — UCC §§ 2-712, 2-713', 'UCC §§ 2-712, 2-713', true),
  ('contracts-001', 'remedies', 'medium', 'A seller fails to deliver unique art promised to a buyer. The buyer seeks specific performance. The court should grant it because:',
   'The seller''s breach was willful.', 'Art is unique and money damages are per se inadequate for unique goods.', 'Specific performance is always available for goods contracts.', 'The UCC requires specific performance for art.',
   'B', 'UCC § 2-716: specific performance may be decreed where goods are unique or in other proper circumstances. Unique art — by definition irreplaceable — makes money damages inadequate because the buyer cannot cover in the marketplace. Specific performance is the proper remedy.', 'Specific Performance — Unique Goods (UCC § 2-716)', 'UCC § 2-716', true),
  ('contracts-001', 'remedies', 'hard', 'A limitation of damages clause in a commercial contract excludes consequential damages for lost profits. The clause is:',
   'Unenforceable per se — all parties are entitled to consequential damages.', 'Enforceable unless it is unconscionable or fails of its essential purpose.', 'Enforceable only if both parties are sophisticated businesses.', 'Enforceable only if the contract is governed by common law, not the UCC.',
   'B', 'UCC § 2-719: parties may limit or modify remedies, including excluding consequential damages, unless (1) the clause is unconscionable, or (2) the limited remedy fails of its essential purpose (e.g., a repair-or-replace remedy that fails to remedy the defect). Between commercial parties, exclusion of consequential damages is presumptively valid.', 'Limitation of Damages Clause — UCC § 2-719', 'UCC § 2-719', true),
  ('contracts-001', 'defenses', 'easy', 'The statute of frauds requires a writing for contracts:',
   'For any amount over $100.', 'Involving the sale of goods for $500 or more, contracts for the sale of land, contracts not performable within one year, surety contracts, and contracts in consideration of marriage.', 'For all commercial transactions.', 'Involving professional services.',
   'B', 'The common law Statute of Frauds (SOF) requires a writing for: (1) contracts for sale of land, (2) contracts not performable within one year, (3) contracts in consideration of marriage, (4) surety/guaranty contracts, and (5) executor/administrator contracts. UCC § 2-201 requires writing for sale of goods ≥ $500.', 'Statute of Frauds — Categories', 'Restatement (Second) of Contracts § 110', true),
  ('contracts-001', 'defenses', 'medium', 'The SOF writing requirement is satisfied by:',
   'A formal contract document signed by both parties.', 'Any writing, however informal, signed by the party to be charged, containing the essential terms.', 'A notarized agreement.', 'An email exchange summarizing the deal.',
   'B', 'The SOF writing requirement is minimal: any writing — memo, letter, receipt, even a cocktail napkin — that is signed by the party to be charged and contains the essential terms of the contract suffices. Courts construe the SOF liberally in favor of enforcement.', 'Statute of Frauds — Writing Requirement', 'Restatement (Second) of Contracts § 131', true),
  ('contracts-001', 'defenses', 'medium', 'Mutual mistake as a defense to contract enforcement requires:',
   'Both parties were mistaken about the same material fact at the time of contracting.', 'Both parties were mistaken about the value of the subject matter.', 'One party was mistaken about a fact the other knew.', 'Both parties were mistaken about future market conditions.',
   'A', 'Mutual mistake (Restatement § 152): both parties must share the same mistake about a material fact existing at the time of contracting. Mistakes about value (not fact) or future conditions (not current facts) generally do not qualify.', 'Mutual Mistake — Elements', 'Restatement (Second) of Contracts § 152', true),
  ('contracts-001', 'defenses', 'hard', 'In Wood v. Boynton, a woman sold a stone for $1, not knowing it was an uncut diamond worth $700. She seeks rescission for mutual mistake. The court should:',
   'Grant rescission — the mistake was about a material fact (the stone''s nature).', 'Deny rescission — the seller bore the risk of the mistake by selling without investigation.', 'Grant rescission — mutual mistake about value always justifies rescission.', 'Deny rescission — only fraudulent misrepresentation allows rescission.',
   'B', 'The court denied rescission in Wood v. Boynton. When a party knows she does not know what she is selling and proceeds anyway, she assumes the risk of the mistake. The seller had the stone for years, had the opportunity to have it appraised, and sold it as-is. Risk assumption bars rescission.', 'Mutual Mistake — Risk Assumption', 'Wood v. Boynton (1885)', true),
  ('contracts-001', 'defenses', 'easy', 'Duress as a defense to contract enforcement means:',
   'One party was under financial stress when contracting.', 'One party''s agreement was the product of an improper threat by the other party that left no reasonable alternative.', 'One party was under time pressure to accept the contract terms.', 'One party relied on the other''s superior bargaining position.',
   'B', 'Duress voids a contract when (1) one party made an improper threat, and (2) the threat left the other party no reasonable alternative but to assent. The threat need not be physical — economic duress (e.g., canceling a critical supply contract mid-performance) can suffice if it leaves no reasonable alternative.', 'Duress — Elements', 'Restatement (Second) of Contracts § 175', true),
  ('contracts-001', 'defenses', 'medium', 'Unconscionability as a defense under UCC § 2-302 allows a court to:',
   'Refuse to enforce the entire contract if it was unfair at formation.', 'Refuse to enforce an unconscionable clause or limit its application.', 'Reduce the contract price to a fair market value.', 'Both A and B.',
   'D', 'UCC § 2-302 and Restatement § 208 give courts discretion to: (1) refuse to enforce the entire contract, (2) refuse to enforce the unconscionable clause only, or (3) limit application of the clause to avoid unconscionable result. Courts have broad equitable power to tailor the remedy.', 'Unconscionability — Court Discretion (UCC § 2-302)', 'UCC § 2-302', true),
  ('contracts-001', 'defenses', 'hard', 'Amy contracts to buy Bob''s car. Amy is 16 (a minor). She pays $3,000. Later, Amy disaffirms the contract. Bob must:',
   'Return $3,000; Amy must return the car in its original condition.', 'Return $3,000 minus the depreciation during Amy''s use.', 'Return $3,000; Amy must return whatever remains of the car.', 'Retain $3,000 — minors must pay for goods they use.',
   'C', 'Under the common law rule of minority/infancy, a minor who disaffirms a contract must return the consideration received (here, the car in whatever condition it is in). The adult must return the full consideration ($3,000). Minority is a complete defense; the minor is not liable for depreciation or use.', 'Minority Defense — Disaffirmance', 'Restatement (Second) of Contracts § 14', true),
  ('contracts-001', 'defenses', 'medium', 'The parol evidence rule bars evidence of:',
   'All prior oral or written negotiations.', 'Prior or contemporaneous oral agreements that contradict or vary the terms of a fully integrated written contract.', 'Subsequent oral modifications of a written contract.', 'Expert testimony about the meaning of contract terms.',
   'B', 'The parol evidence rule (Restatement § 215): if parties have reduced their agreement to a final, fully integrated writing, prior or contemporaneous oral (or written) agreements that contradict the writing are inadmissible. The rule does not bar evidence of subsequent modifications, course of dealing, or evidence to explain (not contradict) ambiguous terms.', 'Parol Evidence Rule — Application', 'Restatement (Second) of Contracts § 215', true),
  ('contracts-001', 'defenses', 'hard', 'A contract is ambiguous as to a key term. Seller argues the term means X; Buyer argues it means Y. Under Raffles v. Wichelhaus (Peerless), if both parties attached different but reasonable meanings to the same term and neither knew the other''s meaning:',
   'The seller''s interpretation controls.', 'The buyer''s interpretation controls.', 'No contract is formed — the parties lacked mutual assent.', 'The court will impose a reasonable meaning.',
   'C', 'Raffles v. Wichelhaus established that if parties attach materially different meanings to a key term and neither knew the other''s meaning, there is no mutual assent and no contract. This is the latent ambiguity doctrine — no agreement was ever formed.', 'Latent Ambiguity — No Mutual Assent (Raffles)', 'Raffles v. Wichelhaus (1864)', true),
  ('contracts-001', 'defenses', 'easy', 'A contract for an illegal purpose is:',
   'Enforceable between the parties.', 'Void and unenforceable.', 'Voidable at the election of the party seeking enforcement.', 'Unenforceable only if the illegality is criminal.',
   'B', 'Contracts for illegal purposes (to violate criminal law or public policy) are void — no court will enforce them. Neither party has rights under such a contract. This differs from voidable contracts (like those formed under duress or by minors), which can be ratified.', 'Illegality — Void Contract', 'Restatement (Second) of Contracts § 178', true),
  ('contracts-001', 'defenses', 'medium', 'Frustration of purpose requires:',
   'Performance becoming impossible.', 'The principal purpose of the contract being substantially frustrated by an unforeseen event whose non-occurrence was a basic assumption, without the party''s fault.', 'Market conditions making the contract less profitable.', 'Both parties agreeing that the purpose has been frustrated.',
   'B', 'Restatement § 265: frustration of purpose excuses performance when (1) the principal purpose is substantially frustrated, (2) by an unforeseen event, (3) whose non-occurrence was a basic assumption of the contract, (4) without the fault of the party seeking excuse. Mere economic adversity is insufficient.', 'Frustration of Purpose — Elements', 'Restatement (Second) of Contracts § 265', true),
  ('contracts-001', 'defenses', 'hard', 'Frank and Gina contract for Frank to perform at Gina''s venue. Three weeks before the event, the venue burns down due to an electrical fault unrelated to either party. Is Frank''s duty to perform excused?',
   'No — Frank could perform elsewhere.', 'Yes — under impossibility (supervening destruction of the subject matter), performance is excused.', 'No — only force majeure clauses excuse performance due to fire.', 'Yes — only if insurance does not cover Gina''s loss.',
   'B', 'Taylor v. Caldwell established the doctrine of supervening impossibility: when a thing essential to performance is destroyed through no fault of either party, performance is excused. The venue is essential to a venue performance contract; its destruction makes performance objectively impossible.', 'Impossibility — Destruction of Subject Matter', 'Taylor v. Caldwell (1863)', true),
  ('contracts-001', 'defenses', 'medium', 'The UCC Statute of Frauds requires a writing for contracts for the sale of goods of $500 or more. Which satisfies the UCC SOF writing requirement?',
   'A letter confirming the deal signed by the seller only, sent to the buyer.', 'An invoice from the seller.', 'A purchase order from the buyer.', 'All of the above if they contain the quantity term.',
   'D', 'UCC § 2-201 requires a writing sufficient to indicate a contract for sale of goods, signed by the party against whom enforcement is sought. Between merchants, a written confirmation signed by one party satisfies the SOF against the receiving party if the recipient does not object within 10 days. Invoices, POs, and confirmations all qualify if they include quantity.', 'UCC Statute of Frauds — Writing (§ 2-201)', 'UCC § 2-201', true),
  ('contracts-001', 'defenses', 'hard', 'Hannah seeks to enforce an oral contract for the sale of Greenacre for $200,000. The seller part-performed by allowing Hannah to make improvements. Under the part performance exception to the Statute of Frauds for land contracts:',
   'Part performance never excuses the writing requirement for land contracts.', 'Hannah may enforce the contract if her actions were unequivocally referable to the alleged contract and not explainable without it.', 'Hannah must fully perform her own obligations before the exception applies.', 'The part performance exception applies only if both parties have substantially performed.',
   'B', 'The part performance exception to the real estate SOF: a purchaser who has taken possession, paid part of the price, and made improvements — acts that are unequivocally referable to the contract and that cannot be explained except by reference to it — may obtain specific performance despite the lack of a writing.', 'Statute of Frauds — Part Performance Exception (Real Estate)', 'Restatement (Second) of Contracts § 129', true),
  ('contracts-001', 'defenses', 'medium', 'A clause in an employment contract says: ''Employer may terminate for any reason.'' Employee argues this is an illusory promise making the contract unenforceable. The employer''s best counter-argument is:',
   'The at-will clause makes both promises mutual.', 'The employee''s services provide consideration; the employee''s promise to work binds both parties for the period of employment.', 'The clause is a standard commercial term.', 'Employment contracts never require consideration from employers.',
   'B', 'In at-will employment, the employee''s promise to work constitutes consideration for the employer''s promise to pay, even though either party can terminate. There is actual performance in exchange for payment. The illusory promise argument fails because the employee''s promise is real for the period before termination.', 'Consideration — At-Will Employment', 'Wood v. Lucy, Lady Duff-Gordon (1917)', true),
  ('contracts-001', 'defenses', 'hard', 'A seller delivers goods but the buyer claims they are defective. The buyer rejects them. Under UCC § 2-602, rejection must be:',
   'Immediate — the buyer must reject upon delivery.', 'Within a reasonable time after delivery, and the buyer must seasonably notify the seller.', 'In writing within 10 days.', 'Only by returning the goods to the seller.',
   'B', 'UCC § 2-602: rejection of goods must occur within a reasonable time after delivery or tender. The buyer must seasonably notify the seller. Failure to timely reject constitutes acceptance. The buyer retains the goods pending seller''s instructions.', 'Rejection — UCC § 2-602', 'UCC § 2-602', true),
  ('contracts-001', 'defenses', 'medium', 'A party claims the contract is void for lack of capacity because she was intoxicated when signing. Under contract law, intoxication as a defense requires:',
   'Blood alcohol above a legal limit.', 'The party lacked capacity to understand the nature of the transaction AND the other party had reason to know.', 'The party was involuntarily intoxicated.', 'Any measurable level of intoxication at the time of signing.',
   'B', 'Restatement § 16: a contract is voidable for intoxication if (1) the party was unable to understand the nature and consequences of the transaction due to intoxication, and (2) the other party had reason to know of the incapacity. Voluntary intoxication does not automatically void a contract.', 'Incapacity — Intoxication', 'Restatement (Second) of Contracts § 16', true),
  ('contracts-001', 'defenses', 'easy', 'An integrated written contract may be supplemented (but not contradicted) by:',
   'Prior oral agreements.', 'Evidence of course of dealing, course of performance, and trade usage.', 'Oral modifications made before signing.', 'Oral modifications made after signing but before breach.',
   'B', 'The parol evidence rule bars evidence that contradicts a written integrated contract. However, courts always admit evidence of course of dealing (prior conduct between these parties), course of performance (how they performed this contract), and trade usage to explain or supplement — but not contradict — the written terms.', 'Parol Evidence — Permitted Supplementation', 'UCC § 1-303', true),
  ('contracts-001', 'defenses', 'hard', 'An arbitration clause in a contract requires all disputes to be arbitrated and bars class actions. A consumer alleges the clause is unconscionable. Under current Supreme Court doctrine:',
   'Courts may refuse to enforce arbitration clauses that are unconscionable under state law.', 'The Federal Arbitration Act preempts state unconscionability rules that specifically target arbitration clauses.', 'Courts may strike class action waivers in arbitration agreements as a matter of public policy.', 'Arbitration clauses are per se unconscionable in consumer contracts.',
   'B', 'AT&T Mobility LLC v. Concepcion: the Federal Arbitration Act (FAA) preempts state laws that invalidate arbitration agreements based on a rule that specifically targets arbitration (e.g., a rule that class action waivers in arbitration are unconscionable). The FAA establishes a liberal federal policy favoring arbitration.', 'Arbitration — FAA Preemption (Concepcion)', 'AT&T Mobility LLC v. Concepcion (2011)', true),
  ('contracts-001', 'defenses', 'medium', 'A contract for the sale of a house fails to include the closing date — a material term. Under the Restatement:',
   'No contract — all material terms must be agreed upon for formation.', 'A court may supply a reasonable closing date if the parties otherwise intended to be bound.', 'The buyer may set any closing date.', 'The contract is voidable at the seller''s option.',
   'B', 'Courts may supply reasonable terms for indefinite or missing contract provisions if the parties clearly intended to be bound. A reasonable closing date based on custom and the circumstances is an example. Complete indefiniteness that prevents enforcement is different from a missing term a court can supply.', 'Open or Indefinite Terms — Court May Supply', 'Restatement (Second) of Contracts § 204', true),
  ('contracts-001', 'ucc_article_2', 'easy', 'UCC Article 2 governs contracts for the:',
   'Sale of real property.', 'Sale of services.', 'Sale of goods.', 'Lease of personal property.',
   'C', 'UCC Article 2 applies to contracts for the sale of goods — movable, tangible personal property. It does not apply to real estate sales (governed by common law), service contracts, or leases (governed by Article 2A).', 'UCC Article 2 — Scope', 'UCC § 2-102', true),
  ('contracts-001', 'ucc_article_2', 'medium', 'When a contract involves both goods and services (a ''mixed'' contract), courts apply:',
   'UCC Article 2 to all aspects.', 'Common law to all aspects.', 'The predominant purpose test: if the dominant purpose is goods, UCC applies; if services, common law applies.', 'UCC to goods portions; common law to services portions.',
   'C', 'The predominant purpose (gravamen) test: courts look at whether the predominant purpose of the contract is the sale of goods or the provision of services. If goods predominate, the UCC governs the entire contract; if services predominate, common law governs.', 'UCC — Mixed Contracts (Predominant Purpose Test)', 'Bonebrake v. Cox (8th Cir. 1974)', true),
  ('contracts-001', 'ucc_article_2', 'medium', 'Under UCC § 2-305, parties may form a contract even if the price is:',
   'Left completely open, as long as price is ascertainable.', 'Expressly agreed to later, left open for good faith determination, or set by reference to market.', 'Fixed by the seller alone.', 'Set by an independent arbitrator after delivery.',
   'B', 'UCC § 2-305 (Open Price Term): a contract for sale may be formed even if the price is not settled. If parties intend to contract, price may be (1) left to be agreed later, (2) left to be determined by market or reference standard, or (3) determined by the buyer or seller in good faith.', 'UCC Open Price Term — § 2-305', 'UCC § 2-305', true),
  ('contracts-001', 'ucc_article_2', 'hard', 'A merchant who deals in goods of the kind sold makes a firm offer in a signed writing. Under UCC § 2-205, how long is this offer irrevocable?',
   '30 days.', 'The time stated in the offer, or if no time is stated, a reasonable time, but not to exceed 3 months.', 'One year.', 'Until the merchant withdraws it.',
   'B', 'UCC § 2-205 (Firm Offers): a merchant''s signed, written offer that gives assurance it will be held open is irrevocable for the time stated, or if no time is stated, for a reasonable time, but in no case may the period exceed 3 months. No consideration is required for the firm offer.', 'UCC Firm Offer — § 2-205', 'UCC § 2-205', true),
  ('contracts-001', 'ucc_article_2', 'easy', 'Under UCC § 2-314, goods sold by a merchant carry an implied warranty of:',
   'Fitness for a particular purpose.', 'Merchantability — that they are fit for the ordinary purposes for which such goods are used.', 'Freedom from all defects.', 'Non-infringement of third-party intellectual property rights.',
   'B', 'UCC § 2-314: every merchant who regularly deals in goods of the kind sold makes an implied warranty of merchantability — that the goods are of at least average quality, adequately packaged, and fit for the ordinary purposes for which such goods are used. Non-merchants do not make this warranty.', 'Implied Warranty of Merchantability — UCC § 2-314', 'UCC § 2-314', true),
  ('contracts-001', 'ucc_article_2', 'medium', 'The implied warranty of fitness for a particular purpose (UCC § 2-315) arises when:',
   'Any seller sells goods for a specific purpose stated by the buyer.', 'A seller, with reason to know of the buyer''s particular purpose, selects goods the buyer relies upon.', 'A buyer informs the seller of a special intended use.', 'The seller is a merchant dealing in goods of the kind sold.',
   'B', 'UCC § 2-315: the warranty of fitness for a particular purpose arises when (1) the seller has reason to know of the buyer''s particular purpose, (2) the seller selects goods for that purpose, and (3) the buyer relies on the seller''s skill or judgment. The seller need not be a merchant.', 'Implied Warranty of Fitness for Particular Purpose — § 2-315', 'UCC § 2-315', true),
  ('contracts-001', 'ucc_article_2', 'hard', 'Under UCC § 2-316, a disclaimer of the implied warranty of merchantability must:',
   'Be in writing only.', 'Mention ''merchantability'' by name and, if in writing, be conspicuous.', 'Use the words ''as is'' or ''with all faults.''', 'Be agreed to before delivery.',
   'B', 'UCC § 2-316: to disclaim the implied warranty of merchantability, the disclaimer must (1) mention the word ''merchantability'' specifically, and (2) if in writing, be conspicuous (visible and readable). ''As is'' language under § 2-316(3) excludes all implied warranties without the specific merchantability language.', 'Disclaimer of Warranty — UCC § 2-316', 'UCC § 2-316', true),
  ('contracts-001', 'ucc_article_2', 'medium', 'When is risk of loss on goods covered by a carrier contract? Under UCC § 2-509:',
   'When the goods are loaded on the carrier.', 'When the goods are delivered to the buyer''s location.', 'When the seller delivers the goods to the carrier if the contract requires carrier shipment (shipment contract) or upon tender at destination (destination contract).', 'When the buyer pays for the goods.',
   'C', 'UCC § 2-509: in a shipment contract (F.O.B. seller''s city), risk passes when seller delivers to the carrier. In a destination contract (F.O.B. buyer''s city), risk passes when the seller tenders the goods at destination. The contract terms (F.O.B.) determine which type applies.', 'Risk of Loss — Carrier Contracts (UCC § 2-509)', 'UCC § 2-509', true),
  ('contracts-001', 'ucc_article_2', 'easy', 'Under the UCC, a buyer''s acceptance of goods:',
   'Is final and irrevocable.', 'May be revoked for a non-conformity that substantially impairs the value if the defect was not discoverable upon inspection.', 'Requires the buyer to waive all warranty claims.', 'Occurs only when the buyer makes an express statement of acceptance.',
   'B', 'UCC § 2-608: a buyer who has accepted goods may revoke acceptance if (1) the non-conformity substantially impairs the value, and (2) the defect was hidden (not discoverable upon inspection), OR the buyer accepted because the seller promised to cure and failed to do so. Revocation must occur before the goods are substantially changed by the buyer.', 'Revocation of Acceptance — UCC § 2-608', 'UCC § 2-608', true),
  ('contracts-001', 'ucc_article_2', 'hard', 'Under F.O.B. seller''s city (shipment contract), goods are damaged in transit by a carrier. Who bears the risk of loss?',
   'The seller — it chose the carrier.', 'The buyer — risk passed to the buyer when the seller delivered to the carrier.', 'The carrier — it was negligent.', 'Shared equally between buyer and seller.',
   'B', 'F.O.B. seller''s city creates a shipment contract. Risk of loss passes to the buyer when the seller delivers the goods to the carrier. Thereafter, the buyer bears the risk during transit. The buyer''s remedy is against the carrier, not the seller (absent seller''s breach).', 'Risk of Loss — F.O.B. Shipment Contract', 'UCC § 2-319, § 2-509', true),
  ('contracts-001', 'ucc_article_2', 'medium', 'Under the entrustment doctrine (UCC § 2-403), if an owner entrusts goods to a merchant dealer in goods of that kind and the merchant sells to a buyer in the ordinary course of business:',
   'The original owner may reclaim the goods.', 'The buyer in the ordinary course acquires title free of the original owner''s claim.', 'The merchant is liable for conversion but the buyer takes good title.', 'The original owner and buyer both have claims.',
   'B', 'UCC § 2-403 (Entrustment): entrusting goods to a merchant who deals in goods of that kind gives the merchant power to transfer all rights of the entruster to a buyer in the ordinary course of business. The innocent buyer''s title is protected; the original owner''s remedy is against the merchant.', 'Entrustment — UCC § 2-403', 'UCC § 2-403', true),
  ('contracts-001', 'ucc_article_2', 'hard', 'A buyer contracts to purchase 500 widgets. The seller delivers 475. The buyer''s remedies under UCC § 2-601 (perfect tender) are:',
   'The buyer must accept and sue for the shortage only.', 'The buyer may reject all 475 widgets, or accept all 475 and sue for the shortage.', 'The buyer must accept because 475 is substantial performance.', 'The buyer may sue only if the shortage was material.',
   'B', 'UCC § 2-601 (perfect tender): if the seller''s tender fails in any respect, the buyer may reject all, accept all, or accept any commercial units and reject the rest. Accepting 475 and seeking damages for the shortage of 25 is one option. Rejecting all 475 is another (buyer is entitled to exact conformity).', 'Perfect Tender — Partial Delivery', 'UCC § 2-601', true),
  ('contracts-001', 'ucc_article_2', 'easy', 'An express warranty under UCC § 2-313 can be created by:',
   'Any statement of fact or promise, description of goods, or sample/model.', 'Only written statements signed by the seller.', 'Only affirmations of fact, not opinions.', 'Only representations made at the time of contracting.',
   'A', 'UCC § 2-313: express warranties arise from (1) affirmations of fact or promise relating to the goods, (2) descriptions of the goods, and (3) samples or models, if they become part of the basis of the bargain. Seller''s opinions (''puffery'') do not create warranties.', 'Express Warranty — UCC § 2-313', 'UCC § 2-313', true),
  ('contracts-001', 'ucc_article_2', 'medium', 'A contract states the goods will be delivered ''about June 1.'' On June 15, the seller tenders. The buyer seeks to reject for late delivery. Under the UCC:',
   'The buyer may reject — ''about June 1'' means June 1.', 'The buyer must accept — ''about'' creates flexibility around the stated date.', 'The buyer may reject only if time is of the essence.', 'The buyer must accept and seek only incidental damages.',
   'B', '''About June 1'' signals an approximation rather than a firm date. Courts interpret ''about'' language to give the seller reasonable commercial flexibility. June 15 delivery is likely within the range of ''about June 1'' absent other evidence that exact timing was critical.', 'UCC — Approximate Time Terms', 'UCC § 2-503', true),
  ('contracts-001', 'ucc_article_2', 'hard', 'Seller and buyer are both merchants. Buyer sends a purchase order for 500 units. Seller responds with a form that contains all the same terms plus a term excluding consequential damages. No one objects. Under UCC § 2-207:',
   'The exclusion of consequential damages is included — both parties are merchants.', 'The exclusion is a material alteration and is not part of the contract.', 'No contract forms — the forms differ.', 'The buyer''s form controls as the initial offer.',
   'B', 'UCC § 2-207: between merchants, additional terms in an acceptance become part of the contract unless they materially alter it. Courts have consistently held that exclusion of consequential damages is a material alteration because it significantly shifts the risk allocation from the bargained terms. It does not enter the contract without express assent.', 'UCC § 2-207 — Material Alteration (Consequential Damages Exclusion)', 'UCC § 2-207', true),
  ('contracts-001', 'ucc_article_2', 'medium', 'A seller repudiates a contract. The buyer ''covers'' by buying substitute goods. To qualify as proper cover under UCC § 2-712, the buyer''s purchase must be:',
   'At a lower price than the contract price.', 'Made in good faith and in a commercially reasonable manner without unreasonable delay.', 'From the same type of seller as the repudiating seller.', 'Exactly equivalent to the contracted goods.',
   'B', 'UCC § 2-712: cover must be made in good faith and without unreasonable delay. The substitute goods need not be identical — just reasonable substitutes. The buyer recovers the difference between the cover price and the contract price.', 'Cover — Good Faith and Commercial Reasonableness (§ 2-712)', 'UCC § 2-712', true),
  ('contracts-001', 'ucc_article_2', 'easy', 'Under the UCC, a merchant is defined as:',
   'Any person who sells goods for profit.', 'A person who deals in goods of the kind or holds himself out as having special knowledge or skill in the goods.', 'Any business with a storefront.', 'Any person who regularly conducts business transactions.',
   'B', 'UCC § 2-104: a merchant is a person who deals in goods of the kind, or who holds out by occupation as having knowledge or skill about the goods or practices involved. Merchants are held to higher standards (e.g., firm offer rule, battle of the forms between merchants, warranty of merchantability).', 'UCC — Definition of Merchant', 'UCC § 2-104', true),
  ('contracts-001', 'ucc_article_2', 'hard', 'Under UCC § 2-207(3), when parties'' forms conflict on key terms and neither form controls, a contract is formed by:',
   'The offeror''s form.', 'Conduct of the parties that recognizes the existence of a contract.', 'The court selecting commercially reasonable terms.', 'No contract — material conflicts in forms prevent formation.',
   'B', 'UCC § 2-207(3): when parties'' conduct establishes a contract despite conflicting forms, the contract consists of the terms on which the writings agree, plus UCC gap-fillers. ''Knockout rule'' — conflicting terms in the forms knock each other out, and UCC default rules fill the gaps.', 'UCC § 2-207(3) — Contract by Conduct / Knockout Rule', 'UCC § 2-207(3)', true),
  ('contracts-001', 'ucc_article_2', 'medium', 'A seller''s goods fail to conform to the contract. Under UCC § 2-711, the buyer''s remedies include:',
   'Rejection and recovery of the price paid.', 'Cover damages.', 'Consequential damages.', 'All of the above.',
   'D', 'UCC § 2-711: when the seller fails to deliver conforming goods, the buyer may cancel the contract, recover any price paid, then pursue: (1) cover (§ 2-712), (2) market price damages (§ 2-713), (3) specific performance for unique goods (§ 2-716), and (4) incidental and consequential damages (§ 2-715).', 'Buyer''s Remedies — UCC § 2-711', 'UCC § 2-711', true),
  ('contracts-001', 'ucc_article_2', 'hard', 'An oral contract for the sale of 200 widgets at $3 each ($600 total) is disputed. The buyer says there was a contract; the seller says there was not. Under UCC § 2-201, which of the following would satisfy the Statute of Frauds to allow enforcement?',
   'The buyer''s testimony alone.', 'A confirmatory memo sent by the buyer and received by the seller, who did not object within 10 days.', 'An invoice from a third-party shipper.', 'The buyer''s payment alone.',
   'B', 'UCC § 2-201: between merchants, a written confirmation of a contract signed by one party satisfies the SOF against the receiving merchant if the receiving merchant does not object in writing within 10 days of receipt. The seller''s failure to object binds the seller despite not signing the confirmation.', 'UCC Statute of Frauds — Merchant Confirmation Exception', 'UCC § 2-201(2)', true)
) AS v(subject_id, category, difficulty, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, rule_tested, case_citation, is_active)
WHERE NOT EXISTS (SELECT 1 FROM quiz_questions q
                  WHERE q.subject_id = v.subject_id AND q.stem = v.stem);

COMMIT;

-- ══ from 20260720000003_seed_civil_procedure.sql ══
-- Civil Procedure: Jurisdiction, Pleading, Discovery, Summary Judgment, Trial, Preclusion, Venue, Class Actions, Appeals
-- 43 MBE questions

BEGIN;

INSERT INTO quiz_questions
  (subject_id, category, difficulty, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, rule_tested, case_citation, is_active)
SELECT v.* FROM (VALUES
('civ-pro-001', 'jurisdiction', 'easy', 'For a federal court to have subject matter jurisdiction based on diversity of citizenship, the amount in controversy must exceed:',
   '$50,000.', '$75,000, exclusive of interest and costs.', '$100,000.', '$25,000.',
   'B', '28 U.S.C. § 1332 grants diversity jurisdiction when (1) the parties are citizens of different states (complete diversity), and (2) the amount in controversy exceeds $75,000, exclusive of interest and costs. The $75,000 threshold is exclusive — claims of exactly $75,000 do not qualify.', 'Diversity Jurisdiction — Amount in Controversy', '28 U.S.C. § 1332', true),
  ('civ-pro-001', 'jurisdiction', 'medium', 'Plaintiff, a citizen of New York, sues Defendant Corp, incorporated in Delaware with its principal place of business in California. For diversity purposes, Defendant Corp is a citizen of:',
   'Delaware only — the state of incorporation.', 'California only — the state of principal place of business.', 'Both Delaware and California.', 'Either Delaware or California at the defendant''s election.',
   'C', '28 U.S.C. § 1332(c): a corporation is a citizen of (1) the state(s) of incorporation, and (2) the state where it has its principal place of business (the ''nerve center'' — where officers direct and control activities). Defendant Corp is a citizen of both Delaware and California.', 'Diversity — Corporate Citizenship', 'Hertz Corp. v. Friend (2010)', true),
  ('civ-pro-001', 'jurisdiction', 'medium', 'Federal question jurisdiction under 28 U.S.C. § 1331 exists when:',
   'A federal law is mentioned in the complaint.', 'The plaintiff''s cause of action arises under the Constitution, laws, or treaties of the United States, as shown on the face of the well-pleaded complaint.', 'The defendant raises a federal defense.', 'Any party asserts a federal claim.',
   'B', 'The well-pleaded complaint rule: federal question jurisdiction exists only when the federal question appears on the face of the plaintiff''s complaint — not in an anticipated defense. Louisville & Nashville R.R. v. Mottley established this foundational principle.', 'Federal Question Jurisdiction — Well-Pleaded Complaint Rule', 'Louisville & Nashville R.R. v. Mottley (1908)', true),
  ('civ-pro-001', 'jurisdiction', 'hard', 'A state court action involves only state law claims. The defendant removes to federal court based on a federal defense. The plaintiff moves to remand. The court should:',
   'Retain the case — any federal issue creates federal jurisdiction.', 'Remand — federal jurisdiction requires the federal question to appear on the face of the complaint.', 'Retain if the federal defense would be dispositive.', 'Retain if the defendant is a federal agency.',
   'B', 'Well-pleaded complaint rule (Mottley): federal question jurisdiction must be established by the plaintiff''s complaint, not by an anticipated or actual federal defense. Removal on the basis of a federal defense is improper; the case must be remanded.', 'Federal Question — No Jurisdiction Based on Federal Defense', 'Louisville & Nashville R.R. v. Mottley (1908)', true),
  ('civ-pro-001', 'jurisdiction', 'medium', 'Personal jurisdiction over a nonresident defendant in a specific jurisdiction case requires:',
   'The defendant''s continuous and systematic contacts with the state.', 'Minimum contacts with the forum state such that exercising jurisdiction would not offend traditional notions of fair play and substantial justice, plus the claim must arise from those contacts.', 'The defendant to have been served with process in the state.', 'The defendant to have consented to jurisdiction.',
   'B', 'International Shoe: specific jurisdiction requires minimum contacts with the forum arising from or relating to the plaintiff''s claim, plus reasonableness. General jurisdiction (continuous/systematic contacts) allows jurisdiction on any claim regardless of where the claim arose.', 'Specific Personal Jurisdiction — International Shoe', 'International Shoe Co. v. Washington (1945)', true),
  ('civ-pro-001', 'jurisdiction', 'hard', 'A defendant was served with process while passing through the forum state. Under Burnham v. Superior Court, this ''tag'' jurisdiction is:',
   'Unconstitutional — transient presence is insufficient minimum contacts.', 'Constitutional — physical presence in the state at time of service is a traditional basis for personal jurisdiction.', 'Constitutional only for residents, not transient visitors.', 'Constitutional only if the forum state has a long-arm statute permitting it.',
   'B', 'Burnham v. Superior Court held that personal service on a nonresident physically present in the forum state (tag jurisdiction) is constitutional, even without minimum contacts. A plurality based this on tradition; Justice Brennan''s concurrence required fairness analysis — but the outcome was unanimous.', 'Tag Jurisdiction — Burnham', 'Burnham v. Superior Court of California (1990)', true),
  ('civ-pro-001', 'jurisdiction', 'medium', 'For a plaintiff to establish general personal jurisdiction over a corporation, the plaintiff must show:',
   'The corporation was incorporated in the forum state.', 'The corporation''s contacts with the state are so continuous and systematic as to render it essentially at home in the forum state.', 'The corporation has an office or employee in the forum state.', 'The corporation''s principal product is sold in the forum state.',
   'B', 'Daimler AG v. Bauman: a corporation is subject to general jurisdiction only where it is ''at home'' — its place of incorporation or principal place of business. Mere continuous business activities (selling products, advertising) do not suffice for general jurisdiction absent exceptional circumstances.', 'General Personal Jurisdiction — ''At Home'' Standard', 'Daimler AG v. Bauman (2014)', true),
  ('civ-pro-001', 'jurisdiction', 'easy', 'Supplemental jurisdiction under 28 U.S.C. § 1367 allows a federal court to hear:',
   'Any state law claim joined in a federal action.', 'State law claims that share a common nucleus of operative fact with claims over which the court has original jurisdiction.', 'Only counterclaims by the defendant.', 'State law claims that do not destroy complete diversity.',
   'B', '28 U.S.C. § 1367: supplemental jurisdiction permits a federal court to hear state claims that form part of the same case or controversy as the federal claim (same common nucleus of operative fact). The court has discretion to decline supplemental jurisdiction in certain circumstances.', 'Supplemental Jurisdiction — § 1367', '28 U.S.C. § 1367', true),
  ('civ-pro-001', 'jurisdiction', 'medium', 'P (NY) sues D (TX) in federal court for $80,000 in personal injury damages. D impleads T (NY) for indemnification. The court has supplemental jurisdiction over the D-T claim because:',
   'D and T are diverse.', 'The impleader claim shares a common nucleus of operative fact with the main claim.', 'Impleader claims always satisfy diversity.', 'T is not a plaintiff and cannot destroy diversity.',
   'B', 'Under § 1367, the court has supplemental jurisdiction over the D-T impleader claim because it arises from the same transaction (the accident) as the main claim. Supplemental jurisdiction fills in where original jurisdiction is lacking for related claims, even if diversity would be lacking between D and T.', 'Supplemental Jurisdiction — Impleader', '28 U.S.C. § 1367', true),
  ('civ-pro-001', 'jurisdiction', 'hard', 'The doctrine of Rooker-Feldman bars federal district courts from:',
   'Reviewing state court decisions — that review belongs to the Supreme Court on certiorari.', 'Entertaining claims that were or could have been raised in state court proceedings.', 'Hearing cases that could have been filed in state court.', 'Exercising jurisdiction over pending state proceedings.',
   'A', 'Rooker-Feldman doctrine: lower federal courts lack jurisdiction to review state court judgments. Review of state court decisions is reserved to the U.S. Supreme Court by certiorari under 28 U.S.C. § 1257. A federal district court may not re-examine a state court decision even if the party alleges a federal constitutional violation.', 'Rooker-Feldman Doctrine', 'Rooker v. Fidelity Trust Co. (1923)', true),
  ('civ-pro-001', 'pleading', 'easy', 'Under FRCP Rule 8(a), a complaint must contain:',
   'A detailed statement of the facts.', 'A short and plain statement of the claim showing the pleader is entitled to relief, plus a demand for relief.', 'Detailed legal theories.', 'All evidence the plaintiff intends to use at trial.',
   'B', 'FRCP 8(a) sets out the basic pleading standard: (1) grounds for the court''s jurisdiction, (2) a short and plain statement of the claim, and (3) a demand for relief. The standard is permissive — notice pleading — but requires plausible factual allegations per Twombly/Iqbal.', 'FRCP Rule 8(a) — Pleading Standard', 'FRCP 8(a)', true),
  ('civ-pro-001', 'pleading', 'medium', 'Under Bell Atlantic Corp. v. Twombly, a complaint must allege facts that:',
   'Are merely consistent with the defendant''s liability.', 'Are plausible on their face — more than mere labels and formulaic recitals.', 'Prove the plaintiff''s case to a preponderance of the evidence.', 'Are supported by at least one witness.',
   'B', 'Twombly raised the pleading standard above ''conceivable'' to ''plausible.'' A complaint must allege enough facts to state a claim that is plausible on its face — not just consistent with liability, but one that the court can reasonably infer crosses the line from possible to plausible.', 'Pleading Standard — Twombly/Iqbal Plausibility', 'Bell Atlantic Corp. v. Twombly (2007)', true),
  ('civ-pro-001', 'pleading', 'hard', 'Under FRCP 9(b), fraud must be pled with particularity. This requires:',
   'General allegations that fraud occurred.', 'The who, what, when, where, and how of the alleged fraud.', 'A bill of particulars filed with the complaint.', 'Sworn statements from witnesses to the fraud.',
   'B', 'FRCP 9(b): in all averments of fraud or mistake, a party must state with particularity the circumstances constituting the fraud. This means identifying the fraudulent statements (what), who made them (who), when and where, and why they were false (how). Mental state may be averred generally.', 'Rule 9(b) — Pleading Fraud With Particularity', 'FRCP 9(b)', true),
  ('civ-pro-001', 'pleading', 'medium', 'Under FRCP 12(b)(6), a defendant may move to dismiss for:',
   'Lack of personal jurisdiction.', 'Failure to state a claim upon which relief can be granted.', 'Insufficient process.', 'Improper venue.',
   'B', 'FRCP 12(b) lists seven defenses that may be raised by motion before answering. 12(b)(6) is the motion to dismiss for failure to state a claim — testing the legal sufficiency of the complaint, not the underlying facts. Courts accept all well-pleaded factual allegations as true.', 'FRCP 12(b)(6) — Motion to Dismiss', 'FRCP 12(b)(6)', true),
  ('civ-pro-001', 'pleading', 'hard', 'A party does not raise a 12(b)(2) (personal jurisdiction) defense in its first responsive pleading or in a pre-answer motion. The defense is:',
   'Preserved for appeal.', 'Waived.', 'Transferred to the forum state.', 'Still available in later stages of litigation.',
   'B', 'FRCP 12(h)(1): a party waives personal jurisdiction (12(b)(2)), improper venue (12(b)(3)), insufficient process (12(b)(4)), and insufficient service of process (12(b)(5)) if not raised in the first responsive pleading or a pre-answer 12(b) motion. These defenses are waivable; subject matter jurisdiction is not.', 'Waiver of Defenses — FRCP 12(h)', 'FRCP 12(h)(1)', true),
  ('civ-pro-001', 'pleading', 'medium', 'An amended complaint as of right under FRCP 15(a)(1) may be filed:',
   'At any time before trial.', 'Once as a matter of course within 21 days after serving the complaint, or within 21 days after service of a responsive pleading or 12(b) motion.', 'Once with leave of court.', 'Within 30 days after service of the answer.',
   'B', 'FRCP 15(a)(1): a party may amend its pleading once as a matter of course within 21 days after serving the complaint, or within 21 days after service of a responsive pleading or certain 12(b) motions. After that, amendment requires written consent of the adverse party or leave of court.', 'Amendment as of Right — FRCP 15(a)', 'FRCP 15(a)', true),
  ('civ-pro-001', 'discovery_civ_pro', 'easy', 'The scope of permissible discovery under FRCP 26(b)(1) is:',
   'Any information the requesting party deems relevant.', 'Nonprivileged matter relevant to any party''s claim or defense and proportional to the needs of the case.', 'Information likely to be admissible at trial.', 'Documents the responding party has in its possession only.',
   'B', 'FRCP 26(b)(1): parties may obtain discovery of any nonprivileged matter that is relevant to any party''s claim or defense and proportional to the needs of the case. Proportionality considers importance of issues, amount in controversy, parties'' resources, importance of discovery, and burden.', 'Scope of Discovery — FRCP 26(b)(1)', 'FRCP 26(b)(1)', true),
  ('civ-pro-001', 'discovery_civ_pro', 'medium', 'The work product doctrine protects from discovery:',
   'All documents a lawyer reviews.', 'Documents and tangible things prepared in anticipation of litigation or for trial by a party or its representative.', 'All attorney communications.', 'Attorney files once a suit is filed.',
   'B', 'FRCP 26(b)(3): work product doctrine protects documents and tangible things prepared in anticipation of litigation by or for a party or its representative. Mental impressions and legal theories (opinion work product) are absolutely protected; ordinary work product may be discovered upon showing substantial need and inability to obtain equivalent without undue hardship.', 'Work Product Doctrine — FRCP 26(b)(3)', 'Hickman v. Taylor (1947)', true),
  ('civ-pro-001', 'discovery_civ_pro', 'medium', 'Attorney-client privilege protects:',
   'All communications between a lawyer and anyone connected to the case.', 'Confidential communications between attorney and client made for the purpose of obtaining legal advice.', 'All documents in an attorney''s possession.', 'Communications between attorneys in the same firm.',
   'B', 'The attorney-client privilege protects confidential communications between attorney and client for the purpose of seeking or giving legal advice. The communication must be (1) between attorney and client, (2) confidential, and (3) for the purpose of legal advice. It does not protect all attorney-client contact or all documents in attorney''s files.', 'Attorney-Client Privilege', 'Restatement (Third) of the Law Governing Lawyers § 68', true),
  ('civ-pro-001', 'discovery_civ_pro', 'hard', 'Under FRCP 37, if a party fails to comply with a discovery order, the court may:',
   'Only impose monetary sanctions.', 'Strike pleadings, dismiss the action, or enter default judgment as ultimate sanctions.', 'Require the party to provide the discovery within 30 additional days.', 'Report the party to the state bar association.',
   'B', 'FRCP 37(b): if a party fails to obey a discovery order, the court may make such orders as are just, including striking pleadings, staying proceedings, dismissing the action, rendering a default judgment, or treating certain facts as established. Sanctions must be proportionate but can be severe for willful non-compliance.', 'Discovery Sanctions — FRCP 37', 'FRCP 37(b)', true),
  ('civ-pro-001', 'discovery_civ_pro', 'medium', 'Electronically stored information (ESI) discovery is governed by:',
   'FRCP 34, which allows parties to request ESI in their possession, custody, or control.', 'FRCP 45, which requires subpoenas for all ESI.', 'No specific federal rule — ESI follows common law.', 'FRCP 26 only — ESI must first be identified in mandatory initial disclosures.',
   'A', 'FRCP 34 was amended to specifically include electronically stored information. Parties may request production of ESI in their opponent''s possession, custody, or control. FRCP 26(b)(2)(B) provides a proportionality exception for ESI not reasonably accessible due to undue burden or cost.', 'Electronic Discovery (ESI) — FRCP 34', 'FRCP 34', true),
  ('civ-pro-001', 'summary_judgment', 'easy', 'Summary judgment under FRCP 56 is appropriate when:',
   'One party is likely to prevail at trial.', 'There is no genuine dispute as to any material fact and the movant is entitled to judgment as a matter of law.', 'The opposing party''s evidence is weak.', 'The court finds the factual disputes are not credible.',
   'B', 'FRCP 56(a): summary judgment shall be granted if the movant shows there is no genuine dispute as to any material fact and the movant is entitled to judgment as a matter of law. Courts view the evidence in the light most favorable to the non-moving party.', 'Summary Judgment Standard — FRCP 56', 'FRCP 56(a)', true),
  ('civ-pro-001', 'summary_judgment', 'medium', 'Under Celotex Corp. v. Catrett, the burden on the summary judgment movant who does not bear the burden of proof at trial is:',
   'To produce evidence negating the non-movant''s case.', 'To point out an absence of evidence supporting the non-movant''s case.', 'To prove there are no disputed facts.', 'To show the non-movant''s evidence is inadmissible.',
   'B', 'Celotex: a defendant who moves for summary judgment and does not bear the burden of proof at trial may satisfy its burden by showing there is an absence of evidence to support the plaintiff''s essential element. The movant need not produce its own evidence affirmatively negating the claim.', 'Summary Judgment — Celotex Moving Burden', 'Celotex Corp. v. Catrett (1986)', true),
  ('civ-pro-001', 'summary_judgment', 'medium', 'To defeat a properly supported summary judgment motion, the non-movant must:',
   'Rely on the allegations in the complaint.', 'Come forward with specific facts creating a genuine dispute for trial.', 'Show a mere scintilla of evidence.', 'Submit an expert declaration.',
   'B', 'Anderson v. Liberty Lobby: to survive summary judgment, the non-movant must present evidence from which a reasonable jury could find in its favor. A mere scintilla of evidence is insufficient; the non-movant must show a genuine issue of material fact — facts that could make a difference at trial.', 'Summary Judgment — Non-Movant Burden', 'Anderson v. Liberty Lobby, Inc. (1986)', true),
  ('civ-pro-001', 'summary_judgment', 'hard', 'A genuine issue of material fact exists when:',
   'Any factual dispute exists in the record.', 'The fact is disputed and the dispute could affect the outcome of the case under applicable law.', 'The parties disagree about the meaning of a contract term.', 'The evidence on both sides is conflicting.',
   'B', 'A ''material'' fact is one that might affect the outcome under substantive law. A ''genuine'' dispute exists if a reasonable jury could find for either side based on the evidence. Not every factual dispute is material — only those that are outcome-determinative under the applicable legal standard.', 'Summary Judgment — Genuine Issue of Material Fact', 'Anderson v. Liberty Lobby, Inc. (1986)', true),
  ('civ-pro-001', 'trial', 'easy', 'Under FRCP 50(a), a motion for judgment as a matter of law (JMOL) may be made:',
   'Only after the jury returns its verdict.', 'At the close of any party''s evidence, before the case goes to the jury.', 'Only by the defendant.', 'After the judge has given jury instructions.',
   'B', 'FRCP 50(a): a party may move for JMOL (formerly ''directed verdict'') at any time before the case is submitted to the jury, but typically after the opposing party has been fully heard on an issue. The standard is whether a reasonable jury would have a legally sufficient basis to find for the non-movant.', 'Judgment as a Matter of Law — FRCP 50(a)', 'FRCP 50(a)', true),
  ('civ-pro-001', 'trial', 'medium', 'The Seventh Amendment right to jury trial in federal courts applies to:',
   'All cases filed in federal court.', 'Suits at common law where the value in controversy exceeds $20.', 'Cases in admiralty and equity.', 'Any case where the plaintiff demands a jury.',
   'B', 'The Seventh Amendment preserves the right to jury trial ''in Suits at common law, where the value in controversy shall exceed twenty dollars.'' The right attaches to legal claims (damages), not equitable claims (injunctions, specific performance, accounting). Courts apply the historical test to determine jury trial rights.', 'Seventh Amendment — Jury Trial Right', 'U.S. Constitution Amend. VII', true),
  ('civ-pro-001', 'trial', 'hard', 'Under Erie Railroad v. Tompkins, a federal court sitting in diversity must apply:',
   'Federal procedural rules and state substantive law.', 'Federal law on all issues.', 'State law on all issues.', 'Federal common law, not state law.',
   'A', 'Erie held that there is no federal general common law; in diversity cases, federal courts must apply the substantive law (including judge-made law) of the state where they sit. Federal courts apply their own procedural rules (FRCP) but state substantive law, including statutes of limitations and choice of law rules.', 'Erie Doctrine — Substance vs. Procedure', 'Erie Railroad Co. v. Tompkins (1938)', true),
  ('civ-pro-001', 'trial', 'medium', 'Under Hanna v. Plumer, when there is a direct conflict between a Federal Rule of Civil Procedure and state law in a diversity case:',
   'State law applies because substantive matters are governed by state law.', 'The FRCP applies if it is a valid exercise of Congress''s rulemaking authority under the Rules Enabling Act.', 'Courts must balance state interest against federal interest.', 'The FRCP applies only to procedural matters with no substantive effect.',
   'B', 'Hanna v. Plumer: when a Federal Rule directly collides with state law, the FRCP controls if (1) it is within the scope of the Rules Enabling Act, and (2) it does not abridge, enlarge, or modify substantive rights. The validity of FRCP rules is presumed; courts defer to the Federal Rules in direct conflicts.', 'Erie — Hanna Doctrine (Direct Conflict with FRCP)', 'Hanna v. Plumer (1965)', true),
  ('civ-pro-001', 'trial', 'hard', 'Under FRCP 51, a party seeking to preserve objections to jury instructions for appeal must:',
   'Object before the charge conference.', 'Object on the record, clearly stating the grounds for the objection, after the instructions are given but before the jury retires.', 'Object within 10 days after trial.', 'File a motion for new trial based on the instruction error.',
   'B', 'FRCP 51: to preserve an objection to a jury instruction for appeal, a party must (1) object on the record, (2) state the grounds with specificity, and (3) do so before the jury retires to deliberate. Failure to timely object waives the issue on appeal, leaving only plain error review.', 'Jury Instructions — Preserving Objections (FRCP 51)', 'FRCP 51', true),
  ('civ-pro-001', 'preclusion', 'easy', 'Claim preclusion (res judicata) bars re-litigation when:',
   'The same parties litigate the same legal theory.', 'There is a final judgment on the merits, between the same parties, on the same claim or cause of action.', 'The same facts were at issue in a prior case.', 'A party is estopped from changing its legal theory.',
   'B', 'Claim preclusion bars re-litigation of the same claim that was or could have been litigated in a prior action that resulted in a final judgment on the merits between the same parties (or their privies). All claims arising from the same transaction must be brought in one action.', 'Claim Preclusion (Res Judicata) — Elements', 'Restatement (Second) of Judgments § 24', true),
  ('civ-pro-001', 'preclusion', 'medium', 'Issue preclusion (collateral estoppel) bars re-litigation of an issue when:',
   'The same claim was litigated in a prior case.', 'The issue was actually litigated and necessarily decided in a prior case in which the same party had a full and fair opportunity to litigate it.', 'The prior judgment was in favor of the plaintiff.', 'The party seeking preclusion was a party in the prior case.',
   'B', 'Issue preclusion requires: (1) the issue was actually litigated (contested and decided), (2) the issue was necessarily decided (essential to the judgment), (3) the judgment is final, and (4) the party against whom preclusion is sought had a full and fair opportunity to litigate the issue.', 'Issue Preclusion (Collateral Estoppel) — Elements', 'Restatement (Second) of Judgments § 27', true),
  ('civ-pro-001', 'preclusion', 'hard', 'Non-mutual offensive collateral estoppel means:',
   'A non-party to a prior suit can use issue preclusion against a party who was in the prior suit.', 'A party may assert issue preclusion on different issues from those decided.', 'Issue preclusion can be asserted by parties on both sides of the dispute.', 'Only defendants may assert issue preclusion.',
   'A', 'Parklane Hosiery Co. v. Shore: the Supreme Court upheld non-mutual offensive collateral estoppel — allowing a plaintiff who was not in a prior suit to use an issue decided against the defendant in the prior suit. Courts retain discretion to deny it when it would be unfair to the defendant.', 'Non-Mutual Offensive Collateral Estoppel', 'Parklane Hosiery Co. v. Shore (1979)', true),
  ('civ-pro-001', 'preclusion', 'medium', 'For claim preclusion, the ''same claim'' is generally defined under the transactional approach as:',
   'Any claim that shares a legal theory with the prior claim.', 'All rights to remedies arising from the same transaction or occurrence.', 'Claims arising from the same legal relationship.', 'Any claim that could have been litigated by a different plaintiff.',
   'B', 'Restatement (Second) of Judgments § 24 adopts the transactional approach: all claims arising from the same transaction or series of connected transactions must be brought in one action. ''Claim'' is defined broadly by facts, not by the legal theory asserted.', 'Claim Preclusion — Transactional Approach', 'Restatement (Second) of Judgments § 24', true),
  ('civ-pro-001', 'preclusion', 'hard', 'Sarah wins a negligence lawsuit against Tom. Tom later sues Sarah for battery arising from the same event. Is Tom''s battery claim barred by claim preclusion?',
   'Yes — both claims arise from the same event.', 'No — Tom is asserting a different legal theory (battery, not negligence).', 'Yes — Tom should have brought the battery claim as a counterclaim.', 'No — claim preclusion only bars re-litigation by the same plaintiff.',
   'C', 'Under FRCP 13(a), a compulsory counterclaim must be asserted in the original action if it arises from the same transaction. Tom''s battery claim arises from the same event as Sarah''s negligence claim — it was a compulsory counterclaim. Failure to raise it in the original action bars it by compulsory counterclaim rules, and claim preclusion would also apply.', 'Claim Preclusion — Compulsory Counterclaims (FRCP 13)', 'FRCP 13(a)', true),
  ('civ-pro-001', 'venue', 'easy', 'Under 28 U.S.C. § 1391, venue in a civil case is proper in:',
   'Any district where any defendant resides.', 'A judicial district where any defendant resides (if all defendants reside in the same state), where a substantial part of the events occurred, or where any defendant is subject to personal jurisdiction if no other district is proper.', 'The district where the plaintiff resides.', 'The district where the contract was signed.',
   'B', '28 U.S.C. § 1391: venue is proper in (1) a district where any defendant resides, if all defendants reside in the same state, (2) a district where a substantial part of the events or omissions giving rise to the claim occurred, or (3) if neither applies, any district where any defendant is subject to personal jurisdiction.', 'Venue — 28 U.S.C. § 1391', '28 U.S.C. § 1391', true),
  ('civ-pro-001', 'venue', 'medium', 'A federal court may transfer a civil case to another district under 28 U.S.C. § 1404(a) when:',
   'Venue in the original court is improper.', 'The transfer serves the convenience of parties and witnesses and is in the interest of justice, and the transferee court is one where the case could have been brought.', 'The plaintiff requests a transfer.', 'The case has been pending for more than one year.',
   'B', '28 U.S.C. § 1404(a): for convenience of parties and witnesses and in the interest of justice, a district court may transfer a civil action to any other district where it might have been brought. Transfer requires that venue would be proper in the transferee court.', 'Venue Transfer — § 1404(a)', '28 U.S.C. § 1404(a)', true),
  ('civ-pro-001', 'venue', 'hard', 'Under 28 U.S.C. § 1406(a), when venue is improper, the court shall:',
   'Dismiss the case.', 'Dismiss or, if it is in the interest of justice, transfer the case to a district where it could have been brought.', 'Transfer the case to the plaintiff''s preferred venue.', 'Order the defendant to waive venue objections.',
   'B', '28 U.S.C. § 1406(a): when venue is improper, the district court shall dismiss or, if in the interest of justice, transfer the case to a district where it could have been brought. Transfer is preferred over dismissal when the statute of limitations has run in the transferee district.', 'Transfer for Improper Venue — § 1406(a)', '28 U.S.C. § 1406(a)', true),
  ('civ-pro-001', 'class_actions', 'medium', 'Under FRCP 23(a), certification of a class action requires:',
   'Only that there are multiple potential plaintiffs.', 'Numerosity, commonality, typicality, and adequacy of representation.', 'A minimum of 100 class members.', 'Only that common questions of law exist.',
   'B', 'FRCP 23(a): to be certified, a class action must satisfy all four prerequisites: (1) numerosity (so many members that joinder is impracticable), (2) commonality (questions of law or fact common to the class), (3) typicality (the representative''s claims are typical of the class), and (4) adequacy (representative and counsel will adequately protect class interests).', 'Class Action — Rule 23(a) Prerequisites', 'FRCP 23(a)', true),
  ('civ-pro-001', 'class_actions', 'hard', 'Under Wal-Mart Stores v. Dukes, the Supreme Court held that commonality under FRCP 23(a)(2) requires:',
   'Any common question of law or fact across class members.', 'Questions of law or fact common to the class that generate common answers apt to drive resolution of the litigation — not just any question uniformly posed to all class members.', 'Only one common question across the class.', 'Common damages suffered by all class members.',
   'B', 'Wal-Mart v. Dukes: commonality requires that the class members'' claims depend on a common contention whose truth or falsity will resolve an issue central to the validity of each claim in one stroke. Asking the same question across all class members (e.g., ''was there discrimination?'') is insufficient without a common answer.', 'Class Action — Commonality Under Wal-Mart v. Dukes', 'Wal-Mart Stores, Inc. v. Dukes (2011)', true),
  ('civ-pro-001', 'class_actions', 'medium', 'Under FRCP 23(b)(3), a class action may be maintained when:',
   'Injunctive relief is sought for the class.', 'Common questions predominate over individual questions, and a class action is superior to other available methods of adjudication.', 'Separate actions would create incompatible standards of conduct.', 'The class has a right to mandatory joinder under FRCP 19.',
   'B', 'FRCP 23(b)(3): the most common damages class action requires (1) predominance — common questions predominate over individual ones, and (2) superiority — class adjudication is superior to alternatives. This is the main vehicle for mass damages cases (consumer fraud, securities).', 'Class Action — Rule 23(b)(3) Predominance and Superiority', 'FRCP 23(b)(3)', true),
  ('civ-pro-001', 'appeals', 'easy', 'Under 28 U.S.C. § 1291, courts of appeals have jurisdiction over:',
   'Interlocutory orders granting or denying injunctions.', 'Final decisions of the district courts.', 'Orders granting summary judgment.', 'All orders entered before trial.',
   'B', '28 U.S.C. § 1291: the courts of appeals have jurisdiction from all final decisions of the district courts. The final judgment rule requires that a case be fully resolved below before appeal as of right. Exceptions include interlocutory appeals under § 1292 and Rule 54(b).', 'Final Judgment Rule — § 1291', '28 U.S.C. § 1291', true),
  ('civ-pro-001', 'appeals', 'medium', 'The collateral order doctrine allows appeal of non-final orders that:',
   'Involve important constitutional questions.', 'Conclusively determine a disputed question, resolve an issue completely separate from the merits, and are effectively unreviewable after final judgment.', 'Are certified by the district court for interlocutory appeal.', 'The defendant designates as immediately appealable.',
   'B', 'Cohen v. Beneficial Industrial Loan Corp.: a non-final order may be immediately appealable if it (1) conclusively determines the disputed question, (2) resolves an important issue completely separate from the merits, and (3) is effectively unreviewable on appeal from a final judgment. The right to be free from standing trial is a classic example.', 'Collateral Order Doctrine', 'Cohen v. Beneficial Industrial Loan Corp. (1949)', true)
) AS v(subject_id, category, difficulty, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, rule_tested, case_citation, is_active)
WHERE NOT EXISTS (SELECT 1 FROM quiz_questions q
                  WHERE q.subject_id = v.subject_id AND q.stem = v.stem);

COMMIT;

-- ══ from 20260720000004_seed_evidence.sql  (25 quoting repairs) ══
-- Evidence: Relevance, Character, Hearsay, Exceptions, Privileges, Experts, Authentication
-- 25 MBE questions

BEGIN;

INSERT INTO quiz_questions
  (subject_id, category, difficulty, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, rule_tested, case_citation, is_active)
SELECT v.* FROM (VALUES
('evidence-001','relevance','easy','Under FRE 401, evidence is relevant if:',
   'It makes a fact more or less probable than it would be without the evidence, and the fact is of consequence to the action.','It directly proves an element of a claim or defense.','Any judge would find it probative.','It is authenticated and not hearsay.',
   'A','FRE 401: evidence is relevant if (a) it has any tendency to make a fact of consequence more or less probable than it would be without the evidence. The threshold is very low — any tendency suffices. Relevance is a necessary but not sufficient condition for admissibility.','Relevance — FRE 401','FRE 401', true),
  ('evidence-001','relevance','medium','Under FRE 403, relevant evidence may be excluded when:',
   'The opposing party objects.','Its probative value is substantially outweighed by the danger of unfair prejudice, confusion of issues, or misleading the jury.','It is cumulative.','The judge believes it is unreliable.',
   'B','FRE 403 gives courts discretion to exclude relevant evidence if the danger of unfair prejudice, confusion of the issues, misleading the jury, undue delay, waste of time, or needless presenting of cumulative evidence substantially outweighs its probative value. Exclusion under 403 requires substantial outweighing — the rule favors admission.','FRE 403 — Balancing Test','FRE 403', true),
  ('evidence-001','relevance','hard','Evidence of a defendant''s prior sexual assault conviction is offered against the defendant in a current sexual assault prosecution. Under FRE 413:',
   'It is inadmissible — character evidence of prior acts is barred.','It is admissible for any relevant purpose, including propensity.','It is admissible only to show modus operandi.','It is admissible if the prior act was similar to the charged offense.',
   'B','FRE 413: in criminal cases involving sexual assault, evidence of the defendant''s commission of another sexual assault is admissible on any matter to which it is relevant, including propensity. This is a specific exception to FRE 404(b)''s general prohibition on character evidence for propensity.','FRE 413 — Prior Acts in Sexual Assault Cases','FRE 413', true),
  ('evidence-001','character_evidence','medium','Under FRE 404(b), evidence of a prior bad act is admissible for:',
   'Proving the defendant''s character for propensity to commit the crime.','Proving motive, opportunity, intent, preparation, plan, knowledge, identity, absence of mistake, or lack of accident.','Impeachment of the defendant''s character witnesses.','Proving that the defendant acted in conformity with the prior bad act.',
   'B','FRE 404(b): character evidence offered to prove propensity is inadmissible. However, evidence of prior acts may be admitted for other purposes — MIMIC+: motive, intent, mistake (absence of), identity, common plan/scheme, knowledge, opportunity, preparation. The judge must also conduct a 403 balancing test.','FRE 404(b) — Prior Acts (MIMIC+)','FRE 404(b)', true),
  ('evidence-001','character_evidence','easy','In a criminal case, a defendant may offer evidence of a pertinent character trait to prove he acted consistently with that trait. The prosecution may rebut by:',
   'Cross-examining the character witness about relevant specific instances.','Calling witnesses to testify about specific instances of bad behavior.','Both A and B.','Offering prior conviction evidence only.',
   'C','FRE 404(a)(2): a defendant may offer character evidence through reputation or opinion witnesses. On cross-examination of those witnesses, the prosecution may ask about specific instances (FRE 405(a)). The prosecution may also call its own character witnesses in rebuttal (FRE 404(a)(2)(A)).','Character Evidence — Defendant''s Trait + Prosecution''s Rebuttal','FRE 404(a)(2)', true),
  ('evidence-001','hearsay','easy','Hearsay under FRE 801 is defined as:',
   'Any out-of-court statement offered to impeach the declarant.','A statement made out of court by a declarant, offered to prove the truth of the matter asserted.','Any prior statement made by a witness.','Any statement by a non-party to the action.',
   'B','FRE 801(c): hearsay is an out-of-court statement (1) made by a declarant, (2) offered to prove the truth of the matter asserted. If offered for another purpose (e.g., to show the listener''s state of mind, to show verbal acts, or to show the effect on the listener), it is not hearsay.','Hearsay — Definition (FRE 801)','FRE 801', true),
  ('evidence-001','hearsay','medium','Dan tells the police: ''Ed shot the victim.'' At trial, Dan refuses to testify. Under FRE 801(d)(1)(A), the police officer may testify to Dan''s statement if:',
   'Dan is unavailable.','Dan is subject to cross-examination and the prior statement was made under oath at a prior proceeding.','Dan''s statement was recorded.','Dan was a witness to the shooting.',
   'B','FRE 801(d)(1)(A): a prior statement of a witness is not hearsay if the declarant testifies at the trial and is subject to cross-examination, and the statement is inconsistent with current testimony and was given under penalty of perjury at a trial, hearing, or other proceeding, or deposition.','Prior Inconsistent Statement — FRE 801(d)(1)(A)','FRE 801(d)(1)(A)', true),
  ('evidence-001','hearsay','medium','An admission by a party-opponent under FRE 801(d)(2) is not hearsay when:',
   'The statement was made under oath.','The statement is offered against the party who made it, and was made in an individual or representative capacity.','The statement is adverse to the party.','The statement was made in a legal proceeding.',
   'B','FRE 801(d)(2): a statement is not hearsay if it is offered against an opposing party and was made by that party in an individual or representative capacity, or by an agent, co-conspirator, or authorized spokesperson. There is no requirement that the statement be against interest when made.','Party Admission — FRE 801(d)(2)','FRE 801(d)(2)', true),
  ('evidence-001','hearsay','hard','A co-conspirator''s statement made during and in furtherance of a conspiracy is:',
   'Hearsay admissible as an exception to the hearsay rule.','Not hearsay under FRE 801(d)(2)(E) — it is a party admission.','Hearsay admissible only if the co-conspirator is unavailable.','Admissible only against the co-conspirator who made it.',
   'B','FRE 801(d)(2)(E): a statement by a co-conspirator made during the course of and in furtherance of the conspiracy is not hearsay — it is a party-opponent admission. The prosecution must establish by a preponderance of the evidence that (1) a conspiracy existed, (2) both the declarant and defendant were members, and (3) the statement was made during and in furtherance of the conspiracy.','Co-Conspirator Statements — FRE 801(d)(2)(E)','FRE 801(d)(2)(E)', true),
  ('evidence-001','hearsay_exceptions','easy','Under FRE 803(1), a present sense impression is admissible if:',
   'Made immediately after the declarant perceives an exciting event.','Made while the declarant is perceiving an event or immediately thereafter.','Made under oath.','Corroborated by independent evidence.',
   'B','FRE 803(1): a present sense impression is a statement describing or explaining an event or condition while the declarant is perceiving it or immediately thereafter. Unlike an excited utterance, it need not arise from a startling event — it requires only contemporaneity.','Hearsay Exception — Present Sense Impression (FRE 803(1))','FRE 803(1)', true),
  ('evidence-001','hearsay_exceptions','medium','An excited utterance under FRE 803(2) requires:',
   'The declarant to be physically excited.','A startling event, the statement to be made while under the stress of excitement, and the statement to relate to the event.','The statement to be made within one hour of the event.','The declarant to be unavailable at trial.',
   'B','FRE 803(2): an excited utterance is a statement relating to a startling event or condition, made while the declarant was under the stress of excitement that it caused. No fixed time limit applies — the key is whether the declarant was still under the stress of the startling event.','Hearsay Exception — Excited Utterance (FRE 803(2))','FRE 803(2)', true),
  ('evidence-001','hearsay_exceptions','hard','Under FRE 803(6), a business record is admissible if:',
   'It was made in the regular course of business.','It was made at or near the time of the recorded act by or from information transmitted by someone with knowledge, in the regular course of a regularly conducted activity, and the opponent does not show lack of trustworthiness.','It was prepared by a business for internal use only.','It was the original record, not a copy.',
   'B','FRE 803(6): business records (records of regularly conducted activity) are admissible if (1) made at or near the time of the event, (2) by someone with knowledge or from information transmitted by someone with knowledge, (3) kept in the regular course of business, (4) it was the regular practice of the business to make such records, and (5) the opponent does not show lack of trustworthiness.','Business Records Exception — FRE 803(6)','FRE 803(6)', true),
  ('evidence-001','hearsay_exceptions','medium','Under FRE 804(b)(1), former testimony of an unavailable witness is admissible if:',
   'The witness is deceased.','The witness is unavailable and the party against whom the testimony is offered had an opportunity and similar motive to cross-examine the witness at the former proceeding.','The parties stipulate to its admission.','The former testimony was given under oath in any legal proceeding.',
   'B','FRE 804(b)(1): former testimony is admissible if the declarant is unavailable and the party against whom it is offered (or a predecessor in interest) had an opportunity and similar motive to develop the testimony by direct, cross, or redirect examination at the prior proceeding.','Former Testimony Exception — FRE 804(b)(1)','FRE 804(b)(1)', true),
  ('evidence-001','hearsay_exceptions','medium','A dying declaration under FRE 804(b)(2) requires:',
   'The declarant to have died by the time of trial.','The declarant to have believed death was imminent, the statement to concern the cause or circumstances of the believed impending death.','The declarant to make the statement in a hospital.','The statement to be made before law enforcement.',
   'B','FRE 804(b)(2): a dying declaration requires (1) unavailability of the declarant, (2) the statement was made while the declarant believed death was imminent, and (3) the statement relates to the cause or circumstances of the believed impending death. In federal court, dying declarations are admissible in homicide cases and civil cases.','Dying Declaration — FRE 804(b)(2)','FRE 804(b)(2)', true),
  ('evidence-001','hearsay_exceptions','hard','A statement against interest under FRE 804(b)(3) differs from a party admission because:',
   'It requires the declarant to be a party.','It requires the declarant to be unavailable and the statement to be against the declarant''s pecuniary, proprietary, or penal interest at the time it was made.','It requires corroborating circumstances.','It is limited to civil cases.',
   'B','FRE 804(b)(3): a statement against interest requires (1) an unavailable declarant, (2) a statement that was against the declarant''s financial, ownership, or criminal (penal) interest at the time made, and (3) for statements exposing the declarant to criminal liability and offered to exculpate the accused, corroborating circumstances indicating trustworthiness. Unlike party admissions, the declarant need not be a party.','Statement Against Interest — FRE 804(b)(3)','FRE 804(b)(3)', true),
  ('evidence-001','impeachment','easy','Under FRE 609(a), a prior felony conviction is admissible to impeach a witness if:',
   'The crime involved dishonesty or false statement, or (for non-defendant witnesses) the crime was punishable by imprisonment for more than one year and the court finds admission would not be substantially outweighed by prejudice.','The crime occurred within 10 years of trial.','The witness has been convicted of a felony in the same jurisdiction.','The conviction was not appealed.',
   'A','FRE 609: prior convictions are admissible to impeach if (1) the crime involved dishonesty/false statement (crimen falsi) — automatically admitted, or (2) for non-defendant witnesses, any crime punishable by more than 1 year imprisonment, subject to 403 balancing. For defendant witnesses, the 403 standard is heightened — excluded unless probative value outweighs prejudice.','Prior Conviction for Impeachment — FRE 609','FRE 609', true),
  ('evidence-001','impeachment','medium','Under FRE 608(b), specific instances of a witness''s prior conduct offered to attack credibility may be:',
   'Proved by extrinsic evidence.','Inquired into on cross-examination at the court''s discretion if probative of the witness''s character for truthfulness or untruthfulness.','Offered only if the conduct resulted in a criminal conviction.','Offered through reputation testimony only.',
   'B','FRE 608(b): specific instances of conduct that are probative of truthfulness (or untruthfulness) may be inquired into on cross-examination, but may not be proved by extrinsic evidence. The questioner is bound by the witness''s answer — no contradicting extrinsic evidence is allowed to prove the specific prior act.','Impeachment — Prior Specific Conduct (FRE 608(b))','FRE 608(b)', true),
  ('evidence-001','impeachment','hard','The collateral matters rule bars extrinsic evidence to contradict a witness on:',
   'Any matter not specifically relevant to the case.','A matter that is collateral — not independently provable to show a fact of consequence, but offered only to impeach the witness''s credibility.','Character evidence offered to impeach.','Matters addressed in the witness''s direct examination.',
   'B','The collateral matters rule: a party may not introduce extrinsic evidence to contradict a witness''s testimony on a collateral matter — one that is relevant only to credibility and not independently relevant to the case. If the answer is not independently provable (i.e., the only purpose is impeachment), the questioner is stuck with the witness''s answer.','Collateral Matters Rule — Extrinsic Impeachment','FRE 608(b)', true),
  ('evidence-001','privileges','easy','The attorney-client privilege is held by:',
   'The attorney.','The client.','Both the attorney and the client jointly.','The court.',
   'B','The attorney-client privilege belongs to the client, not the attorney. Only the client may waive the privilege (intentionally or inadvertently). The attorney has an ethical obligation to assert the privilege on behalf of the client but cannot independently waive it.','Attorney-Client Privilege — Holder','FRE 501', true),
  ('evidence-001','privileges','medium','The privilege against adverse spousal testimony in federal criminal cases (Trammel rule) may be asserted by:',
   'The defendant spouse only.','The witness spouse — who may choose to testify or not.','Either spouse.','The state on behalf of the marriage.',
   'B','Trammel v. United States: the witness-spouse privilege (adverse spousal testimony) belongs to the witness spouse. The witness spouse may choose to testify against the defendant spouse but cannot be compelled to do so. The defendant spouse can no longer prevent the witness spouse from testifying voluntarily.','Spousal Testimonial Privilege — Trammel','Trammel v. United States (1980)', true),
  ('evidence-001','expert_witnesses','easy','Under FRE 702 (Daubert standard), expert testimony is admissible if:',
   'The expert has relevant credentials.','The expert''s testimony is based on sufficient facts, the product of reliable principles and methods reliably applied to the facts of the case.','The expert''s opinion is generally accepted in the relevant scientific community.','The expert''s opinion is not the ultimate issue in the case.',
   'B','FRE 702 (post-Daubert): courts act as gatekeepers for expert testimony. The expert must have knowledge, skill, experience, training, or education; the testimony must be based on sufficient facts or data; the testimony must be the product of reliable principles and methods; and the expert must have reliably applied the principles to the facts.','Expert Testimony — FRE 702 / Daubert Standard','Daubert v. Merrell Dow Pharmaceuticals (1993)', true),
  ('evidence-001','expert_witnesses','medium','Under FRE 703, an expert may base an opinion on:',
   'Only facts in evidence at trial.','Facts or data that experts in the particular field would reasonably rely on, even if not admissible.','The expert''s personal experience only.','Documents authenticated at trial.',
   'B','FRE 703: an expert may base an opinion on facts or data perceived by or made known to the expert, if experts in the field would reasonably rely on such data in forming opinions. The underlying data need not be admissible in evidence — e.g., hearsay that medical professionals regularly rely upon.','Expert Opinion Basis — FRE 703','FRE 703', true),
  ('evidence-001','authentication','easy','Under FRE 901, authentication requires:',
   'A notary''s seal on documents.','Evidence sufficient to support a finding that the item is what the proponent claims it to be.','The original document only.','Two witnesses to identify the document.',
   'B','FRE 901: authentication is satisfied by evidence sufficient to support a finding that the item is what the proponent claims. This is a low threshold — the court determines only whether there is enough evidence for a reasonable jury to conclude the item is authentic. FRE 902 lists self-authenticating documents that need no extrinsic evidence.','Authentication — FRE 901','FRE 901', true),
  ('evidence-001','authentication','medium','Under FRE 1002 (Best Evidence Rule), the original document must be produced:',
   'In all cases involving documents.','When a party seeks to prove the content of a writing, recording, or photograph.','Only when the document is more than 50 years old.','Only in criminal trials.',
   'B','FRE 1002 (Original Writing Rule): to prove the content of a writing, recording, or photograph, the original must be produced. The rule applies only when the content of the document itself is at issue, not when a witness is testifying from personal knowledge about facts that happen to be in a document.','Best Evidence Rule — FRE 1002','FRE 1002', true),
  ('evidence-001','authentication','hard','Under FRE 1003, a duplicate is admissible to the same extent as the original:',
   'Never — only originals are admissible.','Unless there is a genuine question about the authenticity of the original or it would be unfair to admit the duplicate.','Only if the original is unavailable.','Only with the opposing party''s consent.',
   'B','FRE 1003: duplicates are generally as admissible as originals. A duplicate may be excluded if there is a genuine question raised as to the authenticity of the original, or if it would be unfair to admit the duplicate in lieu of the original. Modern copying technology makes duplicates generally as reliable as originals.','Duplicate Documents — FRE 1003','FRE 1003', true)
) AS v(subject_id, category, difficulty, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, rule_tested, case_citation, is_active)
WHERE NOT EXISTS (SELECT 1 FROM quiz_questions q
                  WHERE q.subject_id = v.subject_id AND q.stem = v.stem);

COMMIT;

-- ══ from 20260720000005_seed_real_property.sql  (2 quoting repairs) ══
-- Real Property: Ownership, Concurrent Ownership, Landlord-Tenant, Recording Acts, Adverse Possession, Easements, Covenants, Mortgages
-- 25 MBE questions

BEGIN;

INSERT INTO quiz_questions
  (subject_id, category, difficulty, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, rule_tested, case_citation, is_active)
SELECT v.* FROM (VALUES
('real-prop-001','ownership','easy','Fee simple absolute is:',
   'A freehold estate that is limited in duration.','The largest possible ownership interest in real property — infinite in duration and freely alienable.','Ownership subject to a condition subsequent.','A life estate measured by the owner''s life.',
   'B','Fee simple absolute (FSA) is the most complete form of property ownership. It is of potentially infinite duration, freely transferable inter vivos and by will or intestacy, and carries no conditions on ownership. Created by ''to A'' or ''to A and his heirs'' at common law.','Fee Simple Absolute — Characteristics',null, true),
  ('real-prop-001','ownership','medium','A conveyance ''to A, but if A ever uses the land for commercial purposes, then to B'' creates:',
   'A fee simple subject to a condition subsequent with a right of entry in B.','A fee simple determinable with an automatic reversion to B.','A fee simple subject to executory limitation, with an executory interest in B.','A life estate in A with remainder in B.',
   'C','''But if'' language followed by a future interest in a third party creates a fee simple subject to executory limitation (FSSEL) in A and an executory interest (shifting) in B. The estate does not automatically revert to the grantor — it shifts to B upon the condition''s occurrence. If the future interest were in the grantor, it would be a fee simple determinable or fee simple subject to condition subsequent.','Fee Simple Subject to Executory Limitation',null, true),
  ('real-prop-001','ownership','hard','The rule against perpetuities (RAP) invalidates a future interest unless:',
   'It is held by an ascertainable person.','It must vest, if at all, within 21 years after a life in being at the time of the conveyance.','It is created by deed rather than will.','The condition is certain to occur.',
   'B','The common law RAP: no interest is valid unless it must vest, if at all, within the period of some life in being at the creation of the interest plus 21 years. If there is any possibility — however remote — that the interest will vest too remotely, it is void from the outset.','Rule Against Perpetuities — Common Law',null, true),
  ('real-prop-001','ownership','medium','A life estate gives the holder (life tenant):',
   'Ownership of the property for the duration of a measuring life.','The right to sell or devise the property.','The right to use the property and take the profits, but not to commit waste.','All the rights of a fee simple owner while alive.',
   'C','A life tenant has the right to possess and use the property and take income during the measuring life. However, the life tenant must not commit waste (actions that permanently damage the property to the detriment of the remainder or reversion holders). Life estates cannot be devised by will (they terminate at death of measuring life) and cannot be sold free of the future interest.','Life Estate — Rights and Duties',null, true),
  ('real-prop-001','ownership','hard','Oscar holds a life estate in Blackacre. He installs solar panels that increase the property''s value. Remainder holder Rena sues claiming this constitutes affirmative waste. The court should:',
   'Require removal — any alteration is waste.','Dismiss — improvements that increase value are ameliorative, not waste.','Require Oscar to compensate Rena for changing the property.','Require Oscar to post a bond before making improvements.',
   'B','Ameliorative waste (improvements) traditionally constituted waste at common law, but modern courts generally do not hold life tenants liable for improvements that increase property value. Waste doctrine focuses on harmful changes — permissive (neglect), voluntary (affirmative destruction) — not beneficial improvements.','Life Estate — Ameliorative Waste',null, true),
  ('real-prop-001','concurrent_ownership','easy','A joint tenancy requires four unities: time, title, interest, and possession. Which best describes the right of survivorship?',
   'Upon the death of one joint tenant, the surviving joint tenant(s) inherit the deceased''s share through the deceased''s estate.','Upon the death of one joint tenant, the surviving joint tenant(s) automatically take the entire property by operation of law.','Upon the death of one joint tenant, the property reverts to the grantor.','Upon the death of one joint tenant, the deceased''s share passes by will or intestacy.',
   'B','In a joint tenancy with right of survivorship (JTWROS), the deceased joint tenant''s interest passes automatically and immediately to the surviving joint tenant(s) by operation of law — outside of probate. This is the defining feature of joint tenancy, distinct from tenancy in common.','Joint Tenancy — Right of Survivorship',null, true),
  ('real-prop-001','concurrent_ownership','medium','Ann and Bob are joint tenants. Ann conveys her interest to Carol during Ann''s lifetime. This:',
   'Is void — joint tenants cannot convey without the other''s consent.','Severs the joint tenancy as to Ann''s share, creating a tenancy in common between Carol and Bob.','Has no effect — Carol steps into Ann''s shoes as a joint tenant.','Creates a tenancy by the entirety between Carol and Bob.',
   'B','A unilateral conveyance by one joint tenant severs the joint tenancy as to that tenant''s share. The four unities (time, title) are destroyed between the grantor and grantee. The result: Carol and Bob hold as tenants in common (no right of survivorship between them), though if there were three original joint tenants, the other two might remain joint tenants between themselves.','Joint Tenancy — Severance by Conveyance',null, true),
  ('real-prop-001','concurrent_ownership','easy','Tenancy by the entirety is available only to:',
   'Co-owners who are unmarried partners.','Legally married spouses — neither can alienate or encumber the property without the other''s consent.','Joint tenants who are related by blood.','Any co-owners who choose it at the time of conveyance.',
   'B','Tenancy by the entirety is a special form of joint tenancy available only to legally married spouses. It includes the right of survivorship and neither spouse can unilaterally convey or encumber the property — protecting the marital home from one spouse''s creditors (in most states).','Tenancy by the Entirety',null, true),
  ('real-prop-001','landlord_tenant','easy','A landlord is required to provide a habitable premises under the implied warranty of habitability. A breach occurs when:',
   'The tenant fails to pay rent on time.','The premises are uninhabitable in ways that substantially affect the tenant''s health or safety.','The landlord fails to make cosmetic repairs.','The tenant complains about any condition.',
   'B','The implied warranty of habitability (Javins v. First National Realty) requires landlords to maintain residential premises in a condition fit for human habitation — addressing essential services (heat, water, structural safety). Minor or cosmetic defects do not breach the warranty.','Implied Warranty of Habitability','Javins v. First National Realty Corp. (1970)', true),
  ('real-prop-001','landlord_tenant','medium','A tenant abandons the lease. In a majority of states, the landlord''s duty is to:',
   'Sue immediately for the full remaining rent.','Accept the surrender and terminate the lease.','Make reasonable efforts to re-let (mitigate damages).','Evict the tenant and re-let at whatever rent is available.',
   'C','The majority of states require landlords to mitigate damages by making reasonable efforts to re-let after a tenant abandons. The landlord may sue for the difference between the lease rent and the re-let rent, plus costs. A minority of states allow the landlord to hold the abandoning tenant responsible for the full rent.','Landlord''s Duty to Mitigate',null, true),
  ('real-prop-001','landlord_tenant','hard','A periodic tenancy automatically renews unless properly terminated. For a month-to-month tenancy, proper notice to terminate at common law requires:',
   '30 days'' notice.','One full period''s notice (one month) given at the start of a period to expire at the end of that period.','14 days'' notice.','Written notice delivered by certified mail.',
   'B','At common law, a periodic tenancy requires notice equal to the length of the period (e.g., month-to-month = one month''s notice). The notice must be given at the beginning of a period to expire at the end of a period — not mid-period. Statutes may vary these requirements.','Periodic Tenancy — Termination Notice',null, true),
  ('real-prop-001','recording_acts','medium','Under a race-notice recording act, a subsequent purchaser prevails over a prior unrecorded deed only if the subsequent purchaser:',
   'Records first, regardless of notice.','Records first AND took without notice of the prior conveyance.','Takes without notice, regardless of recording.','Records within 30 days of purchase.',
   'B','In race-notice jurisdictions, a subsequent bona fide purchaser prevails only if (1) the subsequent purchaser had no actual or constructive notice of the prior conveyance when purchasing, AND (2) the subsequent purchaser records first. Both conditions must be satisfied.','Recording Acts — Race-Notice',null, true),
  ('real-prop-001','recording_acts','hard','O conveys Blackacre to A by deed. A does not record. O then conveys to B for value. B has actual notice of the prior deed to A. In a notice jurisdiction:',
   'B prevails — B recorded first.','A prevails — B had actual notice of A''s prior deed.','B prevails — O had authority to convey.','A prevails — A had possession.',
   'B','In a pure notice jurisdiction, a subsequent purchaser prevails over a prior unrecorded interest if the subsequent purchaser took without notice (actual, constructive, or inquiry). Because B had actual notice of A''s deed, B is not a bona fide purchaser and A prevails, even though A did not record.','Recording Acts — Notice (BFP Doctrine)',null, true),
  ('real-prop-001','recording_acts','easy','Constructive (record) notice means:',
   'A party actually read a recorded document.','A party is deemed to have notice of all properly recorded instruments in the chain of title, even if never actually read.','A party should have investigated but did not.','A party received oral notice of a competing claim.',
   'B','Constructive record notice: recording a deed in the chain of title gives constructive notice to all subsequent purchasers — they are charged with notice of what a proper title search would reveal, whether or not they actually searched. This incentivizes recording.','Constructive (Record) Notice',null, true),
  ('real-prop-001','adverse_possession','easy','Adverse possession requires all of the following EXCEPT:',
   'Actual possession.','Open and notorious use.','Continuous for the statutory period.','Payment of property taxes.',
   'D','Most states do not require payment of property taxes for adverse possession, though some do. The traditional elements are: (1) actual entry and possession, (2) open and notorious (visible, not hidden), (3) exclusive (not shared with owner), (4) hostile/adverse (without owner''s permission), and (5) continuous for the statutory period.','Adverse Possession — Elements',null, true),
  ('real-prop-001','adverse_possession','medium','Tacking in adverse possession allows:',
   'Two adverse possessors to combine their periods of possession to meet the statutory period, if there is privity between them.','An adverse possessor to pause possession without losing credit for prior years.','The true owner to stop the period from running by recording a deed.','The adverse possessor to assert the claim without actual possession.',
   'A','Tacking permits successive adverse possessors to combine their periods of possession to satisfy the statute of limitations, but only if there is privity between the successive possessors — a voluntary transfer of the claim to adverse possession (e.g., deed or devise). Privity cannot be created by a forcible dispossession.','Adverse Possession — Tacking',null, true),
  ('real-prop-001','adverse_possession','hard','A neighbor builds a fence two feet over the property line in good faith, believing it to be the true boundary. In a jurisdiction requiring hostile intent, this fence encroachment:',
   'Satisfies the hostile element — the encroachment is against the owner''s title.','Does not satisfy the hostile element — good faith means the encroacher does not claim against the owner.','Satisfies the hostile element only if the encroachment was intentional.','Automatically gives the neighbor title after 10 years.',
   'A','''Hostile'' in adverse possession means without the owner''s permission and against the owner''s interests, not that the possessor intended to claim another''s land. Most jurisdictions use an objective standard: the possessor treated the land as their own. Good faith mistake satisfies the objective hostile test.','Adverse Possession — Hostile Intent (Objective Standard)',null, true),
  ('real-prop-001','easements','easy','An easement appurtenant:',
   'Benefits a specific person regardless of land ownership.','Benefits the dominant tenement and runs with the land.','Is personal to the holder and expires on death.','Is revocable by the servient tenement owner.',
   'B','An easement appurtenant benefits a specific parcel (dominant tenement) by burdening an adjacent parcel (servient tenement). It runs with the land — passing automatically to successive owners of the dominant tenement without separate conveyance.','Easement Appurtenant — Runs with Land',null, true),
  ('real-prop-001','easements','medium','An easement by necessity arises when:',
   'A court determines it is fair to impose an easement.','A parcel is so landlocked that it cannot be used without crossing a neighbor''s land, and the landlocked parcel was once part of the same tract as the servient land.','A buyer fails to verify access before purchase.','A prescriptive easement has been abandoned.',
   'B','An easement by necessity is implied when a grantor conveys a parcel that cannot be accessed without crossing retained or previously common land. The necessity must exist at the time of severance of the parcels. When the necessity ceases, the easement terminates.','Easement by Necessity',null, true),
  ('real-prop-001','easements','hard','An easement by prescription is acquired by:',
   'Open, notorious, continuous, and hostile use without the owner''s permission for the statutory period.','Paying the owner consideration for the right to cross the land.','Filing an adverse possession claim after 10 years.','Demonstrating actual necessity for access.',
   'A','An easement by prescription parallels adverse possession but for use rather than possession. The elements are: (1) actual use, (2) open and notorious, (3) continuous for the statutory period, and (4) hostile/adverse (without permission). Unlike adverse possession, exclusivity is not required — the user need not exclude the true owner.','Easement by Prescription',null, true),
  ('real-prop-001','covenants','easy','A real covenant is enforceable against a successor if:',
   'The covenant is in writing and there was privity.','The covenant was intended to run, touches and concerns the land, there was privity (horizontal at formation, vertical at transfer), and successors had notice.','The covenant benefits adjacent property.','The covenant was created for a public purpose.',
   'B','For a real covenant to run at law to bind a covenantor''s successor: (1) original parties intended covenant to run, (2) covenant touches and concerns the land (directly relates to use or enjoyment), (3) horizontal privity (at creation: grantor-grantee relationship), (4) vertical privity (successive ownership of the burdened estate), and (5) successor had notice.','Real Covenant — Requirements to Run',null, true),
  ('real-prop-001','covenants','medium','An equitable servitude differs from a real covenant in that it:',
   'Requires horizontal privity to be enforceable.','May be enforced in equity without the privity requirements, as long as the party had notice.','Runs only with the dominant tenement.','Requires vertical privity for enforcement against successors.',
   'B','An equitable servitude (Tulk v. Moxhay) is enforceable in equity against successors who take with notice, without the strict privity requirements of real covenants. It requires: (1) intent to bind successors, (2) touches and concerns land, and (3) notice. It is enforced by injunction rather than damages.','Equitable Servitude vs. Real Covenant','Tulk v. Moxhay (1848)', true),
  ('real-prop-001','mortgages','easy','Under a mortgage, if the mortgagor defaults:',
   'The lender immediately owns the property.','The lender must commence foreclosure proceedings to enforce its security interest.','The mortgagor loses all rights to the property automatically.','The lender may take possession without judicial process.',
   'B','A mortgage is a security interest in real property — it does not transfer title to the lender. Upon default, the lender must follow the state''s foreclosure process (judicial or non-judicial) to enforce the security interest and obtain the right to sell the property.','Mortgage — Default and Foreclosure',null, true),
  ('real-prop-001','mortgages','medium','The equity of redemption allows:',
   'The mortgagor to redeem the property before the foreclosure sale by paying the full debt.','The mortgagor to redeem after the foreclosure sale for a limited period.','The lender to demand full payment before the maturity date.','A junior lienholder to redeem the property from the senior lender.',
   'A','The equitable right of redemption (equity of redemption) allows a defaulting mortgagor to cure the default and redeem the property up until the foreclosure sale. Many states also provide a statutory right of redemption — a period after the foreclosure sale during which the mortgagor may redeem.','Equity of Redemption',null, true),
  ('real-prop-001','mortgages','hard','A deficiency judgment after a foreclosure sale is available when:',
   'The foreclosure sale proceeds exceed the mortgage debt.','The foreclosure sale proceeds are less than the outstanding debt, allowing the lender to sue the mortgagor personally for the difference.','The lender agrees to a deed in lieu of foreclosure.','The mortgagor files for bankruptcy after the foreclosure.',
   'B','If the foreclosure sale does not generate enough to pay off the mortgage debt, the lender may pursue a deficiency judgment — a personal judgment against the mortgagor for the balance. Many states have anti-deficiency statutes that limit or prohibit deficiency judgments, particularly for purchase money mortgages.','Deficiency Judgment After Foreclosure',null, true)
) AS v(subject_id, category, difficulty, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, rule_tested, case_citation, is_active)
WHERE NOT EXISTS (SELECT 1 FROM quiz_questions q
                  WHERE q.subject_id = v.subject_id AND q.stem = v.stem);

COMMIT;

-- ══ from 20260720000006_seed_torts.sql  (6 quoting repairs) ══
-- Torts: Intentional Torts, Negligence, Strict Liability, Products Liability, Defamation, Nuisance, Damages
-- 25 MBE questions

BEGIN;

INSERT INTO quiz_questions
  (subject_id, category, difficulty, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, rule_tested, case_citation, is_active)
SELECT v.* FROM (VALUES
('torts-001','intentional_torts','easy','Battery requires:',
   'An intent to cause harmful or offensive contact and actual physical harm.','An intent to cause harmful or offensive contact, which results in such contact.','Deliberate violence against another person.','Offensive words or threats causing apprehension.',
   'B','Battery: (1) intent to cause harmful or offensive contact, and (2) harmful or offensive contact results. Intent to make contact is required, not intent to harm. Contact with the person or something closely connected to the person (e.g., clothing, a cane) qualifies. Damages are presumed.','Battery — Elements',null, true),
  ('torts-001','intentional_torts','medium','Assault requires:',
   'Physical contact with the plaintiff.','Intent to cause apprehension, and reasonable apprehension of imminent harmful or offensive contact.','Words threatening future harm.','A weapon or other dangerous instrumentality.',
   'B','Assault: (1) intent to cause apprehension, (2) reasonable apprehension of imminent harmful or offensive contact. Words alone generally cannot constitute assault (no apprehension of physical contact); physical contact itself is battery, not assault. The plaintiff must be aware of the threatened contact.','Assault — Elements',null, true),
  ('torts-001','intentional_torts','medium','False imprisonment requires:',
   'Imprisonment in a jail or correctional facility.','Intent to confine, and actual confinement in a bounded area that the plaintiff is aware of or harmed by.','An unlawful arrest by law enforcement.','Confinement for more than one hour.',
   'B','False imprisonment: (1) intent to confine, (2) actual confinement within a bounded area, and (3) plaintiff is aware of or harmed by the confinement. There must be no reasonable means of escape that the plaintiff can use without danger, hardship, or affront to dignity.','False Imprisonment — Elements',null, true),
  ('torts-001','intentional_torts','hard','Shopkeeper''s privilege allows a merchant to detain a suspected shoplifter if:',
   'The merchant has reasonable grounds to believe shoplifting occurred, detains in a reasonable manner, and for a reasonable time to investigate.','Any store employee suspects theft.','The suspect is caught on camera.','Law enforcement has been called.',
   'A','The shopkeeper''s privilege (Restatement § 120A): a shopkeeper may detain a suspected shoplifter if (1) there are reasonable grounds to believe theft occurred or is occurring, (2) detention is done in a reasonable manner (not excessive force), and (3) only for a reasonable time necessary to investigate or summon police.','Shopkeeper''s Privilege',null, true),
  ('torts-001','intentional_torts','medium','Intentional infliction of emotional distress (IIED) requires:',
   'Any intentional emotional harm.','Extreme and outrageous conduct, intent (or recklessness) to cause severe emotional distress, and severe emotional distress results.','Physical contact causing emotional trauma.','Repeated harassment over a period of time.',
   'B','IIED (Restatement § 46): (1) extreme and outrageous conduct (exceeds all bounds tolerated by decent society), (2) intent to cause severe emotional distress or reckless disregard of high probability of causing it, and (3) causation of severe emotional distress. ''Extreme and outrageous'' is a high bar.','IIED — Elements',null, true),
  ('torts-001','intentional_torts','hard','A defendant with intent to commit battery against A accidentally hits B instead. Under the doctrine of transferred intent:',
   'Defendant has no liability to B — there was no intent to contact B.','Intent to commit battery against A transfers to B — defendant is liable for battery against B.','Defendant is liable only for negligence toward B.','Defendant is liable to A for battery but not to B.',
   'B','Transferred intent: when a defendant intends to commit an intentional tort against one person but the tort occurs against a different person, the intent transfers. Traditional torts for which intent transfers include: battery, assault, false imprisonment, trespass to land, and trespass to chattels.','Transferred Intent',null, true),
  ('torts-001','negligence','easy','The elements of negligence are:',
   'Intent, causation, and damages.','Duty, breach, causation (actual and proximate), and damages.','Strict liability, causation, and harm.','Knowledge of the risk, unreasonable conduct, and injury.',
   'B','Negligence requires: (1) a duty of care owed to the plaintiff, (2) breach of that duty (conduct falling below the reasonable person standard), (3) actual causation (but-for cause), (4) proximate causation (legal cause/foreseeability), and (5) actual damages. All five elements must be proven.','Negligence — Elements',null, true),
  ('torts-001','negligence','medium','The reasonable person standard in negligence is:',
   'The standard of a similarly trained professional.','What an ordinarily prudent person would do in similar circumstances.','What the defendant believed was appropriate.','A standard adjusted for the defendant''s subjective mental state.',
   'B','The objective reasonable person standard: negligence is judged by what a hypothetical reasonable person (average intelligence, reasonable knowledge and skill) would do under the same or similar circumstances. Defendants are not judged by their individual capacity — those below average are still held to the reasonable person standard.','Reasonable Person Standard',null, true),
  ('torts-001','negligence','hard','A professional (e.g., a doctor) is held to:',
   'The ordinary reasonable person standard.','The standard of a reasonably competent member of the same profession under similar circumstances.','The highest degree of care technically possible.','A standard set by licensing boards.',
   'B','Professionals are held to the standard of a reasonably competent member of their profession (specialty) in similar circumstances, not merely the reasonable layperson. Medical specialists are held to the standard of their specialty, not general practitioners.','Professional Standard of Care',null, true),
  ('torts-001','negligence','medium','Res ipsa loquitur allows a plaintiff to prove negligence circumstantially if:',
   'The plaintiff cannot identify the specific negligent act.','The accident is of a type that does not normally occur without negligence, the instrumentality was within the defendant''s exclusive control, and the plaintiff did not contribute.','The plaintiff suffered a severe injury.','The defendant cannot explain how the accident occurred.',
   'B','Res ipsa loquitur (the thing speaks for itself): permits an inference of negligence when (1) the event is of a type that normally does not occur absent negligence, (2) the defendant had exclusive control over the instrumentality, and (3) the plaintiff did not contribute to the occurrence. It shifts the burden of production, not persuasion.','Res Ipsa Loquitur — Elements',null, true),
  ('torts-001','negligence','hard','The ''but for'' test of actual causation means:',
   'The defendant''s negligence was a proximate cause of the injury.','The plaintiff would not have been injured but for the defendant''s negligent conduct.','The negligent act was the most significant cause of the injury.','Multiple actors contributed to the injury.',
   'B','Actual (factual) causation is established by the but-for test: plaintiff must prove that but for the defendant''s negligent conduct, the harm would not have occurred. When multiple defendants each independently caused sufficient harm, the substantial factor test may be used.','Actual Causation — But-For Test',null, true),
  ('torts-001','negligence','medium','In Palsgraf v. Long Island Railroad, the court held that a defendant owes a duty of care only to:',
   'Everyone who might foreseeably be injured by negligent conduct.','Those who are in the foreseeable zone of danger from the defendant''s negligent conduct.','Anyone the defendant could have seen at the time of the act.','Those who have a pre-existing relationship with the defendant.',
   'B','Cardozo''s majority in Palsgraf: the defendant owes a duty only to those within the foreseeable zone of danger — those foreseeably at risk from the specific negligent act. Mrs. Palsgraf was too far from the trainmen''s negligent act to be a foreseeable plaintiff. Andrews'' dissent argued duty runs to all.','Proximate Causation — Palsgraf / Zone of Danger','Palsgraf v. Long Island Railroad Co. (1928)', true),
  ('torts-001','negligence','hard','A superseding cause:',
   'Is any intervening act that breaks the causal chain.','Is an intervening cause that was not foreseeable and that breaks the original defendant''s liability.','Is only relevant when a third party acts intentionally.','Is any intervening cause that contributed to the plaintiff''s injury.',
   'B','An intervening cause breaks the chain of proximate causation only if it is unforeseeable (superseding). Foreseeable intervening causes (rescue attempts, ordinary negligence of others, medical malpractice) do not relieve the original defendant. Criminal acts of third parties may be superseding unless their occurrence was foreseeable.','Superseding Cause',null, true),
  ('torts-001','negligence','medium','Comparative fault replaces the common law contributory negligence rule by:',
   'Barring recovery if the plaintiff is more than 50% at fault.','Reducing the plaintiff''s recovery proportionally to her share of fault.','Allocating fault equally between the parties.','Eliminating all damages when the plaintiff was partially at fault.',
   'B','Pure comparative fault (minority of states): plaintiff''s recovery is reduced by her percentage of fault, no matter how great. Modified comparative fault (most states): plaintiff may recover only if her fault does not exceed 50% (or 51%) of the total. Both replace the all-or-nothing contributory negligence bar.','Comparative Fault — Replacing Contributory Negligence',null, true),
  ('torts-001','strict_liability','easy','A defendant engaged in an abnormally dangerous activity is liable for resulting harm:',
   'Only if negligent in how the activity was conducted.','Without proof of negligence, based on strict liability.','Only to adjacent landowners.','Only if the activity violated a statute.',
   'B','Strict liability for abnormally dangerous activities (Restatement § 520): the defendant is liable without proof of negligence if the activity (1) involves serious risk of harm, (2) cannot be made safe even with utmost care, (3) is not common usage, (4) is inappropriate for the location, and (5) the risk outweighs the utility.','Strict Liability — Abnormally Dangerous Activities',null, true),
  ('torts-001','strict_liability','medium','Under Rylands v. Fletcher, a defendant who brings onto land a dangerous substance that escapes and harms another is:',
   'Liable only if negligent.','Strictly liable for all natural consequences of the escape.','Liable only if the substance was inherently dangerous.','Not liable if the escape was caused by an act of God.',
   'B','Rylands v. Fletcher established the English predecessor to strict liability for dangerous instrumentalities. A person who brings onto land a dangerous substance that is likely to do harm if it escapes is strictly liable if it escapes and causes damage. American courts adopted this rule for ultra-hazardous activities.','Rylands v. Fletcher — Strict Liability','Rylands v. Fletcher (1868)', true),
  ('torts-001','products_liability','easy','Under strict products liability (Restatement § 402A), a manufacturer is liable for:',
   'Any injury caused by its product.','A product that is defective and unreasonably dangerous when it leaves the seller''s control.','A product the buyer did not use as intended.','Breach of an express warranty only.',
   'B','Restatement (Second) § 402A: a seller who sells a product in a defective condition unreasonably dangerous to the user or consumer is strictly liable for physical harm caused to the ultimate user, even if the seller exercised all possible care and there is no contractual privity between them.','Strict Products Liability — § 402A','Restatement (Second) of Torts § 402A', true),
  ('torts-001','products_liability','medium','A manufacturing defect exists when:',
   'The product''s design makes it unreasonably dangerous.','A specific unit departs from the intended design and is thereby more dangerous.','The product lacks adequate warnings.','The product fails to meet consumer expectations.',
   'B','A manufacturing defect: the product as made differs from the intended design. It makes an individual product unit more dangerous than it should have been — a departure from the manufacturer''s own specifications. The plaintiff must show the specific unit deviated from the design.','Manufacturing Defect',null, true),
  ('torts-001','products_liability','hard','Under the risk-utility test for design defects, a product is defectively designed if:',
   'The product injured the plaintiff.','The foreseeable risks of harm posed by the product could have been reduced by a reasonable alternative design whose omission renders the product not reasonably safe.','The product did not meet industry standards.','The product failed to include warnings.',
   'B','Restatement (Third) of Torts § 2(b) adopts the risk-utility test for design defects: a product is defectively designed if the foreseeable risks of harm could have been reduced or avoided by a reasonable alternative design (RAD) and the omission of the RAD renders the product not reasonably safe. This requires proof of a feasible alternative.','Design Defect — Risk-Utility Test / RAD','Restatement (Third) of Torts § 2(b)', true),
  ('torts-001','defamation','easy','Defamation requires:',
   'A false statement.','A false statement of fact, published to a third party, that harms the plaintiff''s reputation.','A harmful opinion.','Malicious intent.',
   'B','Defamation (libel/slander) requires: (1) a false statement of fact (not opinion), (2) publication to at least one third party, (3) identification of the plaintiff, (4) fault (at least negligence for private plaintiffs per Gertz), and (5) damages (presumed for libel per se; required for slander without the per se exceptions).','Defamation — Elements',null, true),
  ('torts-001','defamation','medium','A public figure suing for defamation must prove:',
   'Negligence.','Actual malice — knowledge of falsity or reckless disregard for truth or falsity.','Intentional harm.','That the defendant acted with ill will.',
   'B','Under New York Times Co. v. Sullivan, a public official (and by extension, public figure) must prove actual malice — the defendant knew the statement was false or acted with reckless disregard for its truth or falsity. This First Amendment-based standard protects robust public debate.','Defamation — Public Figure / Actual Malice','New York Times Co. v. Sullivan (1964)', true),
  ('torts-001','nuisance','easy','Private nuisance is defined as:',
   'Any annoying or bothersome activity by a neighbor.','An intentional, negligent, or abnormally dangerous act that substantially and unreasonably interferes with another''s use and enjoyment of their property.','Any action that reduces the plaintiff''s property value.','Conduct that violates local zoning laws.',
   'B','Private nuisance: a substantial and unreasonable interference with another''s use and enjoyment of land. ''Substantial'' means more than mere annoyance; ''unreasonable'' requires balancing the utility of the conduct against the gravity of the harm.','Private Nuisance — Elements',null, true),
  ('torts-001','nuisance','medium','Public nuisance is an act that:',
   'Affects only adjacent landowners.','Unreasonably interferes with a right common to the general public.','Is illegal under local ordinance.','Is a persistent trespass to public land.',
   'B','Public nuisance: an unreasonable interference with a right common to the general public — e.g., blocking a public road, contaminating a public water supply, or creating conditions endangering public health or safety. A private person may sue for public nuisance only by showing special harm different in kind from that suffered by the public.','Public Nuisance — Elements',null, true),
  ('torts-001','damages_torts','easy','Compensatory damages in tort law are designed to:',
   'Punish the defendant.','Make the plaintiff whole by compensating for actual losses.','Deter future misconduct.','Cover only economic losses.',
   'B','Compensatory damages aim to restore the plaintiff to the position they would have been in but for the tort. They include special (economic) damages — medical expenses, lost wages, property damage — and general (non-economic) damages — pain and suffering, emotional distress, loss of enjoyment of life.','Compensatory Damages — Goal',null, true),
  ('torts-001','damages_torts','hard','Punitive damages in tort cases are awarded when:',
   'The plaintiff suffers severe injuries.','The defendant''s conduct was intentional, malicious, fraudulent, or so reckless as to show conscious disregard for the rights of others.','Economic damages are very high.','The defendant is a large corporation.',
   'B','Punitive damages are awarded in addition to compensatory damages to punish and deter egregious misconduct. They require a finding that the defendant acted with malice, fraud, oppression, or reckless disregard for others'' rights. Due process limits their amount relative to compensatory damages (BMW v. Gore).','Punitive Damages — Standard','BMW of North America v. Gore (1996)', true)
) AS v(subject_id, category, difficulty, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, rule_tested, case_citation, is_active)
WHERE NOT EXISTS (SELECT 1 FROM quiz_questions q
                  WHERE q.subject_id = v.subject_id AND q.stem = v.stem);

COMMIT;
